(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,98655,e=>{"use strict";var i=e.i(37654);let n=[{id:"cat-1",slug:"metabolic-peptides",name:"Metabolic Peptides",description:"Peptides involved in metabolic regulation, energy homeostasis, and body composition research. Includes GLP-1, GIP, and glucagon receptor agonists.",image:"/images/category-metabolic.webp",productCount:9},{id:"cat-2",slug:"recovery-peptides",name:"Recovery & Repair Peptides",description:"Tissue repair and wound healing peptides for regenerative medicine studies. Used worldwide by researchers, labs, and institutions for in-vitro research.",image:"/images/category-recovery.webp",productCount:4},{id:"cat-3",slug:"cognitive-peptides",name:"Cognitive Peptides",description:"Nootropic and neuroprotective peptides for neuroscience, memory, attention, and CNS research. Studied in-vitro by researchers, labs, and institutions.",image:"/images/category-cognitive.webp",productCount:4},{id:"cat-4",slug:"anti-aging-peptides",name:"Anti-Aging Peptides",description:"Peptides studied for their role in longevity, skin health, cellular energy, and age-related biological processes.",image:"/images/category-aging.webp",productCount:9},{id:"cat-5",slug:"accessories",name:"Research Accessories",description:"Essential supplies for peptide research including bacteriostatic water and reconstitution materials. Used by researchers, labs, and institutions worldwide.",image:"/images/category-accessories.webp",productCount:1},{id:"cat-6",slug:"blends",name:"Research Blends",description:"Multi-peptide research blends co-lyophilized in a single vial for combined-pathway study designs. Supplied to individual researchers, laboratories, and institutions for in-vitro and laboratory research use only.",image:"/images/product-klow-80mg.webp",productCount:4}],t={de:{products:{"glp-3-rt":{name:"GLP-3 (RT)",description:"Triple-Agonist-Peptid, das GLP-1-, GIP- und Glucagon-Rezeptoren adressiert, für die Stoffwechsel- und Adipositasforschung.",longDescription:"GLP-3 (RT) ist ein neuartiges Triple-Agonist-Peptid, das gleichzeitig GLP-1-, GIP- und Glucagon-Rezeptoren adressiert. Dieser einzigartige dreifache Mechanismus ermöglicht eine umfassende Untersuchung metabolischer Signalwege, wie sie mit Einzel- oder Dual-Agonisten nicht möglich ist, und macht die Substanz zu einer erstklassigen Forschungssubstanz für Stoffwechsel- und Adipositasstudien.",benefits:["Triple-Rezeptor-Agonist (GLP-1 + GIP + Glucagon)","Untersuchung fortgeschrittener metabolischer Signalwege","Studien zu Adipositas und Körperzusammensetzung","Für die umfassende Stoffwechseluntersuchung Dual-Agonisten überlegen","Publikationsreife Ergebnisse mit einer Reinheit von über 99 %"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. GLP-3 (RT) wurde in Stoffwechsel-Forschungssettings bei verschiedenen Konzentrationen untersucht. Die rekonstituierte Lösung bei 2-8 °C lagern und innerhalb von 30 Tagen verwenden.",faq:[{question:"Was macht GLP-3 (RT) einzigartig?",answer:"GLP-3 (RT) ist ein Triple-Agonist, der GLP-1-, GIP- und Glucagon-Rezeptoren gleichzeitig adressiert und damit eine umfassende Untersuchung metabolischer Signalwege ermöglicht, die mit Einzel- oder Dual-Rezeptor-Agonisten nicht möglich ist."},{question:"Wie sollte ich GLP-3 (RT) lagern?",answer:"Lyophilisiertes Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["metabolisch","Triple-Agonist","GLP-1","GIP","Glucagon","Bestseller","Forschungspeptid"]},"ghk-cu":{name:"GHK-Cu (Kupferpeptid)",description:"Kupferpeptid-Komplex für Forschungsanwendungen zu Hautregeneration, Wundheilung und Anti-Aging.",longDescription:"GHK-Cu ist ein natürlich vorkommendes Tripeptid (Glycyl-L-Histidyl-L-Lysin) mit hoher Affinität zu Kupfer(II)-Ionen. Es kommt im menschlichen Plasma, Speichel und Urin vor, seine Konzentration nimmt mit dem Alter ab. Umfangreiche Forschung hat seine Rolle bei Wundheilung, Gewebeumbau, Kollagensynthese und Anti-Aging-Mechanismen aufgezeigt.",benefits:["Stimuliert in Studien die Kollagensynthese","Wundheilung und Gewebeumbau","Antioxidative Eigenschaften","Forschung zur Modulation der Genexpression","Studien zu Haarfollikeln"],researchGuide:"GHK-Cu kann in Wasser oder PBS gelöst werden. Für topische Forschungsanwendungen werden üblicherweise Konzentrationen von 0,01-1 % verwendet. Bei 2-8 °C lagern.",faq:[{question:"In welcher Form wird dieses Produkt geliefert?",answer:"GHK-Cu wird als lyophilisiertes blaues Pulver geliefert (aufgrund des Kupfergehalts)."},{question:"Ist das dasselbe wie GHK?",answer:"GHK-Cu ist die kupfergebundene Form des GHK-Tripeptids, die im Körper natürlich vorkommende bioaktive Form."}],tags:["Anti-Aging","Kupfer","Haut","Wundheilung","Forschungspeptid"]},semax:{name:"Semax",description:"Synthetisches ACTH-Analogon-Neuropeptid für die Forschung zu kognitiver Funktion, Neuroprotektion und ZNS.",longDescription:"Semax ist ein synthetisches Peptid, abgeleitet vom Fragment 4-10 des adrenocorticotropen Hormons (ACTH), mit einer Pro-Gly-Pro-Modifikation am C-Terminus für erhöhte Stabilität. Es wurde umfassend auf neuroprotektive Eigenschaften, kognitive Verbesserung und als Forschungswerkzeug zum Verständnis der BDNF-vermittelten Neuroplastizität untersucht.",benefits:["BDNF-Hochregulierung in Studien","Studien zu Neuroprotektions-Signalwegen","Forschung zur kognitiven Funktion","Studien zur Schlaganfall-Erholung","NGF-Modulation"],researchGuide:"Mit bakteriostatischem Wasser rekonstituieren. Wird in Tiermodellen häufig intranasal untersucht. Weist eine relativ kurze Halbwertszeit auf. Bei 2-8 °C lagern.",faq:[{question:"Wie hängt Semax mit ACTH zusammen?",answer:"Semax basiert auf dem ACTH(4-10)-Fragment, wurde jedoch am C-Terminus mit einem Pro-Gly-Pro-Tripeptid für metabolische Stabilität modifiziert."},{question:"Wie lauten Molekulargewicht und Formel von Semax?",answer:"Semax hat die Summenformel C37H51N9O10S und ein Molekulargewicht von etwa 813,9 g/mol (PubChem CID 122178). Seine Aminosäuresequenz ist Met-Glu-His-Phe-Pro-Gly-Pro."},{question:"Welche Reinheit hat Semax von Miro Biotech?",answer:"Jede Charge wird unabhängig von einem Drittlabor getestet und auf 99,1 % Reinheit verifiziert, mit einem Analysenzertifikat für die Charge."},{question:"Wie wird Semax in Forschungssettings gehandhabt?",answer:"Semax wird als lyophilisiertes Pulver geliefert und typischerweise mit bakteriostatischem Wasser für die Laborarbeit rekonstituiert. In publizierten Tierstudien wurde es meist intranasal oder subkutan verabreicht. Es ist ausschließlich für die In-vitro- und Laborforschung bestimmt."},{question:"Wofür wurde Semax untersucht?",answer:"Publizierte Forschung hat Semax in Tiermodellen zur Neurotrophin-Signalgebung (BDNF und TrkB), zur Neuroprotektion und zur zerebralen Ischämie sowie in genomweiten Genexpressionsanalysen nach experimentellem Schlaganfall untersucht."}],tags:["kognitiv","neuroprotektiv","ACTH","Nootropikum","Forschungspeptid"],aka:["ACTH(4-10) Pro-Gly-Pro","Met-Glu-His-Phe-Pro-Gly-Pro","MEHFPGP"],whatIs:"Semax ist ein synthetisches Heptapeptid (Met-Glu-His-Phe-Pro-Gly-Pro), ein Analogon des ACTH(4-10)-Fragments mit einem angefügten Pro-Gly-Pro-Rest für metabolische Stabilität. Es wird als Forschungssubstanz in Studien zur Neurotrophin-Signalgebung, Neuroprotektion und Kognition eingesetzt. Geliefert ausschließlich für die In-vitro- und Laborforschung.",mechanism:"In publizierter Tierforschung wurde berichtet, dass Semax die Expression des Brain-derived Neurotrophic Factor (BDNF) und seines TrkB-Rezeptors im Hippocampus rasch erhöht und die dopaminerge und serotonerge Signalgebung moduliert. Weitere Studien beschreiben eine Hemmung Enkephalin-abbauender Enzyme sowie eine Interaktion mit Melanocortin-Rezeptoren. Diese Signalwege werden in Modellen der Neuroplastizität und zerebralen Ischämie untersucht; entsprechende Mechanismen beim Menschen sind nicht belegt.",receptorTargets:["BDNF-/TrkB-Signalweg","Dopaminerge Signalgebung","Serotonerge Signalgebung","Melanocortin-Rezeptoren (MC4/MC5)","Enkephalin-abbauende Enzyme"],specs:[{label:"Sequenz",value:"Met-Glu-His-Phe-Pro-Gly-Pro (MEHFPGP)"},{label:"Klassifizierung",value:"Synthetisches Heptapeptid, ACTH(4-10)-Analogon"},{label:"Erscheinungsbild",value:"Weißes lyophilisiertes Pulver"},{label:"Löslichkeit",value:"Löslich in Wasser und bakteriostatischem Wasser"}],researchApplications:[{title:"Neurotrophin-Signalgebung",description:"Eingesetzt in Studien zur BDNF- und TrkB-Expression und zu nachgeschalteten Neuroplastizitäts-Signalwegen."},{title:"Neuroprotektion",description:"Untersucht in Nagermodellen der zerebralen Ischämie und der Ischämie-Reperfusions-Schädigung."},{title:"Kognition und Verhalten",description:"Erforscht in Untersuchungen zu Lern-, Aufmerksamkeits- und gedächtnisbezogenen Endpunkten in Tiermodellen."},{title:"Genexpression",description:"Angewandt in genomweiten Transkriptionsstudien immun- und gefäßbezogener Gene nach experimentellem Schlaganfall."}],keyStudies:[{title:"Semax, ein Analogon von ACTH(4-10) mit kognitiven Effekten, reguliert die BDNF- und trkB-Expression im Hippocampus der Ratte",source:"Brain Research",year:2006,url:"https://pubmed.ncbi.nlm.nih.gov/16996037/",finding:"Berichtete, dass Semax die BDNF- und TrkB-Expression im Hippocampus der Ratte rasch erhöhte."},{title:"Semax und Pro-Gly-Pro aktivieren die Transkription von Neurotrophinen und ihren Rezeptorgenen nach zerebraler Ischämie",source:"Cellular and Molecular Neurobiology",year:2010,url:"https://pubmed.ncbi.nlm.nih.gov/19633950/",finding:"Beobachtete eine Aktivierung der Transkription von Neurotrophin- und Rezeptorgenen nach zerebraler Ischämie in einem Rattenmodell."},{title:"Das Peptid Semax beeinflusst die Expression von Genen des Immun- und Gefäßsystems bei fokaler Hirnischämie der Ratte: genomweite Transkriptionsanalyse",source:"BMC Genomics",year:2014,url:"https://pubmed.ncbi.nlm.nih.gov/24661604/",finding:"Die genomweite Analyse beschrieb Veränderungen der immun- und gefäßbezogenen Genexpression nach fokaler Ischämie."},{title:"Proteinexpressionsprofil im Gehirn bestätigt die schützende Wirkung des ACTH(4-7)PGP-Peptids (Semax) in einem Ratten-Modell der zerebralen Ischämie-Reperfusion",source:"International Journal of Molecular Sciences",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34201112/",finding:"Das proteomische Profiling berichtete Veränderungen auf Proteinebene, die mit einer schützenden Wirkung in einem Ratten-Modell der Ischämie-Reperfusion vereinbar sind."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit weißem lyophilisiertem Semax-Pulver. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich.",comparison:{heading:"Semax vs. Selank in der Forschung",columns:["","Semax","Selank"],rows:[{label:"Abgeleitet von",values:["ACTH(4-10)-Fragment","Tuftsin (IgG-abgeleitetes Peptid)"]},{label:"Peptidlänge",values:["Heptapeptid (7 AS)","Heptapeptid (7 AS)"]},{label:"Primärer Forschungsfokus",values:["Neurotrophine, Neuroprotektion","Anxiolytisch, immunmodulatorisch"]},{label:"Übliche Verabreichung in Studien",values:["Intranasal, subkutan","Intranasal"]}]}},selank:{name:"Selank",description:"Von Tuftsin abgeleitetes Heptapeptid für die Forschung zu Verhalten, Kognition und Immunmodulation.",longDescription:"Selank ist ein synthetisches Heptapeptid, abgeleitet vom natürlich vorkommenden Tetrapeptid Tuftsin, mit einer zusätzlichen Gly-Pro-Sequenz für metabolische Stabilität. Am Institut für Molekulargenetik der Russischen Akademie der Wissenschaften entwickelt, wurde es in Forschungsmodellen auf seine verhaltensbezogenen, kognitiven und immunmodulatorischen Eigenschaften untersucht.",benefits:["Forschung zu angstbezogenen Signalwegen","Studien zur kognitiven Verbesserung","Forschung zur Immunmodulation","Forschung zur BDNF-Modulation","Studien zur Interaktion mit dem Serotoninsystem"],researchGuide:"Mit bakteriostatischem Wasser rekonstituieren. Selank wird in Tiermodellen häufig intranasal untersucht. Nach der Rekonstitution bei 2-8 °C lagern.",faq:[{question:"Was ist Tuftsin?",answer:"Tuftsin ist ein natürliches Tetrapeptid (Thr-Lys-Pro-Arg), das durch enzymatische Spaltung von IgG entsteht. Selank ist ein modifiziertes Analogon mit erhöhter Stabilität."}],tags:["kognitiv","Nootropikum","Verhalten","Forschungspeptid"]},"bpc-157":{name:"BPC-157",description:"Body-Protection-Compound aus menschlichem Magensaft, erforscht für Gewebereparatur, Darmgesundheit und Erholung nach Verletzungen.",longDescription:"BPC-157 (Body Protection Compound-157) ist ein synthetisches Pentadecapeptid aus 15 Aminosäuren. Es ist von einem schützenden Protein im Magensaft abgeleitet. Umfangreiche Forschung hat seine bemerkenswerte Fähigkeit aufgezeigt, die Wundheilung zu beschleunigen, Organe zu schützen und Magengeschwüren vorzubeugen. Studien haben gezeigt, dass es in Tiermodellen die Heilung von Sehnen, Muskeln und Knochen fördert.",benefits:["Forschung zu Wundheilungsmechanismen","Studien zu Signalwegen der Sehnen- und Bänderreparatur","Forschung zu Mechanismen des Magenschutzes","Studien zu Angiogenese-Signalwegen","Forschung zur Entzündungsmodulation"],researchGuide:"BPC-157 wird typischerweise mit bakteriostatischem Wasser rekonstituiert. Für In-vitro-Studien liegen übliche Konzentrationen im Bereich von 1-10 μg/mL. Die rekonstituierte Lösung bei 2-8 °C lagern und innerhalb von 30 Tagen verwenden.",faq:[{question:"Wie hoch ist die Reinheit Ihres BPC-157?",answer:"Unser BPC-157 wird auf eine Reinheit von ≥99,3 % getestet, mit vollständigen Analysenzertifikaten, die verfügbar sind."},{question:"Wie sollte ich BPC-157 lagern?",answer:"Lyophilisiertes Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten werden."},{question:"Wie hoch ist das Molekulargewicht?",answer:"Das Molekulargewicht von BPC-157 beträgt 1419,53 g/mol."}],tags:["Heilung","Gewebereparatur","Magen","Regeneration","Forschungspeptid"]},"nad-plus":{name:"NAD+",description:"Coenzym Nicotinamid-Adenin-Dinukleotid für die Forschung zu zellulärem Energiestoffwechsel, DNA-Reparatur und Langlebigkeit.",longDescription:"NAD+ (Nicotinamid-Adenin-Dinukleotid) ist ein essenzielles Coenzym, das in jeder lebenden Zelle vorkommt. Es spielt eine zentrale Rolle im zellulären Energiestoffwechsel, bei der DNA-Reparatur, der Genexpression und der Zellsignalgebung. Der NAD+-Spiegel nimmt mit dem Alter natürlicherweise ab, was es zu einem Schwerpunkt der Langlebigkeits- und Anti-Aging-Forschung macht.",benefits:["Forschung zum zellulären Energiestoffwechsel","Studien zu DNA-Reparatur-Signalwegen","Forschung zur Sirtuin-Aktivierung","Studien zu Langlebigkeit und Alterung","Forschung zur mitochondrialen Funktion"],researchGuide:"NAD+ ist wasserlöslich und kann in sterilem Wasser oder Puffer rekonstituiert werden. Mit Vorsicht handhaben, da es lichtempfindlich ist. Zur Langzeitlagerung bei -20 °C, kurzfristig bei 2-8 °C lagern.",faq:[{question:"Was ist der Unterschied zwischen NAD+ und NMN?",answer:"NAD+ ist das aktive Coenzym selbst, während NMN (Nicotinamid-Mononukleotid) eine Vorstufe ist, die Zellen in NAD+ umwandeln."},{question:"Wie sollte NAD+ gelagert werden?",answer:"Lyophilisiertes NAD+ vor Licht geschützt bei -20 °C lagern. Rekonstituierte Lösungen sollten zeitnah verwendet werden."}],tags:["Anti-Aging","Langlebigkeit","Zellenergie","DNA-Reparatur"]},"tb-500":{name:"TB-500",description:"Synthetisches Analogon von Thymosin Beta-4, untersucht für Geweberegeneration, Wundheilung und Entzündungsmodulation.",longDescription:"TB-500 ist eine synthetische Version von Thymosin Beta-4, einem 43-Aminosäuren-Peptid, das natürlicherweise in praktisch allen menschlichen und tierischen Zellen vorkommt. Es spielt eine zentrale Rolle bei Gewebereparatur, Regeneration und Schutz. Forschung hat seine Fähigkeit aufgezeigt, die Zellmigration und Blutgefäßbildung zu fördern und Entzündungen zu reduzieren.",benefits:["Studien zu Zellmigration und Gewebereparatur","Forschung zur Entzündungsmodulation","Studien zu Angiogenese-Signalwegen","Stimulierung von Haarfollikeln in Studien","Forschung zum Schutz von Herzgewebe"],researchGuide:"TB-500 mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. Übliche Forschungskonzentrationen liegen bei 2,5-5 mg/mL. Nach der Rekonstitution bei 2-8 °C lagern.",faq:[{question:"Wie lautet die Sequenz von TB-500?",answer:"TB-500 ist die aktive Region (17-23) von Thymosin Beta-4 mit der Sequenz Ac-LKKTETQ."},{question:"Ist das das vollständige Thymosin Beta-4?",answer:"TB-500 stellt das aktive Fragment dar. Wir bieten vollständiges Thymosin Beta-4 auch separat an."}],tags:["Heilung","entzündungshemmend","Gewebereparatur","Regeneration","Forschungspeptid"]},tesamorelin:{name:"Tesamorelin",description:"GHRH-Analogon, das die Freisetzung von Wachstumshormon stimuliert, erforscht für Stoffwechselregulation und Studien zur Körperzusammensetzung.",longDescription:"Tesamorelin ist ein synthetisches Analogon des Growth-Hormone-Releasing-Hormone (GHRH) aus 44 Aminosäuren. Es stimuliert die Hypophyse, Wachstumshormon auf physiologische Weise freizusetzen. Es wurde umfassend auf seine Effekte auf Körperzusammensetzung, viszerale Adipositas und metabolische Parameter untersucht.",benefits:["Studien zu Signalwegen der Wachstumshormon-Freisetzung","Forschung zu viszeraler Adipositas","Studien zur Körperzusammensetzung","Forschung zur Stoffwechselregulation"],researchGuide:"Mit bakteriostatischem Wasser rekonstituieren. Tesamorelin ist ein GHRH-Analogon mit physiologischen GH-freisetzenden Eigenschaften. Nach der Rekonstitution bei 2-8 °C lagern.",faq:[{question:"Wie unterscheidet sich Tesamorelin von anderen GHRH-Analoga?",answer:"Tesamorelin ist ein modifiziertes GHRH-Analogon, das eine pulsatile GH-Freisetzung stimuliert und damit die natürliche Physiologie enger nachbildet als eine konstante Stimulation."}],tags:["metabolisch","GHRH","Wachstumshormon","Forschungspeptid"]},"mots-c":{name:"MOTS-c",description:"Mitochondrial abgeleitetes Peptid, untersucht für Stoffwechselregulation, Insulinsensitivität und zelluläre Homöostase.",longDescription:"MOTS-c (Mitochondrial Open Reading Frame of the 12S rRNA Type-c) ist ein mitochondrial abgeleitetes Peptid, das im mitochondrialen Genom kodiert wird. Es hat sich als bedeutende Forschungssubstanz zur Untersuchung von Stoffwechselregulation, Belastungsphysiologie, Insulinsensitivität und zellulärer Energiehomöostase etabliert.",benefits:["Mitochondrial abgeleitetes Signalpeptid","Forschung zur Insulinsensitivität","Studien zur Belastungsphysiologie","Zelluläre Energiehomöostase","Forschung zur Stoffwechselregulation"],researchGuide:"Mit sterilem oder bakteriostatischem Wasser rekonstituieren. MOTS-c ist ein relativ stabiles Peptid. Zur Langzeitlagerung bei -20 °C, kurzfristig bei 2-8 °C lagern.",faq:[{question:"Was ist ein mitochondrial abgeleitetes Peptid?",answer:"MDPs sind Peptide, die im mitochondrialen Genom statt in der Kern-DNA kodiert werden. MOTS-c gehört zu den am besten untersuchten MDPs."}],tags:["metabolisch","mitochondrial","Insulinsensitivität","Forschungspeptid"]},"cjc-1295":{name:"CJC-1295 (ohne DAC)",description:"Hochreines (99,60 %) CJC-1295 ohne DAC Forschungspeptid. GHRH-Analogon für Wachstumshormon-Sekretion, pulsatile GH-Freisetzung und Studien zu metabolischen Signalwegen.",longDescription:"CJC-1295 (ohne DAC) ist ein synthetisches Analogon des Growth-Hormone-Releasing-Hormone (GHRH), bestehend aus den ersten 29 Aminosäuren des GHRH mit modifizierten Resten zur Verbesserung der Rezeptorbindung und biologischen Stabilität. Anders als die DAC-modifizierte Variante erzeugt CJC-1295 ohne DAC kürzere, physiologischere Pulse der Wachstumshormon-Freisetzung, was es zu einer bevorzugten Substanz für die Untersuchung natürlicher GH-Sekretionsmuster und der Stoffwechselregulation macht.",benefits:["Studien zur pulsatilen Wachstumshormon-Freisetzung","Forschung zur GHRH-Rezeptorbindung","Studien zu Signalwegen der Stoffwechselregulation","Forschung zu Körperzusammensetzung und Magermasse","Für physiologische GH-Puls-Studien der DAC-Variante überlegen"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. CJC-1295 (ohne DAC) hat eine kürzere Halbwertszeit als DAC-modifizierte Varianten und unterstützt pulsatile GH-Freisetzungsmuster. Die rekonstituierte Lösung bei 2-8 °C lagern und innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist der Unterschied zwischen CJC-1295 mit und ohne DAC?",answer:"Die DAC-Modifikation (Drug Affinity Complex) verlängert die Halbwertszeit erheblich. Ohne DAC erzeugt CJC-1295 kürzere, physiologischere GH-Pulse, was für die Untersuchung natürlicher GH-Sekretionsdynamik bevorzugt wird."},{question:"Wie sollte ich CJC-1295 lagern?",answer:"Lyophilisiertes Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["metabolisch","GHRH","Wachstumshormon","Sekretagogum","Forschungspeptid"]},ipamorelin:{name:"Ipamorelin",description:"Hochreines (99,20 %) Ipamorelin Forschungspeptid. Selektives Wachstumshormon-Sekretagogum für GH-Freisetzung, Ghrelin-Rezeptorbindung und metabolische Forschungsanwendungen.",longDescription:"Ipamorelin ist ein synthetisches Pentapeptid und selektives Wachstumshormon-Sekretagogum, das am Ghrelin-/GHS-Rezeptor (GHS-R1a) wirkt. Es zeichnet sich durch seine hohe Selektivität aus und stimuliert die GH-Freisetzung, ohne die Spiegel von Cortisol, ACTH oder Prolaktin wesentlich zu beeinflussen. Diese Selektivität macht es zu einem der saubersten Forschungswerkzeuge zur Untersuchung isolierter GH-Signalwege und nachgeschalteter metabolischer Effekte.",benefits:["Studien zur selektiven GH-Freisetzung ohne Cortisol-Anstieg","Studien zur Ghrelin-Rezeptorbindung (GHS-R1a)","Forschung zur sauberen Isolierung des GH-Signalwegs","Studien zu Stoffwechsel und Körperzusammensetzung","Minimale Off-Target-Hormoneffekte in Studien"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. Ipamorelin ist für seine Selektivität in GH-Freisetzungsstudien bekannt, mit minimalem Effekt auf andere Hypophysenhormone. Die rekonstituierte Lösung bei 2-8 °C lagern und innerhalb von 30 Tagen verwenden.",faq:[{question:"Was unterscheidet Ipamorelin von anderen GH-Sekretagoga?",answer:"Ipamorelin ist eines der selektivsten GHRPs und stimuliert die GH-Freisetzung, ohne Cortisol, ACTH oder Prolaktin wesentlich zu erhöhen, was es ideal für die Untersuchung isolierter GH-Signalgebung macht."},{question:"Wie sollte ich Ipamorelin lagern?",answer:"Lyophilisiertes Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten werden."}],tags:["metabolisch","GHRP","Wachstumshormon","Sekretagogum","Ghrelin","Forschungspeptid"]},"mt-2":{name:"MT-2 (Melanotan 2)",description:"Hochreines (99,10 %) MT-2 Melanotan 2 Forschungspeptid. Synthetischer Melanocortin-Agonist für Pigmentierungs-Signalwege, Photoprotektion und Studien an MC-Rezeptoren.",longDescription:"MT-2 (Melanotan 2) ist ein synthetisches zyklisches Heptapeptid-Analogon des Alpha-Melanozyten-stimulierenden Hormons (α-MSH). Es wirkt als nicht-selektiver Agonist an den Melanocortin-Rezeptoren MC1R bis MC5R. Die Forschung konzentrierte sich auf seine Rolle bei Melanogenese und Pigmentierungs-Signalwegen, photoprotektiven Mechanismen und der breiteren Signalgebung des Melanocortin-Systems. Es ist ein zentrales Forschungswerkzeug zur Untersuchung der MC-Rezeptor-Pharmakologie.",benefits:["Forschung an Melanocortin-Rezeptoren (MC1R-MC5R)","Studien zu Melanogenese und Pigmentierungs-Signalwegen","Forschung zu Photoprotektionsmechanismen","Pharmakologische Forschung am α-MSH-Analogon","Studien zur Hautbiologie und UV-Reaktion"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. MT-2 ist lichtempfindlich; bei Handhabung und Lagerung vor direktem Licht schützen. Die rekonstituierte Lösung bei 2-8 °C lagern und innerhalb von 30 Tagen verwenden.",faq:[{question:"Wie ist das Verhältnis zwischen MT-2 und α-MSH?",answer:"MT-2 ist ein synthetisches zyklisches Analogon des Alpha-Melanozyten-stimulierenden Hormons (α-MSH) mit erhöhter metabolischer Stabilität und breiterer Affinität zu Melanocortin-Rezeptoren."},{question:"Wie sollte MT-2 gelagert werden?",answer:"Lyophilisiertes Pulver vor Licht geschützt bei -20 °C lagern. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und vor direktem Licht geschützt werden."}],tags:["Melanocortin","Pigmentierung","Haut","Photoprotektion","Anti-Aging","Forschungspeptid"]},"bacteriostatic-water":{name:"Bakteriostatisches Wasser",description:"Bakteriostatisches Wasser in pharmazeutischer Qualität zur Rekonstitution von Peptiden. Steril, Konservierung mit 0,9 % Benzylalkohol.",longDescription:"Bakteriostatisches Wasser in pharmazeutischer Qualität (USP) mit 0,9 % Benzylalkohol als Konservierungsmittel. Steriles, pyrogenfreies Wasser, geeignet zur Rekonstitution lyophilisierter Peptide für Forschungszwecke. Jedes Vial wird unter aseptischen Bedingungen versiegelt und auf Sterilität geprüft.",benefits:["Pharmazeutische Qualität (USP)","Steril und pyrogenfrei","Konservierung mit 0,9 % Benzylalkohol","Mehrfachverwendung dank Konservierungsmittel","Unverzichtbar für die Peptid-Rekonstitution"],researchGuide:"Bakteriostatisches Wasser zur Rekonstitution lyophilisierter Peptide verwenden. Die gewünschte Menge mit einer sterilen Spritze aufziehen, langsam an der Wand in das Peptidvial injizieren und sanft schwenken. Nicht schütteln.",faq:[{question:"Was ist bakteriostatisches Wasser?",answer:"Bakteriostatisches Wasser ist steriles Wasser mit 0,9 % Benzylalkohol, der das Bakterienwachstum hemmt und so die Mehrfachverwendung aus demselben Vial ermöglicht."},{question:"Wie lange hält rekonstituiertes Peptid?",answer:"Bei Rekonstitution mit bakteriostatischem Wasser und Lagerung bei 2-8 °C bleiben die meisten Peptide 28-30 Tage stabil."}],tags:["Zubehör","Rekonstitution","Wasser"]},"cjc-1295-ipamorelin":{name:"CJC-1295 + Ipamorelin Mischung",description:"Forschungsmischung aus CJC-1295 (ohne DAC) und Ipamorelin, 5mg je Substanz pro 10mg-Vial. Ein GHRH-Analogon gepaart mit einem selektiven Ghrelin-Rezeptor-Sekretagogum für Studien zum Wachstumshormon-Signalweg und Stoffwechsel.",longDescription:"Diese Forschungsmischung kombiniert CJC-1295 (ohne DAC), ein synthetisches Analogon des Growth-Hormone-Releasing-Hormone (GHRH), mit Ipamorelin, einem selektiven Sekretagogum des Ghrelin-/GHS-R1a-Rezeptors, mit 5mg jeder Substanz pro 10mg-Vial. Beide wirken auf komplementären Signalwegen: CJC-1295 adressiert den GHRH-Rezeptor, während Ipamorelin den Ghrelin-Rezeptor adressiert, eine Kombination, die auf ihre gemeinsame Wirkung auf die pulsatile Wachstumshormon-Freisetzung untersucht wird. Sie wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Forschung an dualem GH-Sekretagogum-Signalweg (GHRH + Ghrelin-Rezeptor)","Studien zur pulsatilen Wachstumshormon-Freisetzung","Selektive GH-Signalgebung mit minimalen Off-Target-Hormoneffekten in Studien","Studien zu Signalwegen der Stoffwechselregulation und Körperzusammensetzung","Einzelvial-Mischung aus 5mg + 5mg für Studiendesigns mit kombinierten Sekretagoga"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. Jedes 10mg-Vial enthält 5mg CJC-1295 und 5mg Ipamorelin. Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist in der CJC-1295 + Ipamorelin Mischung enthalten?",answer:"Jedes 10mg-Vial enthält 5mg CJC-1295 (ohne DAC) und 5mg Ipamorelin, als einzelne Mischung co-lyophilisiert."},{question:"Warum werden CJC-1295 und Ipamorelin zusammen untersucht?",answer:"CJC-1295 ist ein GHRH-Analogon und Ipamorelin ein selektives Sekretagogum des Ghrelin-/GHS-R1a-Rezeptors. Da sie auf komplementären Signalwegen wirken, untersuchen Forschende das Paar, um ihre gemeinsame Wirkung auf die pulsatile Wachstumshormon-Freisetzung zu erforschen."},{question:"Wie sollte ich die Mischung lagern?",answer:"Lyophilisiertes Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["metabolisch","GHRH","Ghrelin","Wachstumshormon","Sekretagogum","Mischung","Forschungspeptid"],aka:["CJC-1295 / Ipamorelin","CJC-1295 No DAC + Ipamorelin","GH-Sekretagogum-Mischung"],whatIs:"Die CJC-1295 + Ipamorelin Mischung ist eine Forschungssubstanz, die ein Analogon des Growth-Hormone-Releasing-Hormone (GHRH) mit einem selektiven Sekretagogum des Ghrelin-Rezeptors (GHS-R1a) paart, mit 5mg jeder Substanz pro 10mg-Vial. Sie wird zur In-vitro-Untersuchung der kombinierten Signalgebung des Wachstumshormon-Signalwegs eingesetzt. Geliefert ausschließlich für die Laborforschung.",mechanism:"In publizierter Forschung adressieren die beiden Substanzen unterschiedliche Rezeptoren, die auf die Wachstumshormon-Freisetzung aus den Somatotrophen der Hypophyse konvergieren. Für CJC-1295, ein GHRH-Analogon, wurde ein anhaltender Anstieg von Wachstumshormon und IGF-I bei gesunden Erwachsenen berichtet, während Ipamorelin als das erste selektive Wachstumshormon-Sekretagogum charakterisiert wurde, das die GH-Freisetzung stimuliert, ohne ACTH oder Cortisol wesentlich zu beeinflussen. Die Mischung wird darauf untersucht, wie diese GHRH- und Ghrelin-Rezeptor-Signalwege interagieren könnten; kombinierte Mechanismen und Ergebnisse beim Menschen sind nicht belegt.",receptorTargets:["GHRH-Rezeptor","Ghrelin-/GHS-R1a-Rezeptor","GH-Freisetzung aus Hypophysen-Somatotrophen","IGF-1-Achse"],blendComposition:[{name:"CJC-1295 (No DAC)",role:"GHRH-Analogon",amount:"5mg"},{name:"Ipamorelin",role:"Ghrelin-Agonist",amount:"5mg"}],specs:[{label:"Zusammensetzung",value:"5mg CJC-1295 (ohne DAC) + 5mg Ipamorelin"},{label:"CJC-1295-Klasse",value:"Synthetisches GHRH(1-29)-Analogon (modifiziert, ohne DAC)"},{label:"Ipamorelin-Klasse",value:"Synthetisches Pentapeptid-GH-Sekretagogum (GHRP)"},{label:"Gesamtmenge pro Vial",value:"10mg co-lyophilisierte Mischung"},{label:"Erscheinungsbild",value:"Weißes lyophilisiertes Pulver"},{label:"Löslichkeit",value:"Löslich in bakteriostatischem Wasser"}],researchApplications:[{title:"Wachstumshormon-Freisetzung",description:"Untersucht auf die kombinierte Wirkung von GHRH- und Ghrelin-Rezeptor-Stimulation auf die pulsatile GH-Sekretion."},{title:"Stoffwechselregulation",description:"Eingesetzt in der Forschung zur GH-/IGF-1-Achse und zu nachgeschalteten metabolischen und körperzusammensetzungsbezogenen Endpunkten."},{title:"Rezeptorpharmakologie",description:"Angewandt zur Untersuchung der Signalgebung am GHRH-Rezeptor und am Ghrelin-/GHS-R1a-Rezeptor parallel."},{title:"Sekretagogum-Selektivität",description:"Erforscht in Studiendesigns, die selektive GH-Freisetzung mit Off-Target-Effekten auf Hypophysenhormone vergleichen."}],keyStudies:[{title:"Anhaltende Stimulation der Sekretion von Wachstumshormon (GH) und Insulin-like Growth Factor I durch CJC-1295, ein langwirksames Analogon des GH-freisetzenden Hormons, bei gesunden Erwachsenen",source:"Journal of Clinical Endocrinology & Metabolism",year:2006,url:"https://pubmed.ncbi.nlm.nih.gov/16352683/",finding:"Berichtete, dass subkutanes CJC-1295 anhaltende, dosisabhängige Anstiege von Wachstumshormon und IGF-I bei gesunden Erwachsenen erzeugte."},{title:"Ipamorelin, das erste selektive Wachstumshormon-Sekretagogum",source:"European Journal of Endocrinology",year:1998,url:"https://pubmed.ncbi.nlm.nih.gov/9849822/",finding:"Charakterisierte Ipamorelin als das erste selektive Wachstumshormon-Sekretagogum und berichtete eine GH-Freisetzung vergleichbar mit GHRH ohne wesentlichen Anstieg von ACTH oder Cortisol."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit 5mg CJC-1295 und 5mg Ipamorelin als co-lyophilisiertes weißes Pulver. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich.",comparison:{heading:"CJC-1295 + Ipamorelin vs. die einzelnen Substanzen",columns:["","Mischung","CJC-1295 (ohne DAC)","Ipamorelin"],rows:[{label:"Rezeptorziel",values:["GHRH + Ghrelin (GHS-R1a)","GHRH-Rezeptor","Ghrelin / GHS-R1a"]},{label:"Klasse",values:["GHRH-Analogon + GHRP","GHRH(1-29)-Analogon","Selektives GH-Sekretagogum"]},{label:"Menge pro Vial",values:["5mg + 5mg (10mg)","5mg / 10mg","10mg"]},{label:"Forschungsfokus",values:["Kombinierter GH-Signalweg","Pulsatile GH-Freisetzung","Selektive GH-Freisetzung"]}]}},"glp-2-tz":{name:"GLP-2 (TZ)",description:"Dualer GIP- und GLP-1-Rezeptor-Agonist, geliefert als lyophilisierter Referenzstandard für die Forschung zu metabolischen Signalwegen und Körperzusammensetzung. Erhältlich in 13 Formaten von 5mg bis 120mg.",longDescription:"GLP-2 (TZ) ist ein synthetischer dualer Inkretin-Rezeptor-Agonist, der aus einem einzigen Peptid sowohl den Rezeptor des glukoseabhängigen insulinotropen Polypeptids (GIP) als auch den Glucagon-like-Peptide-1-Rezeptor (GLP-1) adressiert. In der publizierten Pharmakologie wurde es als fettsäuremodifiziertes Peptid für eine verlängerte Exposition konzipiert und auf seine kombinierte Wirkung auf Inkretin-Signalgebung, Glukosehandhabung und Körpergewicht in tierexperimentellen und klinischen Forschungsmodellen untersucht. Es wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Forschung an dualem Inkretin-Rezeptor-Agonisten (GIP + GLP-1)","Studien zu Signalwegen der glukoseabhängigen Insulin-Signalgebung","Forschung zu Körperzusammensetzung und Adipositas","Studien zu Stoffwechselregulation und Energiehomöostase","13 Formate (5mg bis 120mg) für dosisabgestufte Studiendesigns"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. GLP-2 (TZ) wird als lyophilisiertes Pulver geliefert. Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Welche Rezeptoren adressiert GLP-2 (TZ)?",answer:"GLP-2 (TZ) ist ein Dual-Agonist, der sowohl den GIP-Rezeptor (glukoseabhängiges insulinotropes Polypeptid) als auch den GLP-1-Rezeptor (Glucagon-like Peptide-1) adressiert, zwei Inkretin-Signalwege, die gemeinsam auf ihre kombinierte Wirkung auf Glukosehandhabung und Körpergewicht untersucht werden."},{question:"Wie lauten Molekulargewicht und Formel von GLP-2 (TZ)?",answer:"GLP-2 (TZ) hat die Summenformel C225H348N48O68 und ein Molekulargewicht von etwa 4813,5 g/mol (PubChem CID 166567236). Es ist auch unter dem Entwicklungscode LY3298176 bekannt."},{question:"Welche Reinheit hat GLP-2 (TZ) von Miro Biotech?",answer:"Jede Charge wird unabhängig von einem Drittlabor getestet und auf 99,27 % Reinheit verifiziert, mit einem Analysenzertifikat für die Charge."},{question:"Wie sollte GLP-2 (TZ) gelagert werden?",answer:"Das lyophilisierte Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["metabolisch","GIP","GLP-1","Inkretin","Dual-Agonist","Gewichtsreduktion","Forschungspeptid"],aka:["LY3298176","Dualer GIP/GLP-1-Rezeptor-Agonist","GIP/GLP-1-Co-Agonist"],whatIs:"GLP-2 (TZ) ist ein synthetischer dualer Inkretin-Rezeptor-Agonist, der aus einem einzigen Peptid sowohl den GIP- als auch den GLP-1-Rezeptor aktiviert. Es wird als Forschungssubstanz in Studien zu Inkretin-Signalgebung, Glukoseregulation und Körperzusammensetzung eingesetzt. Geliefert ausschließlich für die In-vitro- und Laborforschung.",mechanism:"In publizierter Forschung wurde GLP-2 (TZ) als fettsäuremodifiziertes Peptid charakterisiert, das den GIP- und den GLP-1-Rezeptor bindet und aktiviert, zwei Inkretin-Signalwege, die auf die glukoseabhängige Insulin-Signalgebung konvergieren. Die Pharmakologie im Entdeckungsstadium berichtete eine Dual-Agonisten-Aktivität an beiden Rezeptoren, und nachfolgende kontrollierte Studien beobachteten Veränderungen des Körpergewichts über die untersuchten Zeiträume. Entsprechende Langzeitmechanismen und Ergebnisse beim Menschen werden weiterhin untersucht.",receptorTargets:["GIP-Rezeptor","GLP-1-Rezeptor","Inkretin-Signalachse","Glukoseabhängige Insulinsekretion"],specs:[{label:"Klassifizierung",value:"Synthetisches dualer GIP/GLP-1-Rezeptor-Agonist-Peptid"},{label:"Entwicklungscode",value:"LY3298176"},{label:"Erscheinungsbild",value:"Weißes lyophilisiertes Pulver"},{label:"Löslichkeit",value:"Löslich in bakteriostatischem Wasser"}],researchApplications:[{title:"Inkretin-Rezeptorpharmakologie",description:"Eingesetzt zur Untersuchung der parallelen Signalgebung am GIP- und am GLP-1-Rezeptor aus einem einzigen Dual-Agonist-Peptid."},{title:"Glukosestoffwechsel",description:"Angewandt in der Forschung zur glukoseabhängigen Insulinsekretion und Stoffwechselregulation."},{title:"Körperzusammensetzung",description:"Untersucht in tierexperimentellen und klinischen Forschungsmodellen auf Effekte auf Körpergewicht und Adipositas."},{title:"Vergleichende Agonisten-Studien",description:"Erforscht neben Einzel-Inkretin-Agonisten, um duale mit Einzel-Signalweg-Aktivität zu vergleichen."}],keyStudies:[{title:"LY3298176, ein neuartiger dualer GIP- und GLP-1-Rezeptor-Agonist zur Behandlung von Typ-2-Diabetes mellitus: von der Entdeckung zum klinischen Proof of Concept",source:"Molecular Metabolism",year:2018,url:"https://pubmed.ncbi.nlm.nih.gov/30473097/",finding:"Berichtete die Entdeckung und pharmakologische Charakterisierung von LY3298176, einem fettsäuremodifizierten Peptid, das als Dual-Agonist am GIP- und GLP-1-Rezeptor konzipiert wurde."},{title:"SURMOUNT-1: Phase-3-Adipositas-Studie mit einmal wöchentlichem LY3298176",source:"New England Journal of Medicine",year:2022,url:"https://pubmed.ncbi.nlm.nih.gov/35658024/",finding:"In der randomisierten SURMOUNT-1-Studie wurde beobachtet, dass der einmal wöchentliche duale GIP/GLP-1-Agonist über 72 Wochen im Vergleich zu Placebo über die untersuchten Dosen hinweg erhebliche mittlere Körpergewichtsreduktionen erzeugte."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit weißem lyophilisiertem Pulver von GLP-2 (TZ) im gewählten Format. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich.",comparison:{heading:"GLP-2 (TZ) vs. Einzel-Inkretin-Agonisten in der Forschung",columns:["","GLP-2 (TZ)","GLP-1-Agonist","GIP-Agonist"],rows:[{label:"Rezeptorziel",values:["GIP + GLP-1","GLP-1-Rezeptor","GIP-Rezeptor"]},{label:"Klasse",values:["Dualer Inkretin-Agonist","Einzel-Inkretin-Agonist","Einzel-Inkretin-Agonist"]},{label:"Forschungsfokus",values:["Kombinierte Inkretin-Signalgebung","GLP-1-Signalweg","GIP-Signalweg"]},{label:"Adressierte Signalwege",values:["Zwei","Einer","Einer"]}]}},klow:{name:"KLOW Mischung",description:"Vier-Peptid-Forschungsmischung aus TB-500, BPC-157, GHK-Cu und KPV, co-lyophilisiert in einem einzigen 80mg-Vial für kombinierte Studien zu Gewebereparatur- und entzündungshemmenden Signalwegen.",longDescription:"Die KLOW Mischung kombiniert vier Forschungspeptide in einem 80mg-Vial: TB-500 (10mg), ein Thymosin-Beta-4-Fragment, untersucht für Zellmigration und Angiogenese; BPC-157 (10mg), ein stabiles gastrisches Pentadecapeptid, untersucht für Gewebereparatur; GHK-Cu (50mg), ein kupferbindendes Tripeptid, untersucht für Gewebeumbau; und KPV (10mg), ein Alpha-MSH-Tripeptid, untersucht für entzündungshemmende Aktivität. Die vier sind gepaart, um komplementäre regenerative und entzündliche Signalwege in einem einzigen Studiendesign zu untersuchen. Sie wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Vierkomponentige Gewebereparatur-Forschung in einem einzigen Vial","Kombinierte Studien zu Angiogenese- und Zellmigrations-Signalwegen","Forschung zu Wundheilung und Gewebeumbau","Studien zu entzündungshemmenden Signalwegen (KPV-Komponente)","Co-lyophilisierte Mischung für Studiendesigns mit kombinierten Signalwegen"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. Jedes 80mg-Vial enthält 10mg TB-500, 10mg BPC-157, 50mg GHK-Cu und 10mg KPV. Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist in der KLOW Mischung enthalten?",answer:"Jedes 80mg-Vial enthält 10mg TB-500, 10mg BPC-157, 50mg GHK-Cu und 10mg KPV, als einzelne Mischung co-lyophilisiert."},{question:"Warum werden diese vier Peptide zusammen untersucht?",answer:"Jede Komponente ist in der publizierten Forschung mit einem eigenen Reparatur- oder Entzündungssignalweg assoziiert. TB-500 und BPC-157 werden für Gewebereparatur untersucht, GHK-Cu für Gewebeumbau und KPV für entzündungshemmende Aktivität, sodass die Mischung eingesetzt wird, um diese komplementären Signalwege in einem einzigen Studiendesign zu untersuchen."},{question:"Wie sollte die Mischung gelagert werden?",answer:"Lyophilisiertes Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["Heilung","Gewebereparatur","entzündungshemmend","Regeneration","Mischung","Forschungspeptid"],aka:["KLOW Healing Blend","TB-500 / BPC-157 / GHK-Cu / KPV Mischung"],whatIs:"Die KLOW Mischung ist eine Forschungssubstanz, die vier Peptide (TB-500, BPC-157, GHK-Cu und KPV) co-lyophilisiert in einem 80mg-Vial kombiniert. Sie wird zur In-vitro-Untersuchung kombinierter Signalwege von Gewebereparatur, Gewebeumbau und Entzündungshemmung eingesetzt. Geliefert ausschließlich für die Laborforschung.",mechanism:"In publizierter Forschung adressiert jede Komponente einen eigenen Signalweg. Für Thymosin Beta-4 (den Ursprung von TB-500) wurde berichtet, dass es Zellmigration und Angiogenese unterstützt; BPC-157 wurde in Tiermodellen mit beschleunigter Gewebeheilung assoziiert; GHK-Cu wurde in der Gewebeumbau- und Wundreparatur-Forschung beschrieben; und für KPV wurde berichtet, dass es über den PepT1-Transporter Entzündungsmarker reduziert. Die Mischung wird darauf untersucht, wie diese Signalwege parallel wirken könnten; kombinierte Mechanismen und Ergebnisse beim Menschen sind nicht belegt.",receptorTargets:["Aktin-sequestrierende / Zellmigrations-Signalwege (TB-500)","Angiogenese- und Gewebereparatur-Signalwege (BPC-157)","Kupferabhängiger Gewebeumbau (GHK-Cu)","PepT1-Transporter und Entzündungssignalgebung (KPV)"],blendComposition:[{name:"TB-500",role:"Thymosin-β4-Fragment",amount:"10mg"},{name:"BPC-157",role:"Gastrisches Pentadecapeptid",amount:"10mg"},{name:"GHK-Cu",role:"Kupfer-Tripeptid",amount:"50mg"},{name:"KPV",role:"α-MSH-Tripeptid",amount:"10mg"}],specs:[{label:"Zusammensetzung",value:"10mg TB-500 + 10mg BPC-157 + 50mg GHK-Cu + 10mg KPV"},{label:"Gesamtmenge pro Vial",value:"80mg co-lyophilisierte Mischung"},{label:"Komponenten",value:"Vier Forschungspeptide"},{label:"Erscheinungsbild",value:"Weißes bis blassblaues lyophilisiertes Pulver (Kupfergehalt)"},{label:"Löslichkeit",value:"Löslich in bakteriostatischem Wasser"}],researchApplications:[{title:"Gewebereparatur",description:"Untersucht auf die kombinierten Effekte von TB-500 und BPC-157 auf Zellmigration und Wundheilung."},{title:"Gewebeumbau",description:"Eingesetzt in der Forschung zu GHK-Cu und kupferabhängigen Umbau-Signalwegen."},{title:"Entzündung",description:"Angewandt zur Untersuchung der entzündungshemmenden Aktivität, die mit der KPV-Komponente assoziiert ist."},{title:"Designs mit kombinierten Signalwegen",description:"Erforscht in Studiendesigns, die einzelne Peptide mit einer mehrkomponentigen Mischung vergleichen."}],keyStudies:[{title:"Stabiles gastrisches Pentadecapeptid BPC 157 und Wundheilung",source:"Frontiers in Pharmacology",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34267654/",finding:"Überprüfte präklinische Berichte, in denen BPC-157 mit beschleunigter Heilung über Haut-, Muskel-, Sehnen- und andere Gewebeverletzungsmodelle bei Tieren assoziiert wurde."},{title:"Tierstudien mit Thymosin Beta, einem multifunktionalen Peptid für Gewebereparatur und -regeneration",source:"Annals of the New York Academy of Sciences",year:2010,url:"https://pubmed.ncbi.nlm.nih.gov/20536453/",finding:"Fasste Tiermodellstudien zusammen, in denen berichtet wurde, dass Thymosin Beta-4 (der Ursprung von TB-500) Zellmigration, Angiogenese und Gewebereparatur unterstützt."},{title:"Das menschliche Tripeptid GHK und Gewebeumbau",source:"Journal of Biomaterials Science, Polymer Edition",year:2008,url:"https://pubmed.ncbi.nlm.nih.gov/18644225/",finding:"Überprüfte das kupferbindende Tripeptid GHK und seine berichteten Rollen in der Gewebeumbau- und Wundreparatur-Forschung."},{title:"PepT1-vermittelte Aufnahme des Tripeptids KPV reduziert intestinale Entzündung",source:"Gastroenterology",year:2008,url:"https://pubmed.ncbi.nlm.nih.gov/18061177/",finding:"Berichtete, dass das Tripeptid KPV über PepT1 aufgenommen wurde und Entzündungsmarker in Zell- und Mausmodellen reduzierte."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit 10mg TB-500, 10mg BPC-157, 50mg GHK-Cu und 10mg KPV als co-lyophilisiertes Pulver. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich.",comparison:{heading:"KLOW vs. die anderen Forschungsmischungen",columns:["","KLOW","GLOW","BPC-157 + TB-500"],rows:[{label:"Komponenten",values:["TB-500, BPC-157, GHK-Cu, KPV","TB-500, BPC-157, GHK-Cu","BPC-157, TB-500"]},{label:"Komponentenanzahl",values:["4","3","2"]},{label:"Gesamt pro Vial",values:["80mg","70mg","10mg / 20mg"]},{label:"Zusätzlicher Fokus",values:["Entzündungshemmend (KPV)","Umbau (GHK-Cu)","Fokussierte duale Reparatur"]}]}},glow:{name:"GLOW Mischung",description:"Drei-Peptid-Forschungsmischung aus TB-500, BPC-157 und GHK-Cu, co-lyophilisiert in einem einzigen 70mg-Vial für kombinierte Studien zu Gewebereparatur- und Umbau-Signalwegen.",longDescription:"Die GLOW Mischung kombiniert drei Forschungspeptide in einem 70mg-Vial: TB-500 (10mg), ein Thymosin-Beta-4-Fragment, untersucht für Zellmigration und Angiogenese; BPC-157 (10mg), ein stabiles gastrisches Pentadecapeptid, untersucht für Gewebereparatur; und GHK-Cu (50mg), ein kupferbindendes Tripeptid, untersucht für Gewebeumbau und Kollagenforschung. Die drei sind gepaart, um komplementäre Reparatur- und Umbau-Signalwege in einem einzigen Studiendesign zu untersuchen. Sie wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Dreikomponentige Gewebereparatur-Forschung in einem einzigen Vial","Kombinierte Studien zu Angiogenese- und Zellmigrations-Signalwegen","Forschung zu Gewebeumbau und Kollagen (GHK-Cu-Komponente)","Studien zu Wundheilungs-Signalwegen","Co-lyophilisierte Mischung für Studiendesigns mit kombinierten Signalwegen"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. Jedes 70mg-Vial enthält 10mg TB-500, 10mg BPC-157 und 50mg GHK-Cu. Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist in der GLOW Mischung enthalten?",answer:"Jedes 70mg-Vial enthält 10mg TB-500, 10mg BPC-157 und 50mg GHK-Cu, als einzelne Mischung co-lyophilisiert."},{question:"Wie unterscheidet sich GLOW von KLOW?",answer:"GLOW enthält drei Komponenten (TB-500, BPC-157, GHK-Cu), während KLOW eine vierte, KPV, für die Forschung zu entzündungshemmenden Signalwegen hinzufügt. GLOW konzentriert sich auf Gewebereparatur und -umbau."},{question:"Wie sollte die Mischung gelagert werden?",answer:"Lyophilisiertes Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["Heilung","Gewebereparatur","Gewebeumbau","Regeneration","Mischung","Forschungspeptid"],aka:["GLOW Healing Blend","TB-500 / BPC-157 / GHK-Cu Mischung"],whatIs:"Die GLOW Mischung ist eine Forschungssubstanz, die drei Peptide (TB-500, BPC-157 und GHK-Cu) co-lyophilisiert in einem 70mg-Vial kombiniert. Sie wird zur In-vitro-Untersuchung kombinierter Signalwege von Gewebereparatur und Gewebeumbau eingesetzt. Geliefert ausschließlich für die Laborforschung.",mechanism:"In publizierter Forschung wurde für Thymosin Beta-4 (den Ursprung von TB-500) berichtet, dass es Zellmigration und Angiogenese unterstützt, BPC-157 wurde in Tiermodellen mit beschleunigter Gewebeheilung assoziiert, und GHK-Cu wurde in der Gewebeumbau- und Wundreparatur-Forschung beschrieben. Die Mischung wird darauf untersucht, wie diese Reparatur- und Umbau-Signalwege parallel wirken könnten; kombinierte Mechanismen und Ergebnisse beim Menschen sind nicht belegt.",receptorTargets:["Aktin-sequestrierende / Zellmigrations-Signalwege (TB-500)","Angiogenese- und Gewebereparatur-Signalwege (BPC-157)","Kupferabhängiger Gewebeumbau (GHK-Cu)","Kollagen- und Matrixsynthese-Signalwege"],blendComposition:[{name:"TB-500",role:"Thymosin-β4-Fragment",amount:"10mg"},{name:"BPC-157",role:"Gastrisches Pentadecapeptid",amount:"10mg"},{name:"GHK-Cu",role:"Kupfer-Tripeptid",amount:"50mg"}],specs:[{label:"Zusammensetzung",value:"10mg TB-500 + 10mg BPC-157 + 50mg GHK-Cu"},{label:"Gesamtmenge pro Vial",value:"70mg co-lyophilisierte Mischung"},{label:"Komponenten",value:"Drei Forschungspeptide"},{label:"Erscheinungsbild",value:"Weißes bis blassblaues lyophilisiertes Pulver (Kupfergehalt)"},{label:"Löslichkeit",value:"Löslich in bakteriostatischem Wasser"}],researchApplications:[{title:"Gewebereparatur",description:"Untersucht auf die kombinierten Effekte von TB-500 und BPC-157 auf Zellmigration und Wundheilung."},{title:"Gewebeumbau",description:"Eingesetzt in der Forschung zu GHK-Cu, Kollagensynthese und kupferabhängigen Umbau-Signalwegen."},{title:"Angiogenese",description:"Angewandt zur Untersuchung der Blutgefäßbildungs-Signalwege, die mit den Komponenten assoziiert sind."},{title:"Designs mit kombinierten Signalwegen",description:"Erforscht in Studiendesigns, die einzelne Peptide mit einer mehrkomponentigen Mischung vergleichen."}],keyStudies:[{title:"Stabiles gastrisches Pentadecapeptid BPC 157 und Wundheilung",source:"Frontiers in Pharmacology",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34267654/",finding:"Überprüfte präklinische Berichte, in denen BPC-157 mit beschleunigter Heilung über Haut-, Muskel-, Sehnen- und andere Gewebeverletzungsmodelle bei Tieren assoziiert wurde."},{title:"Tierstudien mit Thymosin Beta, einem multifunktionalen Peptid für Gewebereparatur und -regeneration",source:"Annals of the New York Academy of Sciences",year:2010,url:"https://pubmed.ncbi.nlm.nih.gov/20536453/",finding:"Fasste Tiermodellstudien zusammen, in denen berichtet wurde, dass Thymosin Beta-4 (der Ursprung von TB-500) Zellmigration, Angiogenese und Gewebereparatur unterstützt."},{title:"Das menschliche Tripeptid GHK und Gewebeumbau",source:"Journal of Biomaterials Science, Polymer Edition",year:2008,url:"https://pubmed.ncbi.nlm.nih.gov/18644225/",finding:"Überprüfte das kupferbindende Tripeptid GHK und seine berichteten Rollen in der Gewebeumbau- und Wundreparatur-Forschung."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit 10mg TB-500, 10mg BPC-157 und 50mg GHK-Cu als co-lyophilisiertes Pulver. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich.",comparison:{heading:"GLOW vs. die anderen Forschungsmischungen",columns:["","GLOW","KLOW","BPC-157 + TB-500"],rows:[{label:"Komponenten",values:["TB-500, BPC-157, GHK-Cu","TB-500, BPC-157, GHK-Cu, KPV","BPC-157, TB-500"]},{label:"Komponentenanzahl",values:["3","4","2"]},{label:"Gesamt pro Vial",values:["70mg","80mg","10mg / 20mg"]},{label:"Zusätzlicher Fokus",values:["Umbau (GHK-Cu)","Entzündungshemmend (KPV)","Fokussierte duale Reparatur"]}]}},"bpc-157-tb-500":{name:"BPC-157 + TB-500 Mischung",description:"Dual-Peptid-Forschungsmischung aus BPC-157 und TB-500 im 50/50-Verhältnis, co-lyophilisiert für fokussierte Studien zu Gewebereparatur- und Regenerations-Signalwegen. Erhältlich in 10mg- und 20mg-Vials.",longDescription:"Diese Forschungsmischung paart BPC-157, ein stabiles gastrisches Pentadecapeptid, untersucht für Gewebereparatur, mit TB-500, einem Thymosin-Beta-4-Fragment, untersucht für Zellmigration und Angiogenese, in einem 50/50-Verhältnis pro Vial. Die beiden sind kombiniert, um eine fokussierte, duale Gewebereparatur über zwei Signalwege in einem einzigen Studiendesign zu untersuchen. Sie wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Fokussierte Gewebereparatur-Forschung über zwei Signalwege","Kombinierte Studien zu Angiogenese und Zellmigration","Forschung zu Wundheilungs- und Sehnenreparatur-Signalwegen","Zwei Komponenten in einem einzigen co-lyophilisierten Vial","50/50-Verhältnis für ausgewogene Designs mit kombinierten Signalwegen"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. Jedes Vial enthält BPC-157 und TB-500 im 50/50-Verhältnis (5mg + 5mg pro 10mg-Vial). Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist in der BPC-157 + TB-500 Mischung enthalten?",answer:"Jedes Vial enthält BPC-157 und TB-500 im 50/50-Verhältnis. Das 10mg-Vial enthält 5mg jeder Substanz und das 20mg-Vial 10mg jeder Substanz, als einzelne Mischung co-lyophilisiert."},{question:"Warum werden BPC-157 und TB-500 zusammen untersucht?",answer:"BPC-157 wird für Gewebereparatur untersucht und TB-500 für Zellmigration und Angiogenese. Da sie mit komplementären Reparatur-Signalwegen assoziiert sind, untersuchen Forschende das Paar, um eine fokussierte, duale Gewebereparatur über zwei Signalwege zu erforschen."},{question:"Wie sollte die Mischung gelagert werden?",answer:"Lyophilisiertes Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["Heilung","Gewebereparatur","Regeneration","Mischung","Forschungspeptid"],aka:["BPC-157 / TB-500 Mischung","BPC + TB Healing Blend"],whatIs:"Die BPC-157 + TB-500 Mischung ist eine Forschungssubstanz, die zwei Gewebereparatur-Peptide im 50/50-Verhältnis pro Vial paart. Sie wird zur In-vitro-Untersuchung fokussierter, dualer Gewebereparatur über zwei Signalwege eingesetzt. Geliefert ausschließlich für die Laborforschung.",mechanism:"In publizierter Forschung wurde BPC-157 mit beschleunigter Gewebeheilung über tierische Verletzungsmodelle hinweg assoziiert, während für Thymosin Beta-4 (den Ursprung von TB-500) berichtet wurde, dass es Zellmigration, Angiogenese und Gewebereparatur unterstützt. Die Mischung wird darauf untersucht, wie diese beiden Reparatur-Signalwege zusammenwirken könnten; kombinierte Mechanismen und Ergebnisse beim Menschen sind nicht belegt.",receptorTargets:["Angiogenese- und Gewebereparatur-Signalwege (BPC-157)","Aktin-sequestrierende / Zellmigrations-Signalwege (TB-500)","Wundheilungs-Signalgebung","Sehnen- und Muskelreparatur-Signalwege"],blendComposition:[{name:"BPC-157",role:"Gastrisches Pentadecapeptid",amount:"50%"},{name:"TB-500",role:"Thymosin-β4-Fragment",amount:"50%"}],specs:[{label:"Zusammensetzung",value:"BPC-157 + TB-500 (50/50-Verhältnis)"},{label:"Menge pro Vial",value:"5mg + 5mg (10mg) oder 10mg + 10mg (20mg)"},{label:"Komponenten",value:"Zwei Forschungspeptide"},{label:"Erscheinungsbild",value:"Weißes lyophilisiertes Pulver"},{label:"Löslichkeit",value:"Löslich in bakteriostatischem Wasser"}],researchApplications:[{title:"Gewebereparatur",description:"Untersucht auf die kombinierte Wirkung von BPC-157 und TB-500 auf Wundheilung und Regeneration."},{title:"Zellmigration",description:"Eingesetzt in der Forschung zu den aktin-sequestrierenden und Zellmigrations-Signalwegen, die mit TB-500 assoziiert sind."},{title:"Angiogenese",description:"Angewandt zur Untersuchung der Blutgefäßbildungs-Signalwege, die mit beiden Komponenten assoziiert sind."},{title:"Designs mit kombinierten Signalwegen",description:"Erforscht in Studiendesigns, die einzelne Peptide mit einer ausgewogenen dualen Mischung vergleichen."}],keyStudies:[{title:"Stabiles gastrisches Pentadecapeptid BPC 157 und Wundheilung",source:"Frontiers in Pharmacology",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34267654/",finding:"Überprüfte präklinische Berichte, in denen BPC-157 mit beschleunigter Heilung über Haut-, Muskel-, Sehnen- und andere Gewebeverletzungsmodelle bei Tieren assoziiert wurde."},{title:"Tierstudien mit Thymosin Beta, einem multifunktionalen Peptid für Gewebereparatur und -regeneration",source:"Annals of the New York Academy of Sciences",year:2010,url:"https://pubmed.ncbi.nlm.nih.gov/20536453/",finding:"Fasste Tiermodellstudien zusammen, in denen berichtet wurde, dass Thymosin Beta-4 (der Ursprung von TB-500) Zellmigration, Angiogenese und Gewebereparatur unterstützt."},{title:"Thymosin Beta4: ein multifunktionales regeneratives Peptid. Grundlegende Eigenschaften und klinische Anwendungen",source:"Expert Opinion on Biological Therapy",year:2012,url:"https://pubmed.ncbi.nlm.nih.gov/22074294/",finding:"Überprüfte die biochemischen Eigenschaften und Mechanismen von Thymosin Beta-4 als aktin-sequestrierendes, geweberegeneratives Peptid, das der Wundreparatur-Forschung zugrunde liegt."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit BPC-157 und TB-500 im 50/50-Verhältnis als co-lyophilisiertes weißes Pulver. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich.",comparison:{heading:"BPC-157 + TB-500 vs. die größeren Forschungsmischungen",columns:["","BPC-157 + TB-500","GLOW","KLOW"],rows:[{label:"Komponenten",values:["BPC-157, TB-500","TB-500, BPC-157, GHK-Cu","TB-500, BPC-157, GHK-Cu, KPV"]},{label:"Komponentenanzahl",values:["2","3","4"]},{label:"Gesamt pro Vial",values:["10mg / 20mg","70mg","80mg"]},{label:"Forschungsfokus",values:["Fokussierte duale Reparatur","Reparatur + Umbau","Reparatur + Umbau + entzündungshemmend"]}]}},kpv:{name:"KPV",description:"Entzündungshemmendes Tripeptid (Lys-Pro-Val), das C-terminale Fragment von Alpha-MSH, geliefert als lyophilisierter Referenzstandard für die Forschung zu Immunmodulation und Darmentzündung.",longDescription:"KPV ist ein Tripeptid (Lys-Pro-Val), das dem C-terminalen Fragment des Alpha-Melanozyten-stimulierenden Hormons (Alpha-MSH) entspricht. Es wurde auf entzündungshemmende Aktivität untersucht, einschließlich der Aufnahme über den PepT1-Transporter und der Effekte auf Entzündungsmarker in Zell- und Tier-Colitis-Modellen. Es wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Forschung zu entzündungshemmenden Signalwegen","Studien zur Immunmodulation","Forschung zu Darm- und intestinaler Entzündung","Studien zur Aufnahme über den PepT1-Transporter","Forschung zum C-terminalen Fragment von Alpha-MSH"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. KPV wird als lyophilisiertes Pulver geliefert. Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist KPV?",answer:"KPV ist ein Tripeptid (Lys-Pro-Val), das dem C-terminalen Fragment (11-13) des Alpha-Melanozyten-stimulierenden Hormons (Alpha-MSH) entspricht und auf entzündungshemmende Aktivität untersucht wird."},{question:"Wie lauten Molekulargewicht und Formel von KPV?",answer:"KPV hat die Summenformel C16H30N4O4 und ein Molekulargewicht von etwa 342,43 g/mol (PubChem CID 125672). Seine Sequenz ist Lys-Pro-Val."},{question:"Welche Reinheit hat KPV von Miro Biotech?",answer:"Jede Charge wird unabhängig von einem Drittlabor getestet und auf 99,41 % Reinheit verifiziert, mit einem Analysenzertifikat für die Charge."},{question:"Wie sollte KPV gelagert werden?",answer:"Das lyophilisierte Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["entzündungshemmend","Immun","Darmgesundheit","Tripeptid","Forschungspeptid"],aka:["Lys-Pro-Val","Alpha-MSH (11-13)","KPV-Tripeptid"],whatIs:"KPV ist ein Tripeptid (Lys-Pro-Val), das C-terminale Fragment von Alpha-MSH, eingesetzt als Forschungssubstanz in Studien zu entzündungshemmenden und immunmodulatorischen Signalwegen. Geliefert ausschließlich für die In-vitro- und Laborforschung.",mechanism:"In publizierter Forschung wurde berichtet, dass KPV über den PepT1-Transporter in intestinale Epithel- und Immunzellen aufgenommen wird und in diesem Setting Entzündungsmarker in Zell- und Maus-Colitis-Modellen reduziert. Weitere Forschung beschrieb ein entzündungshemmendes Profil, das sich von dem der zentralen Melanocortin-Peptide unterscheiden lässt. Diese Signalwege werden in Modellen der intestinalen und immunologischen Entzündung untersucht; entsprechende Mechanismen beim Menschen sind nicht belegt.",receptorTargets:["PepT1-Peptidtransporter","NF-kB-Entzündungssignalgebung","Melanocortin-Signalweg (Alpha-MSH-Fragment)","Intestinale Epithel- und Immunzellen"],specs:[{label:"Sequenz",value:"Lys-Pro-Val (KPV)"},{label:"Klassifizierung",value:"Tripeptid, C-terminales Fragment von Alpha-MSH"},{label:"Erscheinungsbild",value:"Weißes lyophilisiertes Pulver"},{label:"Löslichkeit",value:"Löslich in bakteriostatischem Wasser"}],researchApplications:[{title:"Intestinale Entzündung",description:"Eingesetzt in der Forschung zu Entzündungsmarkern in Zell- und Tier-Colitis-Modellen."},{title:"Immunmodulation",description:"Untersucht auf entzündungshemmende Aktivität als C-terminales Fragment von Alpha-MSH."},{title:"Transporteraufnahme",description:"Angewandt zur Untersuchung der PepT1-vermittelten Aufnahme in Epithel- und Immunzellen."},{title:"Melanocortin-Pharmakologie",description:"Erforscht neben den zentralen Melanocortin-Peptiden, um entzündungshemmende Profile zu vergleichen."}],keyStudies:[{title:"PepT1-vermittelte Aufnahme des Tripeptids KPV reduziert intestinale Entzündung",source:"Gastroenterology",year:2008,url:"https://pubmed.ncbi.nlm.nih.gov/18061177/",finding:"Berichtete, dass KPV über den PepT1-Transporter in intestinale Epithel- und Immunzellen aufgenommen wurde und in diesem Setting Entzündungsmarker in Zell- und Maus-Colitis-Modellen reduzierte."},{title:"Aufschlüsselung der entzündungshemmenden Wirkung der zentralen und C-terminalen (KPV) Alpha-Melanozyten-stimulierenden Hormon-Peptide",source:"Journal of Pharmacology and Experimental Therapeutics",year:2003,url:"https://pubmed.ncbi.nlm.nih.gov/12750433/",finding:"Beobachtete, dass das C-terminale Alpha-MSH-Tripeptid KPV in den untersuchten Modellen ein entzündungshemmendes Profil aufwies, das sich von dem der zentralen Melanocortin-Peptide unterscheiden ließ."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit weißem lyophilisiertem KPV-Pulver. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich."},glutathione:{name:"Glutathion",description:"Master-Antioxidans-Tripeptid (gamma-Glu-Cys-Gly), geliefert als lyophilisierter Referenzstandard für die Forschung zu oxidativem Stress, Redox-Biologie und Entgiftung. Erhältlich in 600mg- und 1500mg-Vials.",longDescription:"Glutathion (GSH) ist ein Tripeptid aus Glutamat, Cystein und Glycin und eines der primären nicht-enzymatischen Antioxidantien in lebenden Zellen. Es wurde umfassend auf seine Rolle bei der Redox-Homöostase, dem GSH/GSSG-Paar, der Entgiftung und der Redox-Signalgebung untersucht. Es wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Forschung zu zellulären Antioxidantien und Redox","Studien zu Signalwegen des oxidativen Stresses","Forschung zum GSH/GSSG-Redox-Paar","Studien zu Entgiftungs-Signalwegen","Forschung zur Redox-Signalgebung"],researchGuide:"Glutathion ist wasserlöslich und kann in sterilem Wasser oder Puffer rekonstituiert werden. Es ist licht- und sauerstoffempfindlich, daher mit Vorsicht handhaben und den Luftkontakt minimieren. Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung gekühlt aufbewahren sowie zeitnah verwenden.",faq:[{question:"Was ist Glutathion?",answer:"Glutathion (GSH) ist ein Tripeptid aus Glutamat, Cystein und Glycin (gamma-Glu-Cys-Gly), untersucht als eines der primären nicht-enzymatischen zellulären Antioxidantien und als zentraler Bestandteil des GSH/GSSG-Redox-Paars."},{question:"Wie lauten Molekulargewicht und Formel von Glutathion?",answer:"Glutathion hat die Summenformel C10H17N3O6S und ein Molekulargewicht von etwa 307,32 g/mol (PubChem CID 124886)."},{question:"Welche Reinheit hat Glutathion von Miro Biotech?",answer:"Jede Charge wird unabhängig von einem Drittlabor getestet und auf 99,69 % Reinheit verifiziert, mit einem Analysenzertifikat für die Charge."},{question:"Wie sollte Glutathion gelagert werden?",answer:"Das lyophilisierte Pulver vor Licht geschützt bei -20 °C lagern. Da es sauerstoffempfindlich ist, sollten rekonstituierte Lösungen zeitnah verwendet und gekühlt aufbewahrt werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["Anti-Aging","Antioxidans","Redox","Entgiftung","Tripeptid","Forschungspeptid"],aka:["GSH","gamma-Glu-Cys-Gly","reduziertes Glutathion"],whatIs:"Glutathion (GSH) ist ein Tripeptid aus Glutamat, Cystein und Glycin, eingesetzt als Forschungssubstanz in Studien zur zellulären Antioxidansaktivität, Redox-Homöostase und Entgiftung. Geliefert ausschließlich für die In-vitro- und Laborforschung.",mechanism:"In publizierter Forschung wurde reduziertes Glutathion (GSH) als essenzielles nicht-enzymatisches zelluläres Antioxidans beschrieben, zentral für die Redox-Homöostase durch das GSH/GSSG-Paar, Entgiftungsreaktionen und die Redox-Signalgebung. Diese Signalwege werden in Modellen des oxidativen Stresses untersucht; entsprechende Mechanismen beim Menschen werden in laufender Redox-Biologie-Forschung untersucht.",receptorTargets:["GSH/GSSG-Redox-Paar","Signalwege von Glutathionperoxidase und -reduktase","Zelluläre Entgiftungs-(Konjugations-)Signalwege","Redox-Signalgebung"],specs:[{label:"Zusammensetzung",value:"Tripeptid (gamma-Glu-Cys-Gly)"},{label:"Klassifizierung",value:"Nicht-enzymatisches zelluläres Antioxidans"},{label:"Erscheinungsbild",value:"Weißes lyophilisiertes Pulver"},{label:"Löslichkeit",value:"Löslich in Wasser und Puffer"}],researchApplications:[{title:"Oxidativer Stress",description:"Eingesetzt in der Forschung zur zellulären Antioxidanskapazität und zu Modellen des oxidativen Stresses."},{title:"Redox-Biologie",description:"Untersucht als zentraler Bestandteil des GSH/GSSG-Redox-Paars."},{title:"Entgiftung",description:"Angewandt zur Untersuchung von Konjugations- und Entgiftungs-Signalwegen."},{title:"Redox-Signalgebung",description:"Erforscht in der Forschung zur redoxabhängigen Zellsignalgebung."}],keyStudies:[{title:"Das Antioxidans Glutathion",source:"Vitamins and Hormones",year:2023,url:"https://pubmed.ncbi.nlm.nih.gov/36707132/",finding:"Überprüfte reduziertes Glutathion (GSH) als essenzielles nicht-enzymatisches zelluläres Antioxidans und beschrieb seine Rolle in der Redox-Homöostase, dem GSH/GSSG-Paar, der Entgiftung und der Redox-Signalgebung."},{title:"Glutathion-Synthese",source:"Biochimica et Biophysica Acta",year:2013,url:"https://pubmed.ncbi.nlm.nih.gov/22995213/",finding:"Überprüfte die zweistufige zytosolische Biosynthese von Glutathion durch Glutamat-Cystein-Ligase und GSH-Synthetase und beschrieb, wie dieser Signalweg berichtetermaßen streng reguliert und in Krankheitszuständen dysreguliert ist."},{title:"Glutathion, Stressreaktionen und Redox-Signalgebung bei Lungenentzündung",source:"Antioxidants & Redox Signaling",year:2005,url:"https://pubmed.ncbi.nlm.nih.gov/15650395/",finding:"Überprüfte, wie Verschiebungen im intrazellulären GSH/GSSG-Verhältnis berichtetermaßen redox-sensitive Signalwege und cystein-basierte Redox-Chemie im Kontext der Lungenentzündung beeinflussen."}],reconstitution:"Typischerweise mit sterilem Wasser oder Puffer für die Laborverwendung rekonstituiert. Da Glutathion sauerstoffempfindlich ist, den Luftkontakt minimieren, das Verdünnungsmittel sanft zugeben und die rekonstituierte Lösung gekühlt aufbewahren sowie innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt aufbewahren und zeitnah verwenden.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit weißem lyophilisiertem Glutathion-Pulver im gewählten Format. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich."},epithalon:{name:"Epithalon",description:"Synthetisches pineales Tetrapeptid (Ala-Glu-Asp-Gly), auch Epitalon geschrieben, geliefert als lyophilisierter Referenzstandard für die Forschung zu Telomerase, pinealem Melatonin und zellulärer Alterung. Erhältlich in 10mg- und 50mg-Vials.",longDescription:"Epithalon (Epitalon, AEDG-Peptid) ist ein synthetisches Tetrapeptid mit der Sequenz Ala-Glu-Asp-Gly, das von der Khavinson-Gruppe aus der Aminosäurezusammensetzung des bovinen Zirbeldrüsenextrakts Epithalamin entwickelt wurde. Es wurde auf Telomerase-Aktivierung und Telomerverlängerung in humanen somatischen Zellkulturen, auf pineale Melatoninrhythmen bei gealterten Primaten und auf neurogene Genexpression in Stammzellmodellen untersucht. Es wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Forschung zu Telomerase und Telomerlänge","Studien zur Zirbeldrüse und zu Melatoninrhythmen","Modelle zu zellulärer Seneszenz und Langlebigkeit","Forschung zu neurogener Genexpression","Studien zu antioxidativen Signalwegen und oxidativem Stress"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. Epithalon wird als lyophilisiertes Pulver geliefert. Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist Epithalon?",answer:"Epithalon (auch Epitalon geschrieben) ist ein synthetisches Tetrapeptid, Ala-Glu-Asp-Gly, das nach der Aminosäurezusammensetzung des Zirbeldrüsenextrakts Epithalamin entworfen wurde. Es wird in Forschungsmodellen zu Telomerase, pinealem Melatonin und zellulärer Alterung untersucht."},{question:"Ist Epithalon dasselbe wie Epitalon?",answer:"Ja. Epithalon, Epitalon und Epithalone sind alternative Schreibweisen desselben AEDG-Tetrapeptids (PubChem CID 219042, CAS 307297-39-8). Epithalamin ist der ältere bovine Zirbeldrüsenextrakt, nach dem es modelliert wurde, und damit ein anderes Material."},{question:"Wie lauten Molekulargewicht und Formel von Epithalon?",answer:"Epithalon hat die Summenformel C14H22N4O9 und ein Molekulargewicht von etwa 390,35 g/mol (PubChem CID 219042). Seine Sequenz ist Ala-Glu-Asp-Gly."},{question:"Welche Reinheit hat Epithalon von Miro Biotech?",answer:"Jede Charge wird unabhängig von einem Drittlabor getestet und auf 99,52 % Reinheit verifiziert, mit einem Analysenzertifikat für die Charge."},{question:"Wie sollte Epithalon gelagert werden?",answer:"Das lyophilisierte Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["Telomerase","pineal","Langlebigkeit","Tetrapeptid","Bioregulator","Forschungspeptid"],aka:["Epitalon","Epithalone","AEDG-Peptid","Ala-Glu-Asp-Gly"],whatIs:"Epithalon (Epitalon) ist ein synthetisches Tetrapeptid, Ala-Glu-Asp-Gly, abgeleitet aus der Aminosäurezusammensetzung des Zirbeldrüsenextrakts Epithalamin. Es wird als Forschungssubstanz in Studien zu Telomerase-Aktivität, pinealen Melatoninrhythmen und Signalwegen der zellulären Alterung eingesetzt. Geliefert ausschließlich für die In-vitro- und Laborforschung.",mechanism:"In publizierter Forschung wurde berichtet, dass Epithalon in telomerase-negativen humanen fetalen Fibroblastenkulturen die Expression der katalytischen Telomerase-Untereinheit, die enzymatische Telomerase-Aktivität und eine Telomerverlängerung induzierte. Separate Arbeiten an gealterten Rhesusaffen berichteten eine wiederhergestellte nächtliche Melatoninausschüttung der Zirbeldrüse, und eine Stammzellstudie berichtete eine erhöhte Expression neurogener Differenzierungsmarker, wobei molekulare Modellierung eine Bindung an Histon-H1-Stellen als möglichen epigenetischen Mechanismus nahelegte. Diese Signalwege werden in Zell- und Tiermodellen untersucht; entsprechende Mechanismen beim Menschen sind nicht belegt.",receptorTargets:["Expression der katalytischen Telomerase-Untereinheit (TERT)","Pineale Melatoninsynthese","Histon-H1-Bindung (vorgeschlagener epigenetischer Mechanismus)","Neurogene Differenzierungsmarker (Nestin, GAP43)"],specs:[{label:"Sequenz",value:"Ala-Glu-Asp-Gly (AEDG)"},{label:"Klassifizierung",value:"Synthetischer pinealer Tetrapeptid-Bioregulator"},{label:"Erscheinungsbild",value:"Weißes lyophilisiertes Pulver"},{label:"Löslichkeit",value:"Löslich in bakteriostatischem Wasser"}],researchApplications:[{title:"Telomerase-Biologie",description:"Eingesetzt in der Forschung zu Telomerase-Aktivierung und Telomerlänge in humanen somatischen Zellkulturen."},{title:"Pineale und zirkadiane Forschung",description:"Untersucht auf Effekte auf pineale Melatoninrhythmen in gealterten Primatenmodellen."},{title:"Zelluläre Alterung",description:"Angewandt in Studien zu Lebensspanne, Alterungsbiomarkern und oxidativem Stress in Nagetiermodellen."},{title:"Epigenetische Regulation",description:"Erforscht auf Histonbindung und Effekte auf die neurogene Genexpression in Stammzellkulturen."}],keyStudies:[{title:"Das Peptid Epithalon induziert Telomerase-Aktivität und Telomerverlängerung in humanen somatischen Zellen",source:"Bulletin of Experimental Biology and Medicine",year:2003,url:"https://pubmed.ncbi.nlm.nih.gov/12937682/",finding:"Berichtete, dass die Zugabe von Epithalon zu telomerase-negativen humanen fetalen Fibroblastenkulturen die Expression der katalytischen Telomerase-Untereinheit, die enzymatische Telomerase-Aktivität und eine Telomerverlängerung induzierte."},{title:"Wirkung von Epitalon auf Alterungsbiomarker, Lebensspanne und spontane Tumorinzidenz bei weiblichen SHR-Mäusen mit Swiss-Abstammung",source:"Biogerontology",year:2003,url:"https://pubmed.ncbi.nlm.nih.gov/14501183/",finding:"Berichtete, dass Epitalon bei weiblichen SHR-Mäusen die Lebensspanne der letzten 10 % der Überlebenden verlängerte, Chromosomenaberrationen im Knochenmark reduzierte und die Leukämieinzidenz senkte, ohne die mittlere Lebensspanne zu verändern."},{title:"AEDG-Peptid (Epitalon) stimuliert Genexpression und Proteinsynthese während der Neurogenese: möglicher epigenetischer Mechanismus",source:"Molecules",year:2020,url:"https://pubmed.ncbi.nlm.nih.gov/32019204/",finding:"Berichtete, dass AEDG neurogene Differenzierungsmarker in humanen gingivalen mesenchymalen Stammzellen erhöhte und in der molekularen Modellierung bevorzugt an Histon-H1-Stellen band, was als epigenetischer Mechanismus vorgeschlagen wurde."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit weißem lyophilisiertem Epithalon-Pulver im gewählten Format. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich."},"ss-31":{name:"SS-31",description:"Mitochondrien-gerichtetes Tetrapeptid (Elamipretid, D-Arg-Dmt-Lys-Phe-NH2), geliefert als lyophilisierter Referenzstandard für die Forschung zu Cardiolipin, mitochondrialer Bioenergetik und Zellenergie. Erhältlich in 10mg- und 50mg-Vials.",longDescription:"SS-31 (Elamipretid, MTP-131, Bendavia) ist ein aromatisch-kationisches Tetrapeptid, D-Arg-Dmt-Lys-Phe-NH2, aus der Szeto-Schiller-Serie. Es wurde auf die selektive Bindung an Cardiolipin in der inneren Mitochondrienmembran, auf Effekte auf den Cytochrom-c-Elektronentransport und die ATP-Synthese in isolierten Mitochondrien sowie in der klinischen Forschung zu mitochondrialen Cardiolipin-Störungen untersucht. Es wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Forschung zu Cardiolipin und innerer Mitochondrienmembran","Studien zu mitochondrialer Bioenergetik und ATP","Forschung zum Cytochrom-c-Elektronentransport","Modelle zu oxidativem Stress und Ischämie","Forschung zu Zellenergie und Alterung"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. SS-31 wird als lyophilisiertes Pulver geliefert. Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist SS-31?",answer:"SS-31 (Elamipretid) ist ein Mitochondrien-gerichtetes aromatisch-kationisches Tetrapeptid, D-Arg-Dmt-Lys-Phe-NH2, das auf seine Interaktion mit Cardiolipin in der inneren Mitochondrienmembran und seine Effekte auf den mitochondrialen Elektronentransport untersucht wird."},{question:"Wie lauten Molekulargewicht und Formel von SS-31?",answer:"SS-31 hat die Summenformel C32H49N9O5 und ein Molekulargewicht von etwa 639,8 g/mol (PubChem CID 11764719, CAS 736992-21-5). Dmt ist 2,6-Dimethyl-L-Tyrosin."},{question:"Wie verhält sich SS-31 zu Elamipretid?",answer:"SS-31 ist die Forschungsbezeichnung für Elamipretid (auch MTP-131 und Bendavia). Publizierte Forschung zu Elamipretid beschreibt die Cardiolipin-Bindung in der inneren Mitochondrienmembran; dieses Produkt ist ein Forschungs-Referenzstandard und keine pharmazeutische Formulierung."},{question:"Welche Reinheit hat SS-31 von Miro Biotech?",answer:"Jede Charge wird unabhängig von einem Drittlabor getestet und auf 99,38 % Reinheit verifiziert, mit einem Analysenzertifikat für die Charge."},{question:"Wie sollte SS-31 gelagert werden?",answer:"Das lyophilisierte Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["Mitochondrien","Cardiolipin","Bioenergetik","Tetrapeptid","Langlebigkeit","Forschungspeptid"],aka:["Elamipretid","MTP-131","Bendavia","Szeto-Schiller-Peptid 31","D-Arg-Dmt-Lys-Phe-NH2"],whatIs:"SS-31 (Elamipretid) ist ein synthetisches aromatisch-kationisches Tetrapeptid, D-Arg-Dmt-Lys-Phe-NH2, das sich in der inneren Mitochondrienmembran anreichert. Es wird als Forschungssubstanz in Studien zu Cardiolipin, Cytochrom-c-Elektronentransport und mitochondrialer ATP-Synthese eingesetzt. Geliefert ausschließlich für die In-vitro- und Laborforschung.",mechanism:"In publizierter Forschung wurde berichtet, dass SS-31 Cardiolipin in der inneren Mitochondrienmembran mit hoher Affinität bindet und dass der SS-31-Cardiolipin-Komplex die Peroxidase-Aktivität von Cytochrom c hemmte und in einem renalen Ischämiemodell der Ratte die Cristae-Struktur schützte. Arbeiten in Liposomen-, Bicellen- und Isolierte-Mitochondrien-Systemen berichteten, dass das Peptid nur mit cardiolipinhaltigen Membranen interagiert, die Elektronenträgerfunktion von Cytochrom c wiederherstellt und die State-3-Atmung erhöht. Klinische Forschung zu Elamipretid beim Barth-Syndrom und bei primärer mitochondrialer Myopathie wurde ebenfalls publiziert. Diese Mechanismen sind in Zell-, Membran- und Tiermodellen charakterisiert.",receptorTargets:["Cardiolipin (innere Mitochondrienmembran)","Cytochrom-c/Cardiolipin-Komplex","Elektronentransportkette und ATP-Synthese","Mitochondriale Cristae-Struktur"],specs:[{label:"Sequenz",value:"D-Arg-Dmt-Lys-Phe-NH2 (Dmt = 2,6-Dimethyl-L-Tyrosin)"},{label:"Klassifizierung",value:"Aromatisch-kationisches Mitochondrien-gerichtetes Tetrapeptid"},{label:"Erscheinungsbild",value:"Weißes lyophilisiertes Pulver"},{label:"Löslichkeit",value:"Löslich in bakteriostatischem Wasser"}],researchApplications:[{title:"Mitochondriale Bioenergetik",description:"Eingesetzt in der Forschung zu Elektronentransport, State-3-Atmung und ATP-Synthese in isolierten Mitochondrien."},{title:"Cardiolipin-Biologie",description:"Untersucht auf Membraninteraktion und Hemmung der Cytochrom-c-Peroxidase-Aktivität in cardiolipinhaltigen Systemen."},{title:"Ischämie und oxidativer Stress",description:"Angewandt in Ischämie-Reperfusions-Modellen zur Untersuchung von Cristae-Schutz und ATP-Erholung."},{title:"Forschung zu mitochondrialen Erkrankungen",description:"Erforscht in der klinischen Forschung zu Störungen des Cardiolipin-Stoffwechsels und mitochondrialer Myopathie."}],keyStudies:[{title:"Die Mitochondrien-gerichtete Verbindung SS-31 re-energetisiert ischämische Mitochondrien durch Interaktion mit Cardiolipin",source:"Journal of the American Society of Nephrology",year:2013,url:"https://pubmed.ncbi.nlm.nih.gov/23813215/",finding:"Berichtete, dass SS-31 Cardiolipin mit hoher Affinität bindet, dass der Komplex die Peroxidase-Aktivität von Cytochrom c hemmt und dass eine Vorbehandlung in einem renalen Ischämiemodell der Ratte die Cristae-Membranen schützte und die ATP-Erholung bei Reperfusion beschleunigte."},{title:"Targeting von mitochondrialem Cardiolipin und dem Cytochrom-c/Cardiolipin-Komplex zur Förderung des Elektronentransports und Optimierung der mitochondrialen ATP-Synthese",source:"British Journal of Pharmacology",year:2014,url:"https://pubmed.ncbi.nlm.nih.gov/24134698/",finding:"Berichtete in Liposomen-, Bicellen- und Isolierte-Mitochondrien-Experimenten, dass SS-31 nur mit cardiolipinhaltigen Membranen interagiert, die Elektronenträgerfunktion von Cytochrom c wiederherstellt und die State-3-Atmung erhöht."},{title:"Eine randomisierte klinische Phase-2/3-Studie mit anschließender offener Verlängerungsphase zur Bewertung der Wirksamkeit von Elamipretid beim Barth-Syndrom",source:"Genetics in Medicine",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/33077895/",finding:"Berichtete, dass in der TAZPOWER-Crossover-Studie die randomisierte Phase ihre primären Endpunkte nicht erreichte, während die 36-wöchige offene Verlängerungsphase Verbesserungen der 6-Minuten-Gehstrecke und der Symptomscores verzeichnete."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit weißem lyophilisiertem SS-31-Pulver im gewählten Format. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich."},vesugen:{name:"Vesugen",description:"Vaskulärer Tripeptid-Bioregulator (Lys-Glu-Asp, KED-Peptid), geliefert als lyophilisierter Referenzstandard für die Forschung zu Endothel, vaskulärer Alterung und Genexpression.",longDescription:"Vesugen (KED-Peptid) ist ein synthetisches Tripeptid mit der Sequenz Lys-Glu-Asp, einer der von der Khavinson-Gruppe entwickelten kurzen Peptid-Bioregulatoren. Es wurde in vaskulären Endothelzellkulturen auf Effekte auf die Expression von Endothelin-1, Connexin und Sirtuin-1, auf Proliferationsmarker in alterndem Endothel und auf neurogenesebezogene Genexpression untersucht. Es wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Forschung zum vaskulären Endothel","Studien zur Expression von Endothelin-1 und Connexin","Forschung zum Sirtuin-1-Signalweg","Modelle zu endothelialer Proliferation und Alterung","Studien zur Genexpression in der Neurogenese"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. Vesugen wird als lyophilisiertes Pulver geliefert. Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist Vesugen?",answer:"Vesugen ist ein synthetisches Tripeptid, Lys-Glu-Asp (KED), aus der Khavinson-Serie kurzer Peptid-Bioregulatoren. Es wird in vaskulären Endothelzellmodellen auf Effekte auf die Expression von Endothelin-1, Connexin, Sirtuin-1 und Proliferationsmarkern untersucht."},{question:"Wie lauten Molekulargewicht und Formel von Vesugen?",answer:"Vesugen hat die Summenformel C15H26N4O8 und ein Molekulargewicht von etwa 390,39 g/mol (PubChem CID 87571363). Seine Sequenz ist Lys-Glu-Asp."},{question:"Welche Reinheit hat Vesugen von Miro Biotech?",answer:"Jede Charge wird unabhängig von einem Drittlabor getestet und auf 99,61 % Reinheit verifiziert, mit einem Analysenzertifikat für die Charge."},{question:"Wie sollte Vesugen gelagert werden?",answer:"Das lyophilisierte Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["vaskulär","Endothel","Bioregulator","Tripeptid","Langlebigkeit","Forschungspeptid"],aka:["KED-Peptid","Lys-Glu-Asp","Lysyl-Glutamyl-Asparaginsäure"],whatIs:"Vesugen ist ein synthetisches Tripeptid, Lys-Glu-Asp (KED), aus der Khavinson-Serie kurzer Peptid-Bioregulatoren. Es wird als Forschungssubstanz in Studien zum vaskulären Endothel, zur Expression von Endothelin-1 und Sirtuin-1 sowie zur endothelialen Proliferation während der Alterung eingesetzt. Geliefert ausschließlich für die In-vitro- und Laborforschung.",mechanism:"In publizierter Forschung wurde berichtet, dass KED die in atherosklerotischen und restenotischen Endothelzellen erhöhte Endothelin-1-Expression normalisierte und die Expression von Connexin und Sirtuin-1 in vitro wiederherstellte. Separate Arbeiten berichteten einen erhöhten Proliferationsmarker Ki-67 in gealterten vaskulären Endothelkulturen, wobei molekulares Docking einen Kontakt mit dem MKI67-Kernpromotor nahelegte, und ein Review beschrieb die Regulation von Zellalterungsgenen (p16, p21) und neuronalen Differenzierungsgenen (NES, GAP43) in Neurogenesemodellen. Diese Effekte sind in Zellkulturmodellen beschrieben; entsprechende Mechanismen beim Menschen sind nicht belegt.",receptorTargets:["Endothelin-1-Expression","Expression von Connexin und Sirtuin-1 (SIRT1)","Ki-67/MKI67-Promotor (vorgeschlagen)","Zellalterungsgene p16 und p21"],specs:[{label:"Sequenz",value:"Lys-Glu-Asp (KED)"},{label:"Klassifizierung",value:"Synthetischer vaskulärer Tripeptid-Bioregulator"},{label:"Erscheinungsbild",value:"Weißes lyophilisiertes Pulver"},{label:"Löslichkeit",value:"Löslich in bakteriostatischem Wasser"}],researchApplications:[{title:"Endothelbiologie",description:"Eingesetzt in der Forschung zur Expression von Endothelin-1, Connexin und Sirtuin-1 in vaskulären Endothelkulturen."},{title:"Vaskuläre Alterung",description:"Untersucht auf die Expression von Proliferationsmarkern in gealtertem Endothelgewebe und Zellmodellen."},{title:"Epigenetische Regulation",description:"Erforscht mittels molekularem Docking an Genpromotoren als vorgeschlagener Wirkmechanismus."},{title:"Neurogenesemodelle",description:"Angewandt in Studien zur Expression von Zellalterungs- und neuronalen Differenzierungsgenen."}],keyStudies:[{title:"Molekulare Aspekte der Aktivität des vasoprotektiven Peptids KED bei Atherosklerose und Restenose",source:"Advances in Gerontology",year:2016,url:"https://pubmed.ncbi.nlm.nih.gov/28539025/",finding:"Berichtete, dass KED die Endothelin-1-Expression normalisierte und die Expression von Connexin und Sirtuin-1 in normalen, atherosklerotischen und restenotischen Endothelzellen in vitro wiederherstellte."},{title:"Epigenetische Aspekte der peptidergen Regulation der Proliferation vaskulärer Endothelzellen während der Alterung",source:"Advances in Gerontology",year:2014,url:"https://pubmed.ncbi.nlm.nih.gov/25051766/",finding:"Berichtete, dass Vesugen den Proliferationsmarker Ki-67 in gealterten vaskulären Endothelkulturen stimulierte, wobei molekulares Docking einen Kontakt mit dem MKI67-Kernpromotor zeigte."},{title:"Peptid KED: molekulargenetische Aspekte der Regulation der Neurogenese bei der Alzheimer-Krankheit",source:"Bulletin of Experimental Biology and Medicine",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34173097/",finding:"Überprüfte Berichte, wonach KED Zellalterungsgene (p16, p21), neuronale Differenzierungsgene (NES, GAP43) und Alzheimer-assoziierte Gene in einem In-vitro-Neurogenesemodell reguliert."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit weißem lyophilisiertem Vesugen-Pulver. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich."},cartalax:{name:"Cartalax",description:"Knorpel-Tripeptid-Bioregulator (Ala-Glu-Asp, AED-Peptid), geliefert als lyophilisierter Referenzstandard für die Forschung zu chondrogener Differenzierung, Bindegewebe und zellulärer Alterung.",longDescription:"Cartalax (AED-Peptid) ist ein synthetisches Tripeptid mit der Sequenz Ala-Glu-Asp, einer der von der Khavinson-Gruppe entwickelten kurzen Peptid-Bioregulatoren. Es wurde in humanen mesenchymalen Stammzellkulturen auf die Expression chondrogener Marker (SOX9, Aggrecan, Typ-II-Kollagen, COMP), in alternden Hautfibroblasten auf MMP-9 und Proliferationsmarker sowie in Stammzell-Alterungsmodellen auf die Expression von IGF1 und NF-kB untersucht. Es wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Forschung zur chondrogenen Differenzierung","Knorpel- und Bindegewebsmodelle","Studien zu MMP-9 und Fibroblastenalterung","Forschung zur Expression von IGF1 und NF-kB","Studien zur Alterung mesenchymaler Stammzellen"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. Cartalax wird als lyophilisiertes Pulver geliefert. Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist Cartalax?",answer:"Cartalax ist ein synthetisches Tripeptid, Ala-Glu-Asp (AED), aus der Khavinson-Serie kurzer Peptid-Bioregulatoren. Es wird in mesenchymalen Stammzell- und Fibroblastenmodellen auf die Expression chondrogener Marker und auf Bindegewebsalterung untersucht."},{question:"Wie lauten Molekulargewicht und Formel von Cartalax?",answer:"Cartalax hat die Summenformel C12H19N3O8 und ein Molekulargewicht von etwa 333,29 g/mol (PubChem CID 87815447). Seine Sequenz ist Ala-Glu-Asp."},{question:"Welche Reinheit hat Cartalax von Miro Biotech?",answer:"Jede Charge wird unabhängig von einem Drittlabor getestet und auf 99,47 % Reinheit verifiziert, mit einem Analysenzertifikat für die Charge."},{question:"Wie sollte Cartalax gelagert werden?",answer:"Das lyophilisierte Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["Knorpel","Chondrozyt","Bindegewebe","Bioregulator","Tripeptid","Forschungspeptid"],aka:["AED-Peptid","Ala-Glu-Asp","T-31-Peptid","Alanyl-Glutamyl-Asparaginsäure"],whatIs:"Cartalax ist ein synthetisches Tripeptid, Ala-Glu-Asp (AED), aus der Khavinson-Serie kurzer Peptid-Bioregulatoren. Es wird als Forschungssubstanz in Studien zur chondrogenen Differenzierung, zu Knorpel- und Bindegewebsmarkern und zur Fibroblastenalterung in Zellkultur eingesetzt. Geliefert ausschließlich für die In-vitro- und Laborforschung.",mechanism:"In publizierter Forschung wurde berichtet, dass AED-Peptid bei 200 ng/ml die Expression der chondrogenen Marker SOX9, Aggrecan, Typ-II-Kollagen und COMP in humanen mesenchymalen Stammzellen während der replikativen Alterung aktivierte. Separate Arbeiten in alternden Hautfibroblastenkulturen berichteten eine Hemmung der MMP-9-Synthese, erhöhtes Ki-67 und CD98hc sowie eine Unterdrückung der caspase-abhängigen Apoptose, und eine Stammzell-Alterungsstudie berichtete eine erhöhte IGF1-Expression zusammen mit einer stimulierten NF-kB-Expression. Diese Effekte sind in Zellkulturmodellen beschrieben; entsprechende Mechanismen beim Menschen sind nicht belegt.",receptorTargets:["Expression von SOX9, Aggrecan und Typ-II-Kollagen","MMP-9-Synthese","Expression von IGF1 und NF-kB","Caspase-abhängige Apoptose"],specs:[{label:"Sequenz",value:"Ala-Glu-Asp (AED)"},{label:"Klassifizierung",value:"Synthetischer Knorpel-Tripeptid-Bioregulator"},{label:"Erscheinungsbild",value:"Weißes lyophilisiertes Pulver"},{label:"Löslichkeit",value:"Löslich in bakteriostatischem Wasser"}],researchApplications:[{title:"Chondrogene Differenzierung",description:"Eingesetzt in der Forschung zur Expression von Knorpelmarkern in humanen mesenchymalen Stammzellkulturen."},{title:"Bindegewebsalterung",description:"Untersucht auf MMP-9-, Proliferations- und Apoptosemarker in alternden Fibroblastenmodellen."},{title:"Wachstumsfaktor-Signalgebung",description:"Angewandt zur Untersuchung der Expression von IGF1 und NF-kB in Stammzell-Alterungskulturen."},{title:"Kurzpeptid-Bioregulation",description:"Erforscht neben anderen Khavinson-Tripeptiden, um Genexpressionsprofile zu vergleichen."}],keyStudies:[{title:"Der Einfluss von Peptiden auf die chondrogene Differenzierung humaner mesenchymaler Stammzellen während der replikativen Alterung",source:"Advances in Gerontology",year:2023,url:"https://pubmed.ncbi.nlm.nih.gov/37782646/",finding:"Berichtete, dass AED-Peptid bei 200 ng/ml die Expression der chondrogenen Marker SOX9, Aggrecan, Typ-II-Kollagen und COMP in humanen mesenchymalen Stammzellen während der replikativen Alterung in vitro aktivierte."},{title:"Peptidregulation der Funktionen von Hautfibroblasten während ihrer Alterung in vitro",source:"Bulletin of Experimental Biology and Medicine",year:2016,url:"https://pubmed.ncbi.nlm.nih.gov/27259496/",finding:"Berichtete, dass kurze Peptide einschließlich AED die MMP-9-Synthese hemmten und Ki-67 und CD98hc in alternden Hautfibroblastenkulturen erhöhten, wobei AED zusätzlich die caspase-abhängige Apoptose unterdrückte."},{title:"Genexpression in Alterungskulturen humaner mesenchymaler Stammzellen: Modulation durch kurze Peptide",source:"Molecular Biology Reports",year:2020,url:"https://pubmed.ncbi.nlm.nih.gov/32399807/",finding:"Berichtete, dass AED, KED und KE in nanomolaren Konzentrationen die IGF1-Expression um ein Mehrfaches erhöhten und die NF-kB-Expression in zwei Alterungsmodellen humaner mesenchymaler Knochenmarkstammzellen stimulierten."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit weißem lyophilisiertem Cartalax-Pulver. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich."},pinealon:{name:"Pinealon",description:"Gehirn-Tripeptid-Bioregulator (Glu-Asp-Arg, EDR-Peptid), geliefert als lyophilisierter Referenzstandard für die Forschung zu neuronalen Kulturen, oxidativem Stress und kognitiver Alterung.",longDescription:"Pinealon (EDR-Peptid) ist ein synthetisches Tripeptid mit der Sequenz Glu-Asp-Arg, einer der von der Khavinson-Gruppe entwickelten kurzen Peptid-Bioregulatoren. Es wurde in Kleinhirn-Körnerzell-, Neutrophilen- und PC12-Kulturen auf die Akkumulation reaktiver Sauerstoffspezies und die Zellviabilität, in einem Rattenmodell der pränatalen Hyperhomocysteinämie auf das Lernverhalten der Nachkommen sowie in neuronalen Kulturmodellen der Neurodegeneration untersucht. Es wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Forschung zu neuronalen Kulturen und Neuroprotektion","Studien zu reaktiven Sauerstoffspezies und Zellviabilität","Modelle zu kognitiver Alterung und Lernen","Forschung zur MAPK/ERK-Signalgebung","Studien zur Genexpression bei Neurodegeneration"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. Pinealon wird als lyophilisiertes Pulver geliefert. Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist Pinealon?",answer:"Pinealon ist ein synthetisches Tripeptid, Glu-Asp-Arg (EDR), aus der Khavinson-Serie kurzer Peptid-Bioregulatoren. Es wird in neuronalen Zellkulturen und Nagetiermodellen auf die Akkumulation reaktiver Sauerstoffspezies, Zellviabilität und lernbezogene Endpunkte untersucht."},{question:"Wie lauten Molekulargewicht und Formel von Pinealon?",answer:"Pinealon hat die Summenformel C15H26N6O8 und ein Molekulargewicht von etwa 418,40 g/mol (PubChem CID 10273502, CAS 175175-23-2). Seine Sequenz ist Glu-Asp-Arg."},{question:"Welche Reinheit hat Pinealon von Miro Biotech?",answer:"Jede Charge wird unabhängig von einem Drittlabor getestet und auf 99,55 % Reinheit verifiziert, mit einem Analysenzertifikat für die Charge."},{question:"Wie sollte Pinealon gelagert werden?",answer:"Das lyophilisierte Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["Neuroprotektion","kognitiv","Bioregulator","Tripeptid","Nootropikum","Forschungspeptid"],aka:["EDR-Peptid","Glu-Asp-Arg","Glutamyl-Aspartyl-Arginin"],whatIs:"Pinealon ist ein synthetisches Tripeptid, Glu-Asp-Arg (EDR), aus der Khavinson-Serie kurzer Peptid-Bioregulatoren. Es wird als Forschungssubstanz in Studien zur neuronalen Zellviabilität, zur Akkumulation reaktiver Sauerstoffspezies und in Modellen der kognitiven Alterung eingesetzt. Geliefert ausschließlich für die In-vitro- und Laborforschung.",mechanism:"In publizierter Forschung wurde berichtet, dass Pinealon die Akkumulation reaktiver Sauerstoffspezies und den nekrotischen Zelltod in Kleinhirn-Körnerzellen, Neutrophilen und PC12-Zellen unter oxidativem Stress begrenzte, mit verzögerter ERK1/2-Aktivierung und Zellzyklus-Modulation, was die Autoren zu der Annahme einer direkten Interaktion mit dem Genom führte. Ein Rattenmodell der pränatalen Hyperhomocysteinämie berichtete ein verbessertes räumliches Lernen der Nachkommen und reduzierte neuronale ROS, und ein Review schlug den Eintritt in Zellen und die Bindung an Histone oder RNA vor, mit nachgeschalteten Effekten auf MAPK/ERK, Caspase-3, p53, SOD2 und GPX1. Diese Befunde stammen aus Zell- und Tiermodellen; entsprechende Mechanismen beim Menschen sind nicht belegt.",receptorTargets:["Akkumulation reaktiver Sauerstoffspezies (ROS)","MAPK/ERK1/2-Signalgebung","Caspase-3- und p53-Apoptose-Signalweg","Antioxidative Enzyme SOD2 und GPX1"],specs:[{label:"Sequenz",value:"Glu-Asp-Arg (EDR)"},{label:"Klassifizierung",value:"Synthetischer Gehirn-Tripeptid-Bioregulator"},{label:"Erscheinungsbild",value:"Weißes lyophilisiertes Pulver"},{label:"Löslichkeit",value:"Löslich in bakteriostatischem Wasser"}],researchApplications:[{title:"Neuroprotektionsmodelle",description:"Eingesetzt in der Forschung zu ROS-Akkumulation und Zellviabilität in neuronalen und PC12-Kulturen."},{title:"Kognitive Alterung",description:"Untersucht in Nagetiermodellen auf räumliches Lernen und neuronale oxidative Marker."},{title:"Neurodegenerationsforschung",description:"Erforscht in neuronalen Kulturen, die Alzheimer- und Huntington-Pathologie modellieren."},{title:"Signalwege",description:"Angewandt zur Untersuchung der Expression von MAPK/ERK, Caspase-3 und antioxidativen Enzymen."}],keyStudies:[{title:"Pinealon erhöht die Zellviabilität durch Unterdrückung des Radikalspiegels und Aktivierung proliferativer Prozesse",source:"Rejuvenation Research",year:2011,url:"https://pubmed.ncbi.nlm.nih.gov/21978084/",finding:"Berichtete, dass Pinealon die ROS-Akkumulation und den nekrotischen Zelltod in Kleinhirn-Körnerzellen, Neutrophilen und PC12-Zellen unter oxidativem Stress dosisabhängig begrenzte, mit verzögerter ERK1/2-Aktivierung."},{title:"Pinealon schützt die Nachkommen der Ratte vor pränataler Hyperhomocysteinämie",source:"International Journal of Clinical and Experimental Medicine",year:2012,url:"https://pubmed.ncbi.nlm.nih.gov/22567179/",finding:"Berichtete, dass Pinealon bei methioninbelasteten trächtigen Ratten die räumliche Orientierung und das Lernen der Nachkommen verbesserte und ROS sowie Nekrose in Kleinhirnneuronen der Nachkommen reduzierte."},{title:"EDR-Peptid: möglicher Mechanismus der Regulation von Genexpression und Proteinsynthese in der Pathogenese der Alzheimer-Krankheit",source:"Molecules",year:2020,url:"https://pubmed.ncbi.nlm.nih.gov/33396470/",finding:"Überprüfte Berichte, wonach EDR die neuronale Apoptose in Neurodegenerationskulturen reduziert und dendritische Dornfortsätze erhält, und schlug eine Histon- und RNA-Bindung mit Effekten auf MAPK/ERK, Caspase-3, p53, SOD2 und GPX1 vor."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit weißem lyophilisiertem Pinealon-Pulver. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich."},thymalin:{name:"Thymalin",description:"Thymus-Polypeptidkomplex, geliefert als lyophilisierter Referenzstandard für die Forschung zu T-Zell-Differenzierung, Immunseneszenz und hämatopoetischen Stammzellen.",longDescription:"Thymalin ist ein Polypeptidkomplex, der ursprünglich durch milde saure Extraktion aus Kälberthymus isoliert und von Morozov und Khavinson entwickelt wurde. Zu seinen charakterisierten aktiven Komponenten gehören die Dipeptide Lys-Glu (KE) und Glu-Trp (EW). Es wurde in humanen hämatopoetischen Stammzellkulturen auf T-Zell-Differenzierungsmarker, in Immunseneszenz-Modellen und in langfristiger Beobachtungsforschung zur Immunfunktion bei älteren Erwachsenen untersucht. Es wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Forschung zur T-Zell-Differenzierung","Modelle zu Immunseneszenz und Thymusalterung","Studien zu hämatopoetischen Stammzellen","Forschung zu den Markern CD28, CD44 und CD117","Studien zur Thymuspeptid-Bioregulation"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. Thymalin wird als lyophilisiertes Pulver geliefert. Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist Thymalin?",answer:"Thymalin ist ein aus Kälberthymus isolierter Polypeptidkomplex, entwickelt von Morozov und Khavinson. Zu seinen charakterisierten aktiven Komponenten gehören die Dipeptide Lys-Glu und Glu-Trp. Es wird in Modellen zu T-Zell-Differenzierung, Immunseneszenz und hämatopoetischen Stammzellen untersucht."},{question:"Ist Thymalin dasselbe wie Thymulin?",answer:"Nein. Thymulin ist ein definiertes zinkabhängiges Nonapeptid-Hormon, während Thymalin ein Multi-Peptid-Thymusextrakt ist. Es handelt sich um unterschiedliche Materialien, die lediglich einen ähnlichen Namen teilen."},{question:"Welche Reinheit hat Thymalin von Miro Biotech?",answer:"Jede Charge wird unabhängig von einem Drittlabor getestet und auf 99,1 % Peptidgehalt verifiziert, mit einem Analysenzertifikat für die Charge."},{question:"Wie sollte Thymalin gelagert werden?",answer:"Das lyophilisierte Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["Immun","Thymus","T-Zelle","Bioregulator","Langlebigkeit","Forschungspeptid"],aka:["Thymus-Polypeptidkomplex","Thymalinum","KE- und EW-Dipeptidkomplex"],whatIs:"Thymalin ist ein aus Kälberthymus isolierter Polypeptidkomplex, zu dessen charakterisierten aktiven Komponenten die Dipeptide Lys-Glu und Glu-Trp gehören. Es wird als Forschungssubstanz in Studien zur T-Zell-Differenzierung, zu Markern hämatopoetischer Stammzellen und zur Immunseneszenz eingesetzt. Geliefert ausschließlich für die In-vitro- und Laborforschung.",mechanism:"In publizierter Forschung wurde berichtet, dass Thymalin in humanen hämatopoetischen Stammzellkulturen die Expression von CD44 und CD117 um das Zwei- bis Dreifache reduzierte und die CD28-Expression um das 6,8-Fache erhöhte, was die Autoren als Stimulation der Differenzierung hin zu reifen CD28-positiven T-Zellen interpretierten. Seine Dipeptidkomponenten KE und EW wurden mittels molekularem Docking an doppelsträngige DNA und mittels bioinformatischer Analyse der Genexpression untersucht. Eine 6-8-jährige Beobachtungsstudie an älteren Erwachsenen, die Thymalin erhielten, berichtete eine geringere Inzidenz von Atemwegsinfektionen. Diese Befunde stammen aus Zellkultur- und Beobachtungsforschung; ein definierter molekularer Mechanismus ist nicht belegt.",receptorTargets:["Kostimulatorischer T-Zell-Marker CD28","Stammzellmarker CD44 und CD117","T-Lymphozyten-Differenzierung","DNA-Bindung der Dipeptide KE und EW (vorgeschlagen)"],specs:[{label:"Zusammensetzung",value:"Thymus-Polypeptidkomplex (Kälberthymus-Extrakt)"},{label:"Charakterisierte Komponenten",value:"Dipeptide Lys-Glu (KE) und Glu-Trp (EW)"},{label:"Erscheinungsbild",value:"Weißes bis cremefarbenes lyophilisiertes Pulver"},{label:"Löslichkeit",value:"Löslich in bakteriostatischem Wasser"}],researchApplications:[{title:"T-Zell-Differenzierung",description:"Eingesetzt in der Forschung zu den Markern CD28, CD44 und CD117 in humanen hämatopoetischen Stammzellkulturen."},{title:"Immunseneszenz",description:"Untersucht in Modellen des altersbedingten Rückgangs der Thymus- und T-Lymphozyten-Funktion."},{title:"Thymuspeptid-Biologie",description:"Angewandt, um den Extrakt mit seinen charakterisierten Dipeptidkomponenten KE und EW zu vergleichen."},{title:"Genexpressions-Bioinformatik",description:"Erforscht mittels molekularem Docking und Expressionsanalyse immunbezogener Gene."}],keyStudies:[{title:"Thymalin: Aktivierung der Differenzierung humaner hämatopoetischer Stammzellen",source:"Bulletin of Experimental Biology and Medicine",year:2020,url:"https://pubmed.ncbi.nlm.nih.gov/33237528/",finding:"Berichtete, dass Thymalin, ein aus dem Thymus isolierter Polypeptidkomplex, in humanen hämatopoetischen Stammzellkulturen die Expression von CD44 und CD117 reduzierte und die CD28-Expression um das 6,8-Fache erhöhte."},{title:"Der Einfluss der Dipeptide KE und EW in der Zusammensetzung des Thymalin-Präparats auf Genexpression und Proteinsynthese",source:"International Journal of Molecular Sciences",year:2023,url:"https://pubmed.ncbi.nlm.nih.gov/37686182/",finding:"Beschrieb Thymalin als Polypeptid-Thymusextrakt, dessen aktive Substanzen KE und EW mittels molekularem Docking an doppelsträngige DNA und mittels bioinformatischer Analyse der Genexpression untersucht wurden."},{title:"Peptide der Zirbeldrüse und des Thymus verlängern das menschliche Leben",source:"Neuro Endocrinology Letters",year:2003,url:"https://pubmed.ncbi.nlm.nih.gov/14523363/",finding:"Berichtete eine 6-8-jährige Beobachtungs-Nachverfolgung von 266 älteren Erwachsenen, die Thymalin und/oder Epithalamin erhielten, mit geringerer Inzidenz akuter Atemwegserkrankungen in den behandelten Gruppen als bei den Kontrollen."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit weißem bis cremefarbenem lyophilisiertem Thymalin-Pulver. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich."},"pt-141":{name:"PT-141",description:"Zyklisches Melanocortin-Heptapeptid (Bremelanotid), ein MC3R/MC4R-Agonist, geliefert als lyophilisierter Referenzstandard für die Melanocortin-Rezeptor-Pharmakologie und die Forschung zu Signalwegen des zentralen Nervensystems.",longDescription:"PT-141 (Bremelanotid) ist ein zyklisches Heptapeptid-Analogon des Alpha-Melanozyten-stimulierenden Hormons, Ac-Nle-cyclo[Asp-His-D-Phe-Arg-Trp-Lys]-OH, das als Agonist an den Melanocortin-Rezeptoren MC3R und MC4R wirkt. Es wurde in Rezeptorbindungs- und Nagetier-Verhaltensmodellen der zentralen Melanocortin-Signalgebung untersucht, und die publizierte klinische Literatur umfasst Phase-2- und Phase-3-Studien einer subkutanen Formulierung. Es wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Forschung an den Melanocortin-Rezeptoren MC3R/MC4R","Studien zu Signalwegen des zentralen Nervensystems","Pharmakologie des Alpha-MSH-Analogons","Rezeptorbindungs- und Signal-Assays","Forschungsmodelle hypothalamischer Schaltkreise"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. PT-141 wird als lyophilisiertes Pulver geliefert. Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist PT-141?",answer:"PT-141 (Bremelanotid) ist ein zyklisches Heptapeptid-Analogon von Alpha-MSH, das als Agonist an den Melanocortin-Rezeptoren MC3R und MC4R wirkt. Es wird in der Rezeptorpharmakologie und in der Forschung zu Signalwegen des zentralen Nervensystems untersucht."},{question:"Wie lauten Molekulargewicht und Formel von PT-141?",answer:"PT-141 hat die Summenformel C50H68N14O10 und ein Molekulargewicht von etwa 1025,2 g/mol (PubChem CID 9941379, CAS 189691-06-3). Seine Sequenz ist Ac-Nle-cyclo[Asp-His-D-Phe-Arg-Trp-Lys]-OH."},{question:"Worin unterscheidet sich PT-141 von MT-2?",answer:"Beide sind synthetische Alpha-MSH-Analoga. MT-2 (Melanotan II) ist ein zyklischer nicht-selektiver Melanocortin-Agonist, der für die Melanogenese untersucht wird, während PT-141 sein Carboxylat-Metabolit-Analogon ist und für die MC3R- und MC4R-Signalgebung im zentralen Nervensystem untersucht wird."},{question:"Welche Reinheit hat PT-141 von Miro Biotech?",answer:"Jede Charge wird unabhängig von einem Drittlabor getestet und auf 99,44 % Reinheit verifiziert, mit einem Analysenzertifikat für die Charge."},{question:"Wie sollte PT-141 gelagert werden?",answer:"Das lyophilisierte Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["Melanocortin","MC4R","Alpha-MSH","Neurowissenschaft","Heptapeptid","Forschungspeptid"],aka:["Bremelanotid","PT141","Vyleesi (zugelassene Formulierung)"],whatIs:"PT-141 (Bremelanotid) ist ein zyklisches Heptapeptid-Analogon von Alpha-MSH, das als Agonist an den Melanocortin-Rezeptoren MC3R und MC4R wirkt. Es wird als Forschungssubstanz in Studien zur Melanocortin-Rezeptor-Pharmakologie und zu Signalwegen des zentralen Nervensystems eingesetzt. Geliefert ausschließlich für die In-vitro- und Laborforschung.",mechanism:"In publizierter Forschung wurde PT-141 als Melanocortin-Agonist mit hoher Affinität zu MC4R und Aktivität an MC3R charakterisiert. Präklinische Arbeiten an weiblichen Rattenmodellen berichteten, dass seine Verhaltenseffekte zentral vermittelt wurden, wobei ortsspezifische Applikation im Gehirn und Mikrodialyse auf hypothalamische Melanocortin-Schaltkreise statt auf periphere vaskuläre Effekte hinwiesen. Frühe humanpharmakokinetische Studien zur intranasalen und subkutanen Applikation berichteten eine Halbwertszeit von etwa zwei Stunden, und spätere Phase-2- und Phase-3-Programme bewerteten eine subkutane Formulierung. Diese Befunde beschreiben die publizierte Literatur; die Substanz wird hier ausschließlich als Referenzstandard für die Forschung geliefert.",receptorTargets:["Melanocortin-Rezeptor 4 (MC4R)","Melanocortin-Rezeptor 3 (MC3R)","Hypothalamische Melanocortin-Schaltkreise","Alpha-MSH-Signalgebung"],specs:[{label:"Sequenz",value:"Ac-Nle-cyclo[Asp-His-D-Phe-Arg-Trp-Lys]-OH"},{label:"Klassifizierung",value:"Zyklisches Heptapeptid-Alpha-MSH-Analogon, MC3R/MC4R-Agonist"},{label:"Erscheinungsbild",value:"Weißes lyophilisiertes Pulver"},{label:"Löslichkeit",value:"Löslich in bakteriostatischem Wasser"}],researchApplications:[{title:"Melanocortin-Rezeptor-Pharmakologie",description:"Eingesetzt in Bindungs- und Signal-Assays zur Charakterisierung des MC3R- und MC4R-Agonismus."},{title:"Signalwege des zentralen Nervensystems",description:"Untersucht in Nagetiermodellen der hypothalamischen Melanocortin-Signalgebung."},{title:"Vergleich von Alpha-MSH-Analoga",description:"Erforscht neben MT-2 und anderen Analoga, um die Rezeptorselektivität zu vergleichen."},{title:"Pharmakokinetische Forschung",description:"Angewandt in publizierten Studien zu intranasalen und subkutanen Applikationswegen."}],keyStudies:[{title:"Bremelanotid: ein Überblick über präklinische ZNS-Effekte auf die weibliche Sexualfunktion",source:"Journal of Sexual Medicine",year:2007,url:"https://pubmed.ncbi.nlm.nih.gov/17958619/",finding:"Fasste präklinische Arbeiten an weiblichen Rattenmodellen zusammen, die berichteten, dass Bremelanotid über zentrale Melanocortin-Signalwege wirkte, wobei ortsspezifische Applikation im Gehirn und Mikrodialyse zur Lokalisierung des Effekts eingesetzt wurden."},{title:"Doppelblinde, placebokontrollierte Bewertung der Sicherheit, der pharmakokinetischen Eigenschaften und der pharmakodynamischen Effekte von intranasalem PT-141, einem Melanocortin-Rezeptor-Agonisten",source:"International Journal of Impotence Research",year:2004,url:"https://pubmed.ncbi.nlm.nih.gov/14963471/",finding:"Berichtete pharmakokinetische und Sicherheitsdaten zu intranasalem PT-141 bei gesunden Männern und Patienten und beschrieb die Substanz als zyklisches Heptapeptid-Melanocortin-Analogon mit einer Halbwertszeit von etwa zwei Stunden."},{title:"Bremelanotid zur Behandlung der hypoaktiven sexuellen Luststörung: zwei randomisierte Phase-3-Studien",source:"Obstetrics and Gynecology",year:2019,url:"https://pubmed.ncbi.nlm.nih.gov/31599840/",finding:"Berichtete zwei 24-wöchige randomisierte, placebokontrollierte Phase-3-Studien (RECONNECT) einer subkutanen Bremelanotid-Formulierung bei prämenopausalen Frauen, wobei Übelkeit, Flush und Kopfschmerzen die am häufigsten berichteten unerwünschten Ereignisse waren."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit weißem lyophilisiertem PT-141-Pulver. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich."},cagrilintide:{name:"Cagrilintide",description:"Langwirksames lipidiertes Amylin-Analogon (AM833, NNC0174-0833), geliefert als lyophilisierter Referenzstandard für die Amylin- und Calcitonin-Rezeptor-Pharmakologie und die Forschung zur Energieaufnahme. Erhältlich in 5mg- und 10mg-Vials.",longDescription:"Cagrilintide ist ein Amylin-Analogon aus 37 Resten, acyliert mit einer C20-Fettdisäure, das von Novo Nordisk als einmal wöchentlicher Amylin-Rezeptor-Agonist entwickelt und als Amylin-Komponente der Kombination aus Cagrilintide und Semaglutid (CagriSema) untersucht wurde. Es wurde als nicht-selektiver Agonist der Amylin- und Calcitonin-Rezeptoren charakterisiert und in Phase-1-, Phase-2- und Phase-3-Forschung zum Gewichtsmanagement bewertet. Es wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Forschung zur Amylin-Rezeptor-Pharmakologie","Studien zum Calcitonin-Rezeptor-Agonismus","Modelle zu Energieaufnahme und Sättigungs-Signalwegen","Forschung zu langwirksamen lipidierten Peptiden","Kombinationsstudien mit Amylin und GLP-1"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. Cagrilintide wird als lyophilisiertes Pulver geliefert. Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist Cagrilintide?",answer:"Cagrilintide (AM833, NNC0174-0833) ist ein langwirksames lipidiertes Analogon des Pankreashormons Amylin. Es wird als nicht-selektiver Amylin- und Calcitonin-Rezeptor-Agonist in der Forschung zu Energieaufnahme und Körpergewicht untersucht."},{question:"Ist Cagrilintide dasselbe wie CagriSema?",answer:"Nein. CagriSema ist die Fixkombination aus Cagrilintide und dem GLP-1-Rezeptor-Agonisten Semaglutid, die in den REDEFINE-Studien untersucht wurde. Dieses Produkt ist Cagrilintide allein, geliefert als Referenzstandard für die Forschung."},{question:"Wie lauten Molekulargewicht und Formel von Cagrilintide?",answer:"Cagrilintide hat die Summenformel C194H312N54O59S2 und ein Molekulargewicht von etwa 4409 g/mol (PubChem CID 171397054, CAS 1415456-99-3). Es ist ein amidiertes Peptid aus 37 Resten mit einer Cys2-Cys7-Disulfidbrücke und einer über einen Gamma-Glutamyl-Spacer gebundenen C20-Fettdisäure."},{question:"Welche Reinheit hat Cagrilintide von Miro Biotech?",answer:"Jede Charge wird unabhängig von einem Drittlabor getestet und auf 99,31 % Reinheit verifiziert, mit einem Analysenzertifikat für die Charge."},{question:"Wie sollte Cagrilintide gelagert werden?",answer:"Das lyophilisierte Pulver zur Langzeitlagerung bei -20 °C aufbewahren. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["Amylin","metabolisch","Gewichtsmanagement","Calcitonin-Rezeptor","langwirksam","Forschungspeptid"],aka:["AM833","NNC0174-0833","Cagrilintide Amylin-Analogon"],whatIs:"Cagrilintide ist ein langwirksames lipidiertes Amylin-Analogon, das als nicht-selektiver Agonist an Amylin- und Calcitonin-Rezeptoren wirkt. Es wird als Forschungssubstanz in Studien zur Sättigungs-Signalgebung, zur Energieaufnahme und zur Kombinationspharmakologie von Amylin und GLP-1 eingesetzt. Geliefert ausschließlich für die In-vitro- und Laborforschung.",mechanism:"In publizierter Forschung wurde Cagrilintide als nicht-selektiver Agonist der Amylin-Rezeptoren (Calcitonin-Rezeptor mit rezeptoraktivitätsmodifizierenden Proteinen) und des Calcitonin-Rezeptors selbst charakterisiert, verglichen mit selektiven und nicht-selektiven Referenzagonisten. Seine C20-Fettdisäure-Acylierung unterstützt die Albuminbindung und eine in einer Phase-1b-Studie berichtete Halbwertszeit von etwa 159-195 Stunden. Eine 26-wöchige Phase-2-Dosisfindungsstudie berichtete mittlere Körpergewichtsreduktionen von 6,0-10,8 % über die einmal wöchentlichen Dosen hinweg gegenüber 3,0 % unter Placebo, und die Phase-3-Studie REDEFINE 1 der Kombination aus Cagrilintide und Semaglutid berichtete nach 68 Wochen eine geschätzte mittlere Veränderung von -20,4 % gegenüber -3,0 % unter Placebo. Diese Befunde beschreiben die publizierte klinische Literatur; die Substanz wird hier ausschließlich als Referenzstandard für die Forschung geliefert.",receptorTargets:["Amylin-Rezeptoren (CTR + RAMP1/2/3)","Calcitonin-Rezeptor (CTR)","Sättigungsschaltkreise im Hinterhirn und Hypothalamus","Interaktion der Amylin- und GLP-1-Signalwege"],specs:[{label:"Sequenz",value:"KCNTATCATQRLAEFLRHSSNNFGPILPPTNVGSNTP-NH2, Cys2-Cys7-Disulfidbrücke"},{label:"Klassifizierung",value:"Lipidiertes langwirksames Amylin-Analogon (C20-Fettdisäure über Gamma-Glu-Spacer)"},{label:"Erscheinungsbild",value:"Weißes lyophilisiertes Pulver"},{label:"Löslichkeit",value:"Löslich in bakteriostatischem Wasser"}],researchApplications:[{title:"Amylin-Rezeptor-Pharmakologie",description:"Eingesetzt in Rezeptor-Signal-Assays zum Vergleich von Amylin- und Calcitonin-Rezeptor-Agonisten."},{title:"Modelle zur Energieaufnahme",description:"Untersucht in der Sättigungs- und Nahrungsaufnahmeforschung in Nagetier- und Humanmodellen."},{title:"Kombinationspharmakologie",description:"Erforscht neben GLP-1-Rezeptor-Agonisten in der Forschung zum Körpergewicht über zwei Signalwege."},{title:"Design langwirksamer Peptide",description:"Angewandt in Studien zu Fettdisäure-Acylierung, Albuminbindung und verlängerter Halbwertszeit."}],keyStudies:[{title:"Einmal wöchentliches Cagrilintide zum Gewichtsmanagement bei Menschen mit Übergewicht und Adipositas: eine Phase-2-Dosisfindungsstudie",source:"The Lancet",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34798060/",finding:"Berichtete eine 26-wöchige Phase-2-Studie an 706 Erwachsenen, in der einmal wöchentliches Cagrilintide 0,3-4,5 mg mittlere Körpergewichtsreduktionen von 6,0-10,8 % gegenüber 3,0 % unter Placebo erzeugte, wobei gastrointestinale Ereignisse und Reaktionen an der Injektionsstelle die häufigsten unerwünschten Ereignisse waren."},{title:"Sicherheit, Verträglichkeit, Pharmakokinetik und Pharmakodynamik der gleichzeitigen Gabe mehrerer Dosen von Cagrilintide mit Semaglutid 2,4 mg: eine Phase-1b-Studie",source:"The Lancet",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/33894838/",finding:"Berichtete eine 20-wöchige Phase-1b-Studie, in der Cagrilintide eine Halbwertszeit von 159-195 Stunden und eine dosisproportionale Exposition zeigte, die die Semaglutid-Exposition nicht veränderte, mit größeren Körpergewichtsreduktionen bei 1,2 und 2,4 mg als unter Placebo."},{title:"Gleichzeitig verabreichtes Cagrilintide und Semaglutid bei Erwachsenen mit Übergewicht oder Adipositas",source:"New England Journal of Medicine",year:2025,url:"https://pubmed.ncbi.nlm.nih.gov/40544433/",finding:"Berichtete die 68-wöchige Phase-3a-Studie REDEFINE 1 an 3417 Erwachsenen mit einer geschätzten mittleren Körpergewichtsveränderung von -20,4 % für Cagrilintide 2,4 mg plus Semaglutid 2,4 mg gegenüber -3,0 % unter Placebo."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit weißem lyophilisiertem Cagrilintide-Pulver im gewählten Format. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich."},dsip:{name:"DSIP",description:"Delta-Schlaf-induzierendes Peptid (Emideltid), ein synthetisches Nonapeptid, geliefert als lyophilisierter Referenzstandard für die Schlaf-EEG-, neuroendokrine und Stressreaktionsforschung. Erhältlich in 2mg-, 5mg- und 10mg-Vials.",longDescription:"DSIP (Trp-Ala-Gly-Gly-Asp-Ala-Ser-Gly-Glu) wurde in den 1970er Jahren aus dem zerebralen Venenblut von Kaninchen während induzierten Schlafs isoliert und nach der Zunahme der Delta-EEG-Aktivität benannt, die das synthetische Peptid nach zentraler Infusion erzeugte. Später wurde es in kleinen frühen Humanstudien zum Schlaf sowie in Nagetierarbeiten zur Hypothalamus-Hypophysen-Achse und zur Stressreaktion untersucht, mit gemischten Ergebnissen; sein endogener Vorläufer und sein Rezeptor wurden nie identifiziert. Es wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Schlaf-EEG- und Delta-Aktivitätsforschung","Studien zu neuroendokrinen und ACTH-Signalwegen","Stressreaktionsmodelle bei Nagetieren","Klassischer Neuropeptid-Referenzstandard","Forschung zu Nonapeptid-Stabilität und Analoga"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. DSIP wird als lyophilisiertes Pulver geliefert. Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist DSIP?",answer:"DSIP (Delta-Schlaf-induzierendes Peptid, INN Emideltid) ist ein Peptid aus neun Resten, das 1977 erstmals aus dem zerebralen Venenblut von Kaninchen charakterisiert wurde. Es wird als Referenz-Neuropeptid in der Schlaf-EEG-, neuroendokrinen und Stressreaktionsforschung untersucht."},{question:"Wurde DSIP am Menschen untersucht?",answer:"Nur in kleinen frühen Studien aus den 1980er und 1990er Jahren, alle mit intravenöser Applikation in Forschungssettings. Die Ergebnisse waren gemischt: Eine Studie von 1981 an sechs Probanden berichtete längeren Schlaf, während eine doppelblinde Studie von 1992 an sechzehn Patienten mit Insomnie zu dem Schluss kam, dass die Effekte schwach waren. Es wird hier ausschließlich als Referenzstandard für die Forschung geliefert."},{question:"Wie lauten Sequenz und Molekulargewicht von DSIP?",answer:"DSIP hat die Sequenz Trp-Ala-Gly-Gly-Asp-Ala-Ser-Gly-Glu (WAGGDASGE), die Summenformel C35H48N10O15 und ein Molekulargewicht von etwa 848,8 g/mol als freies Peptid (PubChem CID 68816, CAS 62568-57-4)."},{question:"Welche Reinheit hat DSIP von Miro Biotech?",answer:"Jede Charge wird unabhängig von einem Drittlabor getestet und auf 99,24 % Reinheit verifiziert, mit einem Analysenzertifikat für die Charge."},{question:"Wie sollte DSIP gelagert werden?",answer:"Das lyophilisierte Pulver zur Langzeitlagerung bei -20 °C aufbewahren, vor Licht und Feuchtigkeit geschützt. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden; wiederholte Einfrier- und Auftauzyklen vermeiden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["Schlaf","Neuropeptid","EEG","neuroendokrin","Stressreaktion","Forschungspeptid"],aka:["Emideltid","Delta-Schlaf-induzierendes Peptid","WAGGDASGE"],whatIs:"DSIP ist ein synthetisches Nonapeptid, benannt nach der Zunahme der Delta-Wellen-EEG-Aktivität, die es bei Kaninchen nach zentraler Infusion erzeugte. Es wird als Forschungssubstanz in Studien zur Schlafregulation, zur ACTH- und Hypophysen-Signalgebung und zu Stressreaktions-Signalwegen eingesetzt. Geliefert ausschließlich für die In-vitro- und Laborforschung.",mechanism:"In publizierter Forschung verstärkte synthetisches DSIP in doppelblinden Experimenten die Delta- und Spindel-EEG-Aktivität nach intraventrikulärer Infusion bei Kaninchen, ein Effekt, den Fragmente und Analoga nicht reproduzierten. Kleine frühe Humanstudien lieferten gemischte Ergebnisse: Eine Crossover-Studie von 1981 an sechs Probanden berichtete eine mediane Zunahme der Gesamtschlafzeit um 59 % ohne klassische Sedierung, während eine doppelblinde Studie von 1992 an sechzehn Patienten mit chronischer Insomnie nur schwache Effekte auf Schlafeffizienz und Schlaflatenz fand. Die endokrinen Daten sind uneinheitlich: Eine Studie an acht Männern berichtete niedrigeres Plasma-ACTH, eine andere fand keine Veränderung von CRH- oder mahlzeitenstimuliertem ACTH und Cortisol. Ein Review aus dem Jahr 2006 stellte fest, dass weder ein DSIP-Gen noch ein Vorläuferprotein oder ein Rezeptor identifiziert wurde, sodass der Mechanismus ungeklärt bleibt. Diese Befunde beschreiben die publizierte Literatur; die Substanz wird hier ausschließlich als Referenzstandard für die Forschung geliefert.",receptorTargets:["Delta-EEG-Aktivität (schlafregulierende Schaltkreise, Mechanismus ungeklärt)","Hypothalamus-Hypophysen-Achse (ACTH, uneinheitliche Befunde)","Stressreaktions-Signalwege in Nagetiermodellen","Kein identifizierter Rezeptor und kein Vorläufergen"],specs:[{label:"Sequenz",value:"Trp-Ala-Gly-Gly-Asp-Ala-Ser-Gly-Glu (WAGGDASGE)"},{label:"Klassifizierung",value:"Synthetisches Nonapeptid, Referenzstandard für ein schlafassoziiertes Neuropeptid"},{label:"Erscheinungsbild",value:"Weißes lyophilisiertes Pulver"},{label:"Löslichkeit",value:"Löslich in Wasser und bakteriostatischem Wasser (etwa 10 mg/mL in neutralem Puffer)"}],researchApplications:[{title:"Schlaf-EEG-Forschung",description:"Eingesetzt als Referenzpeptid in Studien zur Delta-Wellen- und Spindelaktivität in Kaninchen- und Rattenmodellen."},{title:"Neuroendokrine Signalgebung",description:"Untersucht auf Effekte auf ACTH, Cortisol und andere Hypophysenhormone in kleinen Human- und Nagetierstudien."},{title:"Stressreaktionsmodelle",description:"Erforscht als stresslimitierender Faktor in Nagetiermodellen emotionalen und physischen Stresses."},{title:"Peptidchemie",description:"Angewandt in Studien zu Analoga, Phosphorylierung und Asp-Gly-Isomerisierung zur Stabilität kurzer Peptide."}],keyStudies:[{title:"Charakterisierung eines Delta-Elektroenzephalogramm-(Schlaf-)induzierenden Peptids",source:"Proceedings of the National Academy of Sciences",year:1977,url:"https://pubmed.ncbi.nlm.nih.gov/265572/",finding:"Isolierte das Nonapeptid aus dem zerebralen Venenblut von Kaninchen, klärte seine Sequenz auf und zeigte in doppelblinden Experimenten an 58 Kaninchen, dass nur das synthetische Peptid in voller Länge, nicht seine Fragmente oder Analoga, die Delta- und Spindel-EEG-Aktivität nach intraventrikulärer Infusion verstärkte."},{title:"Akute und verzögerte Effekte von DSIP (Delta-Schlaf-induzierendes Peptid) auf das menschliche Schlafverhalten",source:"International Journal of Clinical Pharmacology, Therapy, and Toxicology",year:1981,url:"https://pubmed.ncbi.nlm.nih.gov/6895513/",finding:"Berichtete eine doppelblinde Crossover-Studie an sechs gesunden Probanden, in der eine einzelne intravenöse Infusion die mediane Gesamtschlafzeit innerhalb von etwa zwei Stunden um 59 % erhöhte und die Schlafeffizienz der folgenden Nacht verbesserte, ohne Sedierung im klassischen pharmakologischen Sinn."},{title:"Effekte des Delta-Schlaf-induzierenden Peptids auf den Schlaf von Patienten mit chronischer Insomnie. Eine doppelblinde Studie",source:"Neuropsychobiology",year:1992,url:"https://pubmed.ncbi.nlm.nih.gov/1299794/",finding:"Berichtete eine doppelblinde Studie an sechzehn Patienten mit chronischer Insomnie, in der drei intravenöse Infusionen eine höhere Schlafeffizienz und eine kürzere Schlaflatenz als Placebo erzeugten, wobei die Autoren die Effekte als schwach und teilweise auf eine Veränderung in der Placebogruppe zurückführbar beurteilten."},{title:"Delta-Schlaf-induzierendes Peptid (DSIP): ein noch immer ungelöstes Rätsel",source:"Journal of Neurochemistry",year:2006,url:"https://pubmed.ncbi.nlm.nih.gov/16539679/",finding:"Überblickte drei Jahrzehnte DSIP-Forschung und kam zu dem Schluss, dass Gen, Vorläuferprotein und Rezeptor des Peptids nie identifiziert wurden und die Evidenz für DSIP als endogenen Schlaffaktor schwach bleibt."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren und wiederholte Einfrier- und Auftauzyklen vermeiden.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit weißem lyophilisiertem DSIP-Pulver im gewählten Format. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich."},"5-amino-1mq":{name:"5-Amino-1MQ",description:"Niedermolekularer NNMT-Inhibitor (5-Amino-1-methylchinoliniumiodid), geliefert als Trockenpulver-Referenzstandard für die Forschung zu Adipozytenstoffwechsel, NAD+-Salvage und Muskelalterung in Zell- und Mausmodellen. Erhältlich in 5mg-, 10mg- und 50mg-Vials.",longDescription:"5-Amino-1MQ ist ein membranpermeables Chinoliniumsalz, das die Nicotinamid-N-Methyltransferase (NNMT) hemmt, das Enzym, das Nicotinamid methyliert und dabei S-Adenosylmethionin verbraucht. Es ging aus einer Struktur-Wirkungs-Studie zu NNMT-Inhibitoren aus dem Jahr 2017 hervor und wurde seitdem in kultivierten Adipozyten sowie in diätinduziert adipösen und gealterten Mäusen untersucht, wo die NNMT-Hemmung mit geringerer Fettmasse, verbesserter Glukoseverwertung und der Aktivierung von Muskelstammzellen assoziiert war. Es ist ein kleines Molekül und kein Peptid und hat keine publizierten Humanstudien. Es wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Forschung zur Hemmung des Enzyms NNMT","Modelle zu Adipozyten-Lipogenese und Fettmasse","Studien zum NAD+- und SAM-Stoffwechsel","Forschung zur Alterung von Muskelstammzellen","Mausmodelle der diätinduzierten Adipositas"],researchGuide:"Mit sterilem oder bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. 5-Amino-1MQ wird als trockenes, wasserlösliches Pulver geliefert, das hygroskopisch ist. Das versiegelte Vial bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt, und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist 5-Amino-1MQ?",answer:"5-Amino-1MQ (5-Amino-1-methylchinolinium) ist ein niedermolekularer Inhibitor der Nicotinamid-N-Methyltransferase (NNMT), eines Enzyms, das im Fettgewebe adipöser Mäuse erhöht ist. Es wird in der Forschung zu Adipozytenstoffwechsel, NAD+-Salvage und Muskelalterung untersucht."},{question:"Ist 5-Amino-1MQ ein Peptid?",answer:"Nein. Es ist ein kleines Chinolinium-Molekül (C10H11IN2 als Iodidsalz, Molekulargewicht etwa 286,1 g/mol). Es ist neben unseren metabolischen Forschungspeptiden gelistet, weil es in denselben Modellen zu Energiebilanz und Fettgewebe untersucht wird, gehört aber zu einer anderen Substanzklasse."},{question:"Wofür wurde 5-Amino-1MQ untersucht?",answer:"Publizierte Arbeiten liegen ausschließlich zu Zellen und Mäusen vor. Bei diätinduziert adipösen Mäusen war die NNMT-Hemmung mit dieser Substanz mit geringerer Fettmasse und kleineren Adipozyten ohne Veränderung der Nahrungsaufnahme sowie mit verbesserter Glukosetoleranz assoziiert. Bei gealterten Mäusen war sie mit der Aktivierung von Muskelstammzellen und besserer Regeneration nach Verletzung assoziiert. Es gibt keine publizierten Humanstudien."},{question:"Welche Reinheit hat 5-Amino-1MQ von Miro Biotech?",answer:"Jede Charge wird unabhängig von einem Drittlabor getestet und auf 99,47 % Reinheit verifiziert, mit einem Analysenzertifikat für die Charge."},{question:"Wie sollte 5-Amino-1MQ gelagert werden?",answer:"Das versiegelte Vial bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt, da der Feststoff hygroskopisch ist. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["NNMT","metabolisch","Adipozyten","NAD+","kleines Molekül","Muskelalterung"],aka:["5-Amino-1-methylchinolinium","NNMTi","5A1MQ"],whatIs:"5-Amino-1MQ ist ein wasserlösliches, membranpermeables kleines Molekül, das die Nicotinamid-N-Methyltransferase (NNMT) hemmt. Es wird als Forschungssubstanz in Studien zur Adipozyten-Lipogenese, zum NAD+- und S-Adenosylmethionin-Stoffwechsel und zur Alterung von Muskelstammzellen in Zellkultur und Mausmodellen eingesetzt. Geliefert ausschließlich für die In-vitro- und Laborforschung.",mechanism:"In publizierter Forschung hemmte 5-Amino-1MQ die NNMT mit einem IC50 im niedrigen mikromolaren Bereich durch Bindung an die Nicotinamid-Substratbindungsstelle und war selektiv gegenüber verwandten Methyltransferasen und Enzymen des NAD+-Salvage-Wegs. In kultivierten 3T3-L1-Adipozyten reduzierte es die Lipogenese und veränderte die Spiegel von 1-Methylnicotinamid und NAD+. Bei diätinduziert adipösen Mäusen war eine elftägige subkutane Behandlung mit etwa 35 % geringerer epididymaler Fettmasse, über 30 % kleineren Adipozyten und rund 30 % niedrigerem Gesamtcholesterin ohne Veränderung der Nahrungsaufnahme assoziiert, und eine 28-Tage-Studie berichtete eine dosisabhängige Begrenzung der Gewichtszunahme mit besserer Glukosetoleranz und weniger hepatischer Steatose. Bei gealterten Mäusen aktivierte die NNMT-Hemmung seneszente Muskelstammzellen und verbesserte die Regeneration nach Verletzung. Diese Befunde beschreiben die publizierte Zell- und Mausliteratur; es gibt keine publizierten Humanstudien, und die Substanz wird hier ausschließlich als Referenzstandard für die Forschung geliefert.",receptorTargets:["Nicotinamid-N-Methyltransferase (NNMT)","Stoffwechsel von Nicotinamid, SAM und 1-Methylnicotinamid","Signalwege der Adipozyten-Lipogenese","Aktivierung von Muskelstammzellen (gealterte Mausmodelle)"],specs:[{label:"Struktur",value:"5-Amino-1-methylchinoliniumiodid, C10H11IN2 (CAS 42464-96-0)"},{label:"Klassifizierung",value:"Niedermolekularer NNMT-Inhibitor (Chinoliniumsalz), kein Peptid"},{label:"Erscheinungsbild",value:"Trockenes Pulver, hygroskopisch"},{label:"Löslichkeit",value:"Löslich in Wasser und bakteriostatischem Wasser"}],researchApplications:[{title:"NNMT-Hemmungs-Assays",description:"Eingesetzt als Referenzinhibitor in Enzymkinetik- und Selektivitäts-Assays gegenüber verwandten Methyltransferasen."},{title:"Adipozytenstoffwechsel",description:"Untersucht in kultivierten 3T3-L1-Adipozyten auf Effekte auf die Lipogenese und NAD+-bezogene Metabolitspiegel."},{title:"Modelle der diätinduzierten Adipositas",description:"Erforscht in Mausmodellen mit fettreicher Diät auf Veränderungen von Fettmasse, Glukosetoleranz und Leberfett."},{title:"Forschung zur Muskelalterung",description:"Angewandt in Studien an gealterten Mäusen zu Aktivierung von Muskelstammzellen, Regeneration und Reaktion auf körperliche Belastung."}],keyStudies:[{title:"Selektive und membranpermeable niedermolekulare Inhibitoren der Nicotinamid-N-Methyltransferase kehren die durch fettreiche Diät induzierte Adipositas bei Mäusen um",source:"Biochemical Pharmacology",year:2018,url:"https://pubmed.ncbi.nlm.nih.gov/29155147/",finding:"Berichtete, dass 5-Amino-1MQ die Lipogenese in kultivierten Adipozyten reduzierte und bei diätinduziert adipösen Mäusen nach elf Tagen subkutaner Behandlung mit etwa 35 % geringerer epididymaler Fettmasse, über 30 % kleineren Adipozyten und rund 30 % niedrigerem Cholesterin bei unveränderter Nahrungsaufnahme assoziiert war."},{title:"Die Hemmung der Nicotinamid-N-Methyltransferase mildert adipositasbedingte Stoffwechselstörungen",source:"Diabetes, Obesity and Metabolism",year:2024,url:"https://pubmed.ncbi.nlm.nih.gov/39161060/",finding:"Berichtete eine 28-Tage-Studie an diätinduziert adipösen Mäusen, in der eine tägliche Behandlung die Gewichts- und Fettzunahme dosisabhängig begrenzte, Glukosetoleranz und Insulinsensitivität verbesserte und die hepatische Steatose verringerte, mit Verteilung in Fett-, Muskel- und Lebergewebe."},{title:"Niedermolekularer Inhibitor der Nicotinamid-N-Methyltransferase aktiviert seneszente Muskelstammzellen und verbessert die Regenerationsfähigkeit gealterter Skelettmuskulatur",source:"Biochemical Pharmacology",year:2019,url:"https://pubmed.ncbi.nlm.nih.gov/30753815/",finding:"Berichtete, dass bei 24 Monate alten Mäusen, die nach einer Muskelverletzung behandelt wurden, die NNMT-Hemmung die Aktivierung von Muskelstammzellen erhöhte und die Regeneration des verletzten Muskels gegenüber Vehikel verbesserte."},{title:"Struktur-Wirkungs-Beziehung niedermolekularer Inhibitoren der Nicotinamid-N-Methyltransferase",source:"Journal of Medicinal Chemistry",year:2017,url:"https://pubmed.ncbi.nlm.nih.gov/28548833/",finding:"Beschrieb die Chinolinium-Reihe, aus der 5-Amino-1MQ ausgewählt wurde, und berichtete eine NNMT-Hemmung im niedrigen mikromolaren Bereich durch Bindung an die Nicotinamid-Substratbindungsstelle."}],reconstitution:"Typischerweise mit sterilem oder bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken, bis sich das Pulver gelöst hat. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das trockene Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt; der Feststoff ist hygroskopisch. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit trockenem 5-Amino-1MQ-Pulver im gewählten Format. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich."},"aod-9604":{name:"AOD-9604",description:"Synthetisches C-terminales Fragment des humanen Wachstumshormons (hGH 177-191, Hexadecapeptid), geliefert als lyophilisierter Referenzstandard für die Forschung zu Lipolyse im Fettgewebe, Fettoxidation und Energiebilanz. Erhältlich in 2mg-, 5mg- und 10mg-Vials.",longDescription:"AOD-9604 ist ein Peptid aus 16 Resten, das der C-terminalen lipolytischen Domäne des humanen Wachstumshormons (Reste 177-191) mit einem zusätzlichen N-terminalen Tyrosin entspricht. Es wurde von Metabolic Pharmaceuticals entwickelt, um die lipolytische Aktivität von hGH ohne dessen wachstumsfördernde Signalgebung zu erhalten. Bei fettleibigen Zucker-Ratten und ob/ob-Mäusen war es mit geringerer Gewichtszunahme und höherer Fettoxidation assoziiert, ohne die bei intaktem hGH beobachtete Hyperglykämie, und es bindet in vitro nicht an den hGH-Rezeptor. Sechs placebokontrollierte Studien am Menschen etablierten sein Sicherheitsprofil, während die 24-wöchige Phase-2b-Adipositasstudie keine signifikante Gewichtsabnahme zeigte und die klinische Entwicklung 2007 eingestellt wurde. Es wird an einzelne Forschende, Labore und Institutionen ausschließlich für die In-vitro- und Laborforschung geliefert.",benefits:["Forschung zur Lipolyse im Fettgewebe in Nagetiermodellen","Studien zu Fettoxidation und Energieverbrauch","Struktur-Wirkungs-Forschung zu hGH-Fragmenten","Modelle zur Expression des Beta-3-adrenergen Rezeptors","Entwicklung von Nachweismethoden für die Dopingkontrolle"],researchGuide:"Mit bakteriostatischem Wasser in der gewünschten Konzentration rekonstituieren. AOD-9604 wird als lyophilisiertes Pulver geliefert. Das lyophilisierte Pulver bei -20 °C lagern und die rekonstituierte Lösung bei 2-8 °C halten sowie innerhalb von 30 Tagen verwenden.",faq:[{question:"Was ist AOD-9604?",answer:"AOD-9604 ist ein synthetisches Fragment des humanen Wachstumshormons aus 16 Resten (Reste 177-191 mit einem N-terminalen Tyrosin), das die lipolytische Domäne von hGH ohne dessen wachstumsfördernde Aktivität bewahrt. Es wird in Nagetiermodellen zu Lipolyse im Fettgewebe, Fettoxidation und Energiebilanz untersucht."},{question:"Wurde AOD-9604 am Menschen untersucht?",answer:"Ja. Sechs randomisierte, placebokontrollierte Studien an 925 Probanden mit oraler und intravenöser Applikation über bis zu 24 Wochen berichteten keine Veränderung von IGF-1, keinen Effekt auf Glukose oder Insulin und ein Nebenwirkungsprofil ähnlich dem von Placebo. Die 24-wöchige Phase-2b-Adipositasstudie zeigte keine signifikante Gewichtsabnahme, und die klinische Entwicklung wurde 2007 eingestellt. Es wird hier ausschließlich als Referenzstandard für die Forschung geliefert."},{question:"Wie lauten Sequenz und Molekulargewicht von AOD-9604?",answer:"AOD-9604 hat die Sequenz Tyr-Leu-Arg-Ile-Val-Gln-Cys-Arg-Ser-Val-Glu-Gly-Ser-Cys-Gly-Phe (YLRIVQCRSVEGSCGF) mit einer Cys7-Cys14-Disulfidbrücke, die Summenformel C78H123N23O23S2 und ein Molekulargewicht von etwa 1815,1 g/mol als freies Peptid (PubChem CID 71300630, CAS 221231-10-3)."},{question:"Welche Reinheit hat AOD-9604 von Miro Biotech?",answer:"Jede Charge wird unabhängig von einem Drittlabor getestet und auf 99,36 % Reinheit verifiziert, mit einem Analysenzertifikat für die Charge."},{question:"Wie sollte AOD-9604 gelagert werden?",answer:"Das lyophilisierte Pulver zur Langzeitlagerung bei -20 °C aufbewahren, vor Licht und Feuchtigkeit geschützt. Rekonstituierte Lösungen sollten bei 2-8 °C gehalten und innerhalb von 30 Tagen verwendet werden; wiederholte Einfrier- und Auftauzyklen vermeiden, da sie die Disulfidbrücke beeinträchtigen können."},{question:"Was ist in meiner Bestellung enthalten?",answer:"Ihre Bestellung enthält das oder die Peptidvial(s). Jede Charge wird von einem unabhängigen Drittlabor mit einem digitalen Analysenzertifikat (COA) geprüft. Ein COA für jedes Produkt ist auf Anfrage erhältlich."}],tags:["Lipolyse","metabolisch","Wachstumshormon-Fragment","Fettgewebe","Fettoxidation","Forschungspeptid"],aka:["AOD9604","Tyr-hGH177-191","hGH-Fragment 176-191","LAT8881"],whatIs:"AOD-9604 ist ein synthetisches Hexadecapeptid, das aus der C-terminalen Region des humanen Wachstumshormons abgeleitet ist und die lipolytische Domäne von hGH von dessen wachstumsfördernder Signalgebung isolieren soll. Es wird als Forschungssubstanz in Studien zu Lipolyse im Fettgewebe, Fettoxidation und Energieverbrauch in Nagetiermodellen sowie als Referenzmaterial in der Entwicklung von Dopingnachweismethoden eingesetzt. Geliefert ausschließlich für die In-vitro- und Laborforschung.",mechanism:"In publizierter Forschung war oral verabreichtes AOD-9604 bei fettleibigen Zucker-Ratten über 19 Tage mit weniger als der Hälfte der Gewichtszunahme der Kontrollen und einer höheren lipolytischen Aktivität im Fettgewebe assoziiert, ohne Verlust der Insulinsensitivität im euglykämischen Clamp, anders als intaktes hGH. Bei ob/ob-Mäusen war eine chronische Behandlung mit geringerer Gewichtszunahme und höherer In-vivo-Fettoxidation ohne Hyperglykämie assoziiert, und das Peptid konkurrierte weder um den hGH-Rezeptor noch induzierte es Proliferation in einer hGH-Rezeptor-Zelllinie. Die Behandlung stellte die reprimierte Expression des Beta-3-adrenergen Rezeptors bei adipösen Mäusen wieder her, chronische Effekte blieben bei Beta-3-Knockout-Mäusen jedoch aus, sodass die Autoren folgerten, dass die lipolytische Wirkung nicht direkt über den Beta-3-Rezeptor vermittelt wird. Am Menschen berichteten sechs placebokontrollierte Studien keine Veränderung von IGF-1 oder des Glukosestoffwechsels; der orale 12-Wochen-Arm mit 1 mg/Tag verlor 2,6 kg gegenüber 0,8 kg unter Placebo ohne Dosisabhängigkeit, und die 24-wöchige Phase-2b-Studie zeigte keine signifikante Gewichtsabnahme. Diese Befunde beschreiben die publizierte Literatur; die Substanz wird hier ausschließlich als Referenzstandard für die Forschung geliefert.",receptorTargets:["Signalwege der Lipolyse und Fettoxidation im Fettgewebe (Nagetiermodelle)","Expression des Beta-3-adrenergen Rezeptors (assoziiert, nicht direkt)","Keine Bindung an den hGH-Rezeptor","Akute Regulation des Energieverbrauchs (Nagetier)"],specs:[{label:"Sequenz",value:"Tyr-Leu-Arg-Ile-Val-Gln-Cys-Arg-Ser-Val-Glu-Gly-Ser-Cys-Gly-Phe (YLRIVQCRSVEGSCGF), Cys7-Cys14-Disulfidbrücke"},{label:"Klassifizierung",value:"Synthetisches C-terminales hGH-Fragment (Hexadecapeptid), lipolytische Domäne"},{label:"Erscheinungsbild",value:"Weißes lyophilisiertes Pulver"},{label:"Löslichkeit",value:"Löslich in Wasser und bakteriostatischem Wasser"}],researchApplications:[{title:"Adipositasmodelle bei Nagetieren",description:"Eingesetzt in Studien an fettleibigen Zucker-Ratten und ob/ob-Mäusen zu Gewichtszunahme, Fettoxidation und Glukoseverwertung."},{title:"Lipolyse-Assays",description:"Untersucht in Fettgewebspräparationen auf lipolytische Aktivität und Glycerolfreisetzung."},{title:"Struktur-Wirkungs-Forschung zu hGH-Fragmenten",description:"Angewandt in Arbeiten, die die lipolytische Domäne des Wachstumshormons von dessen rezeptorvermittelter Wachstumssignalgebung trennen."},{title:"Entwicklung von Dopingnachweismethoden",description:"Dient als Referenzmaterial für den LC-MS-Nachweis und In-vitro-Metabolismusstudien zu Wachstumshormon-Fragmenten."}],keyStudies:[{title:"Metabolische Studien zu einer synthetischen lipolytischen Domäne (AOD9604) des humanen Wachstumshormons",source:"Hormone Research",year:2e3,url:"https://pubmed.ncbi.nlm.nih.gov/11146367/",finding:"Berichtete, dass fettleibige Zucker-Ratten, die 19 Tage lang orales AOD9604 erhielten, weniger als die Hälfte des Körpergewichts der Kontrollen zunahmen, eine höhere lipolytische Aktivität im Fettgewebe zeigten und im euglykämischen Clamp eine normale Insulinsensitivität behielten, anders als Tiere, die intaktes Wachstumshormon erhielten."},{title:"Die Effekte von humanem GH und seinem lipolytischen Fragment (AOD9604) auf den Lipidstoffwechsel nach chronischer Behandlung bei adipösen Mäusen und beta(3)-AR-Knockout-Mäusen",source:"Endocrinology",year:2001,url:"https://pubmed.ncbi.nlm.nih.gov/11713213/",finding:"Berichtete, dass eine 14-tägige Behandlung Körpergewicht und Fett bei adipösen Mäusen reduzierte und die reprimierte Expression des Beta-3-adrenergen Rezeptors wiederherstellte, während chronische Effekte bei Beta-3-Knockout-Mäusen ausblieben, woraus die Autoren folgerten, dass die lipolytische Wirkung nicht direkt rezeptorvermittelt ist."},{title:"Sicherheit und Verträglichkeit des Hexadecapeptids AOD9604 am Menschen",source:"Journal of Endocrinology and Metabolism",year:2013,url:"https://www.jofem.org/index.php/jofem/article/view/157/194",finding:"Fasste sechs randomisierte, doppelblinde, placebokontrollierte Studien an 925 Probanden mit oralem und intravenösem AOD9604 über bis zu 24 Wochen zusammen und berichtete keinen Effekt auf Serum-IGF-1 oder den Kohlenhydratstoffwechsel, keine Anti-Drug-Antikörper und ein von Placebo nicht unterscheidbares Nebenwirkungsprofil."},{title:"Zentrale und periphere molekulare Zielstrukturen für die Antiadipositas-Pharmakotherapie",source:"Clinical Pharmacology and Therapeutics",year:2010,url:"https://pubmed.ncbi.nlm.nih.gov/20445536/",finding:"Überblickte das klinische AOD9604-Programm und vermerkte eine Gewichtsveränderung von 2,6 kg gegenüber 0,8 kg unter Placebo im 12-Wochen-Arm mit 1 mg/Tag ohne Dosisabhängigkeit sowie die Einstellung der Entwicklung 2007, nachdem eine 24-wöchige Studie an 536 Probanden keine signifikante Gewichtsabnahme gezeigt hatte."}],reconstitution:"Typischerweise mit bakteriostatischem Wasser für die Laborverwendung rekonstituiert. Das Verdünnungsmittel langsam an der Vialwand zugeben und sanft schwenken statt zu schütteln. Die rekonstituierte Lösung gekühlt aufbewahren und innerhalb eines definierten Forschungszeitraums verwenden.",storage:"Das lyophilisierte Pulver versiegelt bei -20 °C lagern, vor Licht und Feuchtigkeit geschützt. Nach der Rekonstitution gekühlt bei 2-8 °C aufbewahren und wiederholte Einfrier- und Auftauzyklen vermeiden.",howSupplied:"Geliefert als einzelnes versiegeltes Vial mit weißem lyophilisiertem AOD-9604-Pulver im gewählten Format. Bakteriostatisches Wasser zur Rekonstitution ist als separate Ergänzung erhältlich."}},categories:{"metabolic-peptides":{name:"Metabolische Peptide",description:"Peptide, die an der Stoffwechselregulation, Energiehomöostase und Forschung zur Körperzusammensetzung beteiligt sind. Umfasst GLP-1-, GIP- und Glukagon-Rezeptor-Agonisten."},"recovery-peptides":{name:"Regenerations- und Reparaturpeptide",description:"Peptide zur Gewebereparatur und Wundheilung für Studien der regenerativen Medizin. Weltweit von Forschenden, Laboren und Institutionen für die In-vitro-Forschung genutzt."},"cognitive-peptides":{name:"Kognitive Peptide",description:"Nootrope und neuroprotektive Peptide für die Neurowissenschaften sowie die Gedächtnis-, Aufmerksamkeits- und ZNS-Forschung. In vitro untersucht von Forschenden, Laboren und Institutionen."},"anti-aging-peptides":{name:"Anti-Aging-Peptide",description:"Peptide, die auf ihre Rolle bei Langlebigkeit, Hautgesundheit, zellulärer Energie und altersbedingten biologischen Prozessen untersucht werden."},blends:{name:"Forschungs-Blends",description:"Multi-Peptid-Forschungs-Blends, co-lyophilisiert in einem einzigen Fläschchen für Studiendesigns mit kombinierten Signalwegen. Geliefert an individuelle Forschende, Labore und Institutionen, ausschließlich zur In-vitro- und Laborforschung."},accessories:{name:"Forschungszubehör",description:"Grundausstattung für die Peptidforschung, darunter bakteriostatisches Wasser und Rekonstitutionsmaterialien. Weltweit von Forschenden, Laboren und Institutionen genutzt."}}},it:{products:{"glp-3-rt":{name:"GLP-3 (RT)",description:"Peptide triplo-agonista che agisce sui recettori GLP-1, GIP e glucagone, per la ricerca metabolica e sull'obesità.",longDescription:"GLP-3 (RT) è un innovativo peptide triplo-agonista che agisce simultaneamente sui recettori GLP-1, GIP e glucagone. Questo esclusivo triplice meccanismo consente uno studio completo delle vie metaboliche, non ottenibile con agonisti singoli o duali, e ne fa una sostanza da ricerca di primo piano per gli studi sul metabolismo e sull'obesità.",benefits:["Triplo agonista recettoriale (GLP-1 + GIP + glucagone)","Studio delle vie metaboliche avanzate","Studi su obesità e composizione corporea","Superiore agli agonisti duali per lo studio metabolico completo","Risultati pronti per la pubblicazione con purezza superiore al 99%"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. GLP-3 (RT) è stato studiato in contesti di ricerca metabolica a diverse concentrazioni. Conservare la soluzione ricostituita a 2-8 °C e utilizzarla entro 30 giorni.",faq:[{question:"Cosa rende unico GLP-3 (RT)?",answer:"GLP-3 (RT) è un triplo agonista che agisce simultaneamente sui recettori GLP-1, GIP e glucagone, consentendo così uno studio completo delle vie metaboliche non ottenibile con agonisti a singolo o doppio recettore."},{question:"Come devo conservare GLP-3 (RT)?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["metabolico","triplo agonista","GLP-1","GIP","glucagone","bestseller","peptide da ricerca"]},"ghk-cu":{name:"GHK-Cu (peptide di rame)",description:"Complesso peptidico di rame per applicazioni di ricerca su rigenerazione cutanea, guarigione delle ferite e anti-invecchiamento.",longDescription:"GHK-Cu è un tripeptide presente in natura (glicil-L-istidil-L-lisina) con elevata affinità per gli ioni rame(II). Si trova nel plasma, nella saliva e nell'urina umani, e la sua concentrazione diminuisce con l'età. Un'ampia ricerca ne ha evidenziato il ruolo nella guarigione delle ferite, nel rimodellamento tissutale, nella sintesi del collagene e nei meccanismi anti-invecchiamento.",benefits:["Stimola la sintesi del collagene negli studi","Guarigione delle ferite e rimodellamento tissutale","Proprietà antiossidanti","Ricerca sulla modulazione dell'espressione genica","Studi sui follicoli piliferi"],researchGuide:"GHK-Cu può essere disciolto in acqua o PBS. Per le applicazioni di ricerca topica si utilizzano comunemente concentrazioni dello 0,01-1%. Conservare a 2-8 °C.",faq:[{question:"In quale forma viene fornito questo prodotto?",answer:"GHK-Cu viene fornito come polvere liofilizzata blu (a causa del contenuto di rame)."},{question:"È lo stesso del GHK?",answer:"GHK-Cu è la forma legata al rame del tripeptide GHK, la forma bioattiva presente naturalmente nell'organismo."}],tags:["anti-invecchiamento","rame","pelle","guarigione delle ferite","peptide da ricerca"]},semax:{name:"Semax",description:"Neuropeptide sintetico analogo dell'ACTH per la ricerca su funzione cognitiva, neuroprotezione e SNC.",longDescription:"Semax è un peptide sintetico derivato dal frammento 4-10 dell'ormone adrenocorticotropo (ACTH), con una modifica Pro-Gly-Pro all'estremità C-terminale per una maggiore stabilità. È stato ampiamente studiato per le proprietà neuroprotettive, il potenziamento cognitivo e come strumento di ricerca per comprendere la neuroplasticità mediata dal BDNF.",benefits:["Sovraregolazione del BDNF negli studi","Studi sulle vie di neuroprotezione","Ricerca sulla funzione cognitiva","Studi sul recupero dopo ictus","Modulazione dell'NGF"],researchGuide:"Ricostituire con acqua batteriostatica. Viene spesso studiato per via intranasale nei modelli animali. Presenta un'emivita relativamente breve. Conservare a 2-8 °C.",faq:[{question:"Come è correlato Semax all'ACTH?",answer:"Semax si basa sul frammento ACTH(4-10), ma è stato modificato all'estremità C-terminale con un tripeptide Pro-Gly-Pro per la stabilità metabolica."},{question:"Quali sono il peso molecolare e la formula di Semax?",answer:"Semax ha formula molecolare C37H51N9O10S e un peso molecolare di circa 813,9 g/mol (PubChem CID 122178). La sua sequenza amminoacidica è Met-Glu-His-Phe-Pro-Gly-Pro."},{question:"Qual è la purezza del Semax di Miro Biotech?",answer:"Ogni lotto viene testato in modo indipendente da un laboratorio terzo e verificato al 99,1% di purezza, con un certificato di analisi per il lotto."},{question:"Come viene gestito Semax nei contesti di ricerca?",answer:"Semax viene fornito come polvere liofilizzata e di norma ricostituito con acqua batteriostatica per il lavoro di laboratorio. Negli studi animali pubblicati è stato per lo più somministrato per via intranasale o sottocutanea. È destinato esclusivamente alla ricerca in-vitro e di laboratorio."},{question:"Per cosa è stato studiato Semax?",answer:"La ricerca pubblicata ha studiato Semax nei modelli animali per la segnalazione delle neurotrofine (BDNF e TrkB), la neuroprotezione e l'ischemia cerebrale, nonché in analisi dell'espressione genica su tutto il genoma dopo ictus sperimentale."}],tags:["cognitivo","neuroprotettivo","ACTH","nootropo","peptide da ricerca"],aka:["ACTH(4-10) Pro-Gly-Pro","Met-Glu-His-Phe-Pro-Gly-Pro","MEHFPGP"],whatIs:"Semax è un eptapeptide sintetico (Met-Glu-His-Phe-Pro-Gly-Pro), un analogo del frammento ACTH(4-10) con un residuo Pro-Gly-Pro aggiunto per la stabilità metabolica. Viene impiegato come sostanza da ricerca in studi sulla segnalazione delle neurotrofine, sulla neuroprotezione e sulla cognizione. Fornito esclusivamente per la ricerca in-vitro e di laboratorio.",mechanism:"Nella ricerca animale pubblicata è stato riferito che Semax aumenta rapidamente l'espressione del fattore neurotrofico cerebrale (BDNF) e del suo recettore TrkB nell'ippocampo e modula la segnalazione dopaminergica e serotoninergica. Altri studi descrivono un'inibizione degli enzimi che degradano le encefaline e un'interazione con i recettori della melanocortina. Queste vie sono studiate in modelli di neuroplasticità e ischemia cerebrale; i meccanismi corrispondenti nell'uomo non sono dimostrati.",receptorTargets:["Via BDNF/TrkB","Segnalazione dopaminergica","Segnalazione serotoninergica","Recettori della melanocortina (MC4/MC5)","Enzimi che degradano le encefaline"],specs:[{label:"Sequenza",value:"Met-Glu-His-Phe-Pro-Gly-Pro (MEHFPGP)"},{label:"Classificazione",value:"Eptapeptide sintetico, analogo dell'ACTH(4-10)"},{label:"Aspetto",value:"Polvere liofilizzata bianca"},{label:"Solubilità",value:"Solubile in acqua e acqua batteriostatica"}],researchApplications:[{title:"Segnalazione delle neurotrofine",description:"Impiegato in studi sull'espressione di BDNF e TrkB e sulle vie di neuroplasticità a valle."},{title:"Neuroprotezione",description:"Studiato in modelli murini di ischemia cerebrale e di danno da ischemia-riperfusione."},{title:"Cognizione e comportamento",description:"Esaminato in studi su endpoint relativi ad apprendimento, attenzione e memoria in modelli animali."},{title:"Espressione genica",description:"Applicato in studi trascrizionali su tutto il genoma di geni immunitari e vascolari dopo ictus sperimentale."}],keyStudies:[{title:"Semax, un analogo dell'ACTH(4-10) con effetti cognitivi, regola l'espressione di BDNF e trkB nell'ippocampo di ratto",source:"Brain Research",year:2006,url:"https://pubmed.ncbi.nlm.nih.gov/16996037/",finding:"Ha riferito che Semax aumentava rapidamente l'espressione di BDNF e TrkB nell'ippocampo di ratto."},{title:"Semax e Pro-Gly-Pro attivano la trascrizione delle neurotrofine e dei loro geni recettoriali dopo ischemia cerebrale",source:"Cellular and Molecular Neurobiology",year:2010,url:"https://pubmed.ncbi.nlm.nih.gov/19633950/",finding:"Ha osservato un'attivazione della trascrizione dei geni delle neurotrofine e dei recettori dopo ischemia cerebrale in un modello di ratto."},{title:"Il peptide Semax influenza l'espressione dei geni del sistema immunitario e vascolare nell'ischemia cerebrale focale del ratto: analisi trascrizionale su tutto il genoma",source:"BMC Genomics",year:2014,url:"https://pubmed.ncbi.nlm.nih.gov/24661604/",finding:"L'analisi su tutto il genoma ha descritto variazioni dell'espressione genica immunitaria e vascolare dopo ischemia focale."},{title:"Il profilo di espressione proteica cerebrale conferma l'effetto protettivo del peptide ACTH(4-7)PGP (Semax) in un modello di ratto di ischemia-riperfusione cerebrale",source:"International Journal of Molecular Sciences",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34201112/",finding:"Il profiling proteomico ha riferito variazioni a livello proteico compatibili con un effetto protettivo in un modello di ratto di ischemia-riperfusione."}],reconstitution:"Di norma ricostituito con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C.",howSupplied:"Fornito come singolo flaconcino sigillato contenente polvere liofilizzata bianca di Semax. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata.",comparison:{heading:"Semax vs. Selank nella ricerca",columns:["","Semax","Selank"],rows:[{label:"Derivato da",values:["Frammento ACTH(4-10)","Tuftsina (peptide derivato dalle IgG)"]},{label:"Lunghezza del peptide",values:["Eptapeptide (7 aa)","Eptapeptide (7 aa)"]},{label:"Focus di ricerca primario",values:["Neurotrofine, neuroprotezione","Ansiolitico, immunomodulante"]},{label:"Somministrazione comune negli studi",values:["Intranasale, sottocutanea","Intranasale"]}]}},selank:{name:"Selank",description:"Eptapeptide derivato dalla tuftsina per la ricerca su comportamento, cognizione e immunomodulazione.",longDescription:"Selank è un eptapeptide sintetico derivato dal tetrapeptide naturale tuftsina, con una sequenza Gly-Pro aggiuntiva per la stabilità metabolica. Sviluppato presso l'Istituto di Genetica Molecolare dell'Accademia Russa delle Scienze, è stato studiato in modelli di ricerca per le sue proprietà comportamentali, cognitive e immunomodulanti.",benefits:["Ricerca sulle vie legate all'ansia","Studi sul potenziamento cognitivo","Ricerca sull'immunomodulazione","Ricerca sulla modulazione del BDNF","Studi sull'interazione con il sistema serotoninergico"],researchGuide:"Ricostituire con acqua batteriostatica. Selank viene spesso studiato per via intranasale nei modelli animali. Dopo la ricostituzione, conservare a 2-8 °C.",faq:[{question:"Cos'è la tuftsina?",answer:"La tuftsina è un tetrapeptide naturale (Thr-Lys-Pro-Arg) prodotto dalla scissione enzimatica delle IgG. Selank è un analogo modificato con maggiore stabilità."}],tags:["cognitivo","nootropo","comportamento","peptide da ricerca"]},"bpc-157":{name:"BPC-157",description:"Body Protection Compound derivato dal succo gastrico umano, studiato per riparazione dei tessuti, salute intestinale e recupero dopo lesioni.",longDescription:"BPC-157 (Body Protection Compound-157) è un pentadecapeptide sintetico di 15 amminoacidi. È derivato da una proteina protettiva del succo gastrico. Un'ampia ricerca ne ha evidenziato la notevole capacità di accelerare la guarigione delle ferite, proteggere gli organi e prevenire le ulcere gastriche. Gli studi hanno mostrato che favorisce la guarigione di tendini, muscoli e ossa nei modelli animali.",benefits:["Ricerca sui meccanismi di guarigione delle ferite","Studi sulle vie di riparazione di tendini e legamenti","Ricerca sui meccanismi di protezione gastrica","Studi sulle vie dell'angiogenesi","Ricerca sulla modulazione dell'infiammazione"],researchGuide:"BPC-157 viene di norma ricostituito con acqua batteriostatica. Per gli studi in-vitro le concentrazioni comuni sono nell'intervallo 1-10 μg/mL. Conservare la soluzione ricostituita a 2-8 °C e utilizzarla entro 30 giorni.",faq:[{question:"Qual è la purezza del vostro BPC-157?",answer:"Il nostro BPC-157 è testato con purezza ≥99,3%, con certificati di analisi completi disponibili."},{question:"Come devo conservare BPC-157?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C."},{question:"Qual è il peso molecolare?",answer:"Il peso molecolare di BPC-157 è 1419,53 g/mol."}],tags:["guarigione","riparazione dei tessuti","gastrico","rigenerazione","peptide da ricerca"]},"nad-plus":{name:"NAD+",description:"Coenzima nicotinammide adenina dinucleotide per la ricerca su metabolismo energetico cellulare, riparazione del DNA e longevità.",longDescription:"NAD+ (nicotinammide adenina dinucleotide) è un coenzima essenziale presente in ogni cellula vivente. Svolge un ruolo centrale nel metabolismo energetico cellulare, nella riparazione del DNA, nell'espressione genica e nella segnalazione cellulare. I livelli di NAD+ diminuiscono naturalmente con l'età, il che ne fa un punto focale della ricerca sulla longevità e sull'anti-invecchiamento.",benefits:["Ricerca sul metabolismo energetico cellulare","Studi sulle vie di riparazione del DNA","Ricerca sull'attivazione delle sirtuine","Studi su longevità e invecchiamento","Ricerca sulla funzione mitocondriale"],researchGuide:"NAD+ è idrosolubile e può essere ricostituito in acqua sterile o tampone. Maneggiare con cura poiché è sensibile alla luce. Conservare a -20 °C per la conservazione a lungo termine e a 2-8 °C per il breve periodo.",faq:[{question:"Qual è la differenza tra NAD+ e NMN?",answer:"NAD+ è il coenzima attivo stesso, mentre NMN (nicotinammide mononucleotide) è un precursore che le cellule convertono in NAD+."},{question:"Come va conservato NAD+?",answer:"Conservare NAD+ liofilizzato a -20 °C al riparo dalla luce. Le soluzioni ricostituite vanno utilizzate tempestivamente."}],tags:["anti-invecchiamento","longevità","energia cellulare","riparazione del DNA"]},"tb-500":{name:"TB-500",description:"Analogo sintetico della timosina beta-4, studiato per rigenerazione dei tessuti, guarigione delle ferite e modulazione dell'infiammazione.",longDescription:"TB-500 è una versione sintetica della timosina beta-4, un peptide di 43 amminoacidi presente naturalmente in praticamente tutte le cellule umane e animali. Svolge un ruolo centrale nella riparazione, rigenerazione e protezione dei tessuti. La ricerca ne ha evidenziato la capacità di favorire la migrazione cellulare e la formazione dei vasi sanguigni e di ridurre l'infiammazione.",benefits:["Studi su migrazione cellulare e riparazione dei tessuti","Ricerca sulla modulazione dell'infiammazione","Studi sulle vie dell'angiogenesi","Stimolazione dei follicoli piliferi negli studi","Ricerca sulla protezione del tessuto cardiaco"],researchGuide:"Ricostituire TB-500 con acqua batteriostatica alla concentrazione desiderata. Le concentrazioni comuni di ricerca sono di 2,5-5 mg/mL. Dopo la ricostituzione, conservare a 2-8 °C.",faq:[{question:"Qual è la sequenza di TB-500?",answer:"TB-500 è la regione attiva (17-23) della timosina beta-4, con sequenza Ac-LKKTETQ."},{question:"È la timosina beta-4 completa?",answer:"TB-500 rappresenta il frammento attivo. Offriamo anche la timosina beta-4 completa separatamente."}],tags:["guarigione","antinfiammatorio","riparazione dei tessuti","rigenerazione","peptide da ricerca"]},tesamorelin:{name:"Tesamorelin",description:"Analogo del GHRH che stimola il rilascio dell'ormone della crescita, studiato per regolazione metabolica e composizione corporea.",longDescription:"Tesamorelin è un analogo sintetico dell'ormone di rilascio dell'ormone della crescita (GHRH) di 44 amminoacidi. Stimola l'ipofisi a rilasciare l'ormone della crescita in modo fisiologico. È stato ampiamente studiato per i suoi effetti sulla composizione corporea, sull'adiposità viscerale e sui parametri metabolici.",benefits:["Studi sulle vie di rilascio dell'ormone della crescita","Ricerca sull'adiposità viscerale","Studi sulla composizione corporea","Ricerca sulla regolazione metabolica"],researchGuide:"Ricostituire con acqua batteriostatica. Tesamorelin è un analogo del GHRH con proprietà fisiologiche di rilascio del GH. Dopo la ricostituzione, conservare a 2-8 °C.",faq:[{question:"In che modo Tesamorelin si differenzia dagli altri analoghi del GHRH?",answer:"Tesamorelin è un analogo modificato del GHRH che stimola un rilascio pulsatile di GH, riproducendo così più fedelmente la fisiologia naturale rispetto a una stimolazione costante."}],tags:["metabolico","GHRH","ormone della crescita","peptide da ricerca"]},"mots-c":{name:"MOTS-c",description:"Peptide di derivazione mitocondriale, studiato per regolazione metabolica, sensibilità all'insulina e omeostasi cellulare.",longDescription:"MOTS-c (Mitochondrial Open Reading Frame of the 12S rRNA Type-c) è un peptide di derivazione mitocondriale codificato nel genoma mitocondriale. Si è affermato come importante sostanza da ricerca per lo studio della regolazione metabolica, della fisiologia dell'esercizio, della sensibilità all'insulina e dell'omeostasi energetica cellulare.",benefits:["Peptide di segnalazione di derivazione mitocondriale","Ricerca sulla sensibilità all'insulina","Studi sulla fisiologia dell'esercizio","Omeostasi energetica cellulare","Ricerca sulla regolazione metabolica"],researchGuide:"Ricostituire con acqua sterile o batteriostatica. MOTS-c è un peptide relativamente stabile. Conservare a -20 °C per la conservazione a lungo termine e a 2-8 °C per il breve periodo.",faq:[{question:"Cos'è un peptide di derivazione mitocondriale?",answer:"Gli MDP sono peptidi codificati nel genoma mitocondriale anziché nel DNA nucleare. MOTS-c è tra gli MDP meglio studiati."}],tags:["metabolico","mitocondriale","sensibilità all'insulina","peptide da ricerca"]},"cjc-1295":{name:"CJC-1295 (senza DAC)",description:"Peptide da ricerca CJC-1295 senza DAC ad alta purezza (99,60%). Analogo del GHRH per secrezione dell'ormone della crescita, rilascio pulsatile di GH e studi sulle vie metaboliche.",longDescription:"CJC-1295 (senza DAC) è un analogo sintetico dell'ormone di rilascio dell'ormone della crescita (GHRH), costituito dai primi 29 amminoacidi del GHRH con residui modificati per migliorare il legame recettoriale e la stabilità biologica. A differenza della variante modificata con DAC, CJC-1295 senza DAC produce impulsi di rilascio dell'ormone della crescita più brevi e più fisiologici, il che ne fa una sostanza preferita per lo studio dei pattern naturali di secrezione del GH e della regolazione metabolica.",benefits:["Studi sul rilascio pulsatile dell'ormone della crescita","Ricerca sul legame al recettore del GHRH","Studi sulle vie di regolazione metabolica","Ricerca su composizione corporea e massa magra","Superiore alla variante DAC per gli studi sugli impulsi fisiologici di GH"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. CJC-1295 (senza DAC) ha un'emivita più breve rispetto alle varianti modificate con DAC e supporta pattern di rilascio pulsatile di GH. Conservare la soluzione ricostituita a 2-8 °C e utilizzarla entro 30 giorni.",faq:[{question:"Qual è la differenza tra CJC-1295 con e senza DAC?",answer:"La modifica DAC (Drug Affinity Complex) prolunga notevolmente l'emivita. Senza DAC, CJC-1295 produce impulsi di GH più brevi e più fisiologici, il che è preferito per lo studio della dinamica naturale di secrezione del GH."},{question:"Come devo conservare CJC-1295?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["metabolico","GHRH","ormone della crescita","secretagogo","peptide da ricerca"]},ipamorelin:{name:"Ipamorelin",description:"Peptide da ricerca Ipamorelin ad alta purezza (99,20%). Secretagogo selettivo dell'ormone della crescita per rilascio di GH, legame al recettore della grelina e applicazioni di ricerca metabolica.",longDescription:"Ipamorelin è un pentapeptide sintetico e un secretagogo selettivo dell'ormone della crescita che agisce sul recettore della grelina/GHS (GHS-R1a). Si distingue per l'elevata selettività e stimola il rilascio di GH senza influenzare in modo significativo i livelli di cortisolo, ACTH o prolattina. Questa selettività ne fa uno degli strumenti di ricerca più puliti per lo studio delle vie di segnalazione isolate del GH e degli effetti metabolici a valle.",benefits:["Studi sul rilascio selettivo di GH senza aumento del cortisolo","Studi sul legame al recettore della grelina (GHS-R1a)","Ricerca sull'isolamento pulito della via di segnalazione del GH","Studi su metabolismo e composizione corporea","Effetti ormonali off-target minimi negli studi"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. Ipamorelin è noto per la sua selettività negli studi sul rilascio di GH, con effetto minimo sugli altri ormoni ipofisari. Conservare la soluzione ricostituita a 2-8 °C e utilizzarla entro 30 giorni.",faq:[{question:"Cosa distingue Ipamorelin dagli altri secretagoghi del GH?",answer:"Ipamorelin è uno dei GHRP più selettivi e stimola il rilascio di GH senza aumentare in modo significativo cortisolo, ACTH o prolattina, il che lo rende ideale per lo studio della segnalazione isolata del GH."},{question:"Come devo conservare Ipamorelin?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C."}],tags:["metabolico","GHRP","ormone della crescita","secretagogo","grelina","peptide da ricerca"]},"mt-2":{name:"MT-2 (Melanotan 2)",description:"Peptide da ricerca MT-2 Melanotan 2 ad alta purezza (99,10%). Agonista sintetico della melanocortina per vie di pigmentazione, fotoprotezione e studi sui recettori MC.",longDescription:"MT-2 (Melanotan 2) è un analogo eptapeptidico ciclico sintetico dell'ormone alfa-melanocita-stimolante (α-MSH). Agisce come agonista non selettivo sui recettori della melanocortina da MC1R a MC5R. La ricerca si è concentrata sul suo ruolo nella melanogenesi e nelle vie di pigmentazione, nei meccanismi fotoprotettivi e nella più ampia segnalazione del sistema melanocortinico. È uno strumento di ricerca centrale per lo studio della farmacologia dei recettori MC.",benefits:["Ricerca sui recettori della melanocortina (MC1R-MC5R)","Studi su melanogenesi e vie di pigmentazione","Ricerca sui meccanismi di fotoprotezione","Ricerca farmacologica sull'analogo dell'α-MSH","Studi sulla biologia cutanea e sulla risposta ai raggi UV"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. MT-2 è sensibile alla luce; proteggere dalla luce diretta durante la manipolazione e la conservazione. Conservare la soluzione ricostituita a 2-8 °C e utilizzarla entro 30 giorni.",faq:[{question:"Qual è il rapporto tra MT-2 e α-MSH?",answer:"MT-2 è un analogo ciclico sintetico dell'ormone alfa-melanocita-stimolante (α-MSH) con maggiore stabilità metabolica e più ampia affinità per i recettori della melanocortina."},{question:"Come va conservato MT-2?",answer:"Conservare la polvere liofilizzata a -20 °C al riparo dalla luce. Le soluzioni ricostituite vanno mantenute a 2-8 °C e protette dalla luce diretta."}],tags:["melanocortina","pigmentazione","pelle","fotoprotezione","anti-invecchiamento","peptide da ricerca"]},"bacteriostatic-water":{name:"Acqua batteriostatica",description:"Acqua batteriostatica di grado farmaceutico per la ricostituzione dei peptidi. Sterile, conservata con alcol benzilico allo 0,9%.",longDescription:"Acqua batteriostatica di grado farmaceutico (USP) con alcol benzilico allo 0,9% come conservante. Acqua sterile e apirogena, adatta alla ricostituzione di peptidi liofilizzati per scopi di ricerca. Ogni flaconcino è sigillato in condizioni asettiche e sottoposto a test di sterilità.",benefits:["Grado farmaceutico (USP)","Sterile e apirogena","Conservata con alcol benzilico allo 0,9%","Uso multiplo grazie al conservante","Indispensabile per la ricostituzione dei peptidi"],researchGuide:"Utilizzare l'acqua batteriostatica per ricostituire i peptidi liofilizzati. Prelevare la quantità desiderata con una siringa sterile, iniettarla lentamente lungo la parete nel flaconcino del peptide e agitare delicatamente per rotazione. Non scuotere.",faq:[{question:"Cos'è l'acqua batteriostatica?",answer:"L'acqua batteriostatica è acqua sterile con alcol benzilico allo 0,9%, che inibisce la crescita batterica consentendo così l'uso multiplo dallo stesso flaconcino."},{question:"Quanto dura un peptide ricostituito?",answer:"I peptidi ricostituiti con acqua batteriostatica e conservati a 2-8 °C rimangono generalmente stabili per 28-30 giorni."}],tags:["accessorio","ricostituzione","acqua"]},"cjc-1295-ipamorelin":{name:"Miscela CJC-1295 + Ipamorelin",description:"Miscela da ricerca di CJC-1295 (senza DAC) e Ipamorelin, 5mg per sostanza per flaconcino da 10mg. Un analogo del GHRH abbinato a un secretagogo selettivo del recettore della grelina per studi sulla via dell'ormone della crescita e sul metabolismo.",longDescription:"Questa miscela da ricerca combina CJC-1295 (senza DAC), un analogo sintetico dell'ormone di rilascio dell'ormone della crescita (GHRH), con Ipamorelin, un secretagogo selettivo del recettore della grelina/GHS-R1a, con 5mg di ciascuna sostanza per flaconcino da 10mg. Entrambi agiscono su vie complementari: CJC-1295 agisce sul recettore del GHRH, mentre Ipamorelin agisce sul recettore della grelina, una combinazione studiata per la loro azione congiunta sul rilascio pulsatile dell'ormone della crescita. Viene fornita a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca su via doppia dei secretagoghi del GH (GHRH + recettore della grelina)","Studi sul rilascio pulsatile dell'ormone della crescita","Segnalazione selettiva del GH con effetti ormonali off-target minimi negli studi","Studi sulle vie di regolazione metabolica e composizione corporea","Miscela in flaconcino singolo da 5mg + 5mg per disegni di studio con secretagoghi combinati"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. Ogni flaconcino da 10mg contiene 5mg di CJC-1295 e 5mg di Ipamorelin. Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Cosa è incluso nella miscela CJC-1295 + Ipamorelin?",answer:"Ogni flaconcino da 10mg contiene 5mg di CJC-1295 (senza DAC) e 5mg di Ipamorelin, co-liofilizzati in un'unica miscela."},{question:"Perché CJC-1295 e Ipamorelin vengono studiati insieme?",answer:"CJC-1295 è un analogo del GHRH e Ipamorelin è un secretagogo selettivo del recettore della grelina/GHS-R1a. Poiché agiscono su vie complementari, i ricercatori studiano la coppia per esplorarne l'azione congiunta sul rilascio pulsatile dell'ormone della crescita."},{question:"Come devo conservare la miscela?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["metabolico","GHRH","grelina","ormone della crescita","secretagogo","miscela","peptide da ricerca"],aka:["CJC-1295 / Ipamorelin","CJC-1295 No DAC + Ipamorelin","Miscela di secretagoghi del GH"],whatIs:"La miscela CJC-1295 + Ipamorelin è una sostanza da ricerca che abbina un analogo dell'ormone di rilascio dell'ormone della crescita (GHRH) a un secretagogo selettivo del recettore della grelina (GHS-R1a), con 5mg di ciascuna sostanza per flaconcino da 10mg. Viene impiegata per lo studio in-vitro della segnalazione combinata della via dell'ormone della crescita. Fornita esclusivamente per la ricerca di laboratorio.",mechanism:"Nella ricerca pubblicata le due sostanze agiscono su recettori distinti che convergono sul rilascio dell'ormone della crescita dalle cellule somatotrope dell'ipofisi. Per CJC-1295, un analogo del GHRH, è stato riferito un aumento prolungato dell'ormone della crescita e dell'IGF-I in adulti sani, mentre Ipamorelin è stato caratterizzato come il primo secretagogo selettivo dell'ormone della crescita, capace di stimolare il rilascio di GH senza influenzare in modo significativo ACTH o cortisolo. La miscela è studiata per capire come queste vie del GHRH e del recettore della grelina possano interagire; i meccanismi combinati e gli esiti nell'uomo non sono dimostrati.",receptorTargets:["Recettore del GHRH","Recettore della grelina/GHS-R1a","Rilascio di GH dalle cellule somatotrope ipofisarie","Asse IGF-1"],blendComposition:[{name:"CJC-1295 (No DAC)",role:"Analogo del GHRH",amount:"5mg"},{name:"Ipamorelin",role:"Agonista della grelina",amount:"5mg"}],specs:[{label:"Composizione",value:"5mg CJC-1295 (senza DAC) + 5mg Ipamorelin"},{label:"Classe di CJC-1295",value:"Analogo sintetico del GHRH(1-29) (modificato, senza DAC)"},{label:"Classe di Ipamorelin",value:"Secretagogo del GH pentapeptidico sintetico (GHRP)"},{label:"Quantità totale per flaconcino",value:"10mg di miscela co-liofilizzata"},{label:"Aspetto",value:"Polvere liofilizzata bianca"},{label:"Solubilità",value:"Solubile in acqua batteriostatica"}],researchApplications:[{title:"Rilascio dell'ormone della crescita",description:"Studiata per l'effetto combinato della stimolazione dei recettori del GHRH e della grelina sulla secrezione pulsatile di GH."},{title:"Regolazione metabolica",description:"Impiegata nella ricerca sull'asse GH/IGF-1 e sugli endpoint metabolici e di composizione corporea a valle."},{title:"Farmacologia recettoriale",description:"Applicata per lo studio in parallelo della segnalazione sul recettore del GHRH e sul recettore della grelina/GHS-R1a."},{title:"Selettività dei secretagoghi",description:"Esplorata in disegni di studio che confrontano il rilascio selettivo di GH con gli effetti off-target sugli ormoni ipofisari."}],keyStudies:[{title:"Stimolazione prolungata della secrezione di ormone della crescita (GH) e di fattore di crescita insulino-simile I da parte di CJC-1295, un analogo a lunga durata d'azione dell'ormone di rilascio del GH, in adulti sani",source:"Journal of Clinical Endocrinology & Metabolism",year:2006,url:"https://pubmed.ncbi.nlm.nih.gov/16352683/",finding:"Ha riferito che CJC-1295 sottocutaneo produceva aumenti prolungati e dose-dipendenti di ormone della crescita e IGF-I in adulti sani."},{title:"Ipamorelin, il primo secretagogo selettivo dell'ormone della crescita",source:"European Journal of Endocrinology",year:1998,url:"https://pubmed.ncbi.nlm.nih.gov/9849822/",finding:"Ha caratterizzato Ipamorelin come il primo secretagogo selettivo dell'ormone della crescita, riferendo un rilascio di GH paragonabile al GHRH senza un aumento significativo di ACTH o cortisolo."}],reconstitution:"Di norma ricostituita con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C.",howSupplied:"Fornita come singolo flaconcino sigillato contenente 5mg di CJC-1295 e 5mg di Ipamorelin come polvere bianca co-liofilizzata. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata.",comparison:{heading:"CJC-1295 + Ipamorelin vs. le singole sostanze",columns:["","Miscela","CJC-1295 (senza DAC)","Ipamorelin"],rows:[{label:"Bersaglio recettoriale",values:["GHRH + grelina (GHS-R1a)","Recettore del GHRH","Grelina / GHS-R1a"]},{label:"Classe",values:["Analogo del GHRH + GHRP","Analogo del GHRH(1-29)","Secretagogo selettivo del GH"]},{label:"Quantità per flaconcino",values:["5mg + 5mg (10mg)","5mg / 10mg","10mg"]},{label:"Focus di ricerca",values:["Via combinata del GH","Rilascio pulsatile di GH","Rilascio selettivo di GH"]}]}},"glp-2-tz":{name:"GLP-2 (TZ)",description:"Doppio agonista dei recettori GIP e GLP-1, fornito come standard di riferimento liofilizzato per la ricerca sulle vie metaboliche e sulla composizione corporea. Disponibile in 13 formati da 5mg a 120mg.",longDescription:"GLP-2 (TZ) è un doppio agonista sintetico dei recettori delle incretine che, da un unico peptide, agisce sia sul recettore del polipeptide insulinotropico glucosio-dipendente (GIP) sia sul recettore del peptide-1 glucagone-simile (GLP-1). Nella farmacologia pubblicata è stato progettato come peptide modificato con acido grasso per un'esposizione prolungata ed è stato studiato per la sua azione combinata sulla segnalazione delle incretine, sulla gestione del glucosio e sul peso corporeo in modelli di ricerca animali e clinici. Viene fornito a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca su doppio agonista dei recettori delle incretine (GIP + GLP-1)","Studi sulle vie di segnalazione insulinica glucosio-dipendente","Ricerca su composizione corporea e obesità","Studi su regolazione metabolica e omeostasi energetica","13 formati (da 5mg a 120mg) per disegni di studio a dosi graduate"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. GLP-2 (TZ) viene fornito come polvere liofilizzata. Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Su quali recettori agisce GLP-2 (TZ)?",answer:"GLP-2 (TZ) è un doppio agonista che agisce sia sul recettore GIP (polipeptide insulinotropico glucosio-dipendente) sia sul recettore GLP-1 (peptide-1 glucagone-simile), due vie delle incretine studiate insieme per la loro azione combinata sulla gestione del glucosio e sul peso corporeo."},{question:"Quali sono il peso molecolare e la formula di GLP-2 (TZ)?",answer:"GLP-2 (TZ) ha formula molecolare C225H348N48O68 e un peso molecolare di circa 4813,5 g/mol (PubChem CID 166567236). È noto anche con il codice di sviluppo LY3298176."},{question:"Qual è la purezza del GLP-2 (TZ) di Miro Biotech?",answer:"Ogni lotto viene testato in modo indipendente da un laboratorio terzo e verificato al 99,27% di purezza, con un certificato di analisi per il lotto."},{question:"Come va conservato GLP-2 (TZ)?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["metabolico","GIP","GLP-1","incretina","doppio agonista","riduzione del peso","peptide da ricerca"],aka:["LY3298176","Doppio agonista dei recettori GIP/GLP-1","Co-agonista GIP/GLP-1"],whatIs:"GLP-2 (TZ) è un doppio agonista sintetico dei recettori delle incretine che, da un unico peptide, attiva sia il recettore GIP sia il recettore GLP-1. Viene impiegato come sostanza da ricerca in studi su segnalazione delle incretine, regolazione del glucosio e composizione corporea. Fornito esclusivamente per la ricerca in-vitro e di laboratorio.",mechanism:"Nella ricerca pubblicata GLP-2 (TZ) è stato caratterizzato come un peptide modificato con acido grasso che lega e attiva il recettore GIP e il recettore GLP-1, due vie delle incretine che convergono sulla segnalazione insulinica glucosio-dipendente. La farmacologia in fase di scoperta ha riferito un'attività di doppio agonismo su entrambi i recettori, e studi controllati successivi hanno osservato variazioni del peso corporeo nei periodi studiati. I meccanismi a lungo termine e gli esiti corrispondenti nell'uomo sono tuttora oggetto di studio.",receptorTargets:["Recettore GIP","Recettore GLP-1","Asse di segnalazione delle incretine","Secrezione insulinica glucosio-dipendente"],specs:[{label:"Classificazione",value:"Peptide sintetico doppio agonista dei recettori GIP/GLP-1"},{label:"Codice di sviluppo",value:"LY3298176"},{label:"Aspetto",value:"Polvere liofilizzata bianca"},{label:"Solubilità",value:"Solubile in acqua batteriostatica"}],researchApplications:[{title:"Farmacologia dei recettori delle incretine",description:"Impiegato per lo studio della segnalazione in parallelo sul recettore GIP e sul recettore GLP-1 a partire da un unico peptide doppio agonista."},{title:"Metabolismo del glucosio",description:"Applicato nella ricerca sulla secrezione insulinica glucosio-dipendente e sulla regolazione metabolica."},{title:"Composizione corporea",description:"Studiato in modelli di ricerca animali e clinici per gli effetti su peso corporeo e adiposità."},{title:"Studi comparativi tra agonisti",description:"Esplorato accanto agli agonisti a singola incretina per confrontare l'attività a doppia via con quella a via singola."}],keyStudies:[{title:"LY3298176, un innovativo doppio agonista dei recettori GIP e GLP-1 per il trattamento del diabete mellito di tipo 2: dalla scoperta alla prova di concetto clinica",source:"Molecular Metabolism",year:2018,url:"https://pubmed.ncbi.nlm.nih.gov/30473097/",finding:"Ha riferito la scoperta e la caratterizzazione farmacologica di LY3298176, un peptide modificato con acido grasso progettato come doppio agonista dei recettori GIP e GLP-1."},{title:"SURMOUNT-1: studio di fase 3 sull'obesità con LY3298176 una volta a settimana",source:"New England Journal of Medicine",year:2022,url:"https://pubmed.ncbi.nlm.nih.gov/35658024/",finding:"Nello studio randomizzato SURMOUNT-1 si è osservato che il duplice agonista GIP/GLP-1 una volta a settimana per 72 settimane produceva, rispetto al placebo, riduzioni medie considerevoli del peso corporeo alle dosi studiate."}],reconstitution:"Di norma ricostituito con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C.",howSupplied:"Fornito come singolo flaconcino sigillato contenente polvere liofilizzata bianca di GLP-2 (TZ) nel formato scelto. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata.",comparison:{heading:"GLP-2 (TZ) vs. gli agonisti a singola incretina nella ricerca",columns:["","GLP-2 (TZ)","Agonista del GLP-1","Agonista del GIP"],rows:[{label:"Bersaglio recettoriale",values:["GIP + GLP-1","Recettore GLP-1","Recettore GIP"]},{label:"Classe",values:["Doppio agonista delle incretine","Agonista a singola incretina","Agonista a singola incretina"]},{label:"Focus di ricerca",values:["Segnalazione combinata delle incretine","Via del GLP-1","Via del GIP"]},{label:"Vie interessate",values:["Due","Una","Una"]}]}},klow:{name:"Miscela KLOW",description:"Miscela da ricerca a quattro peptidi di TB-500, BPC-157, GHK-Cu e KPV, co-liofilizzati in un unico flaconcino da 80mg per studi combinati sulle vie di riparazione dei tessuti e antinfiammatorie.",longDescription:"La miscela KLOW combina quattro peptidi da ricerca in un flaconcino da 80mg: TB-500 (10mg), un frammento della timosina beta-4, studiato per migrazione cellulare e angiogenesi; BPC-157 (10mg), un pentadecapeptide gastrico stabile, studiato per la riparazione dei tessuti; GHK-Cu (50mg), un tripeptide legante il rame, studiato per il rimodellamento tissutale; e KPV (10mg), un tripeptide dell'alfa-MSH, studiato per l'attività antinfiammatoria. I quattro sono abbinati per studiare vie rigenerative e infiammatorie complementari in un unico disegno di studio. Viene fornita a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca sulla riparazione dei tessuti a quattro componenti in un unico flaconcino","Studi combinati sulle vie dell'angiogenesi e della migrazione cellulare","Ricerca su guarigione delle ferite e rimodellamento tissutale","Studi sulle vie antinfiammatorie (componente KPV)","Miscela co-liofilizzata per disegni di studio con vie combinate"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. Ogni flaconcino da 80mg contiene 10mg di TB-500, 10mg di BPC-157, 50mg di GHK-Cu e 10mg di KPV. Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Cosa è incluso nella miscela KLOW?",answer:"Ogni flaconcino da 80mg contiene 10mg di TB-500, 10mg di BPC-157, 50mg di GHK-Cu e 10mg di KPV, co-liofilizzati in un'unica miscela."},{question:"Perché questi quattro peptidi vengono studiati insieme?",answer:"Nella ricerca pubblicata ogni componente è associato a una propria via di riparazione o di infiammazione. TB-500 e BPC-157 sono studiati per la riparazione dei tessuti, GHK-Cu per il rimodellamento tissutale e KPV per l'attività antinfiammatoria, così la miscela viene impiegata per studiare queste vie complementari in un unico disegno di studio."},{question:"Come va conservata la miscela?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["guarigione","riparazione dei tessuti","antinfiammatorio","rigenerazione","miscela","peptide da ricerca"],aka:["KLOW Healing Blend","Miscela TB-500 / BPC-157 / GHK-Cu / KPV"],whatIs:"La miscela KLOW è una sostanza da ricerca che combina quattro peptidi (TB-500, BPC-157, GHK-Cu e KPV) co-liofilizzati in un flaconcino da 80mg. Viene impiegata per lo studio in-vitro delle vie combinate di riparazione dei tessuti, rimodellamento tissutale e attività antinfiammatoria. Fornita esclusivamente per la ricerca di laboratorio.",mechanism:"Nella ricerca pubblicata ogni componente agisce su una propria via. Per la timosina beta-4 (l'origine di TB-500) è stato riferito che sostiene la migrazione cellulare e l'angiogenesi; BPC-157 è stato associato a una guarigione tissutale accelerata nei modelli animali; GHK-Cu è stato descritto nella ricerca su rimodellamento tissutale e riparazione delle ferite; e per KPV è stato riferito che riduce i marcatori infiammatori tramite il trasportatore PepT1. La miscela è studiata per capire come queste vie possano agire in parallelo; i meccanismi combinati e gli esiti nell'uomo non sono dimostrati.",receptorTargets:["Vie di sequestro dell'actina / migrazione cellulare (TB-500)","Vie di angiogenesi e riparazione dei tessuti (BPC-157)","Rimodellamento tissutale rame-dipendente (GHK-Cu)","Trasportatore PepT1 e segnalazione infiammatoria (KPV)"],blendComposition:[{name:"TB-500",role:"Frammento della timosina β4",amount:"10mg"},{name:"BPC-157",role:"Pentadecapeptide gastrico",amount:"10mg"},{name:"GHK-Cu",role:"Tripeptide di rame",amount:"50mg"},{name:"KPV",role:"Tripeptide dell'α-MSH",amount:"10mg"}],specs:[{label:"Composizione",value:"10mg TB-500 + 10mg BPC-157 + 50mg GHK-Cu + 10mg KPV"},{label:"Quantità totale per flaconcino",value:"80mg di miscela co-liofilizzata"},{label:"Componenti",value:"Quattro peptidi da ricerca"},{label:"Aspetto",value:"Polvere liofilizzata da bianca ad azzurro pallido (contenuto di rame)"},{label:"Solubilità",value:"Solubile in acqua batteriostatica"}],researchApplications:[{title:"Riparazione dei tessuti",description:"Studiata per gli effetti combinati di TB-500 e BPC-157 su migrazione cellulare e guarigione delle ferite."},{title:"Rimodellamento tissutale",description:"Impiegata nella ricerca su GHK-Cu e sulle vie di rimodellamento rame-dipendenti."},{title:"Infiammazione",description:"Applicata per lo studio dell'attività antinfiammatoria associata alla componente KPV."},{title:"Disegni con vie combinate",description:"Esplorata in disegni di studio che confrontano i singoli peptidi con una miscela a più componenti."}],keyStudies:[{title:"Il pentadecapeptide gastrico stabile BPC 157 e la guarigione delle ferite",source:"Frontiers in Pharmacology",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34267654/",finding:"Ha esaminato i dati preclinici in cui BPC-157 è stato associato a una guarigione accelerata in modelli di lesione di cute, muscolo, tendine e altri tessuti negli animali."},{title:"Studi su animali con timosina beta, un peptide multifunzionale per la riparazione e la rigenerazione dei tessuti",source:"Annals of the New York Academy of Sciences",year:2010,url:"https://pubmed.ncbi.nlm.nih.gov/20536453/",finding:"Ha riassunto studi su modelli animali in cui è stato riferito che la timosina beta-4 (l'origine di TB-500) sostiene migrazione cellulare, angiogenesi e riparazione dei tessuti."},{title:"Il tripeptide umano GHK e il rimodellamento tissutale",source:"Journal of Biomaterials Science, Polymer Edition",year:2008,url:"https://pubmed.ncbi.nlm.nih.gov/18644225/",finding:"Ha esaminato il tripeptide legante il rame GHK e i suoi ruoli riferiti nella ricerca su rimodellamento tissutale e riparazione delle ferite."},{title:"L'assorbimento mediato da PepT1 del tripeptide KPV riduce l'infiammazione intestinale",source:"Gastroenterology",year:2008,url:"https://pubmed.ncbi.nlm.nih.gov/18061177/",finding:"Ha riferito che il tripeptide KPV veniva assorbito tramite PepT1 e riduceva i marcatori infiammatori in modelli cellulari e murini."}],reconstitution:"Di norma ricostituita con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C.",howSupplied:"Fornita come singolo flaconcino sigillato contenente 10mg di TB-500, 10mg di BPC-157, 50mg di GHK-Cu e 10mg di KPV come polvere co-liofilizzata. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata.",comparison:{heading:"KLOW vs. le altre miscele da ricerca",columns:["","KLOW","GLOW","BPC-157 + TB-500"],rows:[{label:"Componenti",values:["TB-500, BPC-157, GHK-Cu, KPV","TB-500, BPC-157, GHK-Cu","BPC-157, TB-500"]},{label:"Numero di componenti",values:["4","3","2"]},{label:"Totale per flaconcino",values:["80mg","70mg","10mg / 20mg"]},{label:"Focus aggiuntivo",values:["Antinfiammatorio (KPV)","Rimodellamento (GHK-Cu)","Riparazione duale focalizzata"]}]}},glow:{name:"Miscela GLOW",description:"Miscela da ricerca a tre peptidi di TB-500, BPC-157 e GHK-Cu, co-liofilizzati in un unico flaconcino da 70mg per studi combinati sulle vie di riparazione e rimodellamento dei tessuti.",longDescription:"La miscela GLOW combina tre peptidi da ricerca in un flaconcino da 70mg: TB-500 (10mg), un frammento della timosina beta-4, studiato per migrazione cellulare e angiogenesi; BPC-157 (10mg), un pentadecapeptide gastrico stabile, studiato per la riparazione dei tessuti; e GHK-Cu (50mg), un tripeptide legante il rame, studiato per il rimodellamento tissutale e la ricerca sul collagene. I tre sono abbinati per studiare vie di riparazione e rimodellamento complementari in un unico disegno di studio. Viene fornita a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca sulla riparazione dei tessuti a tre componenti in un unico flaconcino","Studi combinati sulle vie dell'angiogenesi e della migrazione cellulare","Ricerca su rimodellamento tissutale e collagene (componente GHK-Cu)","Studi sulle vie di guarigione delle ferite","Miscela co-liofilizzata per disegni di studio con vie combinate"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. Ogni flaconcino da 70mg contiene 10mg di TB-500, 10mg di BPC-157 e 50mg di GHK-Cu. Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Cosa è incluso nella miscela GLOW?",answer:"Ogni flaconcino da 70mg contiene 10mg di TB-500, 10mg di BPC-157 e 50mg di GHK-Cu, co-liofilizzati in un'unica miscela."},{question:"In cosa GLOW si differenzia da KLOW?",answer:"GLOW contiene tre componenti (TB-500, BPC-157, GHK-Cu), mentre KLOW ne aggiunge un quarto, KPV, per la ricerca sulle vie antinfiammatorie. GLOW si concentra su riparazione e rimodellamento dei tessuti."},{question:"Come va conservata la miscela?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["guarigione","riparazione dei tessuti","rimodellamento tissutale","rigenerazione","miscela","peptide da ricerca"],aka:["GLOW Healing Blend","Miscela TB-500 / BPC-157 / GHK-Cu"],whatIs:"La miscela GLOW è una sostanza da ricerca che combina tre peptidi (TB-500, BPC-157 e GHK-Cu) co-liofilizzati in un flaconcino da 70mg. Viene impiegata per lo studio in-vitro delle vie combinate di riparazione e rimodellamento dei tessuti. Fornita esclusivamente per la ricerca di laboratorio.",mechanism:"Nella ricerca pubblicata per la timosina beta-4 (l'origine di TB-500) è stato riferito che sostiene migrazione cellulare e angiogenesi, BPC-157 è stato associato a una guarigione tissutale accelerata nei modelli animali e GHK-Cu è stato descritto nella ricerca su rimodellamento tissutale e riparazione delle ferite. La miscela è studiata per capire come queste vie di riparazione e rimodellamento possano agire in parallelo; i meccanismi combinati e gli esiti nell'uomo non sono dimostrati.",receptorTargets:["Vie di sequestro dell'actina / migrazione cellulare (TB-500)","Vie di angiogenesi e riparazione dei tessuti (BPC-157)","Rimodellamento tissutale rame-dipendente (GHK-Cu)","Vie di sintesi del collagene e della matrice"],blendComposition:[{name:"TB-500",role:"Frammento della timosina β4",amount:"10mg"},{name:"BPC-157",role:"Pentadecapeptide gastrico",amount:"10mg"},{name:"GHK-Cu",role:"Tripeptide di rame",amount:"50mg"}],specs:[{label:"Composizione",value:"10mg TB-500 + 10mg BPC-157 + 50mg GHK-Cu"},{label:"Quantità totale per flaconcino",value:"70mg di miscela co-liofilizzata"},{label:"Componenti",value:"Tre peptidi da ricerca"},{label:"Aspetto",value:"Polvere liofilizzata da bianca ad azzurro pallido (contenuto di rame)"},{label:"Solubilità",value:"Solubile in acqua batteriostatica"}],researchApplications:[{title:"Riparazione dei tessuti",description:"Studiata per gli effetti combinati di TB-500 e BPC-157 su migrazione cellulare e guarigione delle ferite."},{title:"Rimodellamento tissutale",description:"Impiegata nella ricerca su GHK-Cu, sulla sintesi del collagene e sulle vie di rimodellamento rame-dipendenti."},{title:"Angiogenesi",description:"Applicata per lo studio delle vie di formazione dei vasi sanguigni associate ai componenti."},{title:"Disegni con vie combinate",description:"Esplorata in disegni di studio che confrontano i singoli peptidi con una miscela a più componenti."}],keyStudies:[{title:"Il pentadecapeptide gastrico stabile BPC 157 e la guarigione delle ferite",source:"Frontiers in Pharmacology",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34267654/",finding:"Ha esaminato i dati preclinici in cui BPC-157 è stato associato a una guarigione accelerata in modelli di lesione di cute, muscolo, tendine e altri tessuti negli animali."},{title:"Studi su animali con timosina beta, un peptide multifunzionale per la riparazione e la rigenerazione dei tessuti",source:"Annals of the New York Academy of Sciences",year:2010,url:"https://pubmed.ncbi.nlm.nih.gov/20536453/",finding:"Ha riassunto studi su modelli animali in cui è stato riferito che la timosina beta-4 (l'origine di TB-500) sostiene migrazione cellulare, angiogenesi e riparazione dei tessuti."},{title:"Il tripeptide umano GHK e il rimodellamento tissutale",source:"Journal of Biomaterials Science, Polymer Edition",year:2008,url:"https://pubmed.ncbi.nlm.nih.gov/18644225/",finding:"Ha esaminato il tripeptide legante il rame GHK e i suoi ruoli riferiti nella ricerca su rimodellamento tissutale e riparazione delle ferite."}],reconstitution:"Di norma ricostituita con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C.",howSupplied:"Fornita come singolo flaconcino sigillato contenente 10mg di TB-500, 10mg di BPC-157 e 50mg di GHK-Cu come polvere co-liofilizzata. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata.",comparison:{heading:"GLOW vs. le altre miscele da ricerca",columns:["","GLOW","KLOW","BPC-157 + TB-500"],rows:[{label:"Componenti",values:["TB-500, BPC-157, GHK-Cu","TB-500, BPC-157, GHK-Cu, KPV","BPC-157, TB-500"]},{label:"Numero di componenti",values:["3","4","2"]},{label:"Totale per flaconcino",values:["70mg","80mg","10mg / 20mg"]},{label:"Focus aggiuntivo",values:["Rimodellamento (GHK-Cu)","Antinfiammatorio (KPV)","Riparazione duale focalizzata"]}]}},"bpc-157-tb-500":{name:"Miscela BPC-157 + TB-500",description:"Miscela da ricerca a doppio peptide di BPC-157 e TB-500 in rapporto 50/50, co-liofilizzati per studi focalizzati sulle vie di riparazione e rigenerazione dei tessuti. Disponibile in flaconcini da 10mg e 20mg.",longDescription:"Questa miscela da ricerca abbina BPC-157, un pentadecapeptide gastrico stabile studiato per la riparazione dei tessuti, con TB-500, un frammento della timosina beta-4 studiato per migrazione cellulare e angiogenesi, in rapporto 50/50 per flaconcino. I due sono combinati per studiare una riparazione dei tessuti focalizzata e duale su due vie in un unico disegno di studio. Viene fornita a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca focalizzata sulla riparazione dei tessuti su due vie","Studi combinati su angiogenesi e migrazione cellulare","Ricerca sulle vie di guarigione delle ferite e riparazione dei tendini","Due componenti in un unico flaconcino co-liofilizzato","Rapporto 50/50 per disegni bilanciati con vie combinate"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. Ogni flaconcino contiene BPC-157 e TB-500 in rapporto 50/50 (5mg + 5mg per flaconcino da 10mg). Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Cosa è incluso nella miscela BPC-157 + TB-500?",answer:"Ogni flaconcino contiene BPC-157 e TB-500 in rapporto 50/50. Il flaconcino da 10mg contiene 5mg di ciascuna sostanza e il flaconcino da 20mg 10mg di ciascuna sostanza, co-liofilizzati in un'unica miscela."},{question:"Perché BPC-157 e TB-500 vengono studiati insieme?",answer:"BPC-157 è studiato per la riparazione dei tessuti e TB-500 per migrazione cellulare e angiogenesi. Poiché sono associati a vie di riparazione complementari, i ricercatori studiano la coppia per esplorare una riparazione dei tessuti focalizzata e duale su due vie."},{question:"Come va conservata la miscela?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["guarigione","riparazione dei tessuti","rigenerazione","miscela","peptide da ricerca"],aka:["Miscela BPC-157 / TB-500","BPC + TB Healing Blend"],whatIs:"La miscela BPC-157 + TB-500 è una sostanza da ricerca che abbina due peptidi per la riparazione dei tessuti in rapporto 50/50 per flaconcino. Viene impiegata per lo studio in-vitro di una riparazione dei tessuti focalizzata e duale su due vie. Fornita esclusivamente per la ricerca di laboratorio.",mechanism:"Nella ricerca pubblicata BPC-157 è stato associato a una guarigione tissutale accelerata in vari modelli animali di lesione, mentre per la timosina beta-4 (l'origine di TB-500) è stato riferito che sostiene migrazione cellulare, angiogenesi e riparazione dei tessuti. La miscela è studiata per capire come queste due vie di riparazione possano agire insieme; i meccanismi combinati e gli esiti nell'uomo non sono dimostrati.",receptorTargets:["Vie di angiogenesi e riparazione dei tessuti (BPC-157)","Vie di sequestro dell'actina / migrazione cellulare (TB-500)","Segnalazione della guarigione delle ferite","Vie di riparazione di tendini e muscoli"],blendComposition:[{name:"BPC-157",role:"Pentadecapeptide gastrico",amount:"50%"},{name:"TB-500",role:"Frammento della timosina β4",amount:"50%"}],specs:[{label:"Composizione",value:"BPC-157 + TB-500 (rapporto 50/50)"},{label:"Quantità per flaconcino",value:"5mg + 5mg (10mg) oppure 10mg + 10mg (20mg)"},{label:"Componenti",value:"Due peptidi da ricerca"},{label:"Aspetto",value:"Polvere liofilizzata bianca"},{label:"Solubilità",value:"Solubile in acqua batteriostatica"}],researchApplications:[{title:"Riparazione dei tessuti",description:"Studiata per l'azione combinata di BPC-157 e TB-500 su guarigione delle ferite e rigenerazione."},{title:"Migrazione cellulare",description:"Impiegata nella ricerca sulle vie di sequestro dell'actina e di migrazione cellulare associate a TB-500."},{title:"Angiogenesi",description:"Applicata per lo studio delle vie di formazione dei vasi sanguigni associate a entrambi i componenti."},{title:"Disegni con vie combinate",description:"Esplorata in disegni di studio che confrontano i singoli peptidi con una miscela duale bilanciata."}],keyStudies:[{title:"Il pentadecapeptide gastrico stabile BPC 157 e la guarigione delle ferite",source:"Frontiers in Pharmacology",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34267654/",finding:"Ha esaminato i dati preclinici in cui BPC-157 è stato associato a una guarigione accelerata in modelli di lesione di cute, muscolo, tendine e altri tessuti negli animali."},{title:"Studi su animali con timosina beta, un peptide multifunzionale per la riparazione e la rigenerazione dei tessuti",source:"Annals of the New York Academy of Sciences",year:2010,url:"https://pubmed.ncbi.nlm.nih.gov/20536453/",finding:"Ha riassunto studi su modelli animali in cui è stato riferito che la timosina beta-4 (l'origine di TB-500) sostiene migrazione cellulare, angiogenesi e riparazione dei tessuti."},{title:"Timosina beta4: un peptide rigenerativo multifunzionale. Proprietà fondamentali e applicazioni cliniche",source:"Expert Opinion on Biological Therapy",year:2012,url:"https://pubmed.ncbi.nlm.nih.gov/22074294/",finding:"Ha esaminato le proprietà biochimiche e i meccanismi della timosina beta-4 come peptide sequestrante l'actina e rigenerativo alla base della ricerca sulla riparazione delle ferite."}],reconstitution:"Di norma ricostituita con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C.",howSupplied:"Fornita come singolo flaconcino sigillato contenente BPC-157 e TB-500 in rapporto 50/50 come polvere bianca co-liofilizzata. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata.",comparison:{heading:"BPC-157 + TB-500 vs. le miscele da ricerca più ampie",columns:["","BPC-157 + TB-500","GLOW","KLOW"],rows:[{label:"Componenti",values:["BPC-157, TB-500","TB-500, BPC-157, GHK-Cu","TB-500, BPC-157, GHK-Cu, KPV"]},{label:"Numero di componenti",values:["2","3","4"]},{label:"Totale per flaconcino",values:["10mg / 20mg","70mg","80mg"]},{label:"Focus di ricerca",values:["Riparazione duale focalizzata","Riparazione + rimodellamento","Riparazione + rimodellamento + antinfiammatorio"]}]}},kpv:{name:"KPV",description:"Tripeptide antinfiammatorio (Lys-Pro-Val), il frammento C-terminale dell'alfa-MSH, fornito come standard di riferimento liofilizzato per la ricerca su immunomodulazione e infiammazione intestinale.",longDescription:"KPV è un tripeptide (Lys-Pro-Val) corrispondente al frammento C-terminale dell'ormone alfa-melanocita-stimolante (alfa-MSH). È stato studiato per l'attività antinfiammatoria, incluso l'assorbimento tramite il trasportatore PepT1 e gli effetti sui marcatori infiammatori in modelli cellulari e animali di colite. Viene fornito a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca sulle vie antinfiammatorie","Studi sull'immunomodulazione","Ricerca su infiammazione intestinale","Studi sull'assorbimento tramite il trasportatore PepT1","Ricerca sul frammento C-terminale dell'alfa-MSH"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. KPV viene fornito come polvere liofilizzata. Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Cos'è KPV?",answer:"KPV è un tripeptide (Lys-Pro-Val) corrispondente al frammento C-terminale (11-13) dell'ormone alfa-melanocita-stimolante (alfa-MSH), studiato per l'attività antinfiammatoria."},{question:"Quali sono il peso molecolare e la formula di KPV?",answer:"KPV ha formula molecolare C16H30N4O4 e un peso molecolare di circa 342,43 g/mol (PubChem CID 125672). La sua sequenza è Lys-Pro-Val."},{question:"Qual è la purezza del KPV di Miro Biotech?",answer:"Ogni lotto viene testato in modo indipendente da un laboratorio terzo e verificato al 99,41% di purezza, con un certificato di analisi per il lotto."},{question:"Come va conservato KPV?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["antinfiammatorio","immunitario","salute intestinale","tripeptide","peptide da ricerca"],aka:["Lys-Pro-Val","Alfa-MSH (11-13)","Tripeptide KPV"],whatIs:"KPV è un tripeptide (Lys-Pro-Val), il frammento C-terminale dell'alfa-MSH, impiegato come sostanza da ricerca in studi su vie antinfiammatorie e immunomodulanti. Fornito esclusivamente per la ricerca in-vitro e di laboratorio.",mechanism:"Nella ricerca pubblicata è stato riferito che KPV viene assorbito nelle cellule epiteliali e immunitarie intestinali tramite il trasportatore PepT1 e, in questo contesto, riduce i marcatori infiammatori in modelli cellulari e murini di colite. Altra ricerca ha descritto un profilo antinfiammatorio distinguibile da quello dei peptidi melanocortinici centrali. Queste vie sono studiate in modelli di infiammazione intestinale e immunitaria; i meccanismi corrispondenti nell'uomo non sono dimostrati.",receptorTargets:["Trasportatore di peptidi PepT1","Segnalazione infiammatoria NF-kB","Via della melanocortina (frammento dell'alfa-MSH)","Cellule epiteliali e immunitarie intestinali"],specs:[{label:"Sequenza",value:"Lys-Pro-Val (KPV)"},{label:"Classificazione",value:"Tripeptide, frammento C-terminale dell'alfa-MSH"},{label:"Aspetto",value:"Polvere liofilizzata bianca"},{label:"Solubilità",value:"Solubile in acqua batteriostatica"}],researchApplications:[{title:"Infiammazione intestinale",description:"Impiegato nella ricerca sui marcatori infiammatori in modelli cellulari e animali di colite."},{title:"Immunomodulazione",description:"Studiato per l'attività antinfiammatoria come frammento C-terminale dell'alfa-MSH."},{title:"Assorbimento tramite trasportatore",description:"Applicato per lo studio dell'assorbimento mediato da PepT1 nelle cellule epiteliali e immunitarie."},{title:"Farmacologia della melanocortina",description:"Esplorato accanto ai peptidi melanocortinici centrali per confrontare i profili antinfiammatori."}],keyStudies:[{title:"L'assorbimento mediato da PepT1 del tripeptide KPV riduce l'infiammazione intestinale",source:"Gastroenterology",year:2008,url:"https://pubmed.ncbi.nlm.nih.gov/18061177/",finding:"Ha riferito che KPV veniva assorbito nelle cellule epiteliali e immunitarie intestinali tramite il trasportatore PepT1 e, in questo contesto, riduceva i marcatori infiammatori in modelli cellulari e murini di colite."},{title:"Scomposizione dell'azione antinfiammatoria dei peptidi centrali e C-terminale (KPV) dell'ormone alfa-melanocita-stimolante",source:"Journal of Pharmacology and Experimental Therapeutics",year:2003,url:"https://pubmed.ncbi.nlm.nih.gov/12750433/",finding:"Ha osservato che il tripeptide C-terminale dell'alfa-MSH KPV presentava, nei modelli studiati, un profilo antinfiammatorio distinguibile da quello dei peptidi melanocortinici centrali."}],reconstitution:"Di norma ricostituito con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C.",howSupplied:"Fornito come singolo flaconcino sigillato contenente polvere liofilizzata bianca di KPV. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata."},glutathione:{name:"Glutatione",description:"Tripeptide antiossidante per eccellenza (gamma-Glu-Cys-Gly), fornito come standard di riferimento liofilizzato per la ricerca su stress ossidativo, biologia redox e detossificazione. Disponibile in flaconcini da 600mg e 1500mg.",longDescription:"Il glutatione (GSH) è un tripeptide composto da glutammato, cisteina e glicina e uno dei principali antiossidanti non enzimatici delle cellule viventi. È stato ampiamente studiato per il suo ruolo nell'omeostasi redox, nella coppia GSH/GSSG, nella detossificazione e nella segnalazione redox. Viene fornito a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca su antiossidanti cellulari e redox","Studi sulle vie dello stress ossidativo","Ricerca sulla coppia redox GSH/GSSG","Studi sulle vie di detossificazione","Ricerca sulla segnalazione redox"],researchGuide:"Il glutatione è idrosolubile e può essere ricostituito in acqua sterile o tampone. È sensibile alla luce e all'ossigeno, quindi maneggiare con cura e ridurre al minimo il contatto con l'aria. Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita in frigorifero, utilizzandola tempestivamente.",faq:[{question:"Cos'è il glutatione?",answer:"Il glutatione (GSH) è un tripeptide composto da glutammato, cisteina e glicina (gamma-Glu-Cys-Gly), studiato come uno dei principali antiossidanti cellulari non enzimatici e componente centrale della coppia redox GSH/GSSG."},{question:"Quali sono il peso molecolare e la formula del glutatione?",answer:"Il glutatione ha formula molecolare C10H17N3O6S e un peso molecolare di circa 307,32 g/mol (PubChem CID 124886)."},{question:"Qual è la purezza del glutatione di Miro Biotech?",answer:"Ogni lotto viene testato in modo indipendente da un laboratorio terzo e verificato al 99,69% di purezza, con un certificato di analisi per il lotto."},{question:"Come va conservato il glutatione?",answer:"Conservare la polvere liofilizzata a -20 °C al riparo dalla luce. Poiché è sensibile all'ossigeno, le soluzioni ricostituite vanno utilizzate tempestivamente e conservate in frigorifero."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["anti-invecchiamento","antiossidante","redox","detossificazione","tripeptide","peptide da ricerca"],aka:["GSH","gamma-Glu-Cys-Gly","glutatione ridotto"],whatIs:"Il glutatione (GSH) è un tripeptide composto da glutammato, cisteina e glicina, impiegato come sostanza da ricerca in studi su attività antiossidante cellulare, omeostasi redox e detossificazione. Fornito esclusivamente per la ricerca in-vitro e di laboratorio.",mechanism:"Nella ricerca pubblicata il glutatione ridotto (GSH) è stato descritto come antiossidante cellulare non enzimatico essenziale, centrale per l'omeostasi redox attraverso la coppia GSH/GSSG, per le reazioni di detossificazione e per la segnalazione redox. Queste vie sono studiate in modelli di stress ossidativo; i meccanismi corrispondenti nell'uomo sono oggetto di ricerca in corso nella biologia redox.",receptorTargets:["Coppia redox GSH/GSSG","Vie della glutatione perossidasi e reduttasi","Vie di detossificazione (coniugazione) cellulare","Segnalazione redox"],specs:[{label:"Composizione",value:"Tripeptide (gamma-Glu-Cys-Gly)"},{label:"Classificazione",value:"Antiossidante cellulare non enzimatico"},{label:"Aspetto",value:"Polvere liofilizzata bianca"},{label:"Solubilità",value:"Solubile in acqua e tampone"}],researchApplications:[{title:"Stress ossidativo",description:"Impiegato nella ricerca sulla capacità antiossidante cellulare e sui modelli di stress ossidativo."},{title:"Biologia redox",description:"Studiato come componente centrale della coppia redox GSH/GSSG."},{title:"Detossificazione",description:"Applicato per lo studio delle vie di coniugazione e detossificazione."},{title:"Segnalazione redox",description:"Esplorato nella ricerca sulla segnalazione cellulare redox-dipendente."}],keyStudies:[{title:"L'antiossidante glutatione",source:"Vitamins and Hormones",year:2023,url:"https://pubmed.ncbi.nlm.nih.gov/36707132/",finding:"Ha esaminato il glutatione ridotto (GSH) come antiossidante cellulare non enzimatico essenziale e ne ha descritto il ruolo nell'omeostasi redox, nella coppia GSH/GSSG, nella detossificazione e nella segnalazione redox."},{title:"Sintesi del glutatione",source:"Biochimica et Biophysica Acta",year:2013,url:"https://pubmed.ncbi.nlm.nih.gov/22995213/",finding:"Ha esaminato la biosintesi citosolica in due fasi del glutatione tramite la glutammato-cisteina ligasi e la GSH sintetasi, descrivendo come questa via risulti, secondo quanto riferito, strettamente regolata e disregolata negli stati patologici."},{title:"Glutatione, risposte allo stress e segnalazione redox nell'infiammazione polmonare",source:"Antioxidants & Redox Signaling",year:2005,url:"https://pubmed.ncbi.nlm.nih.gov/15650395/",finding:"Ha esaminato come le variazioni del rapporto intracellulare GSH/GSSG influenzino, secondo quanto riferito, le vie redox-sensibili e la chimica redox basata sulla cisteina nel contesto dell'infiammazione polmonare."}],reconstitution:"Di norma ricostituito con acqua sterile o tampone per l'uso in laboratorio. Poiché il glutatione è sensibile all'ossigeno, ridurre al minimo il contatto con l'aria, aggiungere delicatamente il diluente e conservare la soluzione ricostituita in frigorifero, utilizzandola entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero e utilizzare tempestivamente.",howSupplied:"Fornito come singolo flaconcino sigillato contenente polvere liofilizzata bianca di glutatione nel formato scelto. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata."},epithalon:{name:"Epithalon",description:"Tetrapeptide pineale sintetico (Ala-Glu-Asp-Gly), scritto anche Epitalon, fornito come standard di riferimento liofilizzato per la ricerca su telomerasi, melatonina pineale e invecchiamento cellulare. Disponibile in flaconcini da 10mg e 50mg.",longDescription:"Epithalon (Epitalon, peptide AEDG) è un tetrapeptide sintetico con sequenza Ala-Glu-Asp-Gly, sviluppato dal gruppo di Khavinson a partire dalla composizione amminoacidica dell'estratto pineale bovino Epithalamin. È stato studiato per l'attivazione della telomerasi e l'allungamento dei telomeri in colture di cellule somatiche umane, per i ritmi della melatonina pineale in primati anziani e per l'espressione di geni neurogenici in modelli di cellule staminali. Viene fornito a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca su telomerasi e lunghezza dei telomeri","Studi sulla ghiandola pineale e sui ritmi della melatonina","Modelli di senescenza cellulare e longevità","Ricerca sull'espressione di geni neurogenici","Studi sulle vie antiossidanti e dello stress ossidativo"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. Epithalon viene fornito come polvere liofilizzata. Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Cos'è Epithalon?",answer:"Epithalon (scritto anche Epitalon) è un tetrapeptide sintetico, Ala-Glu-Asp-Gly, progettato sulla base della composizione amminoacidica dell'estratto pineale Epithalamin. Viene studiato in modelli di ricerca su telomerasi, melatonina pineale e invecchiamento cellulare."},{question:"Epithalon ed Epitalon sono la stessa cosa?",answer:"Sì. Epithalon, Epitalon ed Epithalone sono grafie alternative dello stesso tetrapeptide AEDG (PubChem CID 219042, CAS 307297-39-8). Epithalamin è il più vecchio estratto pineale bovino sul quale è stato modellato, ed è un materiale diverso."},{question:"Quali sono il peso molecolare e la formula di Epithalon?",answer:"Epithalon ha formula molecolare C14H22N4O9 e un peso molecolare di circa 390,35 g/mol (PubChem CID 219042). La sua sequenza è Ala-Glu-Asp-Gly."},{question:"Qual è la purezza dell'Epithalon di Miro Biotech?",answer:"Ogni lotto viene testato in modo indipendente da un laboratorio terzo e verificato al 99,52% di purezza, con un certificato di analisi per il lotto."},{question:"Come va conservato Epithalon?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["telomerasi","pineale","longevità","tetrapeptide","bioregolatore","peptide da ricerca"],aka:["Epitalon","Epithalone","Peptide AEDG","Ala-Glu-Asp-Gly"],whatIs:"Epithalon (Epitalon) è un tetrapeptide sintetico, Ala-Glu-Asp-Gly, derivato dalla composizione amminoacidica dell'estratto pineale Epithalamin. È impiegato come sostanza da ricerca in studi sull'attività della telomerasi, sui ritmi della melatonina pineale e sulle vie dell'invecchiamento cellulare. Fornito esclusivamente per la ricerca in-vitro e di laboratorio.",mechanism:"Nella ricerca pubblicata è stato riferito che Epithalon induce l'espressione della subunità catalitica della telomerasi, l'attività enzimatica della telomerasi e l'allungamento dei telomeri in colture di fibroblasti fetali umani telomerasi-negativi. Un lavoro separato su macachi rhesus anziani ha riferito il ripristino della produzione notturna di melatonina da parte della ghiandola pineale, e uno studio su cellule staminali ha riferito una maggiore espressione di marcatori di differenziazione neurogenica, con la modellazione molecolare che suggerisce il legame a siti dell'istone H1 come possibile meccanismo epigenetico. Queste vie sono studiate in modelli cellulari e animali; i meccanismi corrispondenti nell'uomo non sono dimostrati.",receptorTargets:["Espressione della subunità catalitica della telomerasi (TERT)","Sintesi della melatonina pineale","Legame all'istone H1 (meccanismo epigenetico proposto)","Marcatori di differenziazione neurogenica (Nestina, GAP43)"],specs:[{label:"Sequenza",value:"Ala-Glu-Asp-Gly (AEDG)"},{label:"Classificazione",value:"Tetrapeptide pineale sintetico bioregolatore"},{label:"Aspetto",value:"Polvere liofilizzata bianca"},{label:"Solubilità",value:"Solubile in acqua batteriostatica"}],researchApplications:[{title:"Biologia della telomerasi",description:"Impiegato nella ricerca sull'attivazione della telomerasi e sulla lunghezza dei telomeri in colture di cellule somatiche umane."},{title:"Ricerca pineale e circadiana",description:"Studiato per gli effetti sui ritmi della melatonina pineale in modelli di primati anziani."},{title:"Invecchiamento cellulare",description:"Applicato in studi su durata della vita, biomarcatori dell'invecchiamento e stress ossidativo in modelli di roditori."},{title:"Regolazione epigenetica",description:"Esplorato per gli effetti sul legame agli istoni e sull'espressione di geni neurogenici in colture di cellule staminali."}],keyStudies:[{title:"Il peptide Epithalon induce l'attività della telomerasi e l'allungamento dei telomeri in cellule somatiche umane",source:"Bulletin of Experimental Biology and Medicine",year:2003,url:"https://pubmed.ncbi.nlm.nih.gov/12937682/",finding:"Ha riferito che l'aggiunta di Epithalon a colture di fibroblasti fetali umani telomerasi-negativi induceva l'espressione della subunità catalitica della telomerasi, l'attività enzimatica della telomerasi e l'allungamento dei telomeri."},{title:"Effetto di Epitalon sui biomarcatori dell'invecchiamento, sulla durata della vita e sull'incidenza di tumori spontanei in topi femmina SHR di derivazione Swiss",source:"Biogerontology",year:2003,url:"https://pubmed.ncbi.nlm.nih.gov/14501183/",finding:"Ha riferito che Epitalon, in topi femmina SHR, aumentava la durata della vita dell'ultimo 10% di sopravvissuti, riduceva le aberrazioni cromosomiche del midollo osseo e abbassava l'incidenza di leucemia, senza modificare la durata media della vita."},{title:"Il peptide AEDG (Epitalon) stimola l'espressione genica e la sintesi proteica durante la neurogenesi: possibile meccanismo epigenetico",source:"Molecules",year:2020,url:"https://pubmed.ncbi.nlm.nih.gov/32019204/",finding:"Ha riferito che AEDG aumentava i marcatori di differenziazione neurogenica in cellule staminali mesenchimali gengivali umane e, tramite modellazione molecolare, si legava preferenzialmente a siti dell'istone H1, proposto come meccanismo epigenetico."}],reconstitution:"Di norma ricostituito con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C.",howSupplied:"Fornito come singolo flaconcino sigillato contenente polvere liofilizzata bianca di Epithalon nel formato scelto. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata."},"ss-31":{name:"SS-31",description:"Tetrapeptide mirato ai mitocondri (elamipretide, D-Arg-Dmt-Lys-Phe-NH2) fornito come standard di riferimento liofilizzato per la ricerca su cardiolipina, bioenergetica mitocondriale ed energia cellulare. Disponibile in flaconcini da 10mg e 50mg.",longDescription:"SS-31 (elamipretide, MTP-131, Bendavia) è un tetrapeptide aromatico-cationico, D-Arg-Dmt-Lys-Phe-NH2, della serie Szeto-Schiller. È stato studiato per il legame selettivo alla cardiolipina sulla membrana mitocondriale interna, per gli effetti sul trasporto di elettroni del citocromo c e sulla sintesi di ATP in mitocondri isolati, e nella ricerca clinica sui disturbi mitocondriali della cardiolipina. Viene fornito a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca su cardiolipina e membrana interna","Studi su bioenergetica mitocondriale e ATP","Ricerca sul trasporto di elettroni del citocromo c","Modelli di stress ossidativo e ischemia","Ricerca su energia cellulare e invecchiamento"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. SS-31 viene fornito come polvere liofilizzata. Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Cos'è SS-31?",answer:"SS-31 (elamipretide) è un tetrapeptide aromatico-cationico mirato ai mitocondri, D-Arg-Dmt-Lys-Phe-NH2, studiato per la sua interazione con la cardiolipina sulla membrana mitocondriale interna e per i suoi effetti sul trasporto mitocondriale di elettroni."},{question:"Quali sono il peso molecolare e la formula di SS-31?",answer:"SS-31 ha formula molecolare C32H49N9O5 e un peso molecolare di circa 639,8 g/mol (PubChem CID 11764719, CAS 736992-21-5). Dmt è la 2,6-dimetil-L-tirosina."},{question:"Che rapporto c'è tra SS-31 ed elamipretide?",answer:"SS-31 è la designazione da ricerca dell'elamipretide (anche MTP-131 e Bendavia). La ricerca pubblicata sull'elamipretide descrive il legame alla cardiolipina nella membrana mitocondriale interna; questo prodotto è uno standard di riferimento per la ricerca e non una formulazione farmaceutica."},{question:"Qual è la purezza dell'SS-31 di Miro Biotech?",answer:"Ogni lotto viene testato in modo indipendente da un laboratorio terzo e verificato al 99,38% di purezza, con un certificato di analisi per il lotto."},{question:"Come va conservato SS-31?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["mitocondri","cardiolipina","bioenergetica","tetrapeptide","longevità","peptide da ricerca"],aka:["Elamipretide","MTP-131","Bendavia","Peptide Szeto-Schiller 31","D-Arg-Dmt-Lys-Phe-NH2"],whatIs:"SS-31 (elamipretide) è un tetrapeptide sintetico aromatico-cationico, D-Arg-Dmt-Lys-Phe-NH2, che si concentra nella membrana mitocondriale interna. È impiegato come sostanza da ricerca in studi su cardiolipina, trasporto di elettroni del citocromo c e sintesi mitocondriale di ATP. Fornito esclusivamente per la ricerca in-vitro e di laboratorio.",mechanism:"Nella ricerca pubblicata è stato riferito che SS-31 lega la cardiolipina sulla membrana mitocondriale interna con alta affinità, e che il complesso SS-31-cardiolipina inibisce l'attività perossidasica del citocromo c, proteggendo la struttura delle creste in un modello di ischemia renale nel ratto. Lavori su sistemi di liposomi, bicelle e mitocondri isolati hanno riferito che il peptide interagisce solo con membrane contenenti cardiolipina, ripristina la funzione di trasportatore di elettroni del citocromo c e aumenta la respirazione di stato 3. È stata pubblicata anche ricerca clinica sull'elamipretide nella sindrome di Barth e nella miopatia mitocondriale primaria. Questi meccanismi sono caratterizzati in modelli cellulari, di membrana e animali.",receptorTargets:["Cardiolipina (membrana mitocondriale interna)","Complesso citocromo c / cardiolipina","Catena di trasporto degli elettroni e sintesi di ATP","Struttura delle creste mitocondriali"],specs:[{label:"Sequenza",value:"D-Arg-Dmt-Lys-Phe-NH2 (Dmt = 2,6-dimetil-L-tirosina)"},{label:"Classificazione",value:"Tetrapeptide aromatico-cationico mirato ai mitocondri"},{label:"Aspetto",value:"Polvere liofilizzata bianca"},{label:"Solubilità",value:"Solubile in acqua batteriostatica"}],researchApplications:[{title:"Bioenergetica mitocondriale",description:"Impiegato nella ricerca su trasporto di elettroni, respirazione di stato 3 e sintesi di ATP in mitocondri isolati."},{title:"Biologia della cardiolipina",description:"Studiato per l'interazione con la membrana e l'inibizione dell'attività perossidasica del citocromo c in sistemi contenenti cardiolipina."},{title:"Ischemia e stress ossidativo",description:"Applicato in modelli di ischemia-riperfusione per indagare la protezione delle creste e il recupero dell'ATP."},{title:"Ricerca sulle malattie mitocondriali",description:"Esplorato nella ricerca clinica sui disturbi del metabolismo della cardiolipina e sulla miopatia mitocondriale."}],keyStudies:[{title:"Il composto mirato ai mitocondri SS-31 rienergizza i mitocondri ischemici interagendo con la cardiolipina",source:"Journal of the American Society of Nephrology",year:2013,url:"https://pubmed.ncbi.nlm.nih.gov/23813215/",finding:"Ha riferito che SS-31 lega la cardiolipina con alta affinità, che il complesso inibisce l'attività perossidasica del citocromo c e che il pretrattamento in un modello di ischemia renale nel ratto proteggeva le membrane delle creste e accelerava il recupero dell'ATP alla riperfusione."},{title:"Mirare alla cardiolipina mitocondriale e al complesso citocromo c/cardiolipina per promuovere il trasporto di elettroni e ottimizzare la sintesi mitocondriale di ATP",source:"British Journal of Pharmacology",year:2014,url:"https://pubmed.ncbi.nlm.nih.gov/24134698/",finding:"Ha riferito, in esperimenti su liposomi, bicelle e mitocondri isolati, che SS-31 interagisce solo con membrane contenenti cardiolipina, ripristina la funzione di trasportatore di elettroni del citocromo c e aumenta la respirazione di stato 3."},{title:"Uno studio clinico randomizzato di fase 2/3 seguito da un'estensione in aperto per valutare l'efficacia dell'elamipretide nella sindrome di Barth",source:"Genetics in Medicine",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/33077895/",finding:"Ha riferito che nello studio crossover TAZPOWER la fase randomizzata non ha raggiunto gli endpoint primari, mentre l'estensione in aperto di 36 settimane ha registrato miglioramenti nella distanza percorsa in 6 minuti e nei punteggi dei sintomi."}],reconstitution:"Di norma ricostituito con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C.",howSupplied:"Fornito come singolo flaconcino sigillato contenente polvere liofilizzata bianca di SS-31 nel formato scelto. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata."},vesugen:{name:"Vesugen",description:"Tripeptide bioregolatore vascolare (Lys-Glu-Asp, peptide KED) fornito come standard di riferimento liofilizzato per la ricerca su endotelio, invecchiamento vascolare ed espressione genica.",longDescription:"Vesugen (peptide KED) è un tripeptide sintetico con sequenza Lys-Glu-Asp, uno dei brevi peptidi bioregolatori sviluppati dal gruppo di Khavinson. È stato studiato in colture di cellule endoteliali vascolari per gli effetti sull'espressione di endotelina-1, connessina e sirtuina-1, per i marcatori di proliferazione nell'endotelio in invecchiamento e per l'espressione di geni correlati alla neurogenesi. Viene fornito a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca sull'endotelio vascolare","Studi sull'espressione di endotelina-1 e connessina","Ricerca sulla via della sirtuina-1","Modelli di proliferazione e invecchiamento endoteliale","Studi sull'espressione di geni della neurogenesi"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. Vesugen viene fornito come polvere liofilizzata. Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Cos'è Vesugen?",answer:"Vesugen è un tripeptide sintetico, Lys-Glu-Asp (KED), della serie di brevi peptidi bioregolatori di Khavinson. Viene studiato in modelli di cellule endoteliali vascolari per gli effetti sull'espressione di endotelina-1, connessina, sirtuina-1 e marcatori di proliferazione."},{question:"Quali sono il peso molecolare e la formula di Vesugen?",answer:"Vesugen ha formula molecolare C15H26N4O8 e un peso molecolare di circa 390,39 g/mol (PubChem CID 87571363). La sua sequenza è Lys-Glu-Asp."},{question:"Qual è la purezza del Vesugen di Miro Biotech?",answer:"Ogni lotto viene testato in modo indipendente da un laboratorio terzo e verificato al 99,61% di purezza, con un certificato di analisi per il lotto."},{question:"Come va conservato Vesugen?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["vascolare","endotelio","bioregolatore","tripeptide","longevità","peptide da ricerca"],aka:["Peptide KED","Lys-Glu-Asp","Acido lisil-glutamil-aspartico"],whatIs:"Vesugen è un tripeptide sintetico, Lys-Glu-Asp (KED), della serie di brevi peptidi bioregolatori di Khavinson. È impiegato come sostanza da ricerca in studi sull'endotelio vascolare, sull'espressione di endotelina-1 e sirtuina-1 e sulla proliferazione endoteliale durante l'invecchiamento. Fornito esclusivamente per la ricerca in-vitro e di laboratorio.",mechanism:"Nella ricerca pubblicata è stato riferito che KED normalizza l'espressione di endotelina-1, aumentata in cellule endoteliali aterosclerotiche e restenotiche, e ripristina l'espressione di connessina e sirtuina-1 in-vitro. Un lavoro separato ha riferito un aumento del marcatore di proliferazione Ki-67 in colture endoteliali vascolari anziane, con il docking molecolare che suggerisce un contatto con il promotore core di MKI67, e una rassegna ha descritto la regolazione di geni dell'invecchiamento cellulare (p16, p21) e di geni della differenziazione neuronale (NES, GAP43) in modelli di neurogenesi. Questi effetti sono descritti in modelli di coltura cellulare; i meccanismi corrispondenti nell'uomo non sono dimostrati.",receptorTargets:["Espressione di endotelina-1","Espressione di connessina e sirtuina-1 (SIRT1)","Promotore di Ki-67 / MKI67 (proposto)","Geni dell'invecchiamento cellulare p16 e p21"],specs:[{label:"Sequenza",value:"Lys-Glu-Asp (KED)"},{label:"Classificazione",value:"Tripeptide vascolare sintetico bioregolatore"},{label:"Aspetto",value:"Polvere liofilizzata bianca"},{label:"Solubilità",value:"Solubile in acqua batteriostatica"}],researchApplications:[{title:"Biologia endoteliale",description:"Impiegato nella ricerca sull'espressione di endotelina-1, connessina e sirtuina-1 in colture endoteliali vascolari."},{title:"Invecchiamento vascolare",description:"Studiato per l'espressione di marcatori di proliferazione in tessuti endoteliali anziani e modelli cellulari."},{title:"Regolazione epigenetica",description:"Esplorato tramite docking molecolare sui promotori genici come meccanismo d'azione proposto."},{title:"Modelli di neurogenesi",description:"Applicato in studi sull'espressione di geni dell'invecchiamento cellulare e della differenziazione neuronale."}],keyStudies:[{title:"Aspetti molecolari dell'attività del peptide vasoprotettivo KED durante aterosclerosi e restenosi",source:"Advances in Gerontology",year:2016,url:"https://pubmed.ncbi.nlm.nih.gov/28539025/",finding:"Ha riferito che KED normalizzava l'espressione di endotelina-1 e ripristinava l'espressione di connessina e sirtuina-1 in cellule endoteliali normali, aterosclerotiche e restenotiche in-vitro."},{title:"Aspetti epigenetici della regolazione peptidergica della proliferazione delle cellule endoteliali vascolari durante l'invecchiamento",source:"Advances in Gerontology",year:2014,url:"https://pubmed.ncbi.nlm.nih.gov/25051766/",finding:"Ha riferito che Vesugen stimolava il marcatore di proliferazione Ki-67 in colture endoteliali vascolari anziane, con il docking molecolare che mostrava un contatto con il promotore core di MKI67."},{title:"Peptide KED: aspetti molecolari e genetici della regolazione della neurogenesi nella malattia di Alzheimer",source:"Bulletin of Experimental Biology and Medicine",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34173097/",finding:"Ha esaminato le segnalazioni secondo cui KED regola geni dell'invecchiamento cellulare (p16, p21), geni della differenziazione neuronale (NES, GAP43) e geni correlati all'Alzheimer in un modello di neurogenesi in-vitro."}],reconstitution:"Di norma ricostituito con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C.",howSupplied:"Fornito come singolo flaconcino sigillato contenente polvere liofilizzata bianca di Vesugen. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata."},cartalax:{name:"Cartalax",description:"Tripeptide bioregolatore della cartilagine (Ala-Glu-Asp, peptide AED) fornito come standard di riferimento liofilizzato per la ricerca su differenziazione condrogenica, tessuto connettivo e invecchiamento cellulare.",longDescription:"Cartalax (peptide AED) è un tripeptide sintetico con sequenza Ala-Glu-Asp, uno dei brevi peptidi bioregolatori sviluppati dal gruppo di Khavinson. È stato studiato in colture di cellule staminali mesenchimali umane per l'espressione di marcatori condrogenici (SOX9, aggrecano, collagene di tipo II, COMP), in fibroblasti cutanei in invecchiamento per MMP-9 e marcatori di proliferazione, e in modelli di invecchiamento di cellule staminali per l'espressione di IGF1 e NF-kB. Viene fornito a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca sulla differenziazione condrogenica","Modelli di cartilagine e tessuto connettivo","Studi su MMP-9 e invecchiamento dei fibroblasti","Ricerca sull'espressione di IGF1 e NF-kB","Studi sull'invecchiamento delle cellule staminali mesenchimali"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. Cartalax viene fornito come polvere liofilizzata. Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Cos'è Cartalax?",answer:"Cartalax è un tripeptide sintetico, Ala-Glu-Asp (AED), della serie di brevi peptidi bioregolatori di Khavinson. Viene studiato in modelli di cellule staminali mesenchimali e fibroblasti per l'espressione di marcatori condrogenici e l'invecchiamento del tessuto connettivo."},{question:"Quali sono il peso molecolare e la formula di Cartalax?",answer:"Cartalax ha formula molecolare C12H19N3O8 e un peso molecolare di circa 333,29 g/mol (PubChem CID 87815447). La sua sequenza è Ala-Glu-Asp."},{question:"Qual è la purezza del Cartalax di Miro Biotech?",answer:"Ogni lotto viene testato in modo indipendente da un laboratorio terzo e verificato al 99,47% di purezza, con un certificato di analisi per il lotto."},{question:"Come va conservato Cartalax?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["cartilagine","condrociti","tessuto connettivo","bioregolatore","tripeptide","peptide da ricerca"],aka:["Peptide AED","Ala-Glu-Asp","Peptide T-31","Acido alanil-glutamil-aspartico"],whatIs:"Cartalax è un tripeptide sintetico, Ala-Glu-Asp (AED), della serie di brevi peptidi bioregolatori di Khavinson. È impiegato come sostanza da ricerca in studi su differenziazione condrogenica, marcatori della cartilagine e del tessuto connettivo e invecchiamento dei fibroblasti in coltura cellulare. Fornito esclusivamente per la ricerca in-vitro e di laboratorio.",mechanism:"Nella ricerca pubblicata è stato riferito che il peptide AED a 200 ng/ml attiva l'espressione dei marcatori condrogenici SOX9, aggrecano, collagene di tipo II e COMP in cellule staminali mesenchimali umane durante l'invecchiamento replicativo. Un lavoro separato su colture di fibroblasti cutanei in invecchiamento ha riferito l'inibizione della sintesi di MMP-9, l'aumento di Ki-67 e CD98hc e la soppressione dell'apoptosi caspasi-dipendente, e uno studio sull'invecchiamento delle cellule staminali ha riferito una maggiore espressione di IGF1 insieme a una stimolazione dell'espressione di NF-kB. Questi effetti sono descritti in modelli di coltura cellulare; i meccanismi corrispondenti nell'uomo non sono dimostrati.",receptorTargets:["Espressione di SOX9, aggrecano e collagene di tipo II","Sintesi di MMP-9","Espressione di IGF1 e NF-kB","Apoptosi caspasi-dipendente"],specs:[{label:"Sequenza",value:"Ala-Glu-Asp (AED)"},{label:"Classificazione",value:"Tripeptide sintetico bioregolatore della cartilagine"},{label:"Aspetto",value:"Polvere liofilizzata bianca"},{label:"Solubilità",value:"Solubile in acqua batteriostatica"}],researchApplications:[{title:"Differenziazione condrogenica",description:"Impiegato nella ricerca sull'espressione di marcatori della cartilagine in colture di cellule staminali mesenchimali umane."},{title:"Invecchiamento del tessuto connettivo",description:"Studiato per i marcatori di MMP-9, proliferazione e apoptosi in modelli di fibroblasti in invecchiamento."},{title:"Segnalazione dei fattori di crescita",description:"Applicato per indagare l'espressione di IGF1 e NF-kB in colture di cellule staminali in invecchiamento."},{title:"Bioregolazione con peptidi brevi",description:"Esplorato accanto ad altri tripeptidi di Khavinson per confrontare i profili di espressione genica."}],keyStudies:[{title:"L'influenza dei peptidi sulla differenziazione condrogenica delle cellule staminali mesenchimali umane durante l'invecchiamento replicativo",source:"Advances in Gerontology",year:2023,url:"https://pubmed.ncbi.nlm.nih.gov/37782646/",finding:"Ha riferito che il peptide AED a 200 ng/ml attivava l'espressione dei marcatori condrogenici SOX9, aggrecano, collagene di tipo II e COMP in cellule staminali mesenchimali umane durante l'invecchiamento replicativo in-vitro."},{title:"Regolazione peptidica delle funzioni dei fibroblasti cutanei durante il loro invecchiamento in-vitro",source:"Bulletin of Experimental Biology and Medicine",year:2016,url:"https://pubmed.ncbi.nlm.nih.gov/27259496/",finding:"Ha riferito che peptidi brevi, tra cui AED, inibivano la sintesi di MMP-9 e aumentavano Ki-67 e CD98hc in colture di fibroblasti cutanei in invecchiamento, con AED che sopprimeva anche l'apoptosi caspasi-dipendente."},{title:"Espressione genica in colture di cellule staminali mesenchimali umane in invecchiamento: modulazione da parte di peptidi brevi",source:"Molecular Biology Reports",year:2020,url:"https://pubmed.ncbi.nlm.nih.gov/32399807/",finding:"Ha riferito che AED, KED e KE a concentrazioni nanomolari aumentavano di diverse volte l'espressione di IGF1 e stimolavano l'espressione di NF-kB in due modelli di invecchiamento di cellule staminali mesenchimali del midollo osseo umano."}],reconstitution:"Di norma ricostituito con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C.",howSupplied:"Fornito come singolo flaconcino sigillato contenente polvere liofilizzata bianca di Cartalax. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata."},pinealon:{name:"Pinealon",description:"Tripeptide bioregolatore cerebrale (Glu-Asp-Arg, peptide EDR) fornito come standard di riferimento liofilizzato per la ricerca su colture neuronali, stress ossidativo e invecchiamento cognitivo.",longDescription:"Pinealon (peptide EDR) è un tripeptide sintetico con sequenza Glu-Asp-Arg, uno dei brevi peptidi bioregolatori sviluppati dal gruppo di Khavinson. È stato studiato in colture di cellule granulari cerebellari, neutrofili e cellule PC12 per l'accumulo di specie reattive dell'ossigeno e la vitalità cellulare, in un modello di iperomocisteinemia prenatale nel ratto per l'apprendimento della prole, e in modelli di neurodegenerazione su colture neuronali. Viene fornito a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca su colture neuronali e neuroprotezione","Studi su specie reattive dell'ossigeno e vitalità cellulare","Modelli di invecchiamento cognitivo e apprendimento","Ricerca sulla segnalazione MAPK/ERK","Studi sull'espressione genica nella neurodegenerazione"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. Pinealon viene fornito come polvere liofilizzata. Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Cos'è Pinealon?",answer:"Pinealon è un tripeptide sintetico, Glu-Asp-Arg (EDR), della serie di brevi peptidi bioregolatori di Khavinson. Viene studiato in colture di cellule neuronali e modelli di roditori per l'accumulo di specie reattive dell'ossigeno, la vitalità cellulare e gli esiti legati all'apprendimento."},{question:"Quali sono il peso molecolare e la formula di Pinealon?",answer:"Pinealon ha formula molecolare C15H26N6O8 e un peso molecolare di circa 418,40 g/mol (PubChem CID 10273502, CAS 175175-23-2). La sua sequenza è Glu-Asp-Arg."},{question:"Qual è la purezza del Pinealon di Miro Biotech?",answer:"Ogni lotto viene testato in modo indipendente da un laboratorio terzo e verificato al 99,55% di purezza, con un certificato di analisi per il lotto."},{question:"Come va conservato Pinealon?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["neuroprotettivo","cognitivo","bioregolatore","tripeptide","nootropo","peptide da ricerca"],aka:["Peptide EDR","Glu-Asp-Arg","Glutamil-aspartil-arginina"],whatIs:"Pinealon è un tripeptide sintetico, Glu-Asp-Arg (EDR), della serie di brevi peptidi bioregolatori di Khavinson. È impiegato come sostanza da ricerca in studi sulla vitalità delle cellule neuronali, sull'accumulo di specie reattive dell'ossigeno e in modelli di invecchiamento cognitivo. Fornito esclusivamente per la ricerca in-vitro e di laboratorio.",mechanism:"Nella ricerca pubblicata è stato riferito che Pinealon limita l'accumulo di specie reattive dell'ossigeno e la morte cellulare necrotica in cellule granulari cerebellari, neutrofili e cellule PC12 sotto stress ossidativo, con attivazione ritardata di ERK1/2 e modulazione del ciclo cellulare, il che ha portato gli autori a proporre un'interazione diretta con il genoma. Un modello di iperomocisteinemia prenatale nel ratto ha riferito un miglioramento dell'apprendimento spaziale della prole e una riduzione delle ROS neuronali, e una rassegna ha proposto l'ingresso nelle cellule e il legame a istoni o RNA, con effetti a valle su MAPK/ERK, caspasi-3, p53, SOD2 e GPX1. Questi risultati provengono da modelli cellulari e animali; i meccanismi corrispondenti nell'uomo non sono dimostrati.",receptorTargets:["Accumulo di specie reattive dell'ossigeno (ROS)","Segnalazione MAPK/ERK1/2","Via apoptotica di caspasi-3 e p53","Enzimi antiossidanti SOD2 e GPX1"],specs:[{label:"Sequenza",value:"Glu-Asp-Arg (EDR)"},{label:"Classificazione",value:"Tripeptide cerebrale sintetico bioregolatore"},{label:"Aspetto",value:"Polvere liofilizzata bianca"},{label:"Solubilità",value:"Solubile in acqua batteriostatica"}],researchApplications:[{title:"Modelli di neuroprotezione",description:"Impiegato nella ricerca sull'accumulo di ROS e sulla vitalità cellulare in colture neuronali e PC12."},{title:"Invecchiamento cognitivo",description:"Studiato in modelli di roditori per l'apprendimento spaziale e i marcatori ossidativi neuronali."},{title:"Ricerca sulla neurodegenerazione",description:"Esplorato in colture neuronali che modellano la patologia di Alzheimer e Huntington."},{title:"Vie di segnalazione",description:"Applicato per indagare l'espressione di MAPK/ERK, caspasi-3 ed enzimi antiossidanti."}],keyStudies:[{title:"Pinealon aumenta la vitalità cellulare sopprimendo i livelli di radicali liberi e attivando i processi proliferativi",source:"Rejuvenation Research",year:2011,url:"https://pubmed.ncbi.nlm.nih.gov/21978084/",finding:"Ha riferito che Pinealon limitava in modo dose-dipendente l'accumulo di ROS e la morte necrotica in cellule granulari cerebellari, neutrofili e cellule PC12 sotto stress ossidativo, con attivazione ritardata di ERK1/2."},{title:"Pinealon protegge la prole di ratto dall'iperomocisteinemia prenatale",source:"International Journal of Clinical and Experimental Medicine",year:2012,url:"https://pubmed.ncbi.nlm.nih.gov/22567179/",finding:"Ha riferito che Pinealon somministrato a ratte gravide sottoposte a carico di metionina migliorava l'orientamento spaziale e l'apprendimento della prole e riduceva ROS e necrosi nei neuroni cerebellari della prole."},{title:"Peptide EDR: possibile meccanismo di regolazione dell'espressione genica e della sintesi proteica coinvolto nella patogenesi della malattia di Alzheimer",source:"Molecules",year:2020,url:"https://pubmed.ncbi.nlm.nih.gov/33396470/",finding:"Ha esaminato le segnalazioni secondo cui EDR riduce l'apoptosi neuronale e preserva le spine dendritiche in colture di neurodegenerazione, e ha proposto il legame a istoni e RNA con effetti su MAPK/ERK, caspasi-3, p53, SOD2 e GPX1."}],reconstitution:"Di norma ricostituito con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C.",howSupplied:"Fornito come singolo flaconcino sigillato contenente polvere liofilizzata bianca di Pinealon. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata."},thymalin:{name:"Thymalin",description:"Complesso polipeptidico timico fornito come standard di riferimento liofilizzato per la ricerca su differenziazione dei linfociti T, immunosenescenza e cellule staminali ematopoietiche.",longDescription:"Thymalin è un complesso polipeptidico originariamente isolato dal timo di vitello mediante estrazione acida blanda, sviluppato da Morozov e Khavinson. I suoi componenti attivi caratterizzati includono i dipeptidi Lys-Glu (KE) e Glu-Trp (EW). È stato studiato in colture di cellule staminali ematopoietiche umane per i marcatori di differenziazione dei linfociti T, in modelli di immunosenescenza e nella ricerca osservazionale a lungo termine sulla funzione immunitaria negli anziani. Viene fornito a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca sulla differenziazione dei linfociti T","Modelli di immunosenescenza e invecchiamento timico","Studi sulle cellule staminali ematopoietiche","Ricerca sui marcatori CD28, CD44 e CD117","Studi sulla bioregolazione con peptidi timici"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. Thymalin viene fornito come polvere liofilizzata. Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Cos'è Thymalin?",answer:"Thymalin è un complesso polipeptidico isolato dal timo di vitello, sviluppato da Morozov e Khavinson. I suoi componenti attivi caratterizzati includono i dipeptidi Lys-Glu e Glu-Trp. Viene studiato in modelli di differenziazione dei linfociti T, immunosenescenza e cellule staminali ematopoietiche."},{question:"Thymalin e timulina sono la stessa cosa?",answer:"No. La timulina è un ormone nonapeptidico definito, zinco-dipendente, mentre Thymalin è un estratto timico multipeptidico. Sono materiali diversi che condividono solo un nome simile."},{question:"Qual è la purezza del Thymalin di Miro Biotech?",answer:"Ogni lotto viene testato in modo indipendente da un laboratorio terzo e verificato al 99,1% di contenuto peptidico, con un certificato di analisi per il lotto."},{question:"Come va conservato Thymalin?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["immunitario","timo","linfociti T","bioregolatore","longevità","peptide da ricerca"],aka:["Complesso polipeptidico timico","Thymalinum","Complesso dei dipeptidi KE ed EW"],whatIs:"Thymalin è un complesso polipeptidico isolato dal timo di vitello, i cui componenti attivi caratterizzati includono i dipeptidi Lys-Glu e Glu-Trp. È impiegato come sostanza da ricerca in studi sulla differenziazione dei linfociti T, sui marcatori delle cellule staminali ematopoietiche e sull'immunosenescenza. Fornito esclusivamente per la ricerca in-vitro e di laboratorio.",mechanism:"Nella ricerca pubblicata è stato riferito che Thymalin riduce l'espressione di CD44 e CD117 di due-tre volte e aumenta l'espressione di CD28 di 6,8 volte in colture di cellule staminali ematopoietiche umane, interpretato dagli autori come stimolazione della differenziazione verso linfociti T maturi CD28-positivi. I suoi componenti dipeptidici KE ed EW sono stati studiati tramite docking molecolare sul DNA a doppio filamento e analisi bioinformatica dell'espressione genica. Uno studio osservazionale di 6-8 anni su anziani trattati con Thymalin ha riferito una minore incidenza di infezioni respiratorie. Questi risultati provengono da colture cellulari e ricerca osservazionale; un meccanismo molecolare definito non è stato dimostrato.",receptorTargets:["Marcatore costimolatorio dei linfociti T CD28","Marcatori di cellule staminali CD44 e CD117","Differenziazione dei linfociti T","Legame al DNA dei dipeptidi KE ed EW (proposto)"],specs:[{label:"Composizione",value:"Complesso polipeptidico timico (estratto di timo di vitello)"},{label:"Componenti caratterizzati",value:"Dipeptidi Lys-Glu (KE) e Glu-Trp (EW)"},{label:"Aspetto",value:"Polvere liofilizzata da bianca a biancastra"},{label:"Solubilità",value:"Solubile in acqua batteriostatica"}],researchApplications:[{title:"Differenziazione dei linfociti T",description:"Impiegato nella ricerca sui marcatori CD28, CD44 e CD117 in colture di cellule staminali ematopoietiche umane."},{title:"Immunosenescenza",description:"Studiato in modelli di declino età-correlato della funzione timica e dei linfociti T."},{title:"Biologia dei peptidi timici",description:"Applicato per confrontare l'estratto con i suoi componenti dipeptidici caratterizzati KE ed EW."},{title:"Bioinformatica dell'espressione genica",description:"Esplorato tramite docking molecolare e analisi dell'espressione di geni correlati al sistema immunitario."}],keyStudies:[{title:"Thymalin: attivazione della differenziazione delle cellule staminali ematopoietiche umane",source:"Bulletin of Experimental Biology and Medicine",year:2020,url:"https://pubmed.ncbi.nlm.nih.gov/33237528/",finding:"Ha riferito che Thymalin, un complesso polipeptidico isolato dal timo, riduceva l'espressione di CD44 e CD117 e aumentava l'espressione di CD28 di 6,8 volte in colture di cellule staminali ematopoietiche umane."},{title:"L'influenza dei dipeptidi KE ed EW nella composizione del farmaco Thymalin sull'espressione genica e sulla sintesi proteica",source:"International Journal of Molecular Sciences",year:2023,url:"https://pubmed.ncbi.nlm.nih.gov/37686182/",finding:"Ha descritto Thymalin come un estratto polipeptidico del timo le cui sostanze attive KE ed EW sono state studiate tramite docking molecolare sul DNA a doppio filamento e analisi bioinformatica dell'espressione genica."},{title:"I peptidi della ghiandola pineale e del timo prolungano la vita umana",source:"Neuro Endocrinology Letters",year:2003,url:"https://pubmed.ncbi.nlm.nih.gov/14523363/",finding:"Ha riferito un follow-up osservazionale di 6-8 anni su 266 anziani trattati con Thymalin e/o Epithalamin, con una minore incidenza di malattie respiratorie acute nei gruppi trattati rispetto ai controlli."}],reconstitution:"Di norma ricostituito con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C.",howSupplied:"Fornito come singolo flaconcino sigillato contenente polvere liofilizzata di Thymalin da bianca a biancastra. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata."},"pt-141":{name:"PT-141",description:"Eptapeptide ciclico della melanocortina (bremelanotide), agonista MC3R/MC4R fornito come standard di riferimento liofilizzato per la ricerca sulla farmacologia dei recettori della melanocortina e sulle vie del sistema nervoso centrale.",longDescription:"PT-141 (bremelanotide) è un analogo eptapeptidico ciclico dell'ormone alfa-melanocita-stimolante, Ac-Nle-cyclo[Asp-His-D-Phe-Arg-Trp-Lys]-OH, che agisce come agonista sui recettori della melanocortina MC3R e MC4R. È stato studiato in modelli di legame recettoriale e in modelli comportamentali su roditori della segnalazione melanocortinica centrale, e la letteratura clinica pubblicata comprende studi di fase 2 e di fase 3 su una formulazione sottocutanea. Viene fornito a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca sui recettori della melanocortina MC3R/MC4R","Studi sulle vie del sistema nervoso centrale","Farmacologia degli analoghi dell'α-MSH","Saggi di legame recettoriale e di segnalazione","Modelli di ricerca sui circuiti ipotalamici"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. PT-141 viene fornito come polvere liofilizzata. Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Cos'è PT-141?",answer:"PT-141 (bremelanotide) è un analogo eptapeptidico ciclico dell'α-MSH che agisce come agonista sui recettori della melanocortina MC3R e MC4R. Viene studiato nella farmacologia recettoriale e nella ricerca sulle vie del sistema nervoso centrale."},{question:"Quali sono il peso molecolare e la formula di PT-141?",answer:"PT-141 ha formula molecolare C50H68N14O10 e un peso molecolare di circa 1025,2 g/mol (PubChem CID 9941379, CAS 189691-06-3). La sua sequenza è Ac-Nle-cyclo[Asp-His-D-Phe-Arg-Trp-Lys]-OH."},{question:"In cosa differisce PT-141 da MT-2?",answer:"Entrambi sono analoghi sintetici dell'α-MSH. MT-2 (Melanotan II) è un agonista ciclico non selettivo della melanocortina studiato per la melanogenesi, mentre PT-141 è il suo analogo metabolita carbossilato ed è studiato per la segnalazione MC3R e MC4R nel sistema nervoso centrale."},{question:"Qual è la purezza del PT-141 di Miro Biotech?",answer:"Ogni lotto viene testato in modo indipendente da un laboratorio terzo e verificato al 99,44% di purezza, con un certificato di analisi per il lotto."},{question:"Come va conservato PT-141?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["melanocortina","MC4R","α-MSH","neuroscienze","eptapeptide","peptide da ricerca"],aka:["Bremelanotide","PT141","Vyleesi (formulazione approvata)"],whatIs:"PT-141 (bremelanotide) è un analogo eptapeptidico ciclico dell'α-MSH che agisce come agonista sui recettori della melanocortina MC3R e MC4R. È impiegato come sostanza da ricerca in studi sulla farmacologia dei recettori della melanocortina e sulle vie di segnalazione del sistema nervoso centrale. Fornito esclusivamente per la ricerca in-vitro e di laboratorio.",mechanism:"Nella ricerca pubblicata PT-141 è stato caratterizzato come agonista della melanocortina con alta affinità per MC4R e attività su MC3R. Il lavoro preclinico in modelli di ratto femmina ha riferito che i suoi effetti comportamentali erano mediati a livello centrale, con la somministrazione cerebrale sito-specifica e la microdialisi che indicavano i circuiti melanocortinici ipotalamici anziché effetti vascolari periferici. I primi studi farmacocinetici nell'uomo sulla somministrazione intranasale e sottocutanea hanno riferito un'emivita di circa due ore, e i successivi programmi di fase 2 e di fase 3 hanno valutato una formulazione sottocutanea. Questi risultati descrivono la letteratura pubblicata; la sostanza viene fornita qui esclusivamente come standard di riferimento per la ricerca.",receptorTargets:["Recettore della melanocortina 4 (MC4R)","Recettore della melanocortina 3 (MC3R)","Circuiti melanocortinici ipotalamici","Segnalazione dell'α-MSH"],specs:[{label:"Sequenza",value:"Ac-Nle-cyclo[Asp-His-D-Phe-Arg-Trp-Lys]-OH"},{label:"Classificazione",value:"Analogo eptapeptidico ciclico dell'α-MSH, agonista MC3R/MC4R"},{label:"Aspetto",value:"Polvere liofilizzata bianca"},{label:"Solubilità",value:"Solubile in acqua batteriostatica"}],researchApplications:[{title:"Farmacologia dei recettori della melanocortina",description:"Impiegato in saggi di legame e di segnalazione che caratterizzano l'agonismo su MC3R e MC4R."},{title:"Vie del sistema nervoso centrale",description:"Studiato in modelli su roditori della segnalazione melanocortinica ipotalamica."},{title:"Confronto tra analoghi dell'α-MSH",description:"Esplorato insieme a MT-2 e ad altri analoghi per confrontare la selettività recettoriale."},{title:"Ricerca farmacocinetica",description:"Applicato in studi pubblicati sulle vie di somministrazione intranasale e sottocutanea."}],keyStudies:[{title:"Bremelanotide: una panoramica degli effetti preclinici sul SNC nella funzione sessuale femminile",source:"Journal of Sexual Medicine",year:2007,url:"https://pubmed.ncbi.nlm.nih.gov/17958619/",finding:"Ha passato in rassegna il lavoro preclinico in modelli di ratto femmina che riferiva un'azione di bremelanotide attraverso le vie melanocortiniche centrali, con somministrazione cerebrale sito-specifica e microdialisi per localizzare l'effetto."},{title:"Valutazione in doppio cieco, controllata con placebo, della sicurezza, delle proprietà farmacocinetiche e degli effetti farmacodinamici di PT-141 intranasale, un agonista dei recettori della melanocortina",source:"International Journal of Impotence Research",year:2004,url:"https://pubmed.ncbi.nlm.nih.gov/14963471/",finding:"Ha riferito dati farmacocinetici e di sicurezza per PT-141 intranasale in maschi sani e in pazienti, descrivendo la sostanza come un analogo eptapeptidico ciclico della melanocortina con un'emivita di circa due ore."},{title:"Bremelanotide per il trattamento del disturbo da desiderio sessuale ipoattivo: due studi randomizzati di fase 3",source:"Obstetrics and Gynecology",year:2019,url:"https://pubmed.ncbi.nlm.nih.gov/31599840/",finding:"Ha riferito due studi di fase 3 randomizzati, controllati con placebo, della durata di 24 settimane (RECONNECT) su una formulazione sottocutanea di bremelanotide in donne in premenopausa, con nausea, vampate e cefalea come eventi avversi riferiti più di frequente."}],reconstitution:"Di norma ricostituito con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C.",howSupplied:"Fornito come singolo flaconcino sigillato contenente polvere liofilizzata bianca di PT-141. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata."},cagrilintide:{name:"Cagrilintide",description:"Analogo lipidato dell'amilina a lunga durata d'azione (AM833, NNC0174-0833) fornito come standard di riferimento liofilizzato per la ricerca sulla farmacologia dei recettori dell'amilina e della calcitonina e sull'apporto energetico. Disponibile in flaconcini da 5mg e 10mg.",longDescription:"Cagrilintide è un analogo dell'amilina di 37 residui acilato con un diacido grasso C20, sviluppato da Novo Nordisk come agonista dei recettori dell'amilina a somministrazione settimanale e studiato come componente amilinica della combinazione cagrilintide più semaglutide (CagriSema). È stata caratterizzata come agonista non selettivo dei recettori dell'amilina e della calcitonina e valutata nella ricerca di fase 1, fase 2 e fase 3 sulla gestione del peso. Viene fornita a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca sulla farmacologia dei recettori dell'amilina","Studi sull'agonismo del recettore della calcitonina","Modelli delle vie dell'apporto energetico e della sazietà","Ricerca sui peptidi lipidati a lunga durata d'azione","Studi sulla combinazione di amilina e GLP-1"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. Cagrilintide viene fornita come polvere liofilizzata. Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Cos'è Cagrilintide?",answer:"Cagrilintide (AM833, NNC0174-0833) è un analogo lipidato a lunga durata d'azione dell'ormone pancreatico amilina. Viene studiata come agonista non selettivo dei recettori dell'amilina e della calcitonina nella ricerca sull'apporto energetico e sul peso corporeo."},{question:"Cagrilintide e CagriSema sono la stessa cosa?",answer:"No. CagriSema è la combinazione a dose fissa di cagrilintide con l'agonista del recettore GLP-1 semaglutide, studiata negli studi REDEFINE. Questo prodotto è cagrilintide da sola, fornita come standard di riferimento per la ricerca."},{question:"Quali sono il peso molecolare e la formula di Cagrilintide?",answer:"Cagrilintide ha formula molecolare C194H312N54O59S2 e un peso molecolare di circa 4409 g/mol (PubChem CID 171397054, CAS 1415456-99-3). È un peptide amidato di 37 residui con un ponte disolfuro Cys2-Cys7 e un diacido grasso C20 legato tramite uno spaziatore gamma-glutammilico."},{question:"Qual è la purezza della Cagrilintide di Miro Biotech?",answer:"Ogni lotto viene testato in modo indipendente da un laboratorio terzo e verificato al 99,31% di purezza, con un certificato di analisi per il lotto."},{question:"Come va conservata Cagrilintide?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["amilina","metabolico","gestione del peso","recettore della calcitonina","lunga durata d'azione","peptide da ricerca"],aka:["AM833","NNC0174-0833","Analogo dell'amilina cagrilintide"],whatIs:"Cagrilintide è un analogo lipidato dell'amilina a lunga durata d'azione che agisce come agonista non selettivo sui recettori dell'amilina e della calcitonina. È impiegata come sostanza da ricerca in studi sulla segnalazione della sazietà, sull'apporto energetico e sulla farmacologia della combinazione di amilina e GLP-1. Fornita esclusivamente per la ricerca in-vitro e di laboratorio.",mechanism:"Nella ricerca pubblicata cagrilintide è stata caratterizzata come agonista non selettivo dei recettori dell'amilina (recettore della calcitonina associato alle proteine modificanti l'attività recettoriale) e dello stesso recettore della calcitonina, a confronto con agonisti di riferimento selettivi e non selettivi. La sua acilazione con un diacido grasso C20 favorisce il legame all'albumina e un'emivita di circa 159-195 ore riferita in uno studio di fase 1b. Uno studio di fase 2 di 26 settimane per la determinazione della dose ha riferito riduzioni medie del peso corporeo del 6,0-10,8% con le diverse dosi settimanali rispetto al 3,0% con placebo, e lo studio di fase 3 REDEFINE 1 sulla combinazione cagrilintide più semaglutide ha riferito una variazione media stimata del -20,4% rispetto al -3,0% per il placebo a 68 settimane. Questi risultati descrivono la letteratura clinica pubblicata; la sostanza viene fornita qui esclusivamente come standard di riferimento per la ricerca.",receptorTargets:["Recettori dell'amilina (CTR + RAMP1/2/3)","Recettore della calcitonina (CTR)","Circuiti della sazietà del rombencefalo e dell'ipotalamo","Interazione tra le vie dell'amilina e del GLP-1"],specs:[{label:"Sequenza",value:"KCNTATCATQRLAEFLRHSSNNFGPILPPTNVGSNTP-NH2, ponte disolfuro Cys2-Cys7"},{label:"Classificazione",value:"Analogo lipidato dell'amilina a lunga durata d'azione (diacido grasso C20 tramite spaziatore gamma-Glu)"},{label:"Aspetto",value:"Polvere liofilizzata bianca"},{label:"Solubilità",value:"Solubile in acqua batteriostatica"}],researchApplications:[{title:"Farmacologia dei recettori dell'amilina",description:"Impiegata in saggi di segnalazione recettoriale che confrontano agonisti dei recettori dell'amilina e della calcitonina."},{title:"Modelli di apporto energetico",description:"Studiata nella ricerca su sazietà e assunzione di cibo in modelli su roditori e nell'uomo."},{title:"Farmacologia delle combinazioni",description:"Esplorata insieme ad agonisti del recettore GLP-1 nella ricerca sul peso corporeo a doppia via."},{title:"Progettazione di peptidi a lunga durata d'azione",description:"Applicata in studi su acilazione con diacidi grassi, legame all'albumina ed emivita prolungata."}],keyStudies:[{title:"Cagrilintide una volta a settimana per la gestione del peso in persone con sovrappeso e obesità: uno studio di fase 2 per la determinazione della dose",source:"The Lancet",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34798060/",finding:"Ha riferito uno studio di fase 2 di 26 settimane su 706 adulti in cui cagrilintide 0,3-4,5 mg una volta a settimana ha prodotto riduzioni medie del peso corporeo del 6,0-10,8% rispetto al 3,0% con placebo, con eventi gastrointestinali e reazioni nel sito di iniezione come eventi avversi più frequenti."},{title:"Sicurezza, tollerabilità, farmacocinetica e farmacodinamica della somministrazione concomitante di dosi multiple di cagrilintide con semaglutide 2,4 mg: uno studio di fase 1b",source:"The Lancet",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/33894838/",finding:"Ha riferito uno studio di fase 1b di 20 settimane in cui cagrilintide ha mostrato un'emivita di 159-195 ore e un'esposizione proporzionale alla dose che non alterava l'esposizione a semaglutide, con riduzioni del peso corporeo maggiori a 1,2 e 2,4 mg rispetto al placebo."},{title:"Cagrilintide e semaglutide in co-somministrazione in adulti con sovrappeso o obesità",source:"New England Journal of Medicine",year:2025,url:"https://pubmed.ncbi.nlm.nih.gov/40544433/",finding:"Ha riferito lo studio di fase 3a REDEFINE 1 di 68 settimane su 3.417 adulti, con una variazione media stimata del peso corporeo del -20,4% per cagrilintide 2,4 mg più semaglutide 2,4 mg rispetto al -3,0% per il placebo."}],reconstitution:"Di norma ricostituita con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C.",howSupplied:"Fornito come singolo flaconcino sigillato contenente polvere liofilizzata bianca di Cagrilintide nel formato scelto. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata."},dsip:{name:"DSIP",description:"Peptide induttore del sonno delta (emideltide), nonapeptide sintetico fornito come standard di riferimento liofilizzato per la ricerca sull'EEG del sonno, neuroendocrina e sulla risposta allo stress. Disponibile in flaconcini da 2mg, 5mg e 10mg.",longDescription:"DSIP (Trp-Ala-Gly-Gly-Asp-Ala-Ser-Gly-Glu) è stato isolato negli anni Settanta dal sangue venoso cerebrale di conigli durante il sonno indotto e deve il suo nome all'aumento dell'attività EEG delta prodotto dal peptide sintetico dopo infusione centrale. È stato in seguito esaminato in piccoli studi umani iniziali sul sonno e in lavori su roditori sull'asse ipotalamo-ipofisario e sulla risposta allo stress, con risultati contrastanti, e il suo precursore endogeno e il suo recettore non sono mai stati identificati. Viene fornito a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca sull'EEG del sonno e sull'attività delta","Studi neuroendocrini e sulla via dell'ACTH","Modelli di risposta allo stress nei roditori","Standard di riferimento neuropeptidico classico","Ricerca sulla stabilità dei nonapeptidi e sugli analoghi"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. DSIP viene fornito come polvere liofilizzata. Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Cos'è DSIP?",answer:"DSIP (peptide induttore del sonno delta, INN emideltide) è un peptide di nove residui caratterizzato per la prima volta nel 1977 dal sangue venoso cerebrale di coniglio. Viene studiato come neuropeptide di riferimento nella ricerca sull'EEG del sonno, neuroendocrina e sulla risposta allo stress."},{question:"DSIP è stato studiato nell'uomo?",answer:"Solo in piccoli studi iniziali degli anni Ottanta e Novanta, tutti con somministrazione endovenosa in contesti di ricerca. I risultati sono stati contrastanti: uno studio del 1981 su sei volontari ha riferito un sonno più lungo, mentre uno studio in doppio cieco del 1992 su sedici pazienti insonni ha concluso che gli effetti erano deboli. Viene fornito qui esclusivamente come standard di riferimento per la ricerca."},{question:"Quali sono la sequenza e il peso molecolare di DSIP?",answer:"DSIP ha sequenza Trp-Ala-Gly-Gly-Asp-Ala-Ser-Gly-Glu (WAGGDASGE), formula molecolare C35H48N10O15 e un peso molecolare di circa 848,8 g/mol come peptide libero (PubChem CID 68816, CAS 62568-57-4)."},{question:"Qual è la purezza del DSIP di Miro Biotech?",answer:"Ogni lotto viene testato in modo indipendente da un laboratorio terzo e verificato al 99,24% di purezza, con un certificato di analisi per il lotto."},{question:"Come va conservato DSIP?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine, al riparo da luce e umidità. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni; evitare ripetuti cicli di congelamento e scongelamento."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["sonno","neuropeptide","EEG","neuroendocrino","risposta allo stress","peptide da ricerca"],aka:["Emideltide","Peptide induttore del sonno delta","WAGGDASGE"],whatIs:"DSIP è un nonapeptide sintetico che deve il suo nome all'aumento dell'attività EEG a onde delta prodotto nei conigli dopo infusione centrale. È impiegato come sostanza da ricerca in studi sulla regolazione del sonno, sulla segnalazione dell'ACTH e dell'ipofisi e sulle vie della risposta allo stress. Fornito esclusivamente per la ricerca in-vitro e di laboratorio.",mechanism:"Nella ricerca pubblicata il DSIP sintetico ha potenziato l'attività EEG delta e dei fusi del sonno dopo infusione intraventricolare nei conigli, in esperimenti in doppio cieco, un effetto che frammenti e analoghi non hanno riprodotto. I piccoli studi umani iniziali hanno dato risultati contrastanti: uno studio crossover del 1981 su sei volontari ha riferito un aumento mediano del 59% del tempo totale di sonno senza sedazione classica, mentre uno studio in doppio cieco del 1992 su sedici insonni cronici ha rilevato solo effetti deboli su efficienza e latenza del sonno. I dati endocrini sono incoerenti: uno studio su otto uomini ha riferito un ACTH plasmatico più basso, un altro non ha trovato variazioni dell'ACTH e del cortisolo stimolati da CRH o dal pasto. Una rassegna del 2006 ha osservato che non sono stati identificati né un gene, né una proteina precursore, né un recettore per il DSIP, per cui il meccanismo resta indefinito. Questi risultati descrivono la letteratura pubblicata; la sostanza viene fornita qui esclusivamente come standard di riferimento per la ricerca.",receptorTargets:["Attività EEG delta (circuiti di regolazione del sonno, meccanismo indefinito)","Asse ipotalamo-ipofisario (ACTH, risultati incoerenti)","Vie della risposta allo stress in modelli su roditori","Nessun recettore o gene precursore identificato"],specs:[{label:"Sequenza",value:"Trp-Ala-Gly-Gly-Asp-Ala-Ser-Gly-Glu (WAGGDASGE)"},{label:"Classificazione",value:"Nonapeptide sintetico, standard di riferimento di neuropeptide associato al sonno"},{label:"Aspetto",value:"Polvere liofilizzata bianca"},{label:"Solubilità",value:"Solubile in acqua e in acqua batteriostatica (circa 10 mg/mL in tampone neutro)"}],researchApplications:[{title:"Ricerca sull'EEG del sonno",description:"Impiegato come peptide di riferimento in studi sull'attività a onde delta e dei fusi del sonno in modelli di coniglio e di ratto."},{title:"Segnalazione neuroendocrina",description:"Studiato per gli effetti su ACTH, cortisolo e altri ormoni ipofisari in piccoli studi sull'uomo e sui roditori."},{title:"Modelli di risposta allo stress",description:"Esplorato come fattore limitante lo stress in modelli su roditori di stress emotivo e fisico."},{title:"Chimica dei peptidi",description:"Applicato in studi su analoghi, fosforilazione e isomerizzazione Asp-Gly sulla stabilità dei peptidi corti."}],keyStudies:[{title:"Caratterizzazione di un peptide induttore del delta-elettroencefalogramma (-sonno)",source:"Proceedings of the National Academy of Sciences",year:1977,url:"https://pubmed.ncbi.nlm.nih.gov/265572/",finding:"Ha isolato il nonapeptide dal sangue venoso cerebrale di coniglio, ne ha stabilito la sequenza e ha mostrato, in esperimenti in doppio cieco su 58 conigli, che solo il peptide sintetico a lunghezza intera, e non i suoi frammenti o analoghi, potenziava l'attività EEG delta e dei fusi del sonno dopo infusione intraventricolare."},{title:"Effetti acuti e ritardati del DSIP (peptide induttore del sonno delta) sul comportamento del sonno nell'uomo",source:"International Journal of Clinical Pharmacology, Therapy, and Toxicology",year:1981,url:"https://pubmed.ncbi.nlm.nih.gov/6895513/",finding:"Ha riferito uno studio crossover in doppio cieco su sei volontari sani in cui una singola infusione endovenosa ha aumentato il tempo totale di sonno mediano del 59% entro circa due ore e ha migliorato l'efficienza del sonno della notte successiva, senza sedazione nel senso farmacologico classico."},{title:"Effetti del peptide induttore del sonno delta sul sonno di pazienti con insonnia cronica. Uno studio in doppio cieco",source:"Neuropsychobiology",year:1992,url:"https://pubmed.ncbi.nlm.nih.gov/1299794/",finding:"Ha riferito uno studio in doppio cieco su sedici pazienti con insonnia cronica in cui tre infusioni endovenose hanno prodotto un'efficienza del sonno più alta e una latenza del sonno più breve rispetto al placebo, ma gli autori hanno giudicato gli effetti deboli e in parte attribuibili a una variazione nel gruppo placebo."},{title:"Peptide induttore del sonno delta (DSIP): un enigma ancora irrisolto",source:"Journal of Neurochemistry",year:2006,url:"https://pubmed.ncbi.nlm.nih.gov/16539679/",finding:"Ha passato in rassegna tre decenni di ricerca sul DSIP e ha concluso che il gene, la proteina precursore e il recettore del peptide non sono mai stati identificati e che le prove a favore del DSIP come fattore endogeno del sonno restano deboli."}],reconstitution:"Di norma ricostituito con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C ed evitare ripetuti cicli di congelamento e scongelamento.",howSupplied:"Fornito come singolo flaconcino sigillato contenente polvere liofilizzata bianca di DSIP nel formato scelto. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata."},"5-amino-1mq":{name:"5-Amino-1MQ",description:"Inibitore di NNMT a piccola molecola (ioduro di 5-ammino-1-metilchinolinio) fornito come standard di riferimento in polvere secca per la ricerca sul metabolismo degli adipociti, sul recupero del NAD+ e sull'invecchiamento muscolare in modelli cellulari e murini. Disponibile in flaconcini da 5mg, 10mg e 50mg.",longDescription:"5-Amino-1MQ è un sale di chinolinio permeabile alle membrane che inibisce la nicotinamide N-metiltransferasi (NNMT), l'enzima che metila la nicotinamide e consuma S-adenosilmetionina. È emerso da uno studio di relazione struttura-attività del 2017 sugli inibitori di NNMT ed è stato da allora esaminato in adipociti in coltura e in topi obesi per dieta e anziani, in cui l'inibizione di NNMT è stata associata a una minore massa grassa, a una migliore gestione del glucosio e all'attivazione delle cellule staminali muscolari. È una piccola molecola e non un peptide, e non ha studi pubblicati sull'uomo. Viene fornito a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca sull'inibizione dell'enzima NNMT","Modelli di lipogenesi degli adipociti e di massa grassa","Studi sul metabolismo di NAD+ e SAM","Ricerca sull'invecchiamento delle cellule staminali muscolari","Modelli murini di obesità indotta dalla dieta"],researchGuide:"Ricostituire con acqua sterile o batteriostatica alla concentrazione desiderata. 5-Amino-1MQ viene fornito come polvere secca idrosolubile e igroscopica. Conservare il flaconcino sigillato a -20 °C, al riparo da luce e umidità, e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Cos'è 5-Amino-1MQ?",answer:"5-Amino-1MQ (5-ammino-1-metilchinolinio) è un inibitore a piccola molecola della nicotinamide N-metiltransferasi (NNMT), un enzima elevato nel tessuto adiposo dei topi obesi. Viene studiato nella ricerca sul metabolismo degli adipociti, sul recupero del NAD+ e sull'invecchiamento muscolare."},{question:"5-Amino-1MQ è un peptide?",answer:"No. È una piccola molecola di chinolinio (C10H11IN2 come sale ioduro, peso molecolare di circa 286,1 g/mol). È elencato accanto ai nostri peptidi da ricerca metabolici perché viene studiato negli stessi modelli di bilancio energetico e di tessuto adiposo, ma appartiene a una classe di composti diversa."},{question:"Per cosa è stato studiato 5-Amino-1MQ?",answer:"Il lavoro pubblicato riguarda solo cellule e topi. In topi obesi per dieta, l'inibizione di NNMT con questa sostanza è stata associata a una minore massa grassa e ad adipociti più piccoli senza variazioni dell'assunzione di cibo, e a una migliore tolleranza al glucosio. In topi anziani è stata associata all'attivazione delle cellule staminali muscolari e a una migliore rigenerazione dopo lesione. Non esistono studi pubblicati sull'uomo."},{question:"Qual è la purezza del 5-Amino-1MQ di Miro Biotech?",answer:"Ogni lotto viene testato in modo indipendente da un laboratorio terzo e verificato al 99,47% di purezza, con un certificato di analisi per il lotto."},{question:"Come va conservato 5-Amino-1MQ?",answer:"Conservare il flaconcino sigillato a -20 °C, al riparo da luce e umidità, perché il solido è igroscopico. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["NNMT","metabolico","adipociti","NAD+","piccola molecola","invecchiamento muscolare"],aka:["5-ammino-1-metilchinolinio","NNMTi","5A1MQ"],whatIs:"5-Amino-1MQ è una piccola molecola idrosolubile e permeabile alle membrane che inibisce la nicotinamide N-metiltransferasi (NNMT). È impiegato come sostanza da ricerca in studi sulla lipogenesi degli adipociti, sul metabolismo di NAD+ e S-adenosilmetionina e sull'invecchiamento delle cellule staminali muscolari in coltura cellulare e in modelli murini. Fornito esclusivamente per la ricerca in-vitro e di laboratorio.",mechanism:"Nella ricerca pubblicata 5-Amino-1MQ ha inibito NNMT con una IC50 nell'ordine del basso micromolare legandosi al sito del substrato nicotinamide, ed è risultato selettivo rispetto alle metiltransferasi correlate e agli enzimi del recupero del NAD+. In adipociti 3T3-L1 in coltura ha ridotto la lipogenesi e modificato i livelli di 1-metilnicotinamide e di NAD+. In topi obesi per dieta, il trattamento sottocutaneo per undici giorni è stato associato a una massa grassa epididimale inferiore di circa il 35%, ad adipociti più piccoli di oltre il 30% e a un colesterolo totale inferiore di circa il 30% senza variazioni dell'assunzione di cibo, e uno studio di 28 giorni ha riferito una limitazione dose-dipendente dell'aumento di peso con una migliore tolleranza al glucosio e una minore steatosi epatica. In topi anziani, l'inibizione di NNMT ha attivato le cellule staminali muscolari senescenti e migliorato la rigenerazione dopo lesione. Questi risultati descrivono la letteratura pubblicata su cellule e topi; non esistono studi pubblicati sull'uomo e la sostanza viene fornita qui esclusivamente come standard di riferimento per la ricerca.",receptorTargets:["Nicotinamide N-metiltransferasi (NNMT)","Metabolismo di nicotinamide, SAM e 1-metilnicotinamide","Vie della lipogenesi degli adipociti","Attivazione delle cellule staminali muscolari (modelli di topo anziano)"],specs:[{label:"Struttura",value:"Ioduro di 5-ammino-1-metilchinolinio, C10H11IN2 (CAS 42464-96-0)"},{label:"Classificazione",value:"Inibitore di NNMT a piccola molecola (sale di chinolinio), non un peptide"},{label:"Aspetto",value:"Polvere secca, igroscopica"},{label:"Solubilità",value:"Solubile in acqua e in acqua batteriostatica"}],researchApplications:[{title:"Saggi di inibizione di NNMT",description:"Impiegato come inibitore di riferimento in saggi di cinetica enzimatica e di selettività rispetto alle metiltransferasi correlate."},{title:"Metabolismo degli adipociti",description:"Studiato in adipociti 3T3-L1 in coltura per gli effetti sulla lipogenesi e sui livelli dei metaboliti correlati al NAD+."},{title:"Modelli di obesità indotta dalla dieta",description:"Esplorato in modelli murini a dieta ricca di grassi per le variazioni di massa grassa, tolleranza al glucosio e grasso epatico."},{title:"Ricerca sull'invecchiamento muscolare",description:"Applicato in studi su topi anziani sull'attivazione delle cellule staminali muscolari, sulla rigenerazione e sulla risposta all'esercizio."}],keyStudies:[{title:"Inibitori a piccola molecola, selettivi e permeabili alle membrane, della nicotinamide N-metiltransferasi invertono l'obesità indotta da dieta ricca di grassi nei topi",source:"Biochemical Pharmacology",year:2018,url:"https://pubmed.ncbi.nlm.nih.gov/29155147/",finding:"Ha riferito che 5-Amino-1MQ ha ridotto la lipogenesi in adipociti in coltura e, in topi obesi per dieta trattati per via sottocutanea per undici giorni, è stato associato a una massa grassa epididimale inferiore di circa il 35%, ad adipociti più piccoli di oltre il 30% e a un colesterolo inferiore di circa il 30% con assunzione di cibo invariata."},{title:"L'inibizione della nicotinamide N-metiltransferasi attenua la disfunzione metabolica correlata all'obesità",source:"Diabetes, Obesity and Metabolism",year:2024,url:"https://pubmed.ncbi.nlm.nih.gov/39161060/",finding:"Ha riferito uno studio di 28 giorni in topi obesi per dieta in cui il trattamento quotidiano ha limitato in modo dose-dipendente l'aumento di peso e di grasso, migliorato la tolleranza al glucosio e la sensibilità all'insulina e ridotto la steatosi epatica, con distribuzione nel tessuto adiposo, muscolare ed epatico."},{title:"Un inibitore a piccola molecola della nicotinamide N-metiltransferasi attiva le cellule staminali muscolari senescenti e migliora la capacità rigenerativa del muscolo scheletrico anziano",source:"Biochemical Pharmacology",year:2019,url:"https://pubmed.ncbi.nlm.nih.gov/30753815/",finding:"Ha riferito che in topi di 24 mesi trattati dopo una lesione muscolare l'inibizione di NNMT ha aumentato l'attivazione delle cellule staminali muscolari e migliorato la rigenerazione del muscolo leso rispetto al veicolo."},{title:"Relazione struttura-attività per inibitori a piccola molecola della nicotinamide N-metiltransferasi",source:"Journal of Medicinal Chemistry",year:2017,url:"https://pubmed.ncbi.nlm.nih.gov/28548833/",finding:"Ha descritto la serie di chinolinio da cui è stato selezionato 5-Amino-1MQ, riferendo un'inibizione di NNMT nell'ordine del basso micromolare tramite legame al sito del substrato nicotinamide."}],reconstitution:"Di norma ricostituito con acqua sterile o batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione finché la polvere non si è sciolta. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere secca sigillata a -20 °C, al riparo da luce e umidità; il solido è igroscopico. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C.",howSupplied:"Fornito come singolo flaconcino sigillato contenente polvere secca di 5-Amino-1MQ nel formato scelto. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata."},"aod-9604":{name:"AOD-9604",description:"Frammento C-terminale sintetico dell'ormone della crescita umano (hGH 177-191, esadecapeptide) fornito come standard di riferimento liofilizzato per la ricerca sulla lipolisi del tessuto adiposo, sull'ossidazione dei grassi e sul bilancio energetico. Disponibile in flaconcini da 2mg, 5mg e 10mg.",longDescription:"AOD-9604 è un peptide di 16 residui corrispondente al dominio lipolitico C-terminale dell'ormone della crescita umano (residui 177-191) con una tirosina N-terminale aggiunta, sviluppato da Metabolic Pharmaceuticals per conservare l'attività lipolitica dell'hGH senza la sua segnalazione di promozione della crescita. In ratti Zucker obesi e topi ob/ob è stato associato a un minore aumento di peso e a una maggiore ossidazione dei grassi senza l'iperglicemia osservata con l'hGH intatto, e non si lega al recettore dell'hGH in vitro. Sei studi clinici controllati con placebo sull'uomo ne hanno definito il profilo di sicurezza, mentre lo studio di fase 2b di 24 settimane sull'obesità non ha mostrato una perdita di peso significativa e lo sviluppo clinico si è concluso nel 2007. Viene fornito a singoli ricercatori, laboratori e istituzioni esclusivamente per la ricerca in-vitro e di laboratorio.",benefits:["Ricerca sulla lipolisi del tessuto adiposo in modelli su roditori","Studi sull'ossidazione dei grassi e sul dispendio energetico","Ricerca struttura-attività sui frammenti dell'hGH","Modelli di espressione del recettore beta-3 adrenergico","Sviluppo di metodi di rilevamento antidoping"],researchGuide:"Ricostituire con acqua batteriostatica alla concentrazione desiderata. AOD-9604 viene fornito come polvere liofilizzata. Conservare la polvere liofilizzata a -20 °C e mantenere la soluzione ricostituita a 2-8 °C, utilizzandola entro 30 giorni.",faq:[{question:"Cos'è AOD-9604?",answer:"AOD-9604 è un frammento sintetico di 16 residui dell'ormone della crescita umano (residui 177-191 con una tirosina N-terminale) che conserva il dominio lipolitico dell'hGH senza la sua attività di promozione della crescita. Viene studiato in modelli su roditori di lipolisi del tessuto adiposo, ossidazione dei grassi e bilancio energetico."},{question:"AOD-9604 è stato studiato nell'uomo?",answer:"Sì. Sei studi randomizzati e controllati con placebo su 925 soggetti, con somministrazione orale ed endovenosa fino a 24 settimane, non hanno riferito variazioni dell'IGF-1, nessun effetto su glucosio o insulina e un profilo di eventi avversi simile al placebo. Lo studio di fase 2b di 24 settimane sull'obesità non ha mostrato una perdita di peso significativa e lo sviluppo clinico è stato interrotto nel 2007. Viene fornito qui esclusivamente come standard di riferimento per la ricerca."},{question:"Quali sono la sequenza e il peso molecolare di AOD-9604?",answer:"AOD-9604 ha sequenza Tyr-Leu-Arg-Ile-Val-Gln-Cys-Arg-Ser-Val-Glu-Gly-Ser-Cys-Gly-Phe (YLRIVQCRSVEGSCGF) con un ponte disolfuro Cys7-Cys14, formula molecolare C78H123N23O23S2 e un peso molecolare di circa 1815,1 g/mol come peptide libero (PubChem CID 71300630, CAS 221231-10-3)."},{question:"Qual è la purezza dell'AOD-9604 di Miro Biotech?",answer:"Ogni lotto viene testato in modo indipendente da un laboratorio terzo e verificato al 99,36% di purezza, con un certificato di analisi per il lotto."},{question:"Come va conservato AOD-9604?",answer:"Conservare la polvere liofilizzata a -20 °C per la conservazione a lungo termine, al riparo da luce e umidità. Le soluzioni ricostituite vanno mantenute a 2-8 °C e utilizzate entro 30 giorni; evitare ripetuti cicli di congelamento e scongelamento, che possono compromettere il ponte disolfuro."},{question:"Cosa è incluso nel mio ordine?",answer:"Il tuo ordine contiene il flaconcino o i flaconcini di peptide. Ogni lotto viene testato da un laboratorio terzo indipendente con un certificato di analisi (COA) digitale. Un COA per ogni prodotto è disponibile su richiesta."}],tags:["lipolisi","metabolico","frammento dell'ormone della crescita","tessuto adiposo","ossidazione dei grassi","peptide da ricerca"],aka:["AOD9604","Tyr-hGH177-191","Frammento hGH 176-191","LAT8881"],whatIs:"AOD-9604 è un esadecapeptide sintetico derivato dalla regione C-terminale dell'ormone della crescita umano, progettato per isolare il dominio lipolitico dell'hGH dalla sua segnalazione di promozione della crescita. È impiegato come sostanza da ricerca in studi sulla lipolisi del tessuto adiposo, sull'ossidazione dei grassi e sul dispendio energetico in modelli su roditori, e come materiale di riferimento nello sviluppo di metodi antidoping. Fornito esclusivamente per la ricerca in-vitro e di laboratorio.",mechanism:"Nella ricerca pubblicata, AOD-9604 somministrato per via orale a ratti Zucker obesi per 19 giorni è stato associato a meno della metà dell'aumento di peso dei controlli e a una maggiore attività lipolitica del tessuto adiposo, senza perdita di sensibilità all'insulina al clamp euglicemico, a differenza dell'hGH intatto. In topi ob/ob il trattamento cronico è stato associato a un minore aumento di peso e a una maggiore ossidazione dei grassi in vivo senza iperglicemia, e il peptide non ha competuto per il recettore dell'hGH né indotto proliferazione in una linea cellulare con recettore dell'hGH. Il trattamento ha ripristinato l'espressione repressa del recettore beta-3 adrenergico in topi obesi, ma gli effetti cronici erano assenti in topi knockout per il recettore beta-3, per cui gli autori hanno concluso che l'azione lipolitica non è mediata direttamente da quel recettore. Nell'uomo, sei studi controllati con placebo non hanno riferito variazioni dell'IGF-1 o del metabolismo del glucosio; il braccio orale da 1 mg/die di 12 settimane ha perso 2,6 kg contro 0,8 kg con placebo senza dipendenza dalla dose, e lo studio di fase 2b di 24 settimane non ha mostrato una perdita di peso significativa. Questi risultati descrivono la letteratura pubblicata; la sostanza viene fornita qui esclusivamente come standard di riferimento per la ricerca.",receptorTargets:["Vie della lipolisi del tessuto adiposo e dell'ossidazione dei grassi (modelli su roditori)","Espressione del recettore beta-3 adrenergico (associata, non diretta)","Nessun legame al recettore dell'hGH","Regolazione acuta del dispendio energetico (roditori)"],specs:[{label:"Sequenza",value:"Tyr-Leu-Arg-Ile-Val-Gln-Cys-Arg-Ser-Val-Glu-Gly-Ser-Cys-Gly-Phe (YLRIVQCRSVEGSCGF), ponte disolfuro Cys7-Cys14"},{label:"Classificazione",value:"Frammento C-terminale sintetico dell'hGH (esadecapeptide), dominio lipolitico"},{label:"Aspetto",value:"Polvere liofilizzata bianca"},{label:"Solubilità",value:"Solubile in acqua e in acqua batteriostatica"}],researchApplications:[{title:"Modelli di obesità nei roditori",description:"Impiegato in studi su ratti Zucker obesi e topi ob/ob su aumento di peso, ossidazione dei grassi e gestione del glucosio."},{title:"Saggi di lipolisi",description:"Studiato in preparazioni di tessuto adiposo per l'attività lipolitica e il rilascio di glicerolo."},{title:"Struttura-attività dei frammenti dell'hGH",description:"Applicato in lavori che separano il dominio lipolitico dell'ormone della crescita dalla sua segnalazione di crescita mediata dal recettore."},{title:"Sviluppo di metodi antidoping",description:"Serve come materiale di riferimento per il rilevamento LC-MS e per studi di metabolismo in-vitro dei frammenti dell'ormone della crescita."}],keyStudies:[{title:"Studi metabolici di un dominio lipolitico sintetico (AOD9604) dell'ormone della crescita umano",source:"Hormone Research",year:2e3,url:"https://pubmed.ncbi.nlm.nih.gov/11146367/",finding:"Ha riferito che ratti Zucker obesi trattati con AOD9604 per via orale per 19 giorni hanno guadagnato meno della metà del peso corporeo dei controlli, hanno mostrato una maggiore attività lipolitica del tessuto adiposo e hanno mantenuto una normale sensibilità all'insulina al clamp euglicemico, a differenza degli animali trattati con ormone della crescita intatto."},{title:"Gli effetti del GH umano e del suo frammento lipolitico (AOD9604) sul metabolismo lipidico dopo trattamento cronico in topi obesi e topi knockout per il beta(3)-AR",source:"Endocrinology",year:2001,url:"https://pubmed.ncbi.nlm.nih.gov/11713213/",finding:"Ha riferito che 14 giorni di trattamento hanno ridotto peso corporeo e massa grassa e ripristinato l'espressione repressa del recettore beta-3 adrenergico in topi obesi, mentre gli effetti cronici erano assenti in topi knockout per il recettore beta-3, portando gli autori a concludere che l'azione lipolitica non è mediata direttamente dal recettore."},{title:"Sicurezza e tollerabilità dell'esadecapeptide AOD9604 nell'uomo",source:"Journal of Endocrinology and Metabolism",year:2013,url:"https://www.jofem.org/index.php/jofem/article/view/157/194",finding:"Ha riassunto sei studi randomizzati, in doppio cieco e controllati con placebo su 925 soggetti con AOD9604 orale ed endovenoso fino a 24 settimane, riferendo nessun effetto sull'IGF-1 sierico o sul metabolismo dei carboidrati, nessun anticorpo anti-farmaco e un profilo di eventi avversi indistinguibile dal placebo."},{title:"Bersagli molecolari centrali e periferici per la farmacoterapia antiobesità",source:"Clinical Pharmacology and Therapeutics",year:2010,url:"https://pubmed.ncbi.nlm.nih.gov/20445536/",finding:"Ha passato in rassegna il programma clinico di AOD9604, osservando una variazione di peso di 2,6 kg contro 0,8 kg con placebo nel braccio orale da 1 mg/die di 12 settimane senza dipendenza dalla dose, e che lo sviluppo è stato interrotto nel 2007 dopo che uno studio di 24 settimane su 536 soggetti non ha mostrato una perdita di peso significativa."}],reconstitution:"Di norma ricostituito con acqua batteriostatica per l'uso in laboratorio. Aggiungere lentamente il diluente lungo la parete del flaconcino e agitare delicatamente per rotazione anziché scuotere. Conservare la soluzione ricostituita in frigorifero e utilizzarla entro un periodo di ricerca definito.",storage:"Conservare la polvere liofilizzata sigillata a -20 °C, al riparo da luce e umidità. Dopo la ricostituzione, conservare in frigorifero a 2-8 °C ed evitare ripetuti cicli di congelamento e scongelamento.",howSupplied:"Fornito come singolo flaconcino sigillato contenente polvere liofilizzata bianca di AOD-9604 nel formato scelto. L'acqua batteriostatica per la ricostituzione è disponibile come integrazione separata."}},categories:{"metabolic-peptides":{name:"Peptidi metabolici",description:"Peptidi coinvolti nella regolazione metabolica, nell'omeostasi energetica e nella ricerca sulla composizione corporea. Comprende agonisti dei recettori GLP-1, GIP e glucagone."},"recovery-peptides":{name:"Peptidi per recupero e riparazione",description:"Peptidi per la riparazione dei tessuti e la guarigione delle ferite per gli studi di medicina rigenerativa. Utilizzati in tutto il mondo da singoli ricercatori, laboratori e istituzioni per la ricerca in-vitro."},"cognitive-peptides":{name:"Peptidi cognitivi",description:"Peptidi nootropi e neuroprotettivi per le neuroscienze e la ricerca su memoria, attenzione e SNC. Studiati in-vitro da singoli ricercatori, laboratori e istituzioni."},"anti-aging-peptides":{name:"Peptidi anti-invecchiamento",description:"Peptidi studiati per il loro ruolo nella longevità, nella salute della pelle, nell'energia cellulare e nei processi biologici legati all'età."},blends:{name:"Miscele da ricerca",description:"Miscele da ricerca multi-peptide, co-liofilizzate in un unico flaconcino per disegni di studio con vie combinate. Fornite a singoli ricercatori, laboratori e istituzioni, esclusivamente per la ricerca in-vitro e di laboratorio."},accessories:{name:"Accessori da ricerca",description:"Materiali di base per la ricerca sui peptidi, tra cui acqua batteriostatica e materiali per la ricostituzione. Utilizzati in tutto il mondo da singoli ricercatori, laboratori e istituzioni."}}},sv:{products:{"glp-3-rt":{name:"GLP-3 (RT)",description:"Trippelagonistpeptid som riktar sig mot GLP-1-, GIP- och glukagonreceptorer för metabol- och fetmaforskning.",longDescription:"GLP-3 (RT) är en ny trippelagonistpeptid som samtidigt riktar sig mot GLP-1-, GIP- och glukagonreceptorer. Denna unika trippelmekanism möjliggör en omfattande undersökning av metabola signalvägar som inte är möjlig med enkel- eller dubbelagonister, vilket gör den till en förstklassig forskningssubstans för metabol- och fetmastudier.",benefits:["Trippelreceptoragonist (GLP-1 + GIP + glukagon)","Avancerad forskning om metabola signalvägar","Studier av fetma och kroppssammansättning","Överlägsen dubbelagonister för omfattande metabol undersökning","Publikationsklara resultat med över 99 % renhet"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. GLP-3 (RT) har studerats i metabola forskningsmiljöer vid olika koncentrationer. Förvara den rekonstituerade lösningen vid 2-8 °C och använd inom 30 dagar.",faq:[{question:"Vad gör GLP-3 (RT) unikt?",answer:"GLP-3 (RT) är en trippelagonist som riktar sig mot GLP-1-, GIP- och glukagonreceptorer samtidigt, vilket möjliggör en omfattande undersökning av metabola signalvägar som inte är möjlig med enkel- eller dubbelreceptoragonister."},{question:"Hur ska jag förvara GLP-3 (RT)?",answer:"Förvara det lyofiliserade pulvret vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["metabol","trippelagonist","GLP-1","GIP","glukagon","bästsäljare","forskningspeptid"]},"ghk-cu":{name:"GHK-Cu (kopparpeptid)",description:"Kopparpeptidkomplex för forskningstillämpningar inom hudregenerering, sårläkning och anti-aging.",longDescription:"GHK-Cu är en naturligt förekommande tripeptid (glycyl-L-histidyl-L-lysin) med hög affinitet för koppar(II)-joner. Den förekommer i human plasma, saliv och urin, och dess koncentration minskar med åldern. Omfattande forskning har visat dess roll vid sårläkning, vävnadsombyggnad, kollagensyntes och anti-aging-mekanismer.",benefits:["Stimulerar kollagensyntes i studier","Sårläkning och vävnadsombyggnad","Antioxidativa egenskaper","Forskning om modulering av genuttryck","Studier av hårfolliklar"],researchGuide:"GHK-Cu kan lösas i vatten eller PBS. För topikala forskningstillämpningar används vanligen koncentrationer på 0,01-1 %. Förvara vid 2-8 °C.",faq:[{question:"I vilken form levereras denna produkt?",answer:"GHK-Cu levereras som ett lyofiliserat blått pulver (på grund av kopparinnehållet)."},{question:"Är detta samma sak som GHK?",answer:"GHK-Cu är den kopparbundna formen av GHK-tripeptiden, den bioaktiva form som förekommer naturligt i kroppen."}],tags:["anti-aging","koppar","hud","sårläkning","forskningspeptid"]},semax:{name:"Semax",description:"Syntetisk ACTH-analog neuropeptid för forskning om kognitiv funktion, neuroprotektion och CNS.",longDescription:"Semax är en syntetisk peptid härledd från fragment 4-10 av det adrenokortikotropa hormonet (ACTH), med en Pro-Gly-Pro-modifiering i C-terminalen för ökad stabilitet. Den har studerats omfattande för neuroprotektiva egenskaper, kognitiv förbättring och som ett forskningsverktyg för att förstå BDNF-medierad neuroplasticitet.",benefits:["BDNF-uppreglering i studier","Studier av neuroprotektiva signalvägar","Forskning om kognitiv funktion","Studier av återhämtning efter stroke","NGF-modulering"],researchGuide:"Rekonstituera med bakteriostatiskt vatten. Studeras ofta intranasalt i djurmodeller. Har en relativt kort halveringstid. Förvara vid 2-8 °C.",faq:[{question:"Hur är Semax relaterat till ACTH?",answer:"Semax bygger på ACTH(4-10)-fragmentet men har modifierats med en Pro-Gly-Pro-tripeptid i C-terminalen för metabol stabilitet."},{question:"Vad är Semax molekylvikt och formel?",answer:"Semax har molekylformeln C37H51N9O10S och en molekylvikt på cirka 813,9 g/mol (PubChem CID 122178). Dess aminosyrasekvens är Met-Glu-His-Phe-Pro-Gly-Pro."},{question:"Vilken renhet har Semax från Miro Biotech?",answer:"Varje batch testas av ett oberoende tredjepartslabb och verifieras till 99,1 % renhet, med ett analyscertifikat för batchen."},{question:"Hur hanteras Semax i forskningsmiljöer?",answer:"Semax levereras som ett lyofiliserat pulver och rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriearbete. I publicerade djurstudier har det oftast administrerats intranasalt eller subkutant. Det är endast avsett för in-vitro- och laboratorieforskning."},{question:"Vad har Semax studerats för?",answer:"Publicerad forskning har undersökt Semax i djurmodeller av neurotrofinsignalering (BDNF och TrkB), neuroprotektion och cerebral ischemi, samt i genomomfattande analyser av genuttryck efter experimentell stroke."}],tags:["kognitiv","neuroprotektiv","ACTH","nootropikum","forskningspeptid"],aka:["ACTH(4-10) Pro-Gly-Pro","Met-Glu-His-Phe-Pro-Gly-Pro","MEHFPGP"],whatIs:"Semax är en syntetisk heptapeptid (Met-Glu-His-Phe-Pro-Gly-Pro), en analog till ACTH(4-10)-fragmentet med en tillagd Pro-Gly-Pro-svans för metabol stabilitet. Den används som forskningssubstans i studier av neurotrofinsignalering, neuroprotektion och kognition. Levereras endast för in-vitro- och laboratorieforskning.",mechanism:"I publicerad djurforskning har Semax rapporterats snabbt öka uttrycket av brain-derived neurotrophic factor (BDNF) och dess TrkB-receptor i hippocampus, samt modulera dopaminerg och serotonerg signalering. Ytterligare studier beskriver hämning av enkefalinnedbrytande enzymer och interaktion med melanokortinreceptorer. Dessa signalvägar undersöks i modeller av neuroplasticitet och cerebral ischemi; motsvarande mekanismer hos människa är inte fastställda.",receptorTargets:["BDNF-/TrkB-signalväg","Dopaminerg signalering","Serotonerg signalering","Melanokortinreceptorer (MC4/MC5)","Enkefalinnedbrytande enzymer"],specs:[{label:"Sekvens",value:"Met-Glu-His-Phe-Pro-Gly-Pro (MEHFPGP)"},{label:"Klassificering",value:"Syntetisk heptapeptid, ACTH(4-10)-analog"},{label:"Utseende",value:"Vitt lyofiliserat pulver"},{label:"Löslighet",value:"Löslig i vatten och bakteriostatiskt vatten"}],researchApplications:[{title:"Neurotrofinsignalering",description:"Används i studier av BDNF- och TrkB-uttryck och nedströms neuroplasticitetssignalvägar."},{title:"Neuroprotektion",description:"Undersöks i gnagarmodeller av cerebral ischemi och ischemi-reperfusionsskada."},{title:"Kognition och beteende",description:"Utforskas i forskning om inlärning, uppmärksamhet och minnesrelaterade effektmått i djurmodeller."},{title:"Genuttryck",description:"Tillämpas i genomomfattande transkriptionsstudier av immun- och kärlrelaterade gener efter experimentell stroke."}],keyStudies:[{title:"Semax, en analog till ACTH(4-10) med kognitiva effekter, reglerar BDNF- och trkB-uttryck i råttans hippocampus",source:"Brain Research",year:2006,url:"https://pubmed.ncbi.nlm.nih.gov/16996037/",finding:"Rapporterade att Semax snabbt ökade BDNF- och TrkB-uttrycket i råttans hippocampus."},{title:"Semax och Pro-Gly-Pro aktiverar transkriptionen av neurotrofiner och deras receptorgener efter cerebral ischemi",source:"Cellular and Molecular Neurobiology",year:2010,url:"https://pubmed.ncbi.nlm.nih.gov/19633950/",finding:"Observerade aktivering av transkription av neurotrofin- och receptorgener efter cerebral ischemi i en råttmodell."},{title:"Peptiden semax påverkar uttrycket av gener kopplade till immun- och kärlsystemen vid fokal hjärnischemi hos råtta: genomomfattande transkriptionsanalys",source:"BMC Genomics",year:2014,url:"https://pubmed.ncbi.nlm.nih.gov/24661604/",finding:"Den genomomfattande analysen beskrev förändringar i immun- och kärlrelaterat genuttryck efter fokal ischemi."},{title:"Proteinuttrycksprofil i hjärnan bekräftar den skyddande effekten av ACTH(4-7)PGP-peptiden (Semax) i en råttmodell av cerebral ischemi-reperfusion",source:"International Journal of Molecular Sciences",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34201112/",finding:"Den proteomiska profileringen rapporterade förändringar på proteinnivå som är förenliga med en skyddande effekt i en råttmodell av ischemi-reperfusion."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C.",howSupplied:"Levereras som en enda försluten flaska med vitt lyofiliserat Semax-pulver. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg.",comparison:{heading:"Semax vs Selank i forskning",columns:["","Semax","Selank"],rows:[{label:"Härledd från",values:["ACTH(4-10)-fragment","Tuftsin (IgG-härledd peptid)"]},{label:"Peptidlängd",values:["Heptapeptid (7 as)","Heptapeptid (7 as)"]},{label:"Primärt forskningsfokus",values:["Neurotrofiner, neuroprotektion","Anxiolytisk, immunmodulerande"]},{label:"Vanlig administreringsväg i studier",values:["Intranasal, subkutan","Intranasal"]}]}},selank:{name:"Selank",description:"Heptapeptid härledd från tuftsin för forskning om beteende, kognition och immunmodulering.",longDescription:"Selank är en syntetisk heptapeptid härledd från den naturligt förekommande tetrapeptiden tuftsin, med en ytterligare Gly-Pro-sekvens för metabol stabilitet. Den utvecklades vid Institutet för molekylär genetik vid Ryska vetenskapsakademin och har studerats för sina beteendemässiga, kognitiva och immunmodulerande egenskaper i forskningsmodeller.",benefits:["Forskning om ångestrelaterade signalvägar","Studier av kognitiv förbättring","Forskning om immunmodulering","Forskning om BDNF-modulering","Studier av interaktion med serotoninsystemet"],researchGuide:"Rekonstituera med bakteriostatiskt vatten. Selank studeras ofta intranasalt i djurmodeller. Förvara vid 2-8 °C efter rekonstituering.",faq:[{question:"Vad är tuftsin?",answer:"Tuftsin är en naturlig tetrapeptid (Thr-Lys-Pro-Arg) som bildas genom enzymatisk klyvning av IgG. Selank är en modifierad analog med förbättrad stabilitet."}],tags:["kognitiv","nootropikum","beteende","forskningspeptid"]},"bpc-157":{name:"BPC-157",description:"Body protection compound härledd från human magsaft, undersökt för vävnadsreparation, tarmhälsa och återhämtning efter skada.",longDescription:"BPC-157 (Body Protection Compound-157) är en syntetisk pentadekapeptid uppbyggd av 15 aminosyror. Den är härledd från ett skyddande protein som finns i magsaft. Omfattande forskning har visat dess anmärkningsvärda förmåga att påskynda sårläkning, skydda organ och förebygga magsår. Studier har visat att den främjar läkning av senor, muskler och ben i djurmodeller.",benefits:["Forskning om sårläkningsmekanismer","Studier av signalvägar för sen- och ligamentreparation","Forskning om mekanismer för magskydd","Studier av angiogenessignalvägar","Forskning om inflammationsmodulering"],researchGuide:"BPC-157 rekonstitueras vanligen med bakteriostatiskt vatten. För in-vitro-studier ligger vanliga koncentrationer i intervallet 1-10 μg/mL. Förvara den rekonstituerade lösningen vid 2-8 °C och använd inom 30 dagar.",faq:[{question:"Vilken renhet har er BPC-157?",answer:"Vår BPC-157 testas till ≥99,3 % renhet, med fullständiga analyscertifikat tillgängliga."},{question:"Hur ska jag förvara BPC-157?",answer:"Förvara lyofiliserat pulver vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C."},{question:"Vad är molekylvikten?",answer:"Molekylvikten för BPC-157 är 1419,53 g/mol."}],tags:["läkning","vävnadsreparation","gastrisk","återhämtning","forskningspeptid"]},"nad-plus":{name:"NAD+",description:"Koenzymet nikotinamidadenindinukleotid för forskning om cellulär energimetabolism, DNA-reparation och livslängd.",longDescription:"NAD+ (nikotinamidadenindinukleotid) är ett kritiskt koenzym som finns i varje levande cell. Det spelar en central roll i cellulär energimetabolism, DNA-reparation, genuttryck och cellsignalering. NAD+-nivåerna minskar naturligt med åldern, vilket gör det till ett viktigt fokus för livslängds- och anti-aging-forskning.",benefits:["Forskning om cellulär energimetabolism","Studier av DNA-reparationssignalvägar","Forskning om sirtuinaktivering","Studier av livslängd och åldrande","Forskning om mitokondriell funktion"],researchGuide:"NAD+ är vattenlösligt och kan rekonstitueras i sterilt vatten eller buffert. Hantera med försiktighet eftersom det är ljuskänsligt. Förvara vid -20 °C för långtidsförvaring och 2-8 °C för kortare tid.",faq:[{question:"Vad är skillnaden mellan NAD+ och NMN?",answer:"NAD+ är själva det aktiva koenzymet, medan NMN (nikotinamidmononukleotid) är en föregångare som celler omvandlar till NAD+."},{question:"Hur ska NAD+ förvaras?",answer:"Förvara lyofiliserat NAD+ vid -20 °C skyddat från ljus. Rekonstituerade lösningar ska användas skyndsamt."}],tags:["anti-aging","livslängd","cellenergi","DNA-reparation"]},"tb-500":{name:"TB-500",description:"Syntetisk analog till Thymosin Beta-4, studerad för vävnadsregenerering, sårläkning och inflammationsmodulering.",longDescription:"TB-500 är en syntetisk version av Thymosin Beta-4, en peptid med 43 aminosyror som naturligt finns i praktiskt taget alla mänskliga och animala celler. Den spelar en avgörande roll vid vävnadsreparation, regenerering och skydd. Forskning har visat dess förmåga att främja cellmigration och blodkärlsbildning samt att minska inflammation.",benefits:["Studier av cellmigration och vävnadsreparation","Forskning om inflammationsmodulering","Studier av angiogenessignalvägar","Stimulering av hårfolliklar i studier","Forskning om skydd av hjärtvävnad"],researchGuide:"Rekonstituera TB-500 med bakteriostatiskt vatten till önskad koncentration. Vanliga forskningskoncentrationer är 2,5-5 mg/mL. Förvara vid 2-8 °C efter rekonstituering.",faq:[{question:"Vad är sekvensen för TB-500?",answer:"TB-500 är den aktiva regionen (17-23) av Thymosin Beta-4 med sekvensen Ac-LKKTETQ."},{question:"Är detta fullängds-Thymosin Beta-4?",answer:"TB-500 representerar det aktiva fragmentet. Vi erbjuder även fullängds-Thymosin Beta-4 separat."}],tags:["läkning","antiinflammatorisk","vävnadsreparation","återhämtning","forskningspeptid"]},tesamorelin:{name:"Tesamorelin",description:"GHRH-analog som stimulerar frisättning av tillväxthormon, undersökt för metabol reglering och studier av kroppssammansättning.",longDescription:"Tesamorelin är en syntetisk analog till tillväxthormonfrisättande hormon (GHRH) bestående av 44 aminosyror. Den stimulerar hypofysen att frisätta tillväxthormon på ett fysiologiskt sätt. Den har studerats omfattande för sina effekter på kroppssammansättning, visceral fettinlagring och metabola parametrar.",benefits:["Studier av signalvägar för frisättning av tillväxthormon","Forskning om visceral fettinlagring","Studier av kroppssammansättning","Forskning om metabol reglering"],researchGuide:"Rekonstituera med bakteriostatiskt vatten. Tesamorelin är en GHRH-analog med fysiologiska GH-frisättande egenskaper. Förvara vid 2-8 °C efter rekonstituering.",faq:[{question:"Hur skiljer sig Tesamorelin från andra GHRH-analoger?",answer:"Tesamorelin är en modifierad GHRH-analog som stimulerar pulsatil GH-frisättning och efterliknar därmed den naturliga fysiologin närmare än konstant stimulering."}],tags:["metabol","GHRH","tillväxthormon","forskningspeptid"]},"mots-c":{name:"MOTS-c",description:"Mitokondriehärledd peptid studerad för metabol reglering, insulinkänslighet och cellulär homeostas.",longDescription:"MOTS-c (Mitochondrial Open Reading Frame of the 12S rRNA Type-c) är en mitokondriehärledd peptid som kodas i det mitokondriella genomet. Den har framträtt som en betydande forskningssubstans för att studera metabol reglering, träningsfysiologi, insulinkänslighet och cellulär energihomeostas.",benefits:["Mitokondriehärledd signalpeptid","Forskning om insulinkänslighet","Studier av träningsfysiologi","Cellulär energihomeostas","Forskning om metabol reglering"],researchGuide:"Rekonstituera med sterilt eller bakteriostatiskt vatten. MOTS-c är en relativt stabil peptid. Förvara vid -20 °C för långtidsförvaring och 2-8 °C för kortare tid.",faq:[{question:"Vad är en mitokondriehärledd peptid?",answer:"MDP:er är peptider som kodas i det mitokondriella genomet i stället för i kärn-DNA. MOTS-c är en av de mest studerade MDP:erna."}],tags:["metabol","mitokondriell","insulinkänslighet","forskningspeptid"]},"cjc-1295":{name:"CJC-1295 (utan DAC)",description:"Högren (99,60 %) CJC-1295 utan DAC forskningspeptid. GHRH-analog för sekretion av tillväxthormon, pulsatil GH-frisättning och studier av metabola signalvägar.",longDescription:"CJC-1295 (utan DAC) är en syntetisk analog till tillväxthormonfrisättande hormon (GHRH) bestående av de första 29 aminosyrorna i GHRH med modifierade rester för att förbättra receptorbindning och biologisk stabilitet. Till skillnad från den DAC-modifierade varianten ger CJC-1295 utan DAC kortare, mer fysiologiska pulser av tillväxthormonfrisättning, vilket gör den till en föredragen substans för att studera naturliga GH-sekretionsmönster och metabol reglering.",benefits:["Studier av pulsatil tillväxthormonfrisättning","Forskning om GHRH-receptorbindning","Studier av signalvägar för metabol reglering","Forskning om kroppssammansättning och muskelmassa","Överlägsen DAC-varianten för studier av fysiologiska GH-pulser"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. CJC-1295 (utan DAC) har en kortare halveringstid än DAC-modifierade varianter och stödjer pulsatila GH-frisättningsmönster. Förvara den rekonstituerade lösningen vid 2-8 °C och använd inom 30 dagar.",faq:[{question:"Vad är skillnaden mellan CJC-1295 med och utan DAC?",answer:"DAC-modifieringen (Drug Affinity Complex) förlänger halveringstiden avsevärt. Utan DAC ger CJC-1295 kortare, mer fysiologiska GH-pulser, vilket föredras för forskning som studerar naturlig GH-sekretionsdynamik."},{question:"Hur ska jag förvara CJC-1295?",answer:"Förvara lyofiliserat pulver vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["metabol","GHRH","tillväxthormon","sekretagog","forskningspeptid"]},ipamorelin:{name:"Ipamorelin",description:"Högren (99,20 %) Ipamorelin forskningspeptid. Selektiv sekretagog för tillväxthormon för GH-frisättning, ghrelinreceptorbindning och metabola forskningstillämpningar.",longDescription:"Ipamorelin är en syntetisk pentapeptid och selektiv sekretagog för tillväxthormon som verkar på ghrelin-/GHS-receptorn (GHS-R1a). Den utmärker sig genom sin höga selektivitet och stimulerar GH-frisättning utan att nämnvärt påverka nivåerna av kortisol, ACTH eller prolaktin. Denna selektivitet gör den till ett av de renaste forskningsverktygen för att studera isolerad GH-signalering och nedströms metabola effekter.",benefits:["Studier av selektiv GH-frisättning utan kortisolökning","Studier av ghrelinreceptorbindning (GHS-R1a)","Forskning om ren isolering av GH-signalvägen","Studier av ämnesomsättning och kroppssammansättning","Minimala off-target-hormoneffekter i studier"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. Ipamorelin är känd för sin selektivitet i GH-frisättningsstudier, med minimal effekt på andra hypofyshormoner. Förvara den rekonstituerade lösningen vid 2-8 °C och använd inom 30 dagar.",faq:[{question:"Vad skiljer Ipamorelin från andra GH-sekretagoger?",answer:"Ipamorelin är en av de mest selektiva GHRP:erna och stimulerar GH-frisättning utan att nämnvärt höja kortisol, ACTH eller prolaktin, vilket gör den idealisk för att studera isolerad GH-signalering."},{question:"Hur ska jag förvara Ipamorelin?",answer:"Förvara lyofiliserat pulver vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C."}],tags:["metabol","GHRP","tillväxthormon","sekretagog","ghrelin","forskningspeptid"]},"mt-2":{name:"MT-2 (Melanotan 2)",description:"Högren (99,10 %) MT-2 Melanotan 2 forskningspeptid. Syntetisk melanokortinagonist för pigmenteringssignalvägar, fotoprotektion och studier av MC-receptorer.",longDescription:"MT-2 (Melanotan 2) är en syntetisk cyklisk heptapeptidanalog till alfa-melanocytstimulerande hormon (α-MSH). Den verkar som en icke-selektiv agonist vid melanokortinreceptorerna MC1R till MC5R. Forskningen har fokuserat på dess roll vid melanogenes och pigmenteringssignalvägar, fotoprotektiva mekanismer och den bredare signaleringen i melanokortinsystemet. Den är ett viktigt forskningsverktyg för att studera MC-receptorfarmakologi.",benefits:["Forskning om melanokortinreceptorer (MC1R-MC5R)","Studier av melanogenes och pigmenteringssignalvägar","Forskning om fotoprotektionsmekanismer","Farmakologisk forskning om α-MSH-analog","Studier av hudbiologi och UV-respons"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. MT-2 är ljuskänsligt; skydda från direkt ljus vid hantering och förvaring. Förvara den rekonstituerade lösningen vid 2-8 °C och använd inom 30 dagar.",faq:[{question:"Vad är sambandet mellan MT-2 och α-MSH?",answer:"MT-2 är en syntetisk cyklisk analog till alfa-melanocytstimulerande hormon (α-MSH) med förbättrad metabol stabilitet och bredare affinitet för melanokortinreceptorer."},{question:"Hur ska MT-2 förvaras?",answer:"Förvara lyofiliserat pulver vid -20 °C skyddat från ljus. Rekonstituerade lösningar ska hållas vid 2-8 °C och skyddas från direkt ljus."}],tags:["melanokortin","pigmentering","hud","fotoprotektion","anti-aging","forskningspeptid"]},"bacteriostatic-water":{name:"Bakteriostatiskt vatten",description:"Bakteriostatiskt vatten av farmaceutisk kvalitet för rekonstituering av peptider. Sterilt, konserverat med 0,9 % bensylalkohol.",longDescription:"Bakteriostatiskt vatten av farmaceutisk kvalitet (USP) som innehåller 0,9 % bensylalkohol som konserveringsmedel. Sterilt, pyrogenfritt vatten lämpligt för rekonstituering av lyofiliserade peptider för forskningsändamål. Varje flaska förseglas under aseptiska förhållanden och testas för sterilitet.",benefits:["Farmaceutisk kvalitet (USP)","Sterilt och pyrogenfritt","Konserverat med 0,9 % bensylalkohol","Flergångsanvändning tack vare konserveringsmedel","Oumbärligt för rekonstituering av peptider"],researchGuide:"Använd bakteriostatiskt vatten för att rekonstituera lyofiliserade peptider. Dra upp önskad mängd med en steril spruta, injicera långsamt längs väggen i peptidflaskan och snurra försiktigt. Skaka inte.",faq:[{question:"Vad är bakteriostatiskt vatten?",answer:"Bakteriostatiskt vatten är sterilt vatten som innehåller 0,9 % bensylalkohol, vilket hämmar bakterietillväxt och möjliggör flergångsanvändning från samma flaska."},{question:"Hur länge håller rekonstituerad peptid?",answer:"Vid rekonstituering med bakteriostatiskt vatten och förvaring vid 2-8 °C förblir de flesta peptider stabila i 28-30 dagar."}],tags:["tillbehör","rekonstituering","vatten"]},"cjc-1295-ipamorelin":{name:"CJC-1295 + Ipamorelin-blandning",description:"Forskningsblandning av CJC-1295 (utan DAC) och Ipamorelin, 5mg av vardera per 10mg-flaska. En GHRH-analog kombinerad med en selektiv sekretagog för ghrelinreceptorn för studier av tillväxthormonsignalvägen och ämnesomsättning.",longDescription:"Denna forskningsblandning kombinerar CJC-1295 (utan DAC), en syntetisk analog till tillväxthormonfrisättande hormon (GHRH), med Ipamorelin, en selektiv sekretagog för ghrelin-/GHS-R1a-receptorn, med 5mg av varje substans per 10mg-flaska. De två verkar på komplementära signalvägar: CJC-1295 engagerar GHRH-receptorn medan Ipamorelin engagerar ghrelinreceptorn, en kombination som studeras för sin sammantagna effekt på pulsatil frisättning av tillväxthormon. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Forskning om GH-sekretagog med dubbla signalvägar (GHRH + ghrelinreceptor)","Studier av pulsatil frisättning av tillväxthormon","Selektiv GH-signalering med minimala off-target-hormoneffekter i studier","Studier av signalvägar för metabol reglering och kroppssammansättning","Enflaskeblandning med 5mg + 5mg för studiedesigner med kombinerade sekretagoger"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. Varje 10mg-flaska innehåller 5mg CJC-1295 och 5mg Ipamorelin. Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vad ingår i CJC-1295 + Ipamorelin-blandningen?",answer:"Varje 10mg-flaska innehåller 5mg CJC-1295 (utan DAC) och 5mg Ipamorelin, co-lyofiliserade som en enda blandning."},{question:"Varför studeras CJC-1295 och Ipamorelin tillsammans?",answer:"CJC-1295 är en GHRH-analog och Ipamorelin är en selektiv sekretagog för ghrelin-/GHS-R1a-receptorn. Eftersom de verkar på komplementära signalvägar studerar forskare paret för att undersöka deras sammantagna effekt på pulsatil frisättning av tillväxthormon."},{question:"Hur ska jag förvara blandningen?",answer:"Förvara lyofiliserat pulver vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["metabol","GHRH","ghrelin","tillväxthormon","sekretagog","blandning","forskningspeptid"],aka:["CJC-1295 / Ipamorelin","CJC-1295 No DAC + Ipamorelin","GH-sekretagogblandning"],whatIs:"CJC-1295 + Ipamorelin-blandningen är en forskningssubstans som kombinerar en analog till tillväxthormonfrisättande hormon (GHRH) med en selektiv sekretagog för ghrelinreceptorn (GHS-R1a), med 5mg av vardera per 10mg-flaska. Den används för att in vitro studera kombinerad signalering i tillväxthormonvägen. Levereras endast för laboratorieforskning.",mechanism:"I publicerad forskning engagerar de två substanserna olika receptorer som konvergerar mot frisättning av tillväxthormon från hypofysens somatotrofer. CJC-1295, en GHRH-analog, har rapporterats ge ihållande ökningar av tillväxthormon och IGF-I hos friska vuxna, medan Ipamorelin karakteriserades som den första selektiva sekretagogen för tillväxthormon, som stimulerar GH-frisättning utan att nämnvärt påverka ACTH eller kortisol. Blandningen studeras för hur dessa GHRH- och ghrelinreceptorsignalvägar kan interagera; kombinerade mekanismer och utfall hos människa är inte fastställda.",receptorTargets:["GHRH-receptor","Ghrelin-/GHS-R1a-receptor","GH-frisättning från hypofysens somatotrofer","IGF-1-axeln"],blendComposition:[{name:"CJC-1295 (No DAC)",role:"GHRH-analog",amount:"5mg"},{name:"Ipamorelin",role:"Ghrelinagonist",amount:"5mg"}],specs:[{label:"Sammansättning",value:"5mg CJC-1295 (utan DAC) + 5mg Ipamorelin"},{label:"CJC-1295-klass",value:"Syntetisk GHRH(1-29)-analog (modifierad, utan DAC)"},{label:"Ipamorelin-klass",value:"Syntetisk pentapeptid GH-sekretagog (GHRP)"},{label:"Total mängd per flaska",value:"10mg co-lyofiliserad blandning"},{label:"Utseende",value:"Vitt lyofiliserat pulver"},{label:"Löslighet",value:"Löslig i bakteriostatiskt vatten"}],researchApplications:[{title:"Frisättning av tillväxthormon",description:"Studeras för den kombinerade effekten av GHRH- och ghrelinreceptorstimulering på pulsatil GH-sekretion."},{title:"Metabol reglering",description:"Används i forskning om GH-/IGF-1-axeln och nedströms metabola och kroppssammansättningsrelaterade effektmått."},{title:"Receptorfarmakologi",description:"Tillämpas för att undersöka signalering vid GHRH-receptorn och ghrelin-/GHS-R1a-receptorn parallellt."},{title:"Sekretagogselektivitet",description:"Utforskas i studiedesigner som jämför selektiv GH-frisättning mot off-target-effekter på hypofyshormoner."}],keyStudies:[{title:"Långvarig stimulering av sekretion av tillväxthormon (GH) och insulinliknande tillväxtfaktor I av CJC-1295, en långverkande analog till GH-frisättande hormon, hos friska vuxna",source:"Journal of Clinical Endocrinology & Metabolism",year:2006,url:"https://pubmed.ncbi.nlm.nih.gov/16352683/",finding:"Rapporterade att subkutant CJC-1295 gav ihållande, dosberoende ökningar av tillväxthormon och IGF-I hos friska vuxna."},{title:"Ipamorelin, den första selektiva sekretagogen för tillväxthormon",source:"European Journal of Endocrinology",year:1998,url:"https://pubmed.ncbi.nlm.nih.gov/9849822/",finding:"Karakteriserade Ipamorelin som den första selektiva sekretagogen för tillväxthormon och rapporterade GH-frisättning jämförbar med GHRH utan nämnvärd ökning av ACTH eller kortisol."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C.",howSupplied:"Levereras som en enda försluten flaska som innehåller 5mg CJC-1295 och 5mg Ipamorelin som ett co-lyofiliserat vitt pulver. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg.",comparison:{heading:"CJC-1295 + Ipamorelin vs de fristående substanserna",columns:["","Blandning","CJC-1295 (utan DAC)","Ipamorelin"],rows:[{label:"Receptormål",values:["GHRH + ghrelin (GHS-R1a)","GHRH-receptor","Ghrelin / GHS-R1a"]},{label:"Klass",values:["GHRH-analog + GHRP","GHRH(1-29)-analog","Selektiv GH-sekretagog"]},{label:"Mängd per flaska",values:["5mg + 5mg (10mg)","5mg / 10mg","10mg"]},{label:"Forskningsfokus",values:["Kombinerad GH-signalväg","Pulsatil GH-frisättning","Selektiv GH-frisättning"]}]}},"glp-2-tz":{name:"GLP-2 (TZ)",description:"Dubbel GIP- och GLP-1-receptoragonist som levereras som en lyofiliserad referensstandard för forskning om metabola signalvägar och kroppssammansättning. Finns i 13 format från 5mg till 120mg.",longDescription:"GLP-2 (TZ) är en syntetisk dubbel inkretinreceptoragonist som engagerar både receptorn för glukosberoende insulinotropt polypeptid (GIP) och receptorn för glukagonliknande peptid-1 (GLP-1) från en enda peptid. I publicerad farmakologi konstruerades den som en fettsyramodifierad peptid för förlängd exponering och studerades för sin kombinerade effekt på inkretinsignalering, glukoshantering och kroppsvikt i djur- och kliniska forskningsmodeller. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Forskning om dubbel inkretinreceptoragonist (GIP + GLP-1)","Studier av signalvägar för glukosberoende insulinsignalering","Forskning om kroppssammansättning och fettinlagring","Studier av metabol reglering och energihomeostas","13 format (5mg till 120mg) för dosstegrande studiedesigner"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. GLP-2 (TZ) levereras som ett lyofiliserat pulver. Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vilka receptorer riktar sig GLP-2 (TZ) mot?",answer:"GLP-2 (TZ) är en dubbelagonist som engagerar både GIP-receptorn (glukosberoende insulinotropt polypeptid) och GLP-1-receptorn (glukagonliknande peptid-1), två inkretinsignalvägar som studeras tillsammans för sin kombinerade effekt på glukoshantering och kroppsvikt."},{question:"Vad är molekylvikt och formel för GLP-2 (TZ)?",answer:"GLP-2 (TZ) har molekylformeln C225H348N48O68 och en molekylvikt på cirka 4813,5 g/mol (PubChem CID 166567236). Den är också känd under utvecklingskoden LY3298176."},{question:"Vilken renhet har GLP-2 (TZ) från Miro Biotech?",answer:"Varje batch testas av ett oberoende tredjepartslabb och verifieras till 99,27 % renhet, med ett analyscertifikat för batchen."},{question:"Hur ska GLP-2 (TZ) förvaras?",answer:"Förvara det lyofiliserade pulvret vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["metabol","GIP","GLP-1","inkretin","dubbelagonist","viktminskning","forskningspeptid"],aka:["LY3298176","Dubbel GIP/GLP-1-receptoragonist","GIP/GLP-1-koagonist"],whatIs:"GLP-2 (TZ) är en syntetisk dubbel inkretinreceptoragonist som aktiverar både GIP- och GLP-1-receptorerna från en enda peptid. Den används som forskningssubstans i studier av inkretinsignalering, glukosreglering och kroppssammansättning. Levereras endast för in-vitro- och laboratorieforskning.",mechanism:"I publicerad forskning karakteriserades GLP-2 (TZ) som en fettsyramodifierad peptid som binder och aktiverar GIP- och GLP-1-receptorerna, två inkretinsignalvägar som konvergerar mot glukosberoende insulinsignalering. Farmakologi i upptäcktsstadiet rapporterade dubbelagonistaktivitet vid båda receptorerna, och efterföljande kontrollerade studier observerade förändringar i kroppsvikt över de studerade perioderna. Motsvarande långsiktiga mekanismer och utfall hos människa är fortfarande under utredning.",receptorTargets:["GIP-receptor","GLP-1-receptor","Inkretinsignalaxeln","Glukosberoende insulinsekretion"],specs:[{label:"Klassificering",value:"Syntetisk dubbel GIP/GLP-1-receptoragonistpeptid"},{label:"Utvecklingskod",value:"LY3298176"},{label:"Utseende",value:"Vitt lyofiliserat pulver"},{label:"Löslighet",value:"Löslig i bakteriostatiskt vatten"}],researchApplications:[{title:"Inkretinreceptorfarmakologi",description:"Används för att studera parallell signalering vid GIP- och GLP-1-receptorerna från en enda dubbelagonistpeptid."},{title:"Glukosmetabolism",description:"Tillämpas i forskning om glukosberoende insulinsekretion och metabol reglering."},{title:"Kroppssammansättning",description:"Undersöks i djur- och kliniska forskningsmodeller för effekter på kroppsvikt och fettinlagring."},{title:"Jämförande agoniststudier",description:"Utforskas jämsides med enkla inkretinagonister för att jämföra dubbel- kontra enkelsignalvägsaktivitet."}],keyStudies:[{title:"LY3298176, en ny dubbel GIP- och GLP-1-receptoragonist för behandling av typ 2-diabetes mellitus: från upptäckt till kliniskt proof of concept",source:"Molecular Metabolism",year:2018,url:"https://pubmed.ncbi.nlm.nih.gov/30473097/",finding:"Rapporterade upptäckten och den farmakologiska karakteriseringen av LY3298176, en fettsyramodifierad peptid konstruerad som en dubbelagonist vid GIP- och GLP-1-receptorerna."},{title:"SURMOUNT-1: fas 3-studie av LY3298176 en gång i veckan vid fetma",source:"New England Journal of Medicine",year:2022,url:"https://pubmed.ncbi.nlm.nih.gov/35658024/",finding:"I den randomiserade SURMOUNT-1-studien observerades att den dubbla GIP/GLP-1-agonisten en gång i veckan gav betydande genomsnittliga minskningar av kroppsvikten över 72 veckor jämfört med placebo över de studerade doserna."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C.",howSupplied:"Levereras som en enda försluten flaska med vitt lyofiliserat pulver av GLP-2 (TZ) i valt format. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg.",comparison:{heading:"GLP-2 (TZ) vs enkla inkretinagonister i forskning",columns:["","GLP-2 (TZ)","GLP-1-agonist","GIP-agonist"],rows:[{label:"Receptormål",values:["GIP + GLP-1","GLP-1-receptor","GIP-receptor"]},{label:"Klass",values:["Dubbel inkretinagonist","Enkel inkretinagonist","Enkel inkretinagonist"]},{label:"Forskningsfokus",values:["Kombinerad inkretinsignalering","GLP-1-signalväg","GIP-signalväg"]},{label:"Engagerade signalvägar",values:["Två","En","En"]}]}},klow:{name:"KLOW-blandning",description:"Fyrpeptidsforskningsblandning av TB-500, BPC-157, GHK-Cu och KPV, co-lyofiliserad i en enda 80mg-flaska för kombinerade studier av signalvägar för vävnadsreparation och antiinflammation.",longDescription:"KLOW-blandningen kombinerar fyra forskningspeptider i en 80mg-flaska: TB-500 (10mg), ett Thymosin Beta-4-fragment som studeras för cellmigration och angiogenes; BPC-157 (10mg), en stabil gastrisk pentadekapeptid som studeras för vävnadsreparation; GHK-Cu (50mg), en kopparbindande tripeptid som studeras för vävnadsombyggnad; och KPV (10mg), en alfa-MSH-tripeptid som studeras för antiinflammatorisk aktivitet. De fyra kombineras för att undersöka komplementära regenerativa och inflammatoriska signalvägar i en enda studiedesign. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Fyrkomponents vävnadsreparationsforskning i en enda flaska","Kombinerade studier av angiogenes- och cellmigrationssignalvägar","Forskning om sårläkning och vävnadsombyggnad","Studier av antiinflammatoriska signalvägar (KPV-komponent)","Co-lyofiliserad blandning för studiedesigner med kombinerade signalvägar"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. Varje 80mg-flaska innehåller 10mg TB-500, 10mg BPC-157, 50mg GHK-Cu och 10mg KPV. Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vad ingår i KLOW-blandningen?",answer:"Varje 80mg-flaska innehåller 10mg TB-500, 10mg BPC-157, 50mg GHK-Cu och 10mg KPV, co-lyofiliserade som en enda blandning."},{question:"Varför studeras dessa fyra peptider tillsammans?",answer:"Varje komponent är i publicerad forskning associerad med en distinkt reparations- eller inflammationssignalväg. TB-500 och BPC-157 studeras för vävnadsreparation, GHK-Cu för vävnadsombyggnad och KPV för antiinflammatorisk aktivitet, så blandningen används för att undersöka dessa komplementära signalvägar i en enda studiedesign."},{question:"Hur ska blandningen förvaras?",answer:"Förvara lyofiliserat pulver vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["läkning","vävnadsreparation","antiinflammatorisk","återhämtning","blandning","forskningspeptid"],aka:["KLOW Healing Blend","TB-500 / BPC-157 / GHK-Cu / KPV-blandning"],whatIs:"KLOW-blandningen är en forskningssubstans som kombinerar fyra peptider (TB-500, BPC-157, GHK-Cu och KPV) co-lyofiliserade i en 80mg-flaska. Den används för att in vitro studera kombinerade signalvägar för vävnadsreparation, vävnadsombyggnad och antiinflammation. Levereras endast för laboratorieforskning.",mechanism:"I publicerad forskning engagerar varje komponent en distinkt signalväg. Thymosin Beta-4 (ursprunget till TB-500) rapporterades stödja cellmigration och angiogenes; BPC-157 associerades med påskyndad vävnadsläkning i djurmodeller; GHK-Cu beskrevs i forskning om vävnadsombyggnad och sårreparation; och KPV rapporterades minska markörer för inflammation via PepT1-transportören. Blandningen studeras för hur dessa signalvägar kan verka parallellt; kombinerade mekanismer och utfall hos människa är inte fastställda.",receptorTargets:["Aktinsekvestrerande / cellmigrationssignalvägar (TB-500)","Angiogenes- och vävnadsreparationssignalvägar (BPC-157)","Kopparberoende vävnadsombyggnad (GHK-Cu)","PepT1-transportören och inflammatorisk signalering (KPV)"],blendComposition:[{name:"TB-500",role:"Thymosin-β4-fragment",amount:"10mg"},{name:"BPC-157",role:"Gastrisk pentadekapeptid",amount:"10mg"},{name:"GHK-Cu",role:"Koppar-tripeptid",amount:"50mg"},{name:"KPV",role:"α-MSH-tripeptid",amount:"10mg"}],specs:[{label:"Sammansättning",value:"10mg TB-500 + 10mg BPC-157 + 50mg GHK-Cu + 10mg KPV"},{label:"Total mängd per flaska",value:"80mg co-lyofiliserad blandning"},{label:"Komponenter",value:"Fyra forskningspeptider"},{label:"Utseende",value:"Vitt till blekblått lyofiliserat pulver (kopparinnehåll)"},{label:"Löslighet",value:"Löslig i bakteriostatiskt vatten"}],researchApplications:[{title:"Vävnadsreparation",description:"Studeras för de kombinerade effekterna av TB-500 och BPC-157 på cellmigration och sårläkning."},{title:"Vävnadsombyggnad",description:"Används i forskning om GHK-Cu och kopparberoende ombyggnadssignalvägar."},{title:"Inflammation",description:"Tillämpas för att undersöka den antiinflammatoriska aktivitet som associeras med KPV-komponenten."},{title:"Designer med kombinerade signalvägar",description:"Utforskas i studiedesigner som jämför enskilda peptider med en flerkomponentsblandning."}],keyStudies:[{title:"Stabil gastrisk pentadekapeptid BPC 157 och sårläkning",source:"Frontiers in Pharmacology",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34267654/",finding:"Granskade prekliniska rapporter där BPC-157 associerades med påskyndad läkning över modeller för hud-, muskel-, sen- och andra vävnadsskador hos djur."},{title:"Djurstudier med Thymosin Beta, en multifunktionell peptid för vävnadsreparation och regenerering",source:"Annals of the New York Academy of Sciences",year:2010,url:"https://pubmed.ncbi.nlm.nih.gov/20536453/",finding:"Sammanfattade djurmodellstudier där det rapporterades att Thymosin Beta-4 (ursprunget till TB-500) stödjer cellmigration, angiogenes och vävnadsreparation."},{title:"Den mänskliga tripeptiden GHK och vävnadsombyggnad",source:"Journal of Biomaterials Science, Polymer Edition",year:2008,url:"https://pubmed.ncbi.nlm.nih.gov/18644225/",finding:"Granskade den kopparbindande tripeptiden GHK och dess rapporterade roller i forskning om vävnadsombyggnad och sårreparation."},{title:"PepT1-medierat upptag av tripeptiden KPV minskar intestinal inflammation",source:"Gastroenterology",year:2008,url:"https://pubmed.ncbi.nlm.nih.gov/18061177/",finding:"Rapporterade att tripeptiden KPV togs upp via PepT1 och minskade markörer för inflammation i cell- och musmodeller."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C.",howSupplied:"Levereras som en enda försluten flaska med 10mg TB-500, 10mg BPC-157, 50mg GHK-Cu och 10mg KPV som ett co-lyofiliserat pulver. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg.",comparison:{heading:"KLOW vs de andra forskningsblandningarna",columns:["","KLOW","GLOW","BPC-157 + TB-500"],rows:[{label:"Komponenter",values:["TB-500, BPC-157, GHK-Cu, KPV","TB-500, BPC-157, GHK-Cu","BPC-157, TB-500"]},{label:"Antal komponenter",values:["4","3","2"]},{label:"Totalt per flaska",values:["80mg","70mg","10mg / 20mg"]},{label:"Ytterligare fokus",values:["Antiinflammatorisk (KPV)","Ombyggnad (GHK-Cu)","Fokuserad dubbelreparation"]}]}},glow:{name:"GLOW-blandning",description:"Trepeptidsforskningsblandning av TB-500, BPC-157 och GHK-Cu, co-lyofiliserad i en enda 70mg-flaska för kombinerade studier av signalvägar för vävnadsreparation och vävnadsombyggnad.",longDescription:"GLOW-blandningen kombinerar tre forskningspeptider i en 70mg-flaska: TB-500 (10mg), ett Thymosin Beta-4-fragment som studeras för cellmigration och angiogenes; BPC-157 (10mg), en stabil gastrisk pentadekapeptid som studeras för vävnadsreparation; och GHK-Cu (50mg), en kopparbindande tripeptid som studeras för vävnadsombyggnad och kollagenforskning. De tre kombineras för att undersöka komplementära reparations- och ombyggnadssignalvägar i en enda studiedesign. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Trekomponents vävnadsreparationsforskning i en enda flaska","Kombinerade studier av angiogenes- och cellmigrationssignalvägar","Forskning om vävnadsombyggnad och kollagen (GHK-Cu-komponent)","Studier av signalvägar för sårläkning","Co-lyofiliserad blandning för studiedesigner med kombinerade signalvägar"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. Varje 70mg-flaska innehåller 10mg TB-500, 10mg BPC-157 och 50mg GHK-Cu. Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vad ingår i GLOW-blandningen?",answer:"Varje 70mg-flaska innehåller 10mg TB-500, 10mg BPC-157 och 50mg GHK-Cu, co-lyofiliserade som en enda blandning."},{question:"Hur skiljer sig GLOW från KLOW?",answer:"GLOW innehåller tre komponenter (TB-500, BPC-157, GHK-Cu), medan KLOW lägger till en fjärde, KPV, för forskning om antiinflammatoriska signalvägar. GLOW fokuserar på vävnadsreparation och vävnadsombyggnad."},{question:"Hur ska blandningen förvaras?",answer:"Förvara lyofiliserat pulver vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["läkning","vävnadsreparation","vävnadsombyggnad","återhämtning","blandning","forskningspeptid"],aka:["GLOW Healing Blend","TB-500 / BPC-157 / GHK-Cu-blandning"],whatIs:"GLOW-blandningen är en forskningssubstans som kombinerar tre peptider (TB-500, BPC-157 och GHK-Cu) co-lyofiliserade i en 70mg-flaska. Den används för att in vitro studera kombinerade signalvägar för vävnadsreparation och vävnadsombyggnad. Levereras endast för laboratorieforskning.",mechanism:"I publicerad forskning rapporterades Thymosin Beta-4 (ursprunget till TB-500) stödja cellmigration och angiogenes, BPC-157 associerades med påskyndad vävnadsläkning i djurmodeller, och GHK-Cu beskrevs i forskning om vävnadsombyggnad och sårreparation. Blandningen studeras för hur dessa reparations- och ombyggnadssignalvägar kan verka parallellt; kombinerade mekanismer och utfall hos människa är inte fastställda.",receptorTargets:["Aktinsekvestrerande / cellmigrationssignalvägar (TB-500)","Angiogenes- och vävnadsreparationssignalvägar (BPC-157)","Kopparberoende vävnadsombyggnad (GHK-Cu)","Signalvägar för kollagen- och matrissyntes"],blendComposition:[{name:"TB-500",role:"Thymosin-β4-fragment",amount:"10mg"},{name:"BPC-157",role:"Gastrisk pentadekapeptid",amount:"10mg"},{name:"GHK-Cu",role:"Koppar-tripeptid",amount:"50mg"}],specs:[{label:"Sammansättning",value:"10mg TB-500 + 10mg BPC-157 + 50mg GHK-Cu"},{label:"Total mängd per flaska",value:"70mg co-lyofiliserad blandning"},{label:"Komponenter",value:"Tre forskningspeptider"},{label:"Utseende",value:"Vitt till blekblått lyofiliserat pulver (kopparinnehåll)"},{label:"Löslighet",value:"Löslig i bakteriostatiskt vatten"}],researchApplications:[{title:"Vävnadsreparation",description:"Studeras för de kombinerade effekterna av TB-500 och BPC-157 på cellmigration och sårläkning."},{title:"Vävnadsombyggnad",description:"Används i forskning om GHK-Cu, kollagensyntes och kopparberoende ombyggnadssignalvägar."},{title:"Angiogenes",description:"Tillämpas för att undersöka de blodkärlsbildningssignalvägar som associeras med komponenterna."},{title:"Designer med kombinerade signalvägar",description:"Utforskas i studiedesigner som jämför enskilda peptider med en flerkomponentsblandning."}],keyStudies:[{title:"Stabil gastrisk pentadekapeptid BPC 157 och sårläkning",source:"Frontiers in Pharmacology",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34267654/",finding:"Granskade prekliniska rapporter där BPC-157 associerades med påskyndad läkning över modeller för hud-, muskel-, sen- och andra vävnadsskador hos djur."},{title:"Djurstudier med Thymosin Beta, en multifunktionell peptid för vävnadsreparation och regenerering",source:"Annals of the New York Academy of Sciences",year:2010,url:"https://pubmed.ncbi.nlm.nih.gov/20536453/",finding:"Sammanfattade djurmodellstudier där det rapporterades att Thymosin Beta-4 (ursprunget till TB-500) stödjer cellmigration, angiogenes och vävnadsreparation."},{title:"Den mänskliga tripeptiden GHK och vävnadsombyggnad",source:"Journal of Biomaterials Science, Polymer Edition",year:2008,url:"https://pubmed.ncbi.nlm.nih.gov/18644225/",finding:"Granskade den kopparbindande tripeptiden GHK och dess rapporterade roller i forskning om vävnadsombyggnad och sårreparation."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C.",howSupplied:"Levereras som en enda försluten flaska med 10mg TB-500, 10mg BPC-157 och 50mg GHK-Cu som ett co-lyofiliserat pulver. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg.",comparison:{heading:"GLOW vs de andra forskningsblandningarna",columns:["","GLOW","KLOW","BPC-157 + TB-500"],rows:[{label:"Komponenter",values:["TB-500, BPC-157, GHK-Cu","TB-500, BPC-157, GHK-Cu, KPV","BPC-157, TB-500"]},{label:"Antal komponenter",values:["3","4","2"]},{label:"Totalt per flaska",values:["70mg","80mg","10mg / 20mg"]},{label:"Ytterligare fokus",values:["Ombyggnad (GHK-Cu)","Antiinflammatorisk (KPV)","Fokuserad dubbelreparation"]}]}},"bpc-157-tb-500":{name:"BPC-157 + TB-500-blandning",description:"Dubbelpeptidsforskningsblandning av BPC-157 och TB-500 i 50/50-förhållande, co-lyofiliserad för fokuserade studier av signalvägar för vävnadsreparation och regenerering. Finns i 10mg- och 20mg-flaskor.",longDescription:"Denna forskningsblandning kombinerar BPC-157, en stabil gastrisk pentadekapeptid som studeras för vävnadsreparation, med TB-500, ett Thymosin Beta-4-fragment som studeras för cellmigration och angiogenes, i ett 50/50-förhållande per flaska. De två kombineras för att undersöka fokuserad, dubbel vävnadsreparation över två signalvägar i en enda studiedesign. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Fokuserad vävnadsreparationsforskning över två signalvägar","Kombinerade studier av angiogenes och cellmigration","Forskning om signalvägar för sårläkning och senreparation","Två komponenter i en enda co-lyofiliserad flaska","50/50-förhållande för balanserade designer med kombinerade signalvägar"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. Varje flaska innehåller BPC-157 och TB-500 i 50/50-förhållande (5mg + 5mg per 10mg-flaska). Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vad ingår i BPC-157 + TB-500-blandningen?",answer:"Varje flaska innehåller BPC-157 och TB-500 i 50/50-förhållande. 10mg-flaskan innehåller 5mg av varje substans och 20mg-flaskan 10mg av varje substans, co-lyofiliserade som en enda blandning."},{question:"Varför studeras BPC-157 och TB-500 tillsammans?",answer:"BPC-157 studeras för vävnadsreparation och TB-500 för cellmigration och angiogenes. Eftersom de associeras med komplementära reparationssignalvägar studerar forskare paret för att undersöka fokuserad, dubbel vävnadsreparation över två signalvägar."},{question:"Hur ska blandningen förvaras?",answer:"Förvara lyofiliserat pulver vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["läkning","vävnadsreparation","återhämtning","blandning","forskningspeptid"],aka:["BPC-157 / TB-500-blandning","BPC + TB Healing Blend"],whatIs:"BPC-157 + TB-500-blandningen är en forskningssubstans som kombinerar två vävnadsreparationspeptider i 50/50-förhållande per flaska. Den används för att in vitro studera fokuserad, dubbel vävnadsreparation över två signalvägar. Levereras endast för laboratorieforskning.",mechanism:"I publicerad forskning associerades BPC-157 med påskyndad vävnadsläkning över djurmodeller för skada, medan Thymosin Beta-4 (ursprunget till TB-500) rapporterades stödja cellmigration, angiogenes och vävnadsreparation. Blandningen studeras för hur dessa två reparationssignalvägar kan samverka; kombinerade mekanismer och utfall hos människa är inte fastställda.",receptorTargets:["Angiogenes- och vävnadsreparationssignalvägar (BPC-157)","Aktinsekvestrerande / cellmigrationssignalvägar (TB-500)","Sårläkningssignalering","Signalvägar för sen- och muskelreparation"],blendComposition:[{name:"BPC-157",role:"Gastrisk pentadekapeptid",amount:"50%"},{name:"TB-500",role:"Thymosin-β4-fragment",amount:"50%"}],specs:[{label:"Sammansättning",value:"BPC-157 + TB-500 (50/50-förhållande)"},{label:"Mängd per flaska",value:"5mg + 5mg (10mg) eller 10mg + 10mg (20mg)"},{label:"Komponenter",value:"Två forskningspeptider"},{label:"Utseende",value:"Vitt lyofiliserat pulver"},{label:"Löslighet",value:"Löslig i bakteriostatiskt vatten"}],researchApplications:[{title:"Vävnadsreparation",description:"Studeras för den kombinerade effekten av BPC-157 och TB-500 på sårläkning och regenerering."},{title:"Cellmigration",description:"Används i forskning om de aktinsekvestrerande och cellmigrationssignalvägar som associeras med TB-500."},{title:"Angiogenes",description:"Tillämpas för att undersöka de blodkärlsbildningssignalvägar som associeras med båda komponenterna."},{title:"Designer med kombinerade signalvägar",description:"Utforskas i studiedesigner som jämför enskilda peptider med en balanserad dubbelblandning."}],keyStudies:[{title:"Stabil gastrisk pentadekapeptid BPC 157 och sårläkning",source:"Frontiers in Pharmacology",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34267654/",finding:"Granskade prekliniska rapporter där BPC-157 associerades med påskyndad läkning över modeller för hud-, muskel-, sen- och andra vävnadsskador hos djur."},{title:"Djurstudier med Thymosin Beta, en multifunktionell peptid för vävnadsreparation och regenerering",source:"Annals of the New York Academy of Sciences",year:2010,url:"https://pubmed.ncbi.nlm.nih.gov/20536453/",finding:"Sammanfattade djurmodellstudier där det rapporterades att Thymosin Beta-4 (ursprunget till TB-500) stödjer cellmigration, angiogenes och vävnadsreparation."},{title:"Thymosin Beta4: en multifunktionell regenerativ peptid. Grundläggande egenskaper och kliniska tillämpningar",source:"Expert Opinion on Biological Therapy",year:2012,url:"https://pubmed.ncbi.nlm.nih.gov/22074294/",finding:"Granskade de biokemiska egenskaperna och mekanismerna hos Thymosin Beta-4 som en aktinsekvestrerande, vävnadsregenererande peptid som ligger till grund för forskning om sårreparation."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C.",howSupplied:"Levereras som en enda försluten flaska med BPC-157 och TB-500 i 50/50-förhållande som ett co-lyofiliserat vitt pulver. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg.",comparison:{heading:"BPC-157 + TB-500 vs de större forskningsblandningarna",columns:["","BPC-157 + TB-500","GLOW","KLOW"],rows:[{label:"Komponenter",values:["BPC-157, TB-500","TB-500, BPC-157, GHK-Cu","TB-500, BPC-157, GHK-Cu, KPV"]},{label:"Antal komponenter",values:["2","3","4"]},{label:"Totalt per flaska",values:["10mg / 20mg","70mg","80mg"]},{label:"Forskningsfokus",values:["Fokuserad dubbelreparation","Reparation + ombyggnad","Reparation + ombyggnad + antiinflammatorisk"]}]}},kpv:{name:"KPV",description:"Antiinflammatorisk tripeptid (Lys-Pro-Val), det C-terminala fragmentet av alfa-MSH, levererad som en lyofiliserad referensstandard för forskning om immunmodulering och tarminflammation.",longDescription:"KPV är en tripeptid (Lys-Pro-Val) som motsvarar det C-terminala fragmentet av alfa-melanocytstimulerande hormon (alfa-MSH). Den har studerats för antiinflammatorisk aktivitet, inklusive upptag via PepT1-transportören och effekter på markörer för inflammation i cell- och djurmodeller av kolit. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Forskning om antiinflammatoriska signalvägar","Studier av immunmodulering","Forskning om tarm- och intestinal inflammation","Studier av upptag via PepT1-transportören","Forskning om det C-terminala fragmentet av alfa-MSH"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. KPV levereras som ett lyofiliserat pulver. Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vad är KPV?",answer:"KPV är en tripeptid (Lys-Pro-Val) som motsvarar det C-terminala fragmentet (11-13) av alfa-melanocytstimulerande hormon (alfa-MSH) och studeras för antiinflammatorisk aktivitet."},{question:"Vad är molekylvikt och formel för KPV?",answer:"KPV har molekylformeln C16H30N4O4 och en molekylvikt på cirka 342,43 g/mol (PubChem CID 125672). Dess sekvens är Lys-Pro-Val."},{question:"Vilken renhet har KPV från Miro Biotech?",answer:"Varje batch testas av ett oberoende tredjepartslabb och verifieras till 99,41 % renhet, med ett analyscertifikat för batchen."},{question:"Hur ska KPV förvaras?",answer:"Förvara det lyofiliserade pulvret vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["antiinflammatorisk","immun","tarmhälsa","tripeptid","forskningspeptid"],aka:["Lys-Pro-Val","Alfa-MSH (11-13)","KPV-tripeptid"],whatIs:"KPV är en tripeptid (Lys-Pro-Val), det C-terminala fragmentet av alfa-MSH, som används som forskningssubstans i studier av antiinflammatoriska och immunmodulerande signalvägar. Levereras endast för in-vitro- och laboratorieforskning.",mechanism:"I publicerad forskning rapporterades KPV tas upp via PepT1-transportören i intestinala epitel- och immunceller och minskar i detta sammanhang markörer för inflammation i cell- och musmodeller av kolit. Ytterligare forskning beskrev en antiinflammatorisk profil som kan skiljas från den hos de centrala melanokortinpeptiderna. Dessa signalvägar undersöks i modeller av intestinal och immunologisk inflammation; motsvarande mekanismer hos människa är inte fastställda.",receptorTargets:["PepT1-peptidtransportör","NF-kB-inflammationssignalering","Melanokortinsignalväg (alfa-MSH-fragment)","Intestinala epitel- och immunceller"],specs:[{label:"Sekvens",value:"Lys-Pro-Val (KPV)"},{label:"Klassificering",value:"Tripeptid, C-terminalt fragment av alfa-MSH"},{label:"Utseende",value:"Vitt lyofiliserat pulver"},{label:"Löslighet",value:"Löslig i bakteriostatiskt vatten"}],researchApplications:[{title:"Intestinal inflammation",description:"Används i forskning om markörer för inflammation i cell- och djurmodeller av kolit."},{title:"Immunmodulering",description:"Undersöks för antiinflammatorisk aktivitet som det C-terminala fragmentet av alfa-MSH."},{title:"Transportörupptag",description:"Tillämpas för att undersöka det PepT1-medierade upptaget i epitel- och immunceller."},{title:"Melanokortinfarmakologi",description:"Utforskas jämsides med de centrala melanokortinpeptiderna för att jämföra antiinflammatoriska profiler."}],keyStudies:[{title:"PepT1-medierat upptag av tripeptiden KPV minskar intestinal inflammation",source:"Gastroenterology",year:2008,url:"https://pubmed.ncbi.nlm.nih.gov/18061177/",finding:"Rapporterade att KPV togs upp via PepT1-transportören i intestinala epitel- och immunceller och minskade i detta sammanhang markörer för inflammation i cell- och musmodeller av kolit."},{title:"Uppdelning av den antiinflammatoriska verkan av de centrala och C-terminala (KPV) alfa-melanocytstimulerande hormonpeptiderna",source:"Journal of Pharmacology and Experimental Therapeutics",year:2003,url:"https://pubmed.ncbi.nlm.nih.gov/12750433/",finding:"Observerade att den C-terminala alfa-MSH-tripeptiden KPV i de studerade modellerna uppvisade en antiinflammatorisk profil som kunde skiljas från den hos de centrala melanokortinpeptiderna."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C.",howSupplied:"Levereras som en enda försluten flaska med vitt lyofiliserat KPV-pulver. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg."},glutathione:{name:"Glutation",description:"Master-antioxidanttripeptid (gamma-Glu-Cys-Gly), levererad som en lyofiliserad referensstandard för forskning om oxidativ stress, redoxbiologi och avgiftning. Finns i 600mg- och 1500mg-flaskor.",longDescription:"Glutation (GSH) är en tripeptid av glutamat, cystein och glycin och en av de primära icke-enzymatiska antioxidanterna i levande celler. Den har studerats omfattande för sin roll i redoxhomeostas, GSH/GSSG-paret, avgiftning och redoxsignalering. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Forskning om cellulära antioxidanter och redox","Studier av signalvägar för oxidativ stress","Forskning om GSH/GSSG-redoxparet","Studier av avgiftningssignalvägar","Forskning om redoxsignalering"],researchGuide:"Glutation är vattenlösligt och kan rekonstitueras i sterilt vatten eller buffert. Det är ljus- och syrekänsligt, så hantera med försiktighet och minimera luftkontakt. Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen kyld samt använd skyndsamt.",faq:[{question:"Vad är glutation?",answer:"Glutation (GSH) är en tripeptid av glutamat, cystein och glycin (gamma-Glu-Cys-Gly), studerad som en av de primära icke-enzymatiska cellulära antioxidanterna och som en central del av GSH/GSSG-redoxparet."},{question:"Vad är molekylvikt och formel för glutation?",answer:"Glutation har molekylformeln C10H17N3O6S och en molekylvikt på cirka 307,32 g/mol (PubChem CID 124886)."},{question:"Vilken renhet har glutation från Miro Biotech?",answer:"Varje batch testas av ett oberoende tredjepartslabb och verifieras till 99,69 % renhet, med ett analyscertifikat för batchen."},{question:"Hur ska glutation förvaras?",answer:"Förvara det lyofiliserade pulvret vid -20 °C skyddat från ljus. Eftersom det är syrekänsligt bör rekonstituerade lösningar användas skyndsamt och hållas kylda."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["anti-aging","antioxidant","redox","avgiftning","tripeptid","forskningspeptid"],aka:["GSH","gamma-Glu-Cys-Gly","reducerat glutation"],whatIs:"Glutation (GSH) är en tripeptid av glutamat, cystein och glycin, som används som forskningssubstans i studier av cellulär antioxidantaktivitet, redoxhomeostas och avgiftning. Levereras endast för in-vitro- och laboratorieforskning.",mechanism:"I publicerad forskning har reducerat glutation (GSH) beskrivits som en essentiell icke-enzymatisk cellulär antioxidant, central för redoxhomeostas genom GSH/GSSG-paret, avgiftningsreaktioner och redoxsignalering. Dessa signalvägar undersöks i modeller av oxidativ stress; motsvarande mekanismer hos människa undersöks i pågående redoxbiologisk forskning.",receptorTargets:["GSH/GSSG-redoxparet","Signalvägar för glutationperoxidas och -reduktas","Cellulära avgiftnings-(konjugerings-)signalvägar","Redoxsignalering"],specs:[{label:"Sammansättning",value:"Tripeptid (gamma-Glu-Cys-Gly)"},{label:"Klassificering",value:"Icke-enzymatisk cellulär antioxidant"},{label:"Utseende",value:"Vitt lyofiliserat pulver"},{label:"Löslighet",value:"Löslig i vatten och buffert"}],researchApplications:[{title:"Oxidativ stress",description:"Används i forskning om cellulär antioxidantkapacitet och modeller av oxidativ stress."},{title:"Redoxbiologi",description:"Undersöks som en central del av GSH/GSSG-redoxparet."},{title:"Avgiftning",description:"Tillämpas för att undersöka konjugerings- och avgiftningssignalvägar."},{title:"Redoxsignalering",description:"Utforskas i forskning om redoxberoende cellsignalering."}],keyStudies:[{title:"Antioxidanten glutation",source:"Vitamins and Hormones",year:2023,url:"https://pubmed.ncbi.nlm.nih.gov/36707132/",finding:"Granskade reducerat glutation (GSH) som en essentiell icke-enzymatisk cellulär antioxidant och beskrev dess roll i redoxhomeostas, GSH/GSSG-paret, avgiftning och redoxsignalering."},{title:"Glutationsyntes",source:"Biochimica et Biophysica Acta",year:2013,url:"https://pubmed.ncbi.nlm.nih.gov/22995213/",finding:"Granskade den tvåstegs cytosoliska biosyntesen av glutation via glutamat-cystein-ligas och GSH-syntetas och beskrev hur denna signalväg rapporteras vara strikt reglerad och dysreglerad i sjukdomstillstånd."},{title:"Glutation, stressvar och redoxsignalering vid lunginflammation",source:"Antioxidants & Redox Signaling",year:2005,url:"https://pubmed.ncbi.nlm.nih.gov/15650395/",finding:"Granskade hur förskjutningar i det intracellulära GSH/GSSG-förhållandet rapporteras påverka redoxkänsliga signalvägar och cysteinbaserad redoxkemi i samband med lunginflammation."}],reconstitution:"Rekonstitueras vanligen med sterilt vatten eller buffert för laboratoriebruk. Eftersom glutation är syrekänsligt, minimera luftkontakt, tillsätt spädningsvätskan försiktigt och håll den rekonstituerade lösningen kyld samt använd inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt och använd skyndsamt.",howSupplied:"Levereras som en enda försluten flaska med vitt lyofiliserat glutationpulver i valt format. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg."},epithalon:{name:"Epithalon",description:"Syntetisk pineal tetrapeptid (Ala-Glu-Asp-Gly), även skriven Epitalon, levererad som en lyofiliserad referensstandard för forskning om telomeras, pineal melatonin och cellulärt åldrande. Finns i 10mg- och 50mg-flaskor.",longDescription:"Epithalon (Epitalon, AEDG-peptid) är en syntetisk tetrapeptid med sekvensen Ala-Glu-Asp-Gly, utvecklad av Khavinson-gruppen utifrån aminosyrasammansättningen i det bovina pinealextraktet Epithalamin. Den har studerats för telomerasaktivering och telomerförlängning i humana somatiska cellkulturer, för pineala melatoninrytmer hos åldrade primater och för neurogent genuttryck i stamcellsmodeller. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Forskning om telomeras och telomerlängd","Studier av tallkottkörteln och melatoninrytmer","Modeller av cellulär senescens och livslängd","Forskning om neurogent genuttryck","Studier av antioxidativa signalvägar och oxidativ stress"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. Epithalon levereras som ett lyofiliserat pulver. Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vad är Epithalon?",answer:"Epithalon (även stavat Epitalon) är en syntetisk tetrapeptid, Ala-Glu-Asp-Gly, utformad efter aminosyrasammansättningen i pinealextraktet Epithalamin. Den studeras i forskningsmodeller för telomeras, pineal melatonin och cellulärt åldrande."},{question:"Är Epithalon samma sak som Epitalon?",answer:"Ja. Epithalon, Epitalon och Epithalone är alternativa stavningar av samma AEDG-tetrapeptid (PubChem CID 219042, CAS 307297-39-8). Epithalamin är det äldre bovina pinealextrakt som den modellerades efter, vilket är ett annat material."},{question:"Vad är molekylvikt och formel för Epithalon?",answer:"Epithalon har molekylformeln C14H22N4O9 och en molekylvikt på cirka 390,35 g/mol (PubChem CID 219042). Dess sekvens är Ala-Glu-Asp-Gly."},{question:"Vilken renhet har Epithalon från Miro Biotech?",answer:"Varje batch testas av ett oberoende tredjepartslabb och verifieras till 99,52 % renhet, med ett analyscertifikat för batchen."},{question:"Hur ska Epithalon förvaras?",answer:"Förvara det lyofiliserade pulvret vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["telomeras","pineal","livslängd","tetrapeptid","bioregulator","forskningspeptid"],aka:["Epitalon","Epithalone","AEDG-peptid","Ala-Glu-Asp-Gly"],whatIs:"Epithalon (Epitalon) är en syntetisk tetrapeptid, Ala-Glu-Asp-Gly, härledd från aminosyrasammansättningen i pinealextraktet Epithalamin. Den används som forskningssubstans i studier av telomerasaktivitet, pineala melatoninrytmer och signalvägar för cellulärt åldrande. Levereras endast för in-vitro- och laboratorieforskning.",mechanism:"I publicerad forskning rapporterades Epithalon inducera uttryck av telomerasets katalytiska subenhet, telomerasets enzymatiska aktivitet och telomerförlängning i telomerasnegativa humana fetala fibroblastkulturer. Separat arbete på åldrade rhesusapor rapporterade återställd nattlig melatoninproduktion från tallkottkörteln, och en stamcellsstudie rapporterade ökat uttryck av markörer för neurogen differentiering, där molekylär modellering antydde bindning till histon H1-säten som en möjlig epigenetisk mekanism. Dessa signalvägar undersöks i cell- och djurmodeller; motsvarande mekanismer hos människa är inte fastställda.",receptorTargets:["Uttryck av telomerasets katalytiska subenhet (TERT)","Pineal melatoninsyntes","Histon H1-bindning (föreslagen epigenetisk mekanism)","Markörer för neurogen differentiering (Nestin, GAP43)"],specs:[{label:"Sekvens",value:"Ala-Glu-Asp-Gly (AEDG)"},{label:"Klassificering",value:"Syntetisk pineal tetrapeptidbioregulator"},{label:"Utseende",value:"Vitt lyofiliserat pulver"},{label:"Löslighet",value:"Löslig i bakteriostatiskt vatten"}],researchApplications:[{title:"Telomerasbiologi",description:"Används i forskning om telomerasaktivering och telomerlängd i humana somatiska cellkulturer."},{title:"Pineal- och dygnsrytmforskning",description:"Studeras för effekter på pineala melatoninrytmer i åldrade primatmodeller."},{title:"Cellulärt åldrande",description:"Tillämpas i studier av livslängd, biomarkörer för åldrande och oxidativ stress i gnagarmodeller."},{title:"Epigenetisk reglering",description:"Utforskas för histonbindning och effekter på neurogent genuttryck i stamcellskulturer."}],keyStudies:[{title:"Epithalon-peptid inducerar telomerasaktivitet och telomerförlängning i humana somatiska celler",source:"Bulletin of Experimental Biology and Medicine",year:2003,url:"https://pubmed.ncbi.nlm.nih.gov/12937682/",finding:"Rapporterade att tillsats av Epithalon till telomerasnegativa humana fetala fibroblastkulturer inducerade uttryck av telomerasets katalytiska subenhet, telomerasets enzymatiska aktivitet och telomerförlängning."},{title:"Effekt av Epitalon på biomarkörer för åldrande, livslängd och spontan tumörincidens hos SHR-honmöss av Swiss-ursprung",source:"Biogerontology",year:2003,url:"https://pubmed.ncbi.nlm.nih.gov/14501183/",finding:"Rapporterade att Epitalon hos SHR-honmöss ökade livslängden för de sista 10 % överlevande, minskade kromosomavvikelser i benmärgen och sänkte leukemiincidensen, utan att ändra medellivslängden."},{title:"AEDG-peptid (Epitalon) stimulerar genuttryck och proteinsyntes under neurogenes: möjlig epigenetisk mekanism",source:"Molecules",year:2020,url:"https://pubmed.ncbi.nlm.nih.gov/32019204/",finding:"Rapporterade att AEDG höjde markörer för neurogen differentiering i humana gingivala mesenkymala stamceller och, enligt molekylär modellering, företrädesvis band till histon H1-säten, vilket föreslogs som en epigenetisk mekanism."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C.",howSupplied:"Levereras som en enda försluten flaska med vitt lyofiliserat Epithalon-pulver i vald storlek. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg."},"ss-31":{name:"SS-31",description:"Mitokondrieriktad tetrapeptid (elamipretid, D-Arg-Dmt-Lys-Phe-NH2) levererad som en lyofiliserad referensstandard för forskning om kardiolipin, mitokondriell bioenergetik och cellulär energi. Finns i 10mg- och 50mg-flaskor.",longDescription:"SS-31 (elamipretid, MTP-131, Bendavia) är en aromatisk-katjonisk tetrapeptid, D-Arg-Dmt-Lys-Phe-NH2, ur Szeto-Schiller-serien. Den har studerats för selektiv bindning till kardiolipin i det inre mitokondriemembranet, för effekter på cytokrom c-elektrontransport och ATP-syntes i isolerade mitokondrier samt i klinisk forskning om mitokondriella kardiolipinsjukdomar. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Forskning om kardiolipin och det inre mitokondriemembranet","Studier av mitokondriell bioenergetik och ATP","Forskning om cytokrom c-elektrontransport","Modeller av oxidativ stress och ischemi","Forskning om cellulär energi och åldrande"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. SS-31 levereras som ett lyofiliserat pulver. Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vad är SS-31?",answer:"SS-31 (elamipretid) är en mitokondrieriktad aromatisk-katjonisk tetrapeptid, D-Arg-Dmt-Lys-Phe-NH2, studerad för sin interaktion med kardiolipin i det inre mitokondriemembranet och sina effekter på mitokondriell elektrontransport."},{question:"Vad är molekylvikt och formel för SS-31?",answer:"SS-31 har molekylformeln C32H49N9O5 och en molekylvikt på cirka 639,8 g/mol (PubChem CID 11764719, CAS 736992-21-5). Dmt är 2,6-dimetyl-L-tyrosin."},{question:"Hur förhåller sig SS-31 till elamipretid?",answer:"SS-31 är forskningsbeteckningen för elamipretid (även MTP-131 och Bendavia). Publicerad forskning om elamipretid beskriver kardiolipinbindning i det inre mitokondriemembranet; denna produkt är en referensstandard för forskning och inte en farmaceutisk beredning."},{question:"Vilken renhet har SS-31 från Miro Biotech?",answer:"Varje batch testas av ett oberoende tredjepartslabb och verifieras till 99,38 % renhet, med ett analyscertifikat för batchen."},{question:"Hur ska SS-31 förvaras?",answer:"Förvara det lyofiliserade pulvret vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["mitokondrier","kardiolipin","bioenergetik","tetrapeptid","livslängd","forskningspeptid"],aka:["Elamipretid","MTP-131","Bendavia","Szeto-Schiller-peptid 31","D-Arg-Dmt-Lys-Phe-NH2"],whatIs:"SS-31 (elamipretid) är en syntetisk aromatisk-katjonisk tetrapeptid, D-Arg-Dmt-Lys-Phe-NH2, som koncentreras i det inre mitokondriemembranet. Den används som forskningssubstans i studier av kardiolipin, cytokrom c-elektrontransport och mitokondriell ATP-syntes. Levereras endast för in-vitro- och laboratorieforskning.",mechanism:"I publicerad forskning rapporterades SS-31 binda kardiolipin i det inre mitokondriemembranet med hög affinitet, och komplexet mellan SS-31 och kardiolipin rapporterades hämma cytokrom c-peroxidasaktivitet och skydda cristae-strukturen i en råttmodell av renal ischemi. Arbete i liposom-, bicell- och isolerade mitokondriesystem rapporterade att peptiden endast interagerar med kardiolipininnehållande membran, återställer cytokrom c-funktionen som elektronbärare och ökar state 3-respirationen. Klinisk forskning om elamipretid vid Barths syndrom och primär mitokondriell myopati har också publicerats. Dessa mekanismer är karakteriserade i cell-, membran- och djurmodeller.",receptorTargets:["Kardiolipin (inre mitokondriemembranet)","Cytokrom c/kardiolipin-komplexet","Elektrontransportkedjan och ATP-syntes","Mitokondriell cristae-struktur"],specs:[{label:"Sekvens",value:"D-Arg-Dmt-Lys-Phe-NH2 (Dmt = 2,6-dimetyl-L-tyrosin)"},{label:"Klassificering",value:"Aromatisk-katjonisk mitokondrieriktad tetrapeptid"},{label:"Utseende",value:"Vitt lyofiliserat pulver"},{label:"Löslighet",value:"Löslig i bakteriostatiskt vatten"}],researchApplications:[{title:"Mitokondriell bioenergetik",description:"Används i forskning om elektrontransport, state 3-respiration och ATP-syntes i isolerade mitokondrier."},{title:"Kardiolipinbiologi",description:"Studeras för membraninteraktion och hämning av cytokrom c-peroxidas i kardiolipininnehållande system."},{title:"Ischemi och oxidativ stress",description:"Tillämpas i ischemi-reperfusionsmodeller för att undersöka skydd av cristae och återhämtning av ATP."},{title:"Forskning om mitokondriella sjukdomar",description:"Utforskas i klinisk forskning om störningar i kardiolipinmetabolismen och mitokondriell myopati."}],keyStudies:[{title:"Den mitokondrieriktade substansen SS-31 återenergiserar ischemiska mitokondrier genom interaktion med kardiolipin",source:"Journal of the American Society of Nephrology",year:2013,url:"https://pubmed.ncbi.nlm.nih.gov/23813215/",finding:"Rapporterade att SS-31 binder kardiolipin med hög affinitet, att komplexet hämmar cytokrom c-peroxidasaktivitet och att förbehandling i en råttmodell av renal ischemi skyddade cristae-membranen och påskyndade ATP-återhämtningen vid reperfusion."},{title:"Riktning mot mitokondriellt kardiolipin och cytokrom c/kardiolipin-komplexet för att främja elektrontransport och optimera mitokondriell ATP-syntes",source:"British Journal of Pharmacology",year:2014,url:"https://pubmed.ncbi.nlm.nih.gov/24134698/",finding:"Rapporterade i experiment med liposomer, biceller och isolerade mitokondrier att SS-31 endast interagerar med kardiolipininnehållande membran, återställer cytokrom c-funktionen som elektronbärare och ökar state 3-respirationen."},{title:"En randomiserad fas 2/3-studie följd av en öppen förlängning för att utvärdera effekten av elamipretid vid Barths syndrom",source:"Genetics in Medicine",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/33077895/",finding:"Rapporterade att den randomiserade fasen i TAZPOWER-crossoverstudien inte nådde sina primära effektmått, medan den 36 veckor långa öppna förlängningen registrerade förbättringar i 6-minuters gångsträcka och symtompoäng."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C.",howSupplied:"Levereras som en enda försluten flaska med vitt lyofiliserat SS-31-pulver i vald storlek. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg."},vesugen:{name:"Vesugen",description:"Vaskulär tripeptidbioregulator (Lys-Glu-Asp, KED-peptid) levererad som en lyofiliserad referensstandard för forskning om endotel, vaskulärt åldrande och genuttryck.",longDescription:"Vesugen (KED-peptid) är en syntetisk tripeptid med sekvensen Lys-Glu-Asp, en av de korta peptidbioregulatorer som utvecklats av Khavinson-gruppen. Den har studerats i vaskulära endotelcellkulturer för effekter på uttrycket av endotelin-1, connexin och sirtuin-1, för proliferationsmarkörer i åldrande endotel och för neurogenesrelaterat genuttryck. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Forskning om vaskulärt endotel","Studier av uttrycket av endotelin-1 och connexin","Forskning om sirtuin-1-signalvägen","Modeller av endotelproliferation och åldrande","Studier av genuttryck vid neurogenes"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. Vesugen levereras som ett lyofiliserat pulver. Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vad är Vesugen?",answer:"Vesugen är en syntetisk tripeptid, Lys-Glu-Asp (KED), ur Khavinson-serien av korta peptidbioregulatorer. Den studeras i vaskulära endotelcellmodeller för effekter på uttrycket av endotelin-1, connexin, sirtuin-1 och proliferationsmarkörer."},{question:"Vad är molekylvikt och formel för Vesugen?",answer:"Vesugen har molekylformeln C15H26N4O8 och en molekylvikt på cirka 390,39 g/mol (PubChem CID 87571363). Dess sekvens är Lys-Glu-Asp."},{question:"Vilken renhet har Vesugen från Miro Biotech?",answer:"Varje batch testas av ett oberoende tredjepartslabb och verifieras till 99,61 % renhet, med ett analyscertifikat för batchen."},{question:"Hur ska Vesugen förvaras?",answer:"Förvara det lyofiliserade pulvret vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["vaskulär","endotel","bioregulator","tripeptid","livslängd","forskningspeptid"],aka:["KED-peptid","Lys-Glu-Asp","Lysyl-glutamyl-asparaginsyra"],whatIs:"Vesugen är en syntetisk tripeptid, Lys-Glu-Asp (KED), ur Khavinson-serien av korta peptidbioregulatorer. Den används som forskningssubstans i studier av vaskulärt endotel, uttryck av endotelin-1 och sirtuin-1 samt endotelproliferation under åldrande. Levereras endast för in-vitro- och laboratorieforskning.",mechanism:"I publicerad forskning rapporterades KED normalisera det förhöjda uttrycket av endotelin-1 i aterosklerotiska och restenotiska endotelceller och återställa uttrycket av connexin och sirtuin-1 in vitro. Separat arbete rapporterade ökad proliferationsmarkör Ki-67 i åldrade vaskulära endotelkulturer, där molekylär dockning antydde kontakt med MKI67-kärnpromotorn, och en översikt beskrev reglering av gener för cellulärt åldrande (p16, p21) och gener för neuronal differentiering (NES, GAP43) i neurogenesmodeller. Dessa effekter beskrivs i cellkulturmodeller; motsvarande mekanismer hos människa är inte fastställda.",receptorTargets:["Uttryck av endotelin-1","Uttryck av connexin och sirtuin-1 (SIRT1)","Ki-67/MKI67-promotorn (föreslagen)","Cellåldrandegenerna p16 och p21"],specs:[{label:"Sekvens",value:"Lys-Glu-Asp (KED)"},{label:"Klassificering",value:"Syntetisk vaskulär tripeptidbioregulator"},{label:"Utseende",value:"Vitt lyofiliserat pulver"},{label:"Löslighet",value:"Löslig i bakteriostatiskt vatten"}],researchApplications:[{title:"Endotelbiologi",description:"Används i forskning om uttrycket av endotelin-1, connexin och sirtuin-1 i vaskulära endotelkulturer."},{title:"Vaskulärt åldrande",description:"Studeras för uttryck av proliferationsmarkörer i åldrad endotelvävnad och cellmodeller."},{title:"Epigenetisk reglering",description:"Utforskas genom molekylär dockning till genpromotorer som en föreslagen verkningsmekanism."},{title:"Neurogenesmodeller",description:"Tillämpas i studier av genuttryck för cellulärt åldrande och neuronal differentiering."}],keyStudies:[{title:"Molekylära aspekter av den vasoprotektiva peptiden KED:s aktivitet vid ateroskleros och restenos",source:"Advances in Gerontology",year:2016,url:"https://pubmed.ncbi.nlm.nih.gov/28539025/",finding:"Rapporterade att KED normaliserade uttrycket av endotelin-1 och återställde uttrycket av connexin och sirtuin-1 i normala, aterosklerotiska och restenotiska endotelceller in vitro."},{title:"Epigenetiska aspekter av peptiderg reglering av vaskulär endotelcellsproliferation under åldrande",source:"Advances in Gerontology",year:2014,url:"https://pubmed.ncbi.nlm.nih.gov/25051766/",finding:"Rapporterade att Vesugen stimulerade proliferationsmarkören Ki-67 i åldrade vaskulära endotelkulturer, där molekylär dockning visade kontakt med MKI67-kärnpromotorn."},{title:"Peptiden KED: molekylärgenetiska aspekter av neurogenesreglering vid Alzheimers sjukdom",source:"Bulletin of Experimental Biology and Medicine",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34173097/",finding:"Granskade rapporter om att KED reglerar gener för cellulärt åldrande (p16, p21), gener för neuronal differentiering (NES, GAP43) och Alzheimerrelaterade gener i en in vitro-modell av neurogenes."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C.",howSupplied:"Levereras som en enda försluten flaska med vitt lyofiliserat Vesugen-pulver. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg."},cartalax:{name:"Cartalax",description:"Brosktripeptidbioregulator (Ala-Glu-Asp, AED-peptid) levererad som en lyofiliserad referensstandard för forskning om kondrogen differentiering, bindväv och cellulärt åldrande.",longDescription:"Cartalax (AED-peptid) är en syntetisk tripeptid med sekvensen Ala-Glu-Asp, en av de korta peptidbioregulatorer som utvecklats av Khavinson-gruppen. Den har studerats i humana mesenkymala stamcellskulturer för uttryck av kondrogena markörer (SOX9, aggrekan, kollagen typ II, COMP), i åldrande hudfibroblaster för MMP-9 och proliferationsmarkörer samt i stamcellsmodeller av åldrande för uttryck av IGF1 och NF-kB. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Forskning om kondrogen differentiering","Modeller av brosk och bindväv","Studier av MMP-9 och fibroblaståldrande","Forskning om uttryck av IGF1 och NF-kB","Studier av åldrande i mesenkymala stamceller"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. Cartalax levereras som ett lyofiliserat pulver. Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vad är Cartalax?",answer:"Cartalax är en syntetisk tripeptid, Ala-Glu-Asp (AED), ur Khavinson-serien av korta peptidbioregulatorer. Den studeras i modeller med mesenkymala stamceller och fibroblaster för uttryck av kondrogena markörer och bindvävsåldrande."},{question:"Vad är molekylvikt och formel för Cartalax?",answer:"Cartalax har molekylformeln C12H19N3O8 och en molekylvikt på cirka 333,29 g/mol (PubChem CID 87815447). Dess sekvens är Ala-Glu-Asp."},{question:"Vilken renhet har Cartalax från Miro Biotech?",answer:"Varje batch testas av ett oberoende tredjepartslabb och verifieras till 99,47 % renhet, med ett analyscertifikat för batchen."},{question:"Hur ska Cartalax förvaras?",answer:"Förvara det lyofiliserade pulvret vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["brosk","kondrocyt","bindväv","bioregulator","tripeptid","forskningspeptid"],aka:["AED-peptid","Ala-Glu-Asp","T-31-peptid","Alanyl-glutamyl-asparaginsyra"],whatIs:"Cartalax är en syntetisk tripeptid, Ala-Glu-Asp (AED), ur Khavinson-serien av korta peptidbioregulatorer. Den används som forskningssubstans i studier av kondrogen differentiering, brosk- och bindvävsmarkörer samt fibroblaståldrande i cellkultur. Levereras endast för in-vitro- och laboratorieforskning.",mechanism:"I publicerad forskning rapporterades AED-peptid vid 200 ng/ml aktivera uttrycket av de kondrogena markörerna SOX9, aggrekan, kollagen typ II och COMP i humana mesenkymala stamceller under replikativt åldrande. Separat arbete i åldrande hudfibroblastkulturer rapporterade hämmad MMP-9-syntes, ökat Ki-67 och CD98hc samt dämpad kaspasberoende apoptos, och en stamcellsstudie av åldrande rapporterade ökat IGF1-uttryck tillsammans med stimulerat NF-kB-uttryck. Dessa effekter beskrivs i cellkulturmodeller; motsvarande mekanismer hos människa är inte fastställda.",receptorTargets:["Uttryck av SOX9, aggrekan och kollagen typ II","MMP-9-syntes","Uttryck av IGF1 och NF-kB","Kaspasberoende apoptos"],specs:[{label:"Sekvens",value:"Ala-Glu-Asp (AED)"},{label:"Klassificering",value:"Syntetisk brosktripeptidbioregulator"},{label:"Utseende",value:"Vitt lyofiliserat pulver"},{label:"Löslighet",value:"Löslig i bakteriostatiskt vatten"}],researchApplications:[{title:"Kondrogen differentiering",description:"Används i forskning om uttryck av broskmarkörer i humana mesenkymala stamcellskulturer."},{title:"Bindvävsåldrande",description:"Studeras för MMP-9-, proliferations- och apoptosmarkörer i åldrande fibroblastmodeller."},{title:"Tillväxtfaktorsignalering",description:"Tillämpas för att undersöka uttrycket av IGF1 och NF-kB i stamcellskulturer under åldrande."},{title:"Kortpeptidbioregulation",description:"Utforskas jämsides med andra Khavinson-tripeptider för att jämföra genuttrycksprofiler."}],keyStudies:[{title:"Peptiders inverkan på kondrogen differentiering av humana mesenkymala stamceller under replikativt åldrande",source:"Advances in Gerontology",year:2023,url:"https://pubmed.ncbi.nlm.nih.gov/37782646/",finding:"Rapporterade att AED-peptid vid 200 ng/ml aktiverade uttrycket av de kondrogena markörerna SOX9, aggrekan, kollagen typ II och COMP i humana mesenkymala stamceller under replikativt åldrande in vitro."},{title:"Peptidreglering av hudfibroblasters funktioner under deras åldrande in vitro",source:"Bulletin of Experimental Biology and Medicine",year:2016,url:"https://pubmed.ncbi.nlm.nih.gov/27259496/",finding:"Rapporterade att korta peptider inklusive AED hämmade MMP-9-syntesen och höjde Ki-67 och CD98hc i åldrande hudfibroblastkulturer, där AED även dämpade kaspasberoende apoptos."},{title:"Genuttryck i åldrande kulturer av humana mesenkymala stamceller: modulering av korta peptider",source:"Molecular Biology Reports",year:2020,url:"https://pubmed.ncbi.nlm.nih.gov/32399807/",finding:"Rapporterade att AED, KED och KE i nanomolära koncentrationer höjde IGF1-uttrycket flerfaldigt och stimulerade NF-kB-uttrycket i två modeller av åldrande humana mesenkymala benmärgsstamceller."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C.",howSupplied:"Levereras som en enda försluten flaska med vitt lyofiliserat Cartalax-pulver. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg."},pinealon:{name:"Pinealon",description:"Hjärntripeptidbioregulator (Glu-Asp-Arg, EDR-peptid) levererad som en lyofiliserad referensstandard för forskning om neuronkulturer, oxidativ stress och kognitivt åldrande.",longDescription:"Pinealon (EDR-peptid) är en syntetisk tripeptid med sekvensen Glu-Asp-Arg, en av de korta peptidbioregulatorer som utvecklats av Khavinson-gruppen. Den har studerats i kulturer av cerebellära granulceller, neutrofiler och PC12-celler för ackumulering av reaktiva syreföreningar och cellviabilitet, i en råttmodell av prenatal hyperhomocysteinemi för avkommans inlärning samt i neuronkulturmodeller av neurodegeneration. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Forskning om neuronkulturer och neuroprotektion","Studier av reaktiva syreföreningar och cellviabilitet","Modeller av kognitivt åldrande och inlärning","Forskning om MAPK/ERK-signalering","Studier av genuttryck vid neurodegeneration"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. Pinealon levereras som ett lyofiliserat pulver. Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vad är Pinealon?",answer:"Pinealon är en syntetisk tripeptid, Glu-Asp-Arg (EDR), ur Khavinson-serien av korta peptidbioregulatorer. Den studeras i neuronala cellkulturer och gnagarmodeller för ackumulering av reaktiva syreföreningar, cellviabilitet och inlärningsrelaterade utfall."},{question:"Vad är molekylvikt och formel för Pinealon?",answer:"Pinealon har molekylformeln C15H26N6O8 och en molekylvikt på cirka 418,40 g/mol (PubChem CID 10273502, CAS 175175-23-2). Dess sekvens är Glu-Asp-Arg."},{question:"Vilken renhet har Pinealon från Miro Biotech?",answer:"Varje batch testas av ett oberoende tredjepartslabb och verifieras till 99,55 % renhet, med ett analyscertifikat för batchen."},{question:"Hur ska Pinealon förvaras?",answer:"Förvara det lyofiliserade pulvret vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["neuroprotektion","kognitiv","bioregulator","tripeptid","nootropikum","forskningspeptid"],aka:["EDR-peptid","Glu-Asp-Arg","Glutamyl-aspartyl-arginin"],whatIs:"Pinealon är en syntetisk tripeptid, Glu-Asp-Arg (EDR), ur Khavinson-serien av korta peptidbioregulatorer. Den används som forskningssubstans i studier av neuronal cellviabilitet, ackumulering av reaktiva syreföreningar och modeller av kognitivt åldrande. Levereras endast för in-vitro- och laboratorieforskning.",mechanism:"I publicerad forskning rapporterades Pinealon begränsa ackumuleringen av reaktiva syreföreningar och nekrotisk celldöd i cerebellära granulceller, neutrofiler och PC12-celler under oxidativ stress, med fördröjd ERK1/2-aktivering och modulering av cellcykeln, vilket fick författarna att föreslå direkt interaktion med genomet. En råttmodell av prenatal hyperhomocysteinemi rapporterade förbättrad spatial inlärning hos avkomman och minskade neuronala ROS, och en översikt föreslog inträde i celler och bindning till histoner eller RNA, med nedströmseffekter på MAPK/ERK, kaspas-3, p53, SOD2 och GPX1. Dessa fynd kommer från cell- och djurmodeller; motsvarande mekanismer hos människa är inte fastställda.",receptorTargets:["Ackumulering av reaktiva syreföreningar (ROS)","MAPK/ERK1/2-signalering","Apoptossignalvägen kaspas-3 och p53","Antioxidantenzymerna SOD2 och GPX1"],specs:[{label:"Sekvens",value:"Glu-Asp-Arg (EDR)"},{label:"Klassificering",value:"Syntetisk hjärntripeptidbioregulator"},{label:"Utseende",value:"Vitt lyofiliserat pulver"},{label:"Löslighet",value:"Löslig i bakteriostatiskt vatten"}],researchApplications:[{title:"Neuroprotektionsmodeller",description:"Används i forskning om ROS-ackumulering och cellviabilitet i neuron- och PC12-kulturer."},{title:"Kognitivt åldrande",description:"Studeras i gnagarmodeller för spatial inlärning och neuronala markörer för oxidativ stress."},{title:"Neurodegenerationsforskning",description:"Utforskas i neuronkulturer som modellerar Alzheimer- och Huntingtonpatologi."},{title:"Signalvägar",description:"Tillämpas för att undersöka uttrycket av MAPK/ERK, kaspas-3 och antioxidantenzymer."}],keyStudies:[{title:"Pinealon ökar cellviabiliteten genom att dämpa nivåerna av fria radikaler och aktivera proliferativa processer",source:"Rejuvenation Research",year:2011,url:"https://pubmed.ncbi.nlm.nih.gov/21978084/",finding:"Rapporterade att Pinealon dosberoende begränsade ROS-ackumulering och nekrotisk död i cerebellära granulceller, neutrofiler och PC12-celler under oxidativ stress, med fördröjd ERK1/2-aktivering."},{title:"Pinealon skyddar råttavkomma mot prenatal hyperhomocysteinemi",source:"International Journal of Clinical and Experimental Medicine",year:2012,url:"https://pubmed.ncbi.nlm.nih.gov/22567179/",finding:"Rapporterade att Pinealon givet till metioninbelastade dräktiga råttor förbättrade avkommans spatiala orientering och inlärning samt minskade ROS och nekros i avkommans cerebellära neuron."},{title:"EDR-peptid: möjlig mekanism för reglering av genuttryck och proteinsyntes involverad i patogenesen vid Alzheimers sjukdom",source:"Molecules",year:2020,url:"https://pubmed.ncbi.nlm.nih.gov/33396470/",finding:"Granskade rapporter om att EDR minskar neuronal apoptos och bevarar dendritiska taggar i neurodegenerationskulturer, och föreslog histon- och RNA-bindning som påverkar MAPK/ERK, kaspas-3, p53, SOD2 och GPX1."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C.",howSupplied:"Levereras som en enda försluten flaska med vitt lyofiliserat Pinealon-pulver. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg."},thymalin:{name:"Thymalin",description:"Tymuspolypeptidkomplex levererat som en lyofiliserad referensstandard för forskning om T-cellsdifferentiering, immunsenescens och hematopoetiska stamceller.",longDescription:"Thymalin är ett polypeptidkomplex som ursprungligen isolerades från kalvtymus genom mild syraextraktion, utvecklat av Morozov och Khavinson. Dess karakteriserade aktiva komponenter inkluderar dipeptiderna Lys-Glu (KE) och Glu-Trp (EW). Det har studerats i humana hematopoetiska stamcellskulturer för markörer för T-cellsdifferentiering, i modeller av immunsenescens samt i långsiktig observationsforskning om immunfunktion hos äldre vuxna. Det levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Forskning om T-cellsdifferentiering","Modeller av immunsenescens och tymusåldrande","Studier av hematopoetiska stamceller","Forskning om markörerna CD28, CD44 och CD117","Studier av tymisk peptidbioregulation"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. Thymalin levereras som ett lyofiliserat pulver. Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vad är Thymalin?",answer:"Thymalin är ett polypeptidkomplex isolerat från kalvtymus, utvecklat av Morozov och Khavinson. Dess karakteriserade aktiva komponenter inkluderar dipeptiderna Lys-Glu och Glu-Trp. Det studeras i modeller av T-cellsdifferentiering, immunsenescens och hematopoetiska stamceller."},{question:"Är Thymalin samma sak som tymulin?",answer:"Nej. Tymulin är ett definierat zinkberoende nonapeptidhormon, medan Thymalin är ett tymusextrakt med flera peptider. De är olika material som bara delar ett liknande namn."},{question:"Vilken renhet har Thymalin från Miro Biotech?",answer:"Varje batch testas av ett oberoende tredjepartslabb och verifieras till 99,1 % peptidinnehåll, med ett analyscertifikat för batchen."},{question:"Hur ska Thymalin förvaras?",answer:"Förvara det lyofiliserade pulvret vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["immun","tymus","T-cell","bioregulator","livslängd","forskningspeptid"],aka:["Tymuspolypeptidkomplex","Thymalinum","KE- och EW-dipeptidkomplex"],whatIs:"Thymalin är ett polypeptidkomplex isolerat från kalvtymus, vars karakteriserade aktiva komponenter inkluderar dipeptiderna Lys-Glu och Glu-Trp. Det används som forskningssubstans i studier av T-cellsdifferentiering, markörer på hematopoetiska stamceller och immunsenescens. Levereras endast för in-vitro- och laboratorieforskning.",mechanism:"I publicerad forskning rapporterades Thymalin minska uttrycket av CD44 och CD117 två- till trefaldigt och öka uttrycket av CD28 6,8-faldigt i humana hematopoetiska stamcellskulturer, vilket författarna tolkade som stimulering av differentiering mot mogna CD28-positiva T-celler. Dess dipeptidkomponenter KE och EW studerades genom molekylär dockning till dubbelsträngat DNA och genom bioinformatisk analys av genuttryck. En 6-8 år lång observationsstudie av äldre vuxna som fått Thymalin rapporterade lägre incidens av luftvägsinfektioner. Dessa fynd kommer från cellkultur- och observationsforskning; en definierad molekylär mekanism har inte fastställts.",receptorTargets:["Kostimulerande T-cellsmarkören CD28","Stamcellsmarkörerna CD44 och CD117","T-lymfocytdifferentiering","DNA-bindning av dipeptiderna KE och EW (föreslagen)"],specs:[{label:"Sammansättning",value:"Tymuspolypeptidkomplex (kalvtymusextrakt)"},{label:"Karakteriserade komponenter",value:"Dipeptiderna Lys-Glu (KE) och Glu-Trp (EW)"},{label:"Utseende",value:"Vitt till benvitt lyofiliserat pulver"},{label:"Löslighet",value:"Löslig i bakteriostatiskt vatten"}],researchApplications:[{title:"T-cellsdifferentiering",description:"Används i forskning om markörerna CD28, CD44 och CD117 i humana hematopoetiska stamcellskulturer."},{title:"Immunsenescens",description:"Studeras i modeller av åldersrelaterad nedgång i tymus- och T-lymfocytfunktion."},{title:"Tymisk peptidbiologi",description:"Tillämpas för att jämföra extraktet med dess karakteriserade dipeptidkomponenter KE och EW."},{title:"Genuttrycksbioinformatik",description:"Utforskas genom molekylär dockning och uttrycksanalys av immunrelaterade gener."}],keyStudies:[{title:"Thymalin: aktivering av differentiering av humana hematopoetiska stamceller",source:"Bulletin of Experimental Biology and Medicine",year:2020,url:"https://pubmed.ncbi.nlm.nih.gov/33237528/",finding:"Rapporterade att Thymalin, ett polypeptidkomplex isolerat från tymus, minskade uttrycket av CD44 och CD117 och ökade uttrycket av CD28 6,8-faldigt i humana hematopoetiska stamcellskulturer."},{title:"Inverkan av dipeptiderna KE och EW i sammansättningen av preparatet Thymalin på genuttryck och proteinsyntes",source:"International Journal of Molecular Sciences",year:2023,url:"https://pubmed.ncbi.nlm.nih.gov/37686182/",finding:"Beskrev Thymalin som ett polypeptidextrakt från tymus vars aktiva substanser KE och EW studerades genom molekylär dockning till dubbelsträngat DNA och genom bioinformatisk analys av genuttryck."},{title:"Peptider från tallkottkörteln och tymus förlänger människans liv",source:"Neuro Endocrinology Letters",year:2003,url:"https://pubmed.ncbi.nlm.nih.gov/14523363/",finding:"Rapporterade en 6-8 år lång observationsuppföljning av 266 äldre vuxna som fått Thymalin och/eller Epithalamin, med lägre incidens av akut luftvägssjukdom i de behandlade grupperna än hos kontrollerna."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C.",howSupplied:"Levereras som en enda försluten flaska med vitt till benvitt lyofiliserat Thymalin-pulver. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg."},"pt-141":{name:"PT-141",description:"Cyklisk melanokortinheptapeptid (bremelanotid), en MC3R/MC4R-agonist levererad som en lyofiliserad referensstandard för forskning om melanokortinreceptorfarmakologi och signalvägar i centrala nervsystemet.",longDescription:"PT-141 (bremelanotid) är en cyklisk heptapeptidanalog till alfa-melanocytstimulerande hormon, Ac-Nle-cyclo[Asp-His-D-Phe-Arg-Trp-Lys]-OH, som verkar som agonist vid melanokortinreceptorerna MC3R och MC4R. Den har studerats i receptorbindningsstudier och beteendemodeller på gnagare av central melanokortinsignalering, och den publicerade kliniska litteraturen omfattar fas 2- och fas 3-studier av en subkutan formulering. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Forskning om melanokortinreceptorerna MC3R/MC4R","Studier av signalvägar i centrala nervsystemet","Farmakologi för alfa-MSH-analoger","Receptorbindnings- och signaleringsanalyser","Forskningsmodeller av hypotalamiska kretsar"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. PT-141 levereras som ett lyofiliserat pulver. Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vad är PT-141?",answer:"PT-141 (bremelanotid) är en cyklisk heptapeptidanalog till alfa-MSH som verkar som agonist vid melanokortinreceptorerna MC3R och MC4R. Den studeras inom receptorfarmakologi och forskning om signalvägar i centrala nervsystemet."},{question:"Vad är molekylvikt och formel för PT-141?",answer:"PT-141 har molekylformeln C50H68N14O10 och en molekylvikt på cirka 1025,2 g/mol (PubChem CID 9941379, CAS 189691-06-3). Dess sekvens är Ac-Nle-cyclo[Asp-His-D-Phe-Arg-Trp-Lys]-OH."},{question:"Hur skiljer sig PT-141 från MT-2?",answer:"Båda är syntetiska alfa-MSH-analoger. MT-2 (Melanotan II) är en cyklisk icke-selektiv melanokortinagonist som studeras för melanogenes, medan PT-141 är dess karboxylatmetabolitanalog och studeras för MC3R- och MC4R-signalering i centrala nervsystemet."},{question:"Vilken renhet har PT-141 från Miro Biotech?",answer:"Varje batch testas av ett oberoende tredjepartslabb och verifieras till 99,44 % renhet, med ett analyscertifikat för batchen."},{question:"Hur ska PT-141 förvaras?",answer:"Förvara det lyofiliserade pulvret vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["melanokortin","MC4R","alfa-MSH","neurovetenskap","heptapeptid","forskningspeptid"],aka:["Bremelanotid","PT141","Vyleesi (godkänd formulering)"],whatIs:"PT-141 (bremelanotid) är en cyklisk heptapeptidanalog till alfa-MSH som verkar som agonist vid melanokortinreceptorerna MC3R och MC4R. Den används som forskningssubstans i studier av melanokortinreceptorfarmakologi och signalvägar i centrala nervsystemet. Levereras endast för in-vitro- och laboratorieforskning.",mechanism:"I publicerad forskning karakteriserades PT-141 som en melanokortinagonist med hög affinitet för MC4R och aktivitet vid MC3R. Prekliniskt arbete i honråttmodeller rapporterade att dess beteendeeffekter förmedlades centralt, där platsspecifik administrering i hjärnan och mikrodialys pekade mot hypotalamiska melanokortinkretsar snarare än perifera vaskulära effekter. Tidiga humana farmakokinetiska studier av intranasal och subkutan administrering rapporterade en halveringstid på ungefär två timmar, och senare fas 2- och fas 3-program utvärderade en subkutan formulering. Dessa fynd beskriver den publicerade litteraturen; substansen levereras här uteslutande som en referensstandard för forskning.",receptorTargets:["Melanokortinreceptor 4 (MC4R)","Melanokortinreceptor 3 (MC3R)","Hypotalamiska melanokortinkretsar","Alfa-MSH-signalering"],specs:[{label:"Sekvens",value:"Ac-Nle-cyclo[Asp-His-D-Phe-Arg-Trp-Lys]-OH"},{label:"Klassificering",value:"Cyklisk heptapeptidanalog till alfa-MSH, MC3R/MC4R-agonist"},{label:"Utseende",value:"Vitt lyofiliserat pulver"},{label:"Löslighet",value:"Löslig i bakteriostatiskt vatten"}],researchApplications:[{title:"Melanokortinreceptorfarmakologi",description:"Används i bindnings- och signaleringsanalyser som karakteriserar agonism vid MC3R och MC4R."},{title:"Signalvägar i centrala nervsystemet",description:"Studeras i gnagarmodeller av hypotalamisk melanokortinsignalering."},{title:"Jämförelse av alfa-MSH-analoger",description:"Utforskas jämsides med MT-2 och andra analoger för att jämföra receptorselektivitet."},{title:"Farmakokinetisk forskning",description:"Tillämpas i publicerade studier av intranasala och subkutana administreringsvägar."}],keyStudies:[{title:"Bremelanotid: en översikt av prekliniska CNS-effekter på kvinnlig sexuell funktion",source:"Journal of Sexual Medicine",year:2007,url:"https://pubmed.ncbi.nlm.nih.gov/17958619/",finding:"Granskade prekliniskt arbete i honråttmodeller som rapporterade att bremelanotid verkade via centrala melanokortinvägar, med platsspecifik administrering i hjärnan och mikrodialys för att lokalisera effekten."},{title:"Dubbelblind, placebokontrollerad utvärdering av säkerhet, farmakokinetiska egenskaper och farmakodynamiska effekter av intranasalt PT-141, en melanokortinreceptoragonist",source:"International Journal of Impotence Research",year:2004,url:"https://pubmed.ncbi.nlm.nih.gov/14963471/",finding:"Rapporterade farmakokinetiska data och säkerhetsdata för intranasalt PT-141 hos friska män och patienter, och beskrev substansen som en cyklisk heptapeptid-melanokortinanalog med en halveringstid på ungefär två timmar."},{title:"Bremelanotid för behandling av hypoaktiv sexuell luststörning: två randomiserade fas 3-studier",source:"Obstetrics and Gynecology",year:2019,url:"https://pubmed.ncbi.nlm.nih.gov/31599840/",finding:"Rapporterade två 24 veckor långa randomiserade, placebokontrollerade fas 3-studier (RECONNECT) av en subkutan bremelanotidformulering hos premenopausala kvinnor, där illamående, rodnad och huvudvärk var de oftast rapporterade biverkningarna."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C.",howSupplied:"Levereras som en enda försluten flaska med vitt lyofiliserat PT-141-pulver. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg."},cagrilintide:{name:"Cagrilintide",description:"Långverkande lipiderad amylinanalog (AM833, NNC0174-0833) levererad som en lyofiliserad referensstandard för forskning om amylin- och kalcitoninreceptorfarmakologi samt energiintag. Finns i 5mg- och 10mg-flaskor.",longDescription:"Cagrilintide är en amylinanalog med 37 aminosyrarester, acylerad med en C20-fettdisyra, utvecklad av Novo Nordisk som en amylinreceptoragonist för administrering en gång i veckan och studerad som amylinkomponenten i kombinationen cagrilintide plus semaglutid (CagriSema). Den har karakteriserats som en icke-selektiv agonist vid amylin- och kalcitoninreceptorer och utvärderats i fas 1-, fas 2- och fas 3-forskning om viktkontroll. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Forskning om amylinreceptorfarmakologi","Studier av kalcitoninreceptoragonism","Modeller av energiintag och mättnadssignalvägar","Forskning om långverkande lipiderade peptider","Kombinationsstudier av amylin och GLP-1"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. Cagrilintide levereras som ett lyofiliserat pulver. Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vad är Cagrilintide?",answer:"Cagrilintide (AM833, NNC0174-0833) är en långverkande lipiderad analog till bukspottkörtelhormonet amylin. Den studeras som en icke-selektiv amylin- och kalcitoninreceptoragonist i forskning om energiintag och kroppsvikt."},{question:"Är Cagrilintide samma sak som CagriSema?",answer:"Nej. CagriSema är kombinationen i fast dos av cagrilintide och GLP-1-receptoragonisten semaglutid som studerats i REDEFINE-studierna. Denna produkt är enbart cagrilintide, levererad som en referensstandard för forskning."},{question:"Vad är molekylvikt och formel för Cagrilintide?",answer:"Cagrilintide har molekylformeln C194H312N54O59S2 och en molekylvikt på cirka 4409 g/mol (PubChem CID 171397054, CAS 1415456-99-3). Det är en amiderad peptid med 37 aminosyrarester, en Cys2-Cys7-disulfidbrygga och en C20-fettdisyra kopplad via en gamma-glutamylspacer."},{question:"Vilken renhet har Cagrilintide från Miro Biotech?",answer:"Varje batch testas av ett oberoende tredjepartslabb och verifieras till 99,31 % renhet, med ett analyscertifikat för batchen."},{question:"Hur ska Cagrilintide förvaras?",answer:"Förvara det lyofiliserade pulvret vid -20 °C för långtidsförvaring. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["amylin","metabol","viktkontroll","kalcitoninreceptor","långverkande","forskningspeptid"],aka:["AM833","NNC0174-0833","Cagrilintide amylinanalog"],whatIs:"Cagrilintide är en långverkande lipiderad amylinanalog som verkar som en icke-selektiv agonist vid amylin- och kalcitoninreceptorer. Den används som forskningssubstans i studier av mättnadssignalering, energiintag och kombinationsfarmakologi för amylin plus GLP-1. Levereras endast för in-vitro- och laboratorieforskning.",mechanism:"I publicerad forskning karakteriserades cagrilintide som en icke-selektiv agonist vid amylinreceptorerna (kalcitoninreceptorn tillsammans med receptoraktivitetsmodifierande proteiner) och vid själva kalcitoninreceptorn, jämförd med selektiva och icke-selektiva referensagonister. Dess C20-fettdisyraacylering stödjer albuminbindning och en halveringstid på ungefär 159-195 timmar som rapporterades i en fas 1b-studie. En 26 veckor lång dosfinnande fas 2-studie rapporterade genomsnittliga minskningar av kroppsvikten på 6,0-10,8 % över doserna en gång i veckan jämfört med 3,0 % med placebo, och fas 3-studien REDEFINE 1 av kombinationen cagrilintide plus semaglutid rapporterade en uppskattad genomsnittlig förändring på -20,4 % jämfört med -3,0 % för placebo vid 68 veckor. Dessa fynd beskriver den publicerade kliniska litteraturen; substansen levereras här uteslutande som en referensstandard för forskning.",receptorTargets:["Amylinreceptorer (CTR + RAMP1/2/3)","Kalcitoninreceptorn (CTR)","Mättnadskretsar i bakhjärnan och hypotalamus","Interaktion mellan amylin- och GLP-1-signalvägarna"],specs:[{label:"Sekvens",value:"KCNTATCATQRLAEFLRHSSNNFGPILPPTNVGSNTP-NH2, Cys2-Cys7-disulfidbrygga"},{label:"Klassificering",value:"Lipiderad långverkande amylinanalog (C20-fettdisyra via gamma-Glu-spacer)"},{label:"Utseende",value:"Vitt lyofiliserat pulver"},{label:"Löslighet",value:"Löslig i bakteriostatiskt vatten"}],researchApplications:[{title:"Amylinreceptorfarmakologi",description:"Används i receptorsignaleringsanalyser som jämför amylin- och kalcitoninreceptoragonister."},{title:"Modeller av energiintag",description:"Studeras i forskning om mättnad och födointag i gnagar- och humanmodeller."},{title:"Kombinationsfarmakologi",description:"Utforskas jämsides med GLP-1-receptoragonister i forskning om kroppsvikt via två signalvägar."},{title:"Design av långverkande peptider",description:"Tillämpas i studier av fettdisyraacylering, albuminbindning och förlängd halveringstid."}],keyStudies:[{title:"Cagrilintide en gång i veckan för viktkontroll hos personer med övervikt och fetma: en dosfinnande fas 2-studie",source:"The Lancet",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/34798060/",finding:"Rapporterade en 26 veckor lång fas 2-studie med 706 vuxna där cagrilintide 0,3-4,5 mg en gång i veckan gav genomsnittliga minskningar av kroppsvikten på 6,0-10,8 % jämfört med 3,0 % med placebo, med gastrointestinala händelser och reaktioner vid injektionsstället som de vanligaste biverkningarna."},{title:"Säkerhet, tolerabilitet, farmakokinetik och farmakodynamik vid samtidig administrering av flera doser cagrilintide med semaglutid 2,4 mg: en fas 1b-studie",source:"The Lancet",year:2021,url:"https://pubmed.ncbi.nlm.nih.gov/33894838/",finding:"Rapporterade en 20 veckor lång fas 1b-studie där cagrilintide uppvisade en halveringstid på 159-195 timmar och dosproportionell exponering som inte påverkade exponeringen för semaglutid, med större minskningar av kroppsvikten vid 1,2 och 2,4 mg än med placebo."},{title:"Samadministrerat cagrilintide och semaglutid hos vuxna med övervikt eller fetma",source:"New England Journal of Medicine",year:2025,url:"https://pubmed.ncbi.nlm.nih.gov/40544433/",finding:"Rapporterade den 68 veckor långa fas 3a-studien REDEFINE 1 med 3 417 vuxna, med en uppskattad genomsnittlig förändring av kroppsvikten på -20,4 % för cagrilintide 2,4 mg plus semaglutid 2,4 mg jämfört med -3,0 % för placebo."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C.",howSupplied:"Levereras som en enda försluten flaska med vitt lyofiliserat Cagrilintide-pulver i vald storlek. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg."},dsip:{name:"DSIP",description:"Delta sleep-inducing peptide (emideltid), en syntetisk nonapeptid levererad som en lyofiliserad referensstandard för forskning om sömn-EEG, neuroendokrina signalvägar och stressrespons. Finns i 2mg-, 5mg- och 10mg-flaskor.",longDescription:"DSIP (Trp-Ala-Gly-Gly-Asp-Ala-Ser-Gly-Glu) isolerades på 1970-talet från cerebralt venblod hos kaniner under inducerad sömn och fick sitt namn efter den ökning av delta-EEG-aktivitet som den syntetiska peptiden gav efter central infusion. Den undersöktes senare i små tidiga humanstudier av sömn och i gnagarstudier av hypotalamus-hypofysaxeln och stressresponsen, med blandade resultat, och dess endogena prekursor och receptor har aldrig identifierats. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Forskning om sömn-EEG och deltaaktivitet","Studier av neuroendokrina signalvägar och ACTH","Stressresponsmodeller hos gnagare","Klassisk referensstandard bland neuropeptider","Forskning om nonapeptiders stabilitet och analoger"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. DSIP levereras som ett lyofiliserat pulver. Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vad är DSIP?",answer:"DSIP (delta sleep-inducing peptide, INN emideltid) är en peptid med nio aminosyrarester som först karakteriserades 1977 från cerebralt venblod hos kaniner. Den studeras som en referensneuropeptid i forskning om sömn-EEG, neuroendokrina signalvägar och stressrespons."},{question:"Har DSIP studerats på människor?",answer:"Endast i små tidiga studier från 1980- och 1990-talen, samtliga med intravenös administrering i forskningsmiljö. Resultaten var blandade: en studie från 1981 på sex frivilliga rapporterade längre sömn, medan en dubbelblind studie från 1992 på sexton patienter med insomni drog slutsatsen att effekterna var svaga. Den levereras här uteslutande som en referensstandard för forskning."},{question:"Vad är sekvens och molekylvikt för DSIP?",answer:"DSIP har sekvensen Trp-Ala-Gly-Gly-Asp-Ala-Ser-Gly-Glu (WAGGDASGE), molekylformeln C35H48N10O15 och en molekylvikt på cirka 848,8 g/mol som fri peptid (PubChem CID 68816, CAS 62568-57-4)."},{question:"Vilken renhet har DSIP från Miro Biotech?",answer:"Varje batch testas av ett oberoende tredjepartslabb och verifieras till 99,24 % renhet, med ett analyscertifikat för batchen."},{question:"Hur ska DSIP förvaras?",answer:"Förvara det lyofiliserade pulvret vid -20 °C för långtidsförvaring, skyddat från ljus och fukt. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar; undvik upprepad frysning och upptining."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["sömn","neuropeptid","EEG","neuroendokrin","stressrespons","forskningspeptid"],aka:["Emideltid","Deltasömninducerande peptid","WAGGDASGE"],whatIs:"DSIP är en syntetisk nonapeptid som fått sitt namn efter den ökning av deltavågsaktivitet i EEG som den gav hos kaniner efter central infusion. Den används som forskningssubstans i studier av sömnreglering, ACTH- och hypofyssignalering samt stressresponsvägar. Levereras endast för in-vitro- och laboratorieforskning.",mechanism:"I publicerad forskning förstärkte syntetisk DSIP delta- och spindelaktiviteten i EEG efter intraventrikulär infusion hos kaniner i dubbelblinda experiment, en effekt som fragment och analoger inte återgav. Små tidiga humanstudier gav blandade resultat: en överkorsningsstudie från 1981 på sex frivilliga rapporterade en medianökning av den totala sömntiden med 59 % utan klassisk sedering, medan en dubbelblind studie från 1992 på sexton patienter med kronisk insomni endast fann svaga effekter på sömneffektivitet och insomningslatens. Endokrina data är motstridiga: en studie på åtta män rapporterade lägre ACTH i plasma, medan en annan inte fann någon förändring av CRH- eller måltidsstimulerat ACTH och kortisol. En översikt från 2006 konstaterade att ingen DSIP-gen, inget prekursorprotein och ingen receptor har identifierats, så mekanismen förblir odefinierad. Dessa fynd beskriver den publicerade litteraturen; substansen levereras här uteslutande som en referensstandard för forskning.",receptorTargets:["Delta-EEG-aktivitet (sömnreglerande kretsar, odefinierad mekanism)","Hypotalamus-hypofysaxeln (ACTH, motstridiga fynd)","Stressresponsvägar i gnagarmodeller","Ingen identifierad receptor eller prekursorgen"],specs:[{label:"Sekvens",value:"Trp-Ala-Gly-Gly-Asp-Ala-Ser-Gly-Glu (WAGGDASGE)"},{label:"Klassificering",value:"Syntetisk nonapeptid, sömnassocierad neuropeptid som referensstandard"},{label:"Utseende",value:"Vitt lyofiliserat pulver"},{label:"Löslighet",value:"Löslig i vatten och bakteriostatiskt vatten (cirka 10 mg/mL i neutral buffert)"}],researchApplications:[{title:"Forskning om sömn-EEG",description:"Används som referenspeptid i studier av deltavågs- och spindelaktivitet i kanin- och råttmodeller."},{title:"Neuroendokrin signalering",description:"Studeras för effekter på ACTH, kortisol och andra hypofyshormoner i små human- och gnagarstudier."},{title:"Stressresponsmodeller",description:"Utforskas som en stressbegränsande faktor i gnagarmodeller av emotionell och fysisk stress."},{title:"Peptidkemi",description:"Tillämpas i studier av analoger, fosforylering och Asp-Gly-isomerisering som rör korta peptiders stabilitet."}],keyStudies:[{title:"Karakterisering av en delta-EEG(-sömn)-inducerande peptid",source:"Proceedings of the National Academy of Sciences",year:1977,url:"https://pubmed.ncbi.nlm.nih.gov/265572/",finding:"Isolerade nonapeptiden från cerebralt venblod hos kaniner, fastställde dess sekvens och visade i dubbelblinda experiment på 58 kaniner att endast den syntetiska fullängdspeptiden, inte dess fragment eller analoger, förstärkte delta- och spindelaktiviteten i EEG efter intraventrikulär infusion."},{title:"Akuta och fördröjda effekter av DSIP (delta sleep-inducing peptide) på människans sömnbeteende",source:"International Journal of Clinical Pharmacology, Therapy, and Toxicology",year:1981,url:"https://pubmed.ncbi.nlm.nih.gov/6895513/",finding:"Rapporterade en dubbelblind överkorsningsstudie på sex friska frivilliga där en enda intravenös infusion ökade medianen för total sömntid med 59 % inom cirka två timmar och förbättrade sömneffektiviteten följande natt, utan sedering i klassisk farmakologisk mening."},{title:"Effekter av delta sleep-inducing peptide på sömnen hos patienter med kronisk insomni. En dubbelblind studie",source:"Neuropsychobiology",year:1992,url:"https://pubmed.ncbi.nlm.nih.gov/1299794/",finding:"Rapporterade en dubbelblind studie på sexton patienter med kronisk insomni där tre intravenösa infusioner gav högre sömneffektivitet och kortare insomningslatens än placebo, men författarna bedömde effekterna som svaga och delvis hänförliga till en förändring i placebogruppen."},{title:"Delta sleep-inducing peptide (DSIP): en ännu olöst gåta",source:"Journal of Neurochemistry",year:2006,url:"https://pubmed.ncbi.nlm.nih.gov/16539679/",finding:"Gick igenom tre decennier av DSIP-forskning och drog slutsatsen att peptidens gen, prekursorprotein och receptor aldrig har identifierats, och att evidensen för DSIP som en endogen sömnfaktor förblir svag."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C och undvik upprepad frysning och upptining.",howSupplied:"Levereras som en enda försluten flaska med vitt lyofiliserat DSIP-pulver i vald storlek. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg."},"5-amino-1mq":{name:"5-Amino-1MQ",description:"Småmolekylär NNMT-hämmare (5-amino-1-metylkinoliniumjodid) levererad som en referensstandard i form av torrt pulver för forskning om adipocytmetabolism, NAD+-återvinning och muskelåldrande i cell- och musmodeller. Finns i 5mg-, 10mg- och 50mg-flaskor.",longDescription:"5-Amino-1MQ är ett membranpermeabelt kinoliniumsalt som hämmar nikotinamid-N-metyltransferas (NNMT), enzymet som metylerar nikotinamid och förbrukar S-adenosylmetionin. Substansen kom fram ur en struktur-aktivitetsstudie av NNMT-hämmare från 2017 och har sedan undersökts i odlade adipocyter samt hos möss med dietinducerad fetma och hos åldrade möss, där NNMT-hämning var associerad med lägre fettmassa, förbättrad glukoshantering och aktivering av muskelstamceller. Det är en liten molekyl och inte en peptid, och det finns inga publicerade humanstudier. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Forskning om hämning av enzymet NNMT","Modeller av adipocytlipogenes och fettmassa","Studier av NAD+- och SAM-metabolism","Forskning om åldrande muskelstamceller","Musmodeller av dietinducerad fetma"],researchGuide:"Rekonstituera med sterilt eller bakteriostatiskt vatten till önskad koncentration. 5-Amino-1MQ levereras som ett torrt, vattenlösligt pulver som är hygroskopiskt. Förvara den förslutna flaskan vid -20 °C, skyddad från ljus och fukt, och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vad är 5-Amino-1MQ?",answer:"5-Amino-1MQ (5-amino-1-metylkinolinium) är en småmolekylär hämmare av nikotinamid-N-metyltransferas (NNMT), ett enzym som är förhöjt i fettväven hos feta möss. Den studeras inom forskning om adipocytmetabolism, NAD+-återvinning och muskelåldrande."},{question:"Är 5-Amino-1MQ en peptid?",answer:"Nej. Det är en liten kinoliniummolekyl (C10H11IN2 som jodidsalt, molekylvikt cirka 286,1 g/mol). Den listas tillsammans med våra metabola forskningspeptider eftersom den studeras i samma modeller av energibalans och fettväv, men det är en annan klass av substans."},{question:"Vad har 5-Amino-1MQ studerats för?",answer:"Publicerat arbete finns endast i celler och möss. Hos möss med dietinducerad fetma var NNMT-hämning med denna substans associerad med lägre fettmassa och mindre adipocyter utan förändrat födointag, samt med förbättrad glukostolerans. Hos åldrade möss var den associerad med aktivering av muskelstamceller och bättre regeneration efter skada. Det finns inga publicerade humanstudier."},{question:"Vilken renhet har 5-Amino-1MQ från Miro Biotech?",answer:"Varje batch testas av ett oberoende tredjepartslabb och verifieras till 99,47 % renhet, med ett analyscertifikat för batchen."},{question:"Hur ska 5-Amino-1MQ förvaras?",answer:"Förvara den förslutna flaskan vid -20 °C, skyddad från ljus och fukt, eftersom det fasta ämnet är hygroskopiskt. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["NNMT","metabol","adipocyt","NAD+","liten molekyl","muskelåldrande"],aka:["5-amino-1-metylkinolinium","NNMTi","5A1MQ"],whatIs:"5-Amino-1MQ är en vattenlöslig, membranpermeabel liten molekyl som hämmar nikotinamid-N-metyltransferas (NNMT). Den används som forskningssubstans i studier av adipocytlipogenes, NAD+- och S-adenosylmetioninmetabolism samt åldrande muskelstamceller i cellkultur och musmodeller. Levereras endast för in-vitro- och laboratorieforskning.",mechanism:"I publicerad forskning hämmade 5-Amino-1MQ NNMT med ett IC50 i det låga mikromolära området genom att binda till nikotinamidsubstratets bindningsställe, och var selektiv gentemot besläktade metyltransferaser och enzymer i NAD+-återvinningen. I odlade 3T3-L1-adipocyter minskade den lipogenesen och förändrade nivåerna av 1-metylnikotinamid och NAD+. Hos möss med dietinducerad fetma var subkutan behandling i elva dagar associerad med cirka 35 % lägre epididymal fettmassa, mer än 30 % mindre adipocyter och omkring 30 % lägre totalkolesterol utan förändrat födointag, och en 28-dagarsstudie rapporterade en dosberoende begränsning av viktökningen med bättre glukostolerans och mindre leversteatos. Hos åldrade möss aktiverade NNMT-hämning senescenta muskelstamceller och förbättrade regenerationen efter skada. Dessa fynd beskriver den publicerade cell- och muslitteraturen; det finns inga publicerade humanstudier, och substansen levereras här uteslutande som en referensstandard för forskning.",receptorTargets:["Nikotinamid-N-metyltransferas (NNMT)","Metabolism av nikotinamid, SAM och 1-metylnikotinamid","Signalvägar för adipocytlipogenes","Aktivering av muskelstamceller (åldrade musmodeller)"],specs:[{label:"Struktur",value:"5-amino-1-metylkinoliniumjodid, C10H11IN2 (CAS 42464-96-0)"},{label:"Klassificering",value:"Småmolekylär NNMT-hämmare (kinoliniumsalt), inte en peptid"},{label:"Utseende",value:"Torrt pulver, hygroskopiskt"},{label:"Löslighet",value:"Löslig i vatten och bakteriostatiskt vatten"}],researchApplications:[{title:"NNMT-hämningsanalyser",description:"Används som referenshämmare i enzymkinetiska analyser och selektivitetsanalyser mot besläktade metyltransferaser."},{title:"Adipocytmetabolism",description:"Studeras i odlade 3T3-L1-adipocyter för effekter på lipogenes och nivåer av NAD+-relaterade metaboliter."},{title:"Modeller av dietinducerad fetma",description:"Utforskas i musmodeller med fettrik kost för förändringar i fettmassa, glukostolerans och leverfett."},{title:"Forskning om muskelåldrande",description:"Tillämpas i studier på åldrade möss av muskelstamcellers aktivering, regeneration och träningsrespons."}],keyStudies:[{title:"Selektiva och membranpermeabla småmolekylära hämmare av nikotinamid-N-metyltransferas reverserar fetma inducerad av fettrik kost hos möss",source:"Biochemical Pharmacology",year:2018,url:"https://pubmed.ncbi.nlm.nih.gov/29155147/",finding:"Rapporterade att 5-Amino-1MQ minskade lipogenesen i odlade adipocyter och att den hos möss med dietinducerad fetma som behandlades subkutant i elva dagar var associerad med cirka 35 % lägre epididymal fettmassa, över 30 % mindre adipocyter och omkring 30 % lägre kolesterol med oförändrat födointag."},{title:"Hämning av nikotinamid-N-metyltransferas mildrar fetmarelaterad metabol dysfunktion",source:"Diabetes, Obesity and Metabolism",year:2024,url:"https://pubmed.ncbi.nlm.nih.gov/39161060/",finding:"Rapporterade en 28-dagarsstudie på möss med dietinducerad fetma där daglig behandling begränsade vikt- och fettökningen på ett dosberoende sätt, förbättrade glukostolerans och insulinkänslighet samt minskade leversteatos, med distribution till fett-, muskel- och levervävnad."},{title:"Småmolekylär hämmare av nikotinamid-N-metyltransferas aktiverar senescenta muskelstamceller och förbättrar regenerationsförmågan i åldrad skelettmuskulatur",source:"Biochemical Pharmacology",year:2019,url:"https://pubmed.ncbi.nlm.nih.gov/30753815/",finding:"Rapporterade att NNMT-hämning hos 24 månader gamla möss som behandlades efter muskelskada ökade aktiveringen av muskelstamceller och förbättrade regenerationen av den skadade muskeln jämfört med vehikel."},{title:"Struktur-aktivitetssamband för småmolekylära hämmare av nikotinamid-N-metyltransferas",source:"Journal of Medicinal Chemistry",year:2017,url:"https://pubmed.ncbi.nlm.nih.gov/28548833/",finding:"Beskrev den kinoliniumserie ur vilken 5-Amino-1MQ valdes, med rapporterad NNMT-hämning i det låga mikromolära området genom bindning vid nikotinamidsubstratets bindningsställe."}],reconstitution:"Rekonstitueras vanligen med sterilt eller bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt tills pulvret har lösts upp. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det torra pulvret förslutet vid -20 °C, skyddat från ljus och fukt; det fasta ämnet är hygroskopiskt. Efter rekonstituering, håll kylt vid 2-8 °C.",howSupplied:"Levereras som en enda försluten flaska med torrt 5-Amino-1MQ-pulver i vald storlek. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg."},"aod-9604":{name:"AOD-9604",description:"Syntetiskt C-terminalt fragment av humant tillväxthormon (hGH 177-191, hexadekapeptid) levererat som en lyofiliserad referensstandard för forskning om lipolys i fettväv, fettoxidation och energibalans. Finns i 2mg-, 5mg- och 10mg-flaskor.",longDescription:"AOD-9604 är en peptid med 16 aminosyrarester som motsvarar den C-terminala lipolytiska domänen av humant tillväxthormon (resterna 177-191) med ett tillagt N-terminalt tyrosin, utvecklad av Metabolic Pharmaceuticals för att behålla hGH:s lipolytiska aktivitet utan dess tillväxtfrämjande signalering. Hos feta Zucker-råttor och ob/ob-möss var den associerad med lägre viktökning och högre fettoxidation utan den hyperglykemi som ses med intakt hGH, och den binder inte till hGH-receptorn in vitro. Sex placebokontrollerade studier på människor fastställde dess säkerhetsprofil, medan den 24 veckor långa fas 2b-studien på fetma inte visade någon signifikant viktminskning och den kliniska utvecklingen avbröts 2007. Den levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning.",benefits:["Forskning om lipolys i fettväv i gnagarmodeller","Studier av fettoxidation och energiförbrukning","Struktur-aktivitetsforskning på hGH-fragment","Modeller av uttryck av beta-3-adrenerga receptorer","Metodutveckling för antidopningsdetektion"],researchGuide:"Rekonstituera med bakteriostatiskt vatten till önskad koncentration. AOD-9604 levereras som ett lyofiliserat pulver. Förvara det lyofiliserade pulvret vid -20 °C och håll den rekonstituerade lösningen vid 2-8 °C samt använd inom 30 dagar.",faq:[{question:"Vad är AOD-9604?",answer:"AOD-9604 är ett syntetiskt fragment av humant tillväxthormon med 16 aminosyrarester (resterna 177-191 med ett N-terminalt tyrosin) som behåller hGH:s lipolytiska domän utan dess tillväxtfrämjande aktivitet. Den studeras i gnagarmodeller av lipolys i fettväv, fettoxidation och energibalans."},{question:"Har AOD-9604 studerats på människor?",answer:"Ja. Sex randomiserade, placebokontrollerade studier på 925 försökspersoner, med oral och intravenös administrering i upp till 24 veckor, rapporterade ingen förändring av IGF-1, ingen effekt på glukos eller insulin och en biverkningsprofil liknande placebo. Den 24 veckor långa fas 2b-studien på fetma visade ingen signifikant viktminskning, och den kliniska utvecklingen avbröts 2007. Den levereras här uteslutande som en referensstandard för forskning."},{question:"Vad är sekvens och molekylvikt för AOD-9604?",answer:"AOD-9604 har sekvensen Tyr-Leu-Arg-Ile-Val-Gln-Cys-Arg-Ser-Val-Glu-Gly-Ser-Cys-Gly-Phe (YLRIVQCRSVEGSCGF) med en disulfidbindning Cys7-Cys14, molekylformeln C78H123N23O23S2 och en molekylvikt på cirka 1815,1 g/mol som fri peptid (PubChem CID 71300630, CAS 221231-10-3)."},{question:"Vilken renhet har AOD-9604 från Miro Biotech?",answer:"Varje batch testas av ett oberoende tredjepartslabb och verifieras till 99,36 % renhet, med ett analyscertifikat för batchen."},{question:"Hur ska AOD-9604 förvaras?",answer:"Förvara det lyofiliserade pulvret vid -20 °C för långtidsförvaring, skyddat från ljus och fukt. Rekonstituerade lösningar ska hållas vid 2-8 °C och användas inom 30 dagar; undvik upprepad frysning och upptining, vilket kan påverka disulfidbindningen."},{question:"Vad ingår i min beställning?",answer:"Din beställning innehåller peptidflaskan/-flaskorna. Varje batch testas av ett oberoende tredjepartslabb med ett digitalt analyscertifikat (COA). Ett COA för valfri produkt finns tillgängligt på begäran."}],tags:["lipolys","metabol","tillväxthormonfragment","fettväv","fettoxidation","forskningspeptid"],aka:["AOD9604","Tyr-hGH177-191","hGH-fragment 176-191","LAT8881"],whatIs:"AOD-9604 är en syntetisk hexadekapeptid som härrör från den C-terminala regionen av humant tillväxthormon och är utformad för att skilja hGH:s lipolytiska domän från dess tillväxtfrämjande signalering. Den används som forskningssubstans i studier av lipolys i fettväv, fettoxidation och energiförbrukning i gnagarmodeller samt som referensmaterial i metodutveckling för antidopning. Levereras endast för in-vitro- och laboratorieforskning.",mechanism:"I publicerad forskning var oral AOD-9604 som gavs till feta Zucker-råttor i 19 dagar associerad med mindre än hälften av kontrollernas viktökning och högre lipolytisk aktivitet i fettväven, utan förlust av insulinkänslighet vid euglykemisk klamp, till skillnad från intakt hGH. Hos ob/ob-möss var kronisk behandling associerad med minskad viktökning och högre fettoxidation in vivo utan hyperglykemi, och peptiden konkurrerade inte om hGH-receptorn och inducerade inte proliferation i en cellinje med hGH-receptorer. Behandlingen återställde det nedtryckta uttrycket av beta-3-adrenerga receptorer hos feta möss, men kroniska effekter saknades hos beta-3-knockoutmöss, så författarna drog slutsatsen att den lipolytiska verkan inte är direkt förmedlad via beta-3-receptorn. Hos människor rapporterade sex placebokontrollerade studier ingen förändring av IGF-1 eller glukosmetabolismen; den orala armen med 1 mg/dag i 12 veckor förlorade 2,6 kg mot 0,8 kg med placebo utan dosberoende, och den 24 veckor långa fas 2b-studien visade ingen signifikant viktminskning. Dessa fynd beskriver den publicerade litteraturen; substansen levereras här uteslutande som en referensstandard för forskning.",receptorTargets:["Signalvägar för lipolys i fettväv och fettoxidation (gnagarmodeller)","Uttryck av beta-3-adrenerga receptorer (associerat, inte direkt)","Ingen bindning till hGH-receptorn","Akut reglering av energiförbrukning (gnagare)"],specs:[{label:"Sekvens",value:"Tyr-Leu-Arg-Ile-Val-Gln-Cys-Arg-Ser-Val-Glu-Gly-Ser-Cys-Gly-Phe (YLRIVQCRSVEGSCGF), disulfid Cys7-Cys14"},{label:"Klassificering",value:"Syntetiskt C-terminalt hGH-fragment (hexadekapeptid), lipolytisk domän"},{label:"Utseende",value:"Vitt lyofiliserat pulver"},{label:"Löslighet",value:"Löslig i vatten och bakteriostatiskt vatten"}],researchApplications:[{title:"Gnagarmodeller av fetma",description:"Används i studier på feta Zucker-råttor och ob/ob-möss av viktökning, fettoxidation och glukoshantering."},{title:"Lipolysanalyser",description:"Studeras i preparat av fettväv för lipolytisk aktivitet och glycerolfrisättning."},{title:"Struktur-aktivitet hos hGH-fragment",description:"Tillämpas i arbete som skiljer tillväxthormonets lipolytiska domän från dess receptorförmedlade tillväxtsignalering."},{title:"Metodutveckling för antidopning",description:"Fungerar som referensmaterial för LC-MS-detektion och in-vitro-metabolismstudier av tillväxthormonfragment."}],keyStudies:[{title:"Metabola studier av en syntetisk lipolytisk domän (AOD9604) av humant tillväxthormon",source:"Hormone Research",year:2e3,url:"https://pubmed.ncbi.nlm.nih.gov/11146367/",finding:"Rapporterade att feta Zucker-råttor som fick oral AOD9604 i 19 dagar ökade mindre än hälften så mycket i kroppsvikt som kontrollerna, visade högre lipolytisk aktivitet i fettväven och behöll normal insulinkänslighet vid euglykemisk klamp, till skillnad från djur som fick intakt tillväxthormon."},{title:"Effekterna av humant GH och dess lipolytiska fragment (AOD9604) på lipidmetabolismen efter kronisk behandling hos feta möss och beta(3)-AR-knockoutmöss",source:"Endocrinology",year:2001,url:"https://pubmed.ncbi.nlm.nih.gov/11713213/",finding:"Rapporterade att 14 dagars behandling minskade kroppsvikt och fett och återställde det nedtryckta uttrycket av beta-3-adrenerga receptorer hos feta möss, medan kroniska effekter saknades hos beta-3-knockoutmöss, vilket ledde författarna till slutsatsen att den lipolytiska verkan inte är direkt receptorförmedlad."},{title:"Säkerhet och tolerabilitet för hexadekapeptiden AOD9604 hos människor",source:"Journal of Endocrinology and Metabolism",year:2013,url:"https://www.jofem.org/index.php/jofem/article/view/157/194",finding:"Sammanfattade sex randomiserade, dubbelblinda, placebokontrollerade studier på 925 försökspersoner med oral och intravenös AOD9604 i upp till 24 veckor, och rapporterade ingen effekt på IGF-1 i serum eller kolhydratmetabolismen, inga antikroppar mot substansen och en biverkningsprofil som inte gick att skilja från placebo."},{title:"Centrala och perifera molekylära mål för farmakoterapi mot fetma",source:"Clinical Pharmacology and Therapeutics",year:2010,url:"https://pubmed.ncbi.nlm.nih.gov/20445536/",finding:"Gick igenom det kliniska AOD9604-programmet och noterade en viktförändring på 2,6 kg mot 0,8 kg med placebo i armen med 1 mg/dag i 12 veckor utan dosberoende, samt att utvecklingen avbröts 2007 efter att en 24 veckor lång studie på 536 försökspersoner inte visat någon signifikant viktminskning."}],reconstitution:"Rekonstitueras vanligen med bakteriostatiskt vatten för laboratoriebruk. Tillsätt spädningsvätskan långsamt mot flaskans vägg och snurra försiktigt i stället för att skaka. Håll den rekonstituerade lösningen kyld och använd den inom ett definierat forskningsfönster.",storage:"Förvara det lyofiliserade pulvret förslutet vid -20 °C, skyddat från ljus och fukt. Efter rekonstituering, håll kylt vid 2-8 °C och undvik upprepad frysning och upptining.",howSupplied:"Levereras som en enda försluten flaska med vitt lyofiliserat AOD-9604-pulver i vald storlek. Bakteriostatiskt vatten för rekonstituering finns som ett separat tillägg."}},categories:{"metabolic-peptides":{name:"Metabola peptider",description:"Peptider som är involverade i metabol reglering, energihomeostas och forskning om kroppssammansättning. Inkluderar agonister för GLP-1-, GIP- och glukagonreceptorer."},"recovery-peptides":{name:"Återhämtnings- och reparationspeptider",description:"Peptider för vävnadsreparation och sårläkning för studier inom regenerativ medicin. Används världen över av forskare, laboratorier och institutioner för in-vitro-forskning."},"cognitive-peptides":{name:"Kognitiva peptider",description:"Nootropa och neuroprotektiva peptider för neurovetenskap samt forskning om minne, uppmärksamhet och CNS. Studeras in vitro av forskare, laboratorier och institutioner."},"anti-aging-peptides":{name:"Anti-aging-peptider",description:"Peptider som studeras för sin roll i livslängd, hudhälsa, cellulär energi och åldersrelaterade biologiska processer."},blends:{name:"Forskningsblandningar",description:"Forskningsblandningar med flera peptider, co-lyofiliserade i en enda flaska för studiedesigner med kombinerade signalvägar. Levereras till enskilda forskare, laboratorier och institutioner endast för in-vitro- och laboratorieforskning."},accessories:{name:"Forskningstillbehör",description:"Grundläggande förnödenheter för peptidforskning, inklusive bakteriostatiskt vatten och rekonstitueringsmaterial. Används av forskare, laboratorier och institutioner världen över."}}}};function a(e,i){if("en"===i)return e;let n=t[i]?.products[e.slug];return n?{...e,...n}:e}function r(e,i){if("en"===i)return e;let n=t[i]?.categories[e.slug];return n?{...e,...n}:e}e.s(["getLocalizedCategories",0,function(e){return"en"===e?n:n.map(i=>r(i,e))},"getLocalizedCategory",0,r,"getLocalizedProduct",0,a,"getLocalizedProducts",0,function(e){return"en"===e?i.products:i.products.map(i=>a(i,e))}],98655)}]);